typedef vector<int> vec;
typedef vector<vec> mat;
//bit.ver
//rankを返す
int Gaussian_elimination(mat &A) {
	if (A.empty())return 0;
	int n = A.size(); int m = A[0].size();
	int le = 0;
	rep(j, m) {
		Rep(i, le, n) {
			if (A[i][j]) {
				swap(A[le], A[i]);
				Rep(i2, le + 1, n) {
					if (A[i2][j]) {
						rep(k, m) {
							A[i2][k] ^= A[le][k];
						}
					}
				}
				le++; break;
			}
		}
	}
	return le;
}

bool can(mat &A, vector<int> s) {
	rep(j, 60) {
		if (s[j] == 0)continue;
		per(i, (int)A.size()) {
			if (A[i][j]) {
				rep(k, 60) {
					s[k] ^= A[i][k];
				}
				break;
			}
		}
	}
	rep(i, 60)if (s[i])return false;
	return true;
}

