template<int COL=64>
struct bitmat{
private:
    vector<bitset<COL>> mat;
    int rank;
public:
    int addRow(bitset<COL> &aRow){
        mat.push_back(aRow);
        return eliminate();
    }
    int eliminate(){
        rank=0;
        for(int col=0;col<COL;++col){
            int pivot=-1;
            for(int row=rank;row<(int)mat.size();++row){
                if(mat[row][col]){
                    pivot=row;
                    break;
                }
            }
            if(pivot==-1)continue;
            swap(mat[pivot],mat[rank]);
            for(int row=rank+1;row<(int)mat.size();++row){
                if(mat[row][col]){
                    mat[row]^=mat[rank];
                }
            }
            ++rank;
        }
        return rank;
    }
    int getRank(){
        return rank;
    }
};


