void exe(ll N, vector<ll> A, vector<bool> bls)
{
    //解説の通り後ろからDPを埋めていく
    vector<set<ll>> dp(N +  1);
    dp[N].insert(0); //(N+1)ラウンド、つまり終了時
    for (ll i = N - 1; i >= 0; i--)
    {
        //各ラウンド(Nラウンド(添え数字iは1小さい)スタート)
        if(bls[i])
        { //Si=1
            if(dp[i+1].find(A[i]) != dp[i+1].end())
            { //AiがDP[i+1]の要素の1つ
                for(auto x : dp[i+1])
                {
                    dp[i].insert(x);
                }
            }
            else
            {
                //dp[i]は空集合
                break; //終了
            }
        }
        else
        { //Si=0
            for(auto x : dp[i+1])
            {
                dp[i].insert(x);
                dp[i].insert(x ^ A[i]);
            }
        }
    }

    OUTX((dp[0].size() == 0 ? 1 : 0));


    return;
}


