	{
		for (long long i=mxlog;i>=0;i--)
		{
			if (x&(1ll<<i))
			{
				if (!a[i]) return 0;
				else x^=a[i];
			}
		}
		return 1;
	}
	void merge(const linear_base &b) 
	{
		for (long long i=mxlog;i>=0;i--) 
		{
			if (b.a[i]) Insert(b.a[i]);
		}
	}
