using namespace std;

bool check(vector<ll> v, ll x) {
  for (int i = 60; i >= 0; --i) {
    ll bit = 1;
    rep(j, i) bit <<= 1;
    if ((x & bit) == 0) continue;
    vector<ll> nv;
    bool found = false;
    rep(i, v.size()) {
      if ((v[i] & bit) == 0) {
        nv.push_back(v[i]);
      } else {
        found = true;
        nv.push_back(v[i] ^ x);
      }
    }
    if (!found) return false;
    x ^= bit;
    swap(v, nv);
  }
  return true;
}

bool nonzero() {
  in(int, N);
  vector<ll> a(N);
  rep(i, N) cin >> a[i];
  in(string, s);
  vector<ll> v;
  for (int i = N - 1; i >= 0; --i) {
    if (s[i] == '0') {
      v.push_back(a[i]);
    } else {
      if (!check(v, a[i])) {
        return true;
      }
    }
  }
  return false;
}

