using namespace std;
using ll=long long;

int msb(ll x){
    ll upper=x>>32;
    if(upper){
        int tmp = __builtin_clz(upper);
        return 63-tmp;
    }
    return 31-__builtin_clz(x);
}
void solve(){
    int n;
    cin>>n;
    vector<ll> a(n);
    for(int i=0;i<n;i++){ 
        cin>>a[i];
    }

    string s;
    cin>>s;
    vector<ll> bases;
    vector<ll> sbases;
    auto add=[](vector<ll>& bases,ll x){
        for(int j=int(bases.size())-1;j>=0;j--){
            int b = msb(bases[j]);
            if(x & (1LL<<b)){
                x^=bases[j];
            }
            if(x==0){
                break;
            }
        }
        if(x!=0){
            bases.push_back(x);
            sort(bases.begin(),bases.end());
        }
        return bases;
    };
    auto sub=[](vector<ll>& bases,ll x){
        ll tmp = -1;
        for(int j=(int)(bases.size())-1;j>=0;j--){
            int b = msb(bases[j]);
            if(x & (1LL<<b)){
                x^=bases[j];
                if(tmp==-1){
                    tmp = j;
                }
            }
            if(x==0){
                break;
            }
        }
        if(x!=0){
            return false;
        }
        bases.erase(bases.begin()+tmp);
        return true;
    };
    auto perform=[&](){
        while(!sbases.empty()){
            ll x = sbases.back(); sbases.pop_back();
            if(!sub(bases,x)){
                return false;
            }
        }
        return true;
    };
    for(int i=n-1;i>=0;i--){
        // cerr<<"#"<<endl;
        if(i!=n-1 && s[i]=='0' && s[i]=='1'){
            if(!perform()){
                cout<<1<<endl;
                return;
            }
        }
        if(s[i]=='0'){
            add(bases,a[i]);
        }
        else{
            add(sbases,a[i]);   
        }

    }
    if(!perform()){
        cout<<1<<endl;
        return;
    }
    cout<<0<<endl;
    return;
}   
int main(){

    int t;
    cin>>t;
    for(int i=0;i<t;i++){
        solve();
    }

    return 0;
}

