void ins(LL x){
	for (LL i=k;~i;--i){
		if (x>>i&1){
			if (!f[i]){f[i]=x; return;}
			else x^=f[i];
		}
	}
}

bool pd(LL x){
	for (LL i=k;~i;--i){
		if (x>>i&1){
			if (!f[i]) return 0;
			x^=f[i];
		}
	}
	return 1;
}

