bool play(int idx, bool given, int bit){
	if(idx==n){
		return given;
	}else{
		bool flip = ((a[idx]&(1ll<<bit))!=0);
		bool pos = 0;
		pos |= (play(idx+1, given, bit) == (s[idx]-'0'));
		if(flip) pos |= (play(idx+1, !given, bit) == (s[idx]-'0'));
		return (pos?s[idx]-'0':1-(s[idx]-'0'));
	}
}

