    reverse(A.begin(), A.end());
    reverse(S.begin(), S.end());
    if (S[0] == '1') return 1;
    ll idx = 0;
    Matrix<Ftwo> prev_mat(0, 0);
    ll prev_rank = 0;
    while (true) {
      ll prev_idx = idx;
      while (idx < N && S[idx] == '0') idx++;
      ll cnt0 = idx - prev_idx;
      while (idx < N && S[idx] == '1') idx++;
      ll cnt1 = idx - prev_idx - cnt0;
      if (cnt1 == 0) break;
      Matrix<Ftwo> mat0(prev_rank + cnt0, msize);
