bool update(ull matrix[64][64], ull a, char sp)
{
    debug_printf("---------- update sp=%c a=%lld\n", sp, a);

    if (sp == '0') {
        ll h = -1;
        rep (hh, 64) {
            bool ok = true;
            rep (ww, 64) if (matrix[hh][ww]) ok = false;
            if (ok) {
                h = hh;
                break;
            }
        }
        if (h < 0) return false;

        rep (ww, 64) matrix[h][ww] = ((a>>ww) & 1ULL);

        debug_printf("--------- matrix 1\n");
        rep (hh, 4) {
            rep (ww, 4) debug_printf("%lld ", matrix[hh][ww]);
            debug_printf("\n");
        }

        ll hhnow = 0;
        rep (ww, 64) {
            ll hhone = -1;
            srep (hh, hhnow, 64) if (matrix[hh][ww]) {
                hhone = hh;
                break;
            }
            if (hhone < 0) continue;
            if (hhone != hhnow) {
                rep (www, 64) matrix[hhnow][www] ^= matrix[hhone][www];
            }
            srep (hh, hhnow+1, 64) {
                if (!matrix[hh][ww]) continue;
                rep (www, 64) {
                    matrix[hh][www] ^= matrix[hhnow][www];
                }
            }
            hhnow++;
        }

        debug_printf("--------- matrix 2\n");
        rep (hh, 4) {
            rep (ww, 4) debug_printf("%lld ", matrix[hh][ww]);
            debug_printf("\n");
        }

        return false;
    }

    ull now = 0;
    rep (hh, 64) {
        ll ww1 = -1;
        rep (ww, 64) if (matrix[hh][ww]) {
            ww1 = ww;
            break;
        }
        if (ww1 < 0) break;
        if ((now & (1LL<<ww1)) == (a & (1LL<<ww1))) continue;
        rep (ww, 64) now ^= (matrix[hh][ww] << ww);
        debug_printf("---- now=%lld\n", now);
    }

    return (now != a);
}

void solve()
{
    debug_printf("------------------------------------- solve\n");
    ll n; llin(n);
    V<ll> alist; llina(alist, n);
    string s; CIN(s);

    ull matrix[64][64];
    memset(matrix, 0, sizeof(matrix));

