constexpr int C{60};

class Solve
{
  int N;
  vector<ll> A;
  string S;
  vector<ll> P;

public:
  Solve(int N) : N{N}, A(N)
  {
    for (auto i{0}; i < N; ++i)
    {
      cin >> A[i];
    }
    cin >> S;
  }

  void flush()
  {
    cout << make_P_Q() << endl;
  }

private:
  int make_P_Q()
  {
    vector<ll> Q;
    for (auto i{0}; i < N; ++i)
    {
      if (S[i] == '1')
      {
        P.push_back(A[i]);
      }
      else
      {
        Q.push_back(A[i]);
        if (i == N - 1 || S[i + 1] == '1')
        {
          reduce(Q);
          Q.clear();
        }
      }
    }
    for (auto e : P)
    {
      if (e != 0)
      {
        return 1;
      }
    }
    return 0;
  }

  void reduce(vector<ll> &Q)
  {
    auto row{size_t{0}};
    for (auto j{C - 1}; j >= 0; --j)
    {
      bool pivot{false};
      for (auto i{row}; i < Q.size(); ++i)
      {
        if (Q[i] >> j & 1)
        {
          pivot = true;
          swap(Q[row], Q[i]);
          break;
        }
      }
      if (!pivot)
      {
        continue;
      }
      for (auto i{row + 1}; i < Q.size(); ++i)
      {
        if (Q[i] >> j & 1)
        {
          Q[i] ^= Q[row];
        }
      }
      for (auto &x : P)
      {
        if (x >> j & 1)
        {
          x ^= Q[row];
        }
      }
      ++row;
    }
  }
};

