            a.push_back(A[i]);
        }
        else{
            v.push_back(A[i]);
        }
    }
    make(v);
    bool check = true;
    for (ll i = 0; i < a.size(); i++) {
        if(!ok(v, a[i])){
            check = false;
        }
    }
    if(check){
        printf("%d\n", 0);
    }
    else{
        printf("%d\n", 1);
    }
}

