    vector<ull> A;
    string S;

    bool input() {
        is >> N;
        A.resize(N);
        is >> A >> S;
        return !!is;
    }

    bool base(vector<ull>& x, ull k){
        for (auto &&xi : x) {
            if(((-xi) & xi) & k){
                k ^= xi;
            }
        } // end xi
        if(k > 0){
            for (auto &&xi : x) {
                if(((-xi) & xi) & k){
                    xi ^= k;
                }
            } // end xi
            x.emplace_back(k);
            return true;
        }
        return false;
    }

    void solve(){
        int l;
        l = N;
        vector<ull> b;

        while(l-- > 0){
            if(S[l] == '1'){
                if(base(b, A[l])){
                    os << 1 << endl;
                    return;
                }
            }
            else {
                base(b, A[l]);
            }
        }
        os << 0 << '\n';
    }

    void run();
};

