            cin >> A[i];
        }
        string S;
        cin >> S;
        reverse(A.begin(), A.end());
        reverse(S.begin(), S.end());

        constexpr ll mx_d = 61;

        mat.assign(mx_d, bs());

        bool is_zero = true;

        for (ll i = 0; i < N; i++) {
            if (S[i] == '0') {
                for (ll j = 0; j < mx_d; j++) {
                    mat[j][i] = (bool)(A[i] & (1ll << j));
                }
            }
            else {
                constexpr ll bk = 201;

                for (ll j = 0; j < mx_d; j++) {
                    mat[j][bk] = (bool)(A[i] & (1ll << j));
                }

                auto mat_cpy = mat;

                int rank = 0;
                for (ll col = 0; col < bk; col++) {
                    int pivot = -1;
                    for (ll row = rank; row < mx_d; ++row) {
                        if (mat[row][col]) {
                            pivot = row;
                            break;
                        }
                    }

                    if (pivot == -1) continue;
                    swap(mat[pivot], mat[rank]);
                    for (ll row = 0; row < mx_d; ++row) {
                        if (row != rank && mat[row][col]) mat[row] ^= mat[rank];
                    }
                    ++rank;
                }

                for (ll row = rank; row < mx_d; ++row) {
                    if (mat[row][bk]) {
                        is_zero = false;
                        break;
                    }
                }

                if (!is_zero) {
                    break;
                }

                mat = mat_cpy;
            }
        }

        if (is_zero)
            cout << 0 << "\n";
        else
            cout << 1 << "\n";
    }
}

