    VL A(N);
    VECCIN(A);
    SCIN(S);
    VL os, zs;
    REP(i, sz(S)) {
        if(S[i] == '0') {
            zs.emplace_back(A[i]);
        } else {
            if(zs.empty()) {
                COUT(1);
                return;
            }
            BitMatrix B(MD + 1, sz(zs));
            for(long long d = MD; d >= 0; --d) {
                for(int i = 0; i < sz(zs); ++i) {
                    if(zs[i] & (1LL << d)) B[MD - d][i] = 1;
                }
            }
            VI b(MD + 1), res(sz(zs));
            b.assign(MD + 1, 0LL);
            for(long long d = MD; d >= 0; --d) {
                if(A[i] & (1LL << d)) b[MD - d] = 1;
            }
            if(linear_equation(B, b, res) == -1) {
                COUT(1);
                return;
            }
        }
    }
    COUT(0);
}

