// BitMatrix 構造体の定義
// （MAX_ROW行 MAX_COL列 の2次元配列として扱える）
// 2次元配列と言っても、各行はvectorや配列でなく bitset<MAX_COL>
// BitMatrix[i] でi行目のbitset<MAX_COL>を読み書きできる
const int MAX_ROW = 200; // to be set appropriately l_e()を使うとき+1注意
const int MAX_COL = 65; // to be set appropriately (-->拡大係数行列のため)
// MAXはあくまでMAXであり、BitMatrix B(H, W); のH, Wは小さくてもよさそう（？）
// --> その場合、下のbitから使ってくれる
struct BitMatrix {
  int H, W;
  bitset<MAX_COL> val[MAX_ROW];
  BitMatrix(int m = 1, int n = 1) : H(m), W(n) {}
  inline bitset<MAX_COL>& operator [] (int i) {return val[i];}
};

// 受け取ったBitMatrix<MAX_COL>にガウスジョルダンの消去法を行い、破壊的に標準形に変える
// （注意！）出てくる標準形 BitMatrix は、上下反転しているので注意。
//          bitset[i] は「下からiビット目」を表し、右端から処理しているため
// 拡大係数行列のときは GJ(A, true) で呼び出す
int GaussJordan(BitMatrix &A, bool is_extended = false) {
  int rank = 0; // 現時点で何rank目まで行を固定したか
  // 列ごとにピボットのある行を見つけ、上に置く行から順番に固定していく
  // （注意！）右端からピボットを見つけていく（結果、得られる標準形は上下反転）
  for (int col = 0; col < A.W; ++col) {
    // ？　拡大係数行列の場合は最後の列は掃き出ししない
    if (is_extended && col == A.W - 1) break;

    // 固定済み行のすぐ下（rank行）から、ピボットを作れる行を探していく
    int pivot = -1;
    for (int row = rank; row < A.H; ++row) {
      if (A[row][col]) {
        pivot = row;
        break;
      }
    }
    // col列にピボットがなかったら次の列へ（rankは増えない）
    if (pivot == -1) continue;

    // col列にピボットを作れる行が見つかったので、固定済み行のすぐ下に固定
    // = 今見ている行 A[pivot]と、固定したい場所にある行 A[rank]をswap
    swap(A[pivot], A[rank]);

    // ピボットのある列の値がすべて 0 になるように掃き出す
    // rank行以外で、ピボットのある列の値が1になっているものをA[rank]で掃き出す
    for (int row = 0; row < A.H; ++row) {
      if (row != rank && A[row][col]) A[row] ^= A[rank];
    }
    ++rank;
  }
  return rank;
}

// F2上の連立一次方程式 Ax = b を解く（解なしの場合 -1 を返す）
// 解が一つに定まる場合（or解なし）を想定しているので、解が複数ある場合に注意
// （注意）拡大係数行列ではなく、l_e(左辺BitMatrix, 右辺vector<int>) で使う
// 元の行列A, ベクトルbは更新されない（解を求めるだけであり、階段行列にはしない）
// vector<int>の引数resに答えが入り、戻り値は rank
// b や res は {0, 1, 1, 0, 1} といった形式で渡す（戻ってくる）
int linear_equation(BitMatrix A, vector<int> b, vector<int> &res) {
  int m = A.H, n = A.W;
  // 行列A, ベクトルbを繋げて、拡大係数行列 M を作成
  // （注意！）ベクトルbを「左端」に繋げている！
  BitMatrix M(m, n + 1);
  for (int i = 0; i < m; ++i) {
    for (int j = 0; j < n; ++j) M[i][j] = A[i][j];
    M[i][n] = b[i]; // ベクトルbは「左端」に繋げる
  }
  // 拡大係数行列Mを標準形へと変形し、rankを求める
  int rank = GaussJordan(M, true);

  // check if it has no solution（解なしの場合-1を返す）
  // rank以降の行（解ありなら全部0になっているはずの行）に、000001 のような行があれば解なし（0x1+0x2+...+0xn=1 で矛盾）
  for (int row = rank; row < m; ++row) if (M[row][n]) return -1;

  // answer（返すのはrankなので、解の個数を知りたければ 2^(n-rank) ※n:=変数の個数=Aの列数
  // ※ GaussJordan()でもrankは求められるので都合で使い分ければいい
  // ベクトルbの部分が答えになる（n=rankの場合、そうなる）
  assert(n==rank); // 元々は無かったが、無いとやらかしそうなので入れた
  res.assign(n, 0);
  for (int i = 0; i < rank; ++i) res[n-1-i] = M[i][n]; // 改造あり
  return rank;
}

