				while(a[i])
				{
					if(a[i]%2==1)
					{
						ct1[nw].push_back(i);
					}
					a[i]/=2;
					nw++;
				}
			}
			else
			{
				int nw=0;
				while(a[i])
				{
					if(a[i]%2==1)
					{
						ct2[nw].push_back(i);
					}
					a[i]/=2;
					nw++;
				}
			}
		}
		bool ok=true;
		for(int i=0;i<64;i++)
		{
			if(ct1[i].size()==0 && ct2[i].size()!=0)
			{
				ok=false;
				break;
			}
			if(ct1[i].size()!=0 && ct2[i].size()!=0)
			{
				if(ct1[i][ct1[i].size()-1]<ct2[i][ct2[i].size()-1])
				{
					ok=false;
					break;
				}
				for(int j=0;j<ct1[i].size();j++)
				{
					if(ct1[i][j]>ct2[i][ct2[i].size()-1])
					{
						cn[i].push_back(ct1[i][j]);
						cnt[ct1[i][j]]++;
					}
				}
			}
		}
		for(int i=0;i<64;i++)
		{
			if(cn[i].size()==0)
			{
				continue;
			}
			bool fd=false;
			int mn=1e9,pp=0;
			for(int j=0;j<cn[i].size();j++)
			{
				int x=cn[i][j];
				if(vis[x])
				{
					continue;
				}
				if(cnt[x]<mn)
				{
					mn=cnt[x];
					pp=x;
					fd=true;
				}
			}
			if(!fd)
			{
				ok=false;
				break;
			}
			vis[pp]=true;
		}
		if(ok)
		{
			cout<<0<<endl;
		}
		else
		{
			cout<<1<<endl;
		}
	}
	return 0;
}

