			while((v1[j]&((LL)1<<k))==0 && k<60){
				if(v3[i]&((LL)1<<k))return false;
				k++;
			}
			if(k>=60)break;
			if(v3[i]&((LL)1<<k))v3[i]^=v1[j];
		}
		if(v3[i])return false;
	}
	return true;
}

