    vector<long long> S(N, 0LL);
    for (long long i = 0; i < N; ++i) {
        if (s_str[i] == '0') {
            S[i] = 0LL;
        }
        else {
            S[i] = 1LL;
        }
    }

    set<long long> oneCanMake1bit;
    for (int i = 0; i < N; ++i) {
        if (S[i] == 1) {
            bitset<64> bit(A[i]);
            for (int b = 0; b < 64; ++b) {
                if (bit[b] == 1) {
                    oneCanMake1bit.insert(b);
                }
            }
        }
    }

    long long numLast0 = 0LL;
    set<long long> zeroCanMake1bit;
    for (int i = N - 1; i >= 0; --i) {
        if (S[i] == 0) {
            ++numLast0;
            bitset<64> bit(A[i]);
            for (int b = 0; b < 64; ++b) {
                if (bit[b] == 1) {
                    zeroCanMake1bit.insert(b);
                }
            }
        }
        else {
            break;
        }
    }

    if (numLast0 == 0) {
        cout << 1 << endl;
        return;
    }

    bool canMake0 = true;
    for (auto e : oneCanMake1bit) {
        if (zeroCanMake1bit.count(e)) {
            continue;
        }
        else {
            canMake0 = false;
            break;
        }
    }

    cout << (canMake0 ? 0 : 1) << endl;
}

