bool sweepable(LL v, vector<LL>& cand){
    for(LL v2: cand){
        if((v ^ v2) < v) v ^= v2;
    }
    return v == 0;
}

void build(vector<LL>& cand){
    //cerr << "buld.." << endl;
    //cerr << cand << endl;
    for(LL i = 0; i < cand.size(); ++i){
        sort(cand.begin(), cand.end(), greater<LL>());
        for(LL j = 0; j < cand.size(); ++j){
            if(i == j) continue;
            if((cand[i] ^ cand[j]) < cand[j]) cand[j] ^= cand[i];
        }
        //cerr << cand << endl;
    }
}

void sweep(vector<LL>& rest, vector<LL>& cand){
    vector<LL> new_rest;
    build(cand);
    for(LL v: rest){
        if(!sweepable(v, cand)){
            new_rest.push_back(v);
        }
    }
    rest.swap(new_rest);
}

