// https://siokoshou.hatenadiary.org/entry/20090704/p1
struct GetNumberOfTrailingZeros {
  constexpr GetNumberOfTrailingZeros() : table() {
    uint64_t hash = 0x03F566ED27179461UL;

    for (int i = 0; i < 64; i++)
    {
      table[hash >> 58] = i;
      hash <<= 1;
    }
  }
  int Calc(int64_t x)
  {
    if (x == 0) return 64;

    uint64_t y = (uint64_t)(x & -x);
    int i = (int)((y * 0x03F566ED27179461UL) >> 58);
    return table[i];
  }
  int table[64];
};

GetNumberOfTrailingZeros gntz;

bool solve() {
  int N;
  cin >> N;
  vector<i64> as(N);
  F0R(i, N) {
    cin >> as[i];
  }
  string S;
  cin >> S;

  // 人1が1回しか行動できないと仮定し、
  // Siが1のときの全てのAiに対し、それ以降に人0が0に出来るか？を求めれば多分OK

  F0R(i, N) {
    if (S[i] == '1') {

      vector<vector<int>> cs(63); // ビットごとに、そのビットを持つ数のindex
      int nc = 0; // 使える数の数
      FOR(j, i + 1, N) {
        if (S[j] != '0') continue;
        nc++;

        i64 n = as[j];
        for(int k=0; n; k++, n>>=1) {
          if (n & 1) {
            cs[k].push_back(j);
          }
        }
      }
      set<int> us;  // 使ったindex

      // 0にできるか？
      auto dfs = [&](auto dfs, i64 val)->bool {

        if (val == 0) return true;
        if (us.size() >= nc) return false;

        // 立っているビット位置を持つ値を全て試す
        int n = gntz.Calc(val);
        F0R(i, cs[n].size()) {
          if (us.find(cs[n][i]) == us.end()) {
            us.insert(cs[n][i]);
            if (dfs(dfs, val ^ as[cs[n][i]])) {
              return true;
            }
            us.erase(cs[n][i]);
          }
        }

        return false;
      };

      // 0にできなかった
      if (!dfs(dfs, as[i])) return false;
    }
  }
  return true;
}


