const int N = 201;

int dp[2][2][60][60][N], n;
long long a[N];
string s;
int yo(int i, int c1, int c2, int k1, int k2) {
	if (i == n) return c1 | c2;
	int &ret = dp[c1][c2][k1][k2][i];
	if (ret != -1) return ret;
	int b1 = (a[i] >> k1) & 1LL;
	int b2 = (a[i] >> k2) & 1LL;
	if (s[i] == '1') {
		ret = yo(i + 1, c1, c2, k1, k2) | yo(i + 1, c1 ^ b1, c2 ^ b2, k1, k2);
	}	
	else {
		ret = (!yo(i + 1, c1, c2, k1, k2)) | (!yo(i + 1, c1 ^ b1, c2 ^ b2, k1, k2));
		ret ^= 1;
	}
	return ret;
}
