		if (s.back() == '1') {
			cout << 1 << '\n'; continue;
		}
		memset(dp, -1, sizeof dp);
		for (int k1 = 0; k1 < 60; k1++) {
			for (int k2 = 0; k2 < 60; k2++) {
				if (ans) break;
				ans |= yo(0, 0, 0, k1, k2);
			}
		}
		cout << ans << '\n';
	}
    return 0;
}

