      sort(v.rbegin(), v.rend());
      ll tmp = a;
      ll cnt = 0;
      while(tmp > 0) {
        cnt++;
        tmp /= 2;
      }

      for(const auto e: v) {
        ll tmp = e;
        ll c = 0;
        while(tmp > 0) {
          c++;
          tmp /= 2;
        }
