const int64_t MAX_ROW = 64; // to be set appropriately
const int64_t MAX_COL = 510; // to be set appropriately
struct BitMatrix {
    int H, W;
    bitset<MAX_COL> val[MAX_ROW];
    BitMatrix(int64_t m = 1, int64_t n = 1) : H(m), W(n) {}
    inline bitset<MAX_COL>& operator [] (int64_t i) { return val[i]; }
};

ostream& operator << (ostream& s, BitMatrix A) {
    s << endl;
    for (int64_t i = 0; i < A.H; ++i) {
        for (int64_t j = 0; j < A.W; ++j) {
            s << A[i][j] << ", ";
        }
        s << endl;
    }
    return s;
}

inline BitMatrix operator * (BitMatrix A, BitMatrix B) {
    BitMatrix R(A.H, B.W);
    BitMatrix tB(B.W, B.H);
    for (int64_t i = 0; i < tB.H; ++i) for (int64_t j = 0; j < tB.W; ++j) tB[i][j] = B[j][i];
    for (int64_t i = 0; i < R.H; ++i) for (int64_t j = 0; j < R.W; ++j) R[i][j] = ((A[i] & tB[j]).count() & 1);
    return R;
}

int64_t GaussJordan(BitMatrix &A, bool is_extended = false) {
    int64_t rank = 0;
    for (int64_t col = 0; col < A.W; ++col) {
        if (is_extended && col == A.W - 1) break;
        int64_t pivot = -1;
        for (int64_t row = rank; row < A.H; ++row) {
            if (A[row][col]) {
                pivot = row;
                break;
            }
        }
        if (pivot == -1) continue;
        swap(A[pivot], A[rank]);
        for (int64_t row = 0; row < A.H; ++row) {
            if (row != rank && A[row][col]) A[row] ^= A[rank];
        }
        ++rank;
    }
    return rank;
}

