constexpr int bitlen = 62;
struct gauss {
    int rank = 0, free = 0;
    vi a;
    vector<bitset<bitlen>> b;
    bool isbit = 0;
    //中身を置き換える
    /*@formatter:on*/
    gauss(vi &t) {
        int n = sz(t);
        rep(i, n) {
            int x = max_element(t.begin() + i, t.end()) - t.begin();
            if (t[x] == 0)break;
            swap(t[i], t[x]);
            int pivot = 1;
            while ((pivot << 1) <= t[i])pivot <<= 1;
            /*i以外*/
            rep(j, i) if (t[j] & pivot)t[j] ^= t[i];
            rep(j, i + 1, n) if (t[j] & pivot)t[j] ^= t[i];
        }
        rank = 0;
        rep(i, n) { if (t[i])rank++; }
        free = n - rank;
        a = t;
    }
    gauss(vector<bitset<bitlen>> &t) {
        isbit = 1;
        int n = sz(t);
        rer(k, bitlen - 1) {
            if (rank >= n)break;
            int x = -1;
            rep(i, rank, n) {
                if (t[i][k]) {
                    x = i;
                    break;
                }
            }
            if (x == -1) { continue; }
            swap(t[rank], t[x]);
            rep(i, rank)if (t[i][k])t[i] ^= t[rank];
            rep(i, rank + 1, n)if (t[i][k])t[i] ^= t[rank];
            rank++;
        }
        free = n - rank;
        b = t;
    }
    mint count_m(bitset<bitlen> &k) {
        bitset<bitlen> s;
        int prev_w = bitlen - 1;
        rep(i, sz(b)) {
            while (prev_w >= 0 && b[i][prev_w] == 0)prev_w--;
            if (prev_w < 0)break;
            if (s[prev_w] != k[prev_w])s ^= b[i];
        }
        if (s == k)return mpow(2, free); else return 0;
    }
    //kが何通り作れるか
    mint count_m(int k) {
        int s = 0;
        rep(i, sz(a)) { if ((s ^ a[i]) <= k)s ^= a[i]; }
        if (s == k) return mpow(2, free); else return 0;
    }
    int count_i(int k) {
        int s = 0;
        rep(i, sz(a)) { if ((s ^ a[i]) <= k)s ^= a[i]; }
        if (s == k) return 1; else return 0;
    }
    int max() {
        auto v = ruix(a);
        return v.back();
    }
    /*@formatter:off*/
};
