ll myRank(const auto& X, ll k) {
  Matrix<Fp> mat(X.size(), k);
  for (int i = 0; i < (ll)X.size(); i++) {
    for (int j = 0; j < k; j++) {
      mat.at(i, j) = X.at(i).at(j);
    }
  }
  mat.self_sweepout();
  ll i = 0;
  for (; i < (ll)X.size(); i++) {
    bool found = false;
    for (ll j = 0; j < k; j++) {
      if (mat.at(i, j) == Fp(1)) {
	found = true;
	break;
      }
    }
    if (!found) break;
  }
  return i;
}


ll solve() {
  ll K = 60;

  ll N; cin >> N;
  vector<ll> A(N);
  for (ll i = 0; i < N; i++) cin >> A.at(i);
  string S; cin >> S;
  reverse(A.begin(), A.end());
  reverse(S.begin(), S.end());
  vector<vector<Fp>> X;
  if (S.at(0) == '1') return 1;

  auto myAppend = [&](ll a) -> void {
    vector<Fp> nv;
    for (ll i = 0; i < K; i++) {
      nv.push_back(Fp(a & 1));
      a >>= 1;
    }
    X.push_back(nv);
  };

  ll i = 0;
  while (true) {
    while (i < N && S.at(i) == '0') {
      myAppend(A.at(i));
      i++;
    }
    ll y = myRank(X, K);
    if (i == N) return 0;
    if (y == K) return 0;
    while (i < N && S.at(i) == '1') {
      myAppend(A.at(i));
      i++;
    }
    ll z = myRank(X, K);
    if (z > y) return 1;
  }
}

