	auto add = [&](ll a){
		for(int i = LOG-1; i >= 0; --i){
			if(a & (1ll<<i)){
				if(base[i] == -1){
					base[i] = a;
					return;
				}else{
					a = a^base[i];
				}
			}
		}
	};

	auto check = [&](ll a){
		for(int i = LOG-1; i >= 0; --i){
			if(a & (1ll<<i)){
				if(base[i] == -1) return false;
				a ^= base[i];
			}
		}
		return true;
	};

	for(int i = n-1; i >= 0; --i){
		if(s[i] == '0'){
			add(A[i]);
		}else{
			if(!check(A[i])){
				std::cout << 1 << "\n";
				return;
			}
		}
	}

