    int n = A.size(), m = A[0].size();

    int r = 0;
    REP(j,m){
        FOR(i,r,n-1){
            if (A[i][j]){
                swap(A[r], A[i]);
                swap(B[r], B[i]);
                break;
            }
        }
        if (A[r][j] == 0) continue;
        FOR(i,r+1,n-1){
            if (A[i][j] == 0) continue;
            FOR(jj,j,m-1){
                A[i][jj] ^= A[r][jj];
            }
            B[i] ^= B[r];
