void to_basis(vector<int> &v) {
    vector<bool> usd(v.size(), 0);
    for (int j = 0; j < 60; j++) {
        int mi = -1;
        for (int l = 0; l < v.size(); l++) {
            if (!usd[l] && (v[l] >> j) % 2) {
                mi = l;
                break;
            }
        }
        if (mi == -1) continue;
        usd[mi] = 1;
        for (int l = 0; l < v.size(); l++) {
            if (l == mi) continue;
            if ((v[l] >> j) % 2)
                v[l] ^= v[mi];
        }
    }
    sort(v.begin(), v.end());
    reverse(v.begin(), v.end());
    while (!v.empty() && v.back() == 0) v.pop_back();
}

