            gv.pb(ls); ls = 0;
        }
        ++ls;
    }
    gv.pb(ls);
    if (s[n - 1] == '1')
        return 1;
    int cs = 0;
    for (int i = 0; i < gv.size(); i += 2) {
        vector<int> cl, cr;
        for (int j = cs; j < cs + gv[i]; j++)
            cl.pb(a[j]);
