// basisの要素を2元体上のベクトルとみなす
// span{basis}がaを含むかどうか
// 含まない場合basisを更新
bool isIncluded(vector<ll>& basis, ll a){
    for(auto& b: basis){
        if(b & (-b) & a) a ^= b;
    }
    if(a == 0) return true;
    for(auto& b: basis){
        if(a & (-a) & b) b ^= a;
    }
    basis.emplace_back(a);
    return false;
}

int solve(const int N, const vector<ll>& A, const string& S){
    vector<ll> basis;
    for(int i=N-1; i>=0; i--){
        bool flag = isIncluded(basis, A[i]);
        if(flag) continue;
        if(S[i]=='1') return 1;
    }
    return 0;
}

