#include<bits/stdc++.h>

using namespace std;

typedef long long int ll;

void solve()
{
	int n;
	cin >> n;
	ll arr[n];
	for(int i = 0; i < n; i++) cin >> arr[i];
	set <ll> s;
	string s1;
	cin >> s1;
	for(int i = 0; i < n; i++) if(s1[i] == '0') s.insert(arr[i]);
	ll XOR = 0;
    for(int i = 0 ; i < n; i++)
    {
    	if(s1[i] == '0')
    	{
    		if(XOR == 0)
    		{
    			s.erase(arr[i]);
    			continue;
			}
    		if(XOR == arr[i]) XOR = (XOR ^ arr[i]);
    		else
    		{
    			if(s.find(XOR) != s.end());
    			else if(s.find(XOR ^ arr[i]) != s.end()) XOR = (XOR ^ arr[i]);
			}
			s.erase(arr[i]);
		}
		else
		{
			if(XOR == 0 || s.find(XOR) != s.end()) XOR = (XOR ^ arr[i]);
		}
	}
	if(n <= 6)
	{
		if(XOR == 0) cout << 0;
		else cout << 1;
	}
	else
	{
		cout << 1;
	}
	cout << "\n";
}

int main()
{
	int t = 1;
	cin >> t;
	while(t--)
	{
		solve();
	}
	return 0;
}

