int binaryGauss(vector<vector<char>> &mat, vector<char> &b, int n, int m) {
    int row = 0, col = 0;
    while (row < m) {
        int j = col;
        while (j < n && mat[row][j] == 0)
            j++;
        if (j == n) {
            b[row] = 0;
        }
        else {
            b[row] = 1;
            for (int i = 0; i < m; i++)
                swap(mat[i][col], mat[i][j]);
            for (int i = row + 1; i < m; i++) {
                if (mat[i][col]) {
                    for (int j = col; j < n; j++)
                        mat[i][j] ^= mat[row][j];
                }
            }
            col++;
        }
        row++;
    }
    return 1;
}

