bool normalize(vector<ll> &basis, ll val) {
	const int n = basis.size();
	const int m = 60;

	rep(i, n) {
		ll cmax = basis[i], pos = i;
		rep(j, i + 1, n) if(chmax(cmax, basis[j])) pos = j;
		if(cmax == 0) break;
		swap(basis[i], basis[pos]);

		int col = m - 1;
		while(col >= 0 and (((basis[i] >> col) & 1) == 0)) col--;

		rep(j, i + 1, n) {
			if((basis[j] >> col) & 1) {
				basis[j] ^= basis[i];
			}
		}

		if((val >> col) & 1) {
			val ^= basis[i];
		}
	}

	return (val == 0LL);
}

