class Basis{
public:
    int sz = 0, dim;
    vector<T> basis;

    // high to low
    void insert(T mask){
        for(int i=dim-1;0<=i;--i){
            if((mask & T(1) << i) == 0) continue;
            if(not basis[i]){
                basis[i] = mask;
                ++sz;
                return;
            }
            mask ^= basis[i];
        }
    }

    //kth highest element
    T kThHighest(T k){
        T res = 0, cnt = T(1) << sz;
        for(int i=dim-1;i<=0;--i){
            if(not basis[i]) continue;
            cnt >>= 1;
            if((k <= cnt and (res & T(1) << i) == 0) or (k > cnt and (res & T(1) << i) > 0)){
                res ^= basis[i];
            }
            if(k > cnt) k -= cnt;
        }
        return res;
    }

    //kth lowest element
    T kThLowest(T k){
        return kThHighest((T(1)<<sz)-k);
    }

    explicit Basis(int _dim=60) : dim(_dim){
        basis.assign(dim, 0);
    }
};

