bool check(vector<ll> v, ll x) {
  bitset<60> bs(x);
  int pivot = 0;
  rep(bit, 60) {
    for (int i = pivot; i < v.size(); ++i) {
      if (!bs[bit]) continue;
      swap(v[pivot], v[i]);
      for (int j = 0; j < v.size(); ++j) {
        if (j == pivot) continue;
        v[j] ^= v[pivot];
      }
      ++pivot;
    }
  }
  rep(i, 60) if ((x >> i) & 1) {
    bool ok = false;
    rep(j, v.size()) if ((v[j] >> i) & 1) {
      ok = true;
    }
    if (!ok) {
      return false;
    }
  }
  return true;
}

