template<typename T,int D>
struct Base{
    T a[D];
    int m;
    Base(){m = 0, memset(a, 0, sizeof(a));}
    void clear(){m = 0, memset(a, 0, sizeof(a));}
    bool ins(T x)
    {
        for(int i = D - 1; ~i; --i)
        if(x >> i & 1)
        {
            if(a[i]) x ^= a[i];
            else{
                m++;
                a[i] = x;return 1;
            }
        }
        return 0;
    }
};
