void hakidashi(vector<ll>& v) {
    int pos = 0;
    for (int d = 60; d >= 0; d--) {
        bool flg = 0;
        for (int i = pos; i < sz(v); i++) {
            if (!(v[i] >> d & 1)) continue;
            flg = 1;
            swap(v[pos], v[i]);
            break;
        }

        for (int i = pos + 1; i < sz(v); i++) {
            if (v[i] >> d & 1) v[i] ^= v[pos];
        }
        if (flg) pos++;
    }
}
bool isin(vector<ll> v, ll bit) {
    ll ret = 0;
    for (ll x : v) {
        for (int d = 60; d >= 0; d--) {
            if (x >> d & 1) {
                if ((bit >> d & 1) ^ (ret >> d & 1)) ret ^= x;
                break;
            }
        }
    }
    return ret == bit;
}
