};

bool sabset(basis a, basis b){
    for(int i=0; i<MAXLOG; i++){
        if(a.base[i]==0 and b.base[i]!=0) return false;
        if(a.base[i] and b.base[i]){
            ll jor = a.base[i] ^ b.base[i];
            if(jor){
                int k=-1;
                while(jor) jor/=2, k++;
                if(!a.base[k]) return false;
            }
        }
    }
    return true;
}

