          return 0;
        else
          return 1;
      }
      else
        return 0;
    }
    else
    {
      if(x==0)
        return 1;
      else
      {
        y=x^a[k];
        if(y==0)
          return 1;
        else
          return 0;
      }
    }
  }
  else
  {
    if(s[k]=='1')
    {
      bool q=sol(s,k+1,x^a[k],a);
      if(q==0)
      {
        ans=0;
        return 0;
      }
      else
      {
       bool w=sol(s,k+1,x,a);
        if(w==0)
          ans=0;
        return w;
      }
    }
    else
    {
      bool q=sol(s,k+1,x^a[k],a);
      if(q==1)
      {
        ans=1;
        return 1;
      }
      else
      {
