        vector<P> v;
        v.push_back(P(0, {}));
        for (int i = n - 1; i >= 0; i--) {
            if (v.back().first == (s[i] - '0')) {
                v.back().second.push_back(a[i]);
            } else {
                int nex = 1 - v.back().first;
                v.push_back(P(nex, {a[i]}));
            }
        }

        for (auto& p : v) {
            sort(p.second.begin(), p.second.end());
        }

        int sz = v.size();
        deque<ll> memo;
        bool f = true;
        for (int i = 0; i < sz; ++i) {
            if (v[i].first == 0) {
                for (ll x : v[i].second) memo.push_back(x);
            } else {
                int sz2 = memo.size();
                int rank = 0;
                for (int j = 59; j >= 0; j--) {
                    int pivot = -1;
                    for (int k = rank; k < sz2; k++) {
                        if (memo[k] >> j & 1) {
                            pivot = k;
                            break;
                        }
                    }

                    if (pivot == -1) continue;
                    swap(memo[pivot], memo[rank]);

                    for (int k = 0; k < sz2; k++) {
                        if (k != rank && (memo[k] >> j & 1)) memo[k] ^= memo[rank];
                    }

                    for (ll& x : v[i].second) {
                        if (x >> j & 1) x ^= memo[rank];
                    }
                    ++rank;
                }

                for (ll x : v[i].second) {
                    if (x != 0) {
                        f = false;
                        break;
                    }
                }

                if (!f) break;

                memo.clear();
            }
        }

        cout << !f << newl;
    }

