int gauss_jordan(vector<vector<int>> &A) {
    int m = A.size(), n = A[0].size();
    int rank = 0;
    for (int col = 0; col < n; ++col) {
        // ピボットを探す
        int pivot = -1;
        int ma = 0;
        for (int row = rank; row < m; ++row) {
            if (abs(A[row][col]) > ma) {
                ma = abs(A[row][col]);
                pivot = row;
            }
        }
        // ピボットがなかったら次の列へ
        if (pivot == -1) continue;

        // まずは行を swap
        swap(A[pivot], A[rank]);

        // ピボットの値を 1 にする
        //auto fac = A[rank][col];
        //for (int col2 = 0; col2 < n; ++col2) A[rank][col2] /= fac;

        // ピボットのある列の値がすべて 0 になるように掃き出す
        for (int row = 0; row < m; ++row) {
            if (row != rank && abs(A[row][col]) > 0) {
                auto fac = A[row][col];
                for (int col2 = 0; col2 < n; ++col2) {
                    A[row][col2] = A[row][col2] ^ (A[rank][col2]);
                }
            }
        }
        ++rank;
    }
    for (int row = 0; row < m; ++row) {
        for(int row2 = row+1; row2<m; ++row2) {
            REP(k, m) {
                if(A[row2][k] == 1) {
                    if(A[row][k] == 1) {
                        for (int col2 = 0; col2 < n; ++col2) {
                            A[row][col2] = A[row][col2] ^ (A[row2][col2]);
                        }
                    }
                    break;
                } 
            }
        }
    }
    return rank;
}
