vector<ll> reduce(vector<ll> l) {
  vector<ll> basis;
  ll use[70] = {}; // use[i] keeps the mask of the vector whose f value is i
  for (ll mask : l) {
    for (int i = 0; i < 60; i++) {
      if ((mask & 1ll << i) == 0) continue; // continue if i != f(mask)
      if (!use[i]) { // If there is no basis vector with the i'th bit set, then insert this vector into the basis
        use[i] = mask;
        basis.push_back(mask);
        break;
      }
      mask ^= use[i]; // Otherwise subtract the basis vector from this vector
    }
  }
  return basis;
}

