long long bit[70];

void insert(long long x) {
	for (int i = 0; i < 60; i++) {
		if (x >> i & 1) {
			if (!bit[i]) {
				bit[i] = x;
				return ;
			}
			x ^= bit[i];
		}
	}
}

bool check(long long x) {
	for (int i = 0; i < 60; i++) {
		if (x >> i & 1) {
			x ^= bit[i];
		}
	}
	return x == 0;
}

