        bool flag=true;
        for(int i=1;i<=n;i++){
            if(str[id[i]]=='1'){
                LB1.ins(arr[id[i]]);
            }
        }
        for(int i=1;i<=n;i++){
            if(str[id[i]]=='0'){
                LB0.ins(arr[id[i]]);
