typedef long long int ll;
int ans=8;
bool sol(string s,int k,ll x,ll a[])
{
  if(ans==1)
    return 1;
  else if(ans==0)
    return 0;
  if(k==s.length()-1)
  {
    ll y;
    if(s[k]=='1')
    {
      if(x==0)
      {
        y=x^a[k];
        if(y==0)
          return 0;
        else
          return 1;
      }
      else
        return 0;
    }
    else
    {
      if(x==0)
        return 1;
      else
      {
        y=x^a[k];
        if(y==0)
          return 1;
        else
          return 0;
      }
    }
  }
  else
  {
    if(s[k]=='1')
    {
      bool q=sol(s,k+1,x,a);
      if(q==0)
      {
        ans=0;
        return 0;
      }
      else
      {
       bool w=sol(s,k+1,x^a[k],a);
        if(w==0)
          ans=0;
        return w;
      }
    }
    else
    {
      bool q=sol(s,k+1,x^a[k],a);
      if(q==1)
      {
        ans=1;
        return 1;
      }
      else
      {
        bool w=sol(s,k+1,x,a);
        if(w==1)
          ans=1;
        return w;
      }
    }
  }
}
