template<class T>
bool updBasis(vec<T, 1>& basis, T a) {
  for (auto &i : basis) if (a >> __lg(i) & 1) a ^= i;
  if (!a) return false;
  for (auto &i : basis) if (i >> __lg(a) & 1) i ^= a;
  basis.emplace_back(a);
  return true;
}
template<class T>
bool check(const vec<T, 1>& basis, T a) {
  for (auto &i : basis) if (a >> __lg(i) & 1) a ^= i;
  return !a;
}

