       for(int i=0;i<n;i++)cin >> a[i];
       string s;
       cin >> s;
       if(s[n-1]=='1'){
           ans[tt] = 1;
       }else{
           vector<long>zero;
           queue<long>one;
           bool chk = false;
           for(int i=0;i<n;i++){
               if(chk){
                   one.push(a[n-1-i]);
               }else{
                    if(s[n-1-i]=='0'){
                        zero.push_back(a[n-1-i]);
                    }else{
                        one.push(a[n-1-i]);
                        chk = true;
                    }
               }

           }

           for(int i=0;i<zero.size();i++){
               sort(zero.begin()+i,zero.end(),greater<long>());
               long bit = getBit(zero[i]);
               if(bit == 0)break;
               for(int j=i+1;j<zero.size();j++){
