std::map<std::pair<Int, Int>, bool> map;

bool dfs(Int x, Int *a, char *s, Int i){
	if(i == 0){
		return x != 0;
	}else{
		bool p, q;
		std::pair<Int, Int> c(x, i - 1);
		auto it = map.find(c);
		if(it == map.end()){
			p = dfs(x, a + 1, s + 1, i - 1);
			map.insert(std::make_pair(c, p));
		}else{
			p = it->second;
		}
		c.first ^= *a;
		it = map.find(c);
		if(it == map.end()){
			q = dfs(x ^ *a, a + 1, s + 1, i - 1);
			map.insert(std::make_pair(c, q));
		}else{
			q = it->second;
		}
		if(*s == '0'){
			return p && q;
		}else{
			return p || q;
		}
	}
}

