	vvvm dp(N + 1, vvm(A + 1, vm(B + 1)));

	dp[0][0][0] = 1;
	rep(i, N) {
		rep(a, A + 1) {
			rep(b, B + 1) {
				rep(x, 2) {
					ll na, nb;
					if (a == A) {
