					}
					else {
						na = x ? (a + 1) : 0;
					}
					if (b == B) {
						nb = B;
					}
					else {
						nb = x ? 0 : (b + 1);
					}

					dp[i + 1][na][nb] += dp[i][a][b];
				}
			}
		}
	}
	return dp[N][A][B];
}


