int find_k(LL val) {
  int k = 0;
  while ((1LL<<k) <= val) {
    k++;
  }
  return k-1;
}

void insert(set<LL>& cur, LL val) {
  for (auto it = cur.rbegin(); it != cur.rend(); it++) {
    int k = find_k(*it);
    if ((1LL<<k) & val) val ^= *it;
  }
  if (val != 0) cur.insert(val);
}

LL rem(const set<LL>& cur, LL val) {
  for (auto it = cur.rbegin(); it != cur.rend(); it++) {
    int k = find_k(*it);
    if ((1LL<<k) & val) val ^= *it;
  }
  return val;
}

