    int pos = 0;
    for (int d = 6; d >= 0; d--) {
        bool flg = 0;
        for (int i = pos; i < sz(v); i++) {
            if (!(v[i] >> d & 1)) continue;
            flg = 1;
            swap(v[pos], v[i]);
            break;
        }
        if (flg) {
            for (int i = pos + 1; i < sz(v); i++) {
                if (v[i] >> 1 & d) v[i] ^= v[pos];
            }
            pos++;
        }
    }
}
