const int N = 234;
int T = 60;
int lst[N];
int mask[N];
bool dp[N][4];
int res[N];
int n;
string s;

int oh(int m) {
    if (m == 1) {
        return 0;
    }
    for (int i = 1; i < 4; i++) {
        if ((1 << i) == m || (1 << i) + 1 == m) {
            return i;
        }
    }
    return -1;
}

bool check() {
    int k = 0;
    int m = 0;
    for (int i = 0; i < n; i++) {
        m |= (1 << mask[i]);
        if (i + 1 == n || (s[i] != s[i + 1])) {
            res[k++] = m;
            m = 0;
        }
    }
    for (int i = 0; i < k; i++) {
        fill(dp[i], dp[i] + 4, 0);
    }
    int a = oh(res[k - 1]);
    if (a == -1) {
        return 1;
    }
    dp[k - 1][0] = dp[k - 1][a] = 1;
    for (int i = k - 2; i >= 0; i--) {
        int b = oh(res[i]);
        int t = (k - i) % 2;
        if (b == -1) {
            for (int j = 0; j < 4; j++) {
                if (dp[i + 1][j] == 0) {
                    return t;
                }
            }
            return (1 ^ t);
        }
        for (int j = 0; j < 4; j++) {
            dp[i][j] = (!dp[i + 1][j] || !dp[i + 1][j ^ b]);
        }
    }
    int t = k % 2;
    if (dp[0][0]) {
        return t;
    }
    return (1 ^ t);
}

void solve() {
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> lst[i];
    }
    cin >> s;
    if (s[n - 1] == '1') {
        cout << 1 << endl;
        return;
    }
    for (int i = 0; i < T; i++) {
        for (int j = i + 1; j < T; j++) {
            for (int t = 0; t < n; t++) {
                bool a = lst[t] & (1ll << i);
                bool b = lst[t] & (1ll << j);
                mask[t] = 1 * a + 2 * b;
            }
            if (!check()) {
               // cout << i << ' ' << j << endl;
                cout << 1 << endl;
                return;
            }
        }
    }
    cout << 0 << endl;
    return;
}

