		if(j == n) continue;
		if(j != cnt) swap(v[j], v[cnt]);
		FOR(j, cnt + 1, n)
			if(v[j] & (1LL << i))
				v[j] ^= v[cnt];

		++cnt;
	}
	return cnt;
}

