void num2vec(size_t &A, vector<int> &vec)
{
    const int dim = 64;    
    size_t mask = 1;    
    vec.resize(dim);
    for(int i = 0; i < dim; ++i)    
    {
        vec[i] = ( (A & mask) == 0) ? 0 : 1;
        mask <<= 1;
    }
}

void make_base(vector<vector<int>> &vec, vector<vector<int>> &base)
{   
    const int dim = 64;

    vector<vector<int>> temp = vec;

    for(int i = 0; i < dim; ++i)
    {
        // i 番目が 1 のベクトルを探す
        vector<int> v;
        int all_zero = 1;
        for(int n = 0; n < static_cast<int>(temp.size()); ++n)
        {
            if(temp[n][i] == 1)
            {
                v = temp[n];
                base.push_back(v);
                all_zero = 0;
                break;
            }
        }

        if(all_zero == 1) { continue; }

        // i 番目を 0 にする (v に当たるベクトルは 0 になる)
        for(int n = 0; n < static_cast<int>(temp.size()); ++n)
        {
            if(temp[n][i] == 1)
            {
                for(int j = 0; j < dim; ++j)
                {
                    temp[n][j] = (temp[n][j] + v[j]) % 2;
                }
            }
        }

        // i 番目を 0 にする base 編
        for(int n = 0; n < static_cast<int>(base.size()-1); ++n)
        {
            if(base[n][i] == 1)
            {
                for(int j = 0; j < dim; ++j)
                {
                    base[n][j] = (base[n][j] + v[j]) % 2;
                }
            }
        }

    }

}

bool include_subspace(vector<vector<int>> &base, vector<int> vec)
{
    const int dim = 64;    
    vector<int> val(base.size(), 0);

    for(size_t n = 0; n < base.size(); ++n)
    {
        int i;    
        for(i = 0; i < dim; ++i)    
        {
            if((base[n][i] == 1))
            {
                break;    
            }
        }

        if(vec[i] == 1)
        {
            val[n] = 1;
        }
    }

    vector<int> vec2(dim, 0);
    for(size_t n = 0; n < base.size(); ++n)
    {
        if(val[n] == 1)    
        {
            for(int j = 0; j < dim; ++j)
            {
                vec2[j] = (vec2[j] + base[n][j])%2;
            }
        }
    }

    for(size_t i = 0; i < dim; ++i)    
    {
        if(vec[i] != vec2[i])
        {
            return false;    
        }
    }

    return true;    
}


void main_proc(void)
{
    int N;     //     
    vector<size_t> A;
    vector<int> S;        // 0 1 ビット列

    load(N, A, S);

    vector<vector<int>> vec(N);
    for(int n = 0; n < N; ++n)    
    {
        num2vec(A[n], vec[n]);
    }

    vector<vector<int>> vec0, vec1;
    for(int n = 0; n < N; ++n)
    {
        if(S[n] == 0)
        {
            vec0.push_back(vec[n]);
        }
        else
        {
            vec1.push_back(vec[n]);
        }
    }

    vector<vector<int>> base0, base1;

    make_base(vec0, base0);
    make_base(vec1, base1);    

    for(size_t i = 0; i < base1.size(); ++i)
    {
        if(!include_subspace(base0, base1[i]))
        {
            cout << 1 << endl;
            return;
        }
    }

    cout << 0 << endl;    

}

int main()
{
    int T;     // 回数
    cin >> T;

    for(int t = 0; t < T; ++t)
    {
        main_proc();
    }

    return 0;    
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
#define int ll
#define tr(c,i) for(auto i=(c).begin(); i != (c).end(); i++)
#define rep(i,n) for(int i=0;i<(n);i++)
#define forup(i,a,b) for(int i=(a);i<=(b);i++)

int bitsz(int n) {
	for (int i = 0; i < 63; ++i)
	{
		if((n&(1ll<<i))) return 1ll<<i;
	}
	// int i = -1;
	// while (n) n >>= 1, i++;
	// return 1ll<<i;
}

bool solve(vector<int>&v, int desired) {
	// cout<<"desired = "<<desired<<" : ";
	// for(auto it:v) cout<<it<<" ";
	// cout<<endl;
	if(v.empty()) return 0;
	int n, t;
	set<int, greater<int> > s, w;
	for (auto it:v) {
		s.insert(it);
	}
	// Guassian Elimination!
	while (!s.empty()) {
		int m = *s.begin();
		s.erase(m);
		w.insert(m);
		int z = bitsz(m) - 1;
		tr (s, it) {
			t = *it;
			if (t>>z & 1) {
				s.erase(t);
				s.insert(t^m);
			}
		}
	}

	int ans= 0;

	for(auto it = w.rbegin(); it!=w.rend(); ++it){
		int curr = bitsz(*it);
		if(desired&curr) ans ^= curr;
	}

	// tr (w, it){
	// 	cout<<*it<<" ";
	// 	int curr = bitsz(*it);
	// 	if(desired&curr) ans ^= *it;
	// }
	// cout<<endl;
	// cout<<ans<<endl;
	return ans == desired;
}

