template <int T>
struct XorSpace
{
	vector <ll> bases;
	int freeNum=0;
	void add(ll x)
	{
		for(auto &basis:bases)
		{
			chmin(x,x^basis);
		}
		if(x==0)
		{
			freeNum++;
			return;
		}
		else bases.push_back(x);
	}
	bool query(ll x)
	{
		for(auto &basis:bases)
		{
			chmin(x,x^basis);
		}
		return (x==0);
	}
};
