#define rep(i, n) for(UL i = 0; i < (n); i++)

struct Problem {
public:
	UL N;
	ULL A[200];
	string S;

	void Solve() {
		UL T; scanf("%u", &T);
		while (T--) {
			scanf("%u", &N);
			rep(i, N) scanf("%llu", &A[i]);
			cin >> S;
			set<ULL> X; rep(i, N) X.insert(A[i]);
			X.insert(0);
			bool uni = false;
			rep(i, N) rep(j, N) {
				if (X.count(A[i] ^ A[j]) == 0) uni = true;
			}
			UL ans = 1;
			if (uni) {
				while (S.size()) {
					if (S.back() - '0' == ans) break;
					ans = 1 - ans;
					S.pop_back();
				}
			}
			else {
				ans = S.back() - '0';
			}
			printf("%u\n", ans);
		}
	}
};

int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}

