const double EPS = 1e-9;
const ll INF = 2; 

ll gmod(ll n)
{
    n%=2;
    if(n<0)
        n+=2;
    return n;    
}

ll gauss (vector < vector<double> > a, vector<double> & ans) {
    ll n = (ll) a.size();
    ll m = (ll) a[0].size() - 1;

    vector<ll> where (m, -1);
    for (ll col=0, row=0; col<m && row<n; ++col) {
        ll sel = row;
        for (ll i=row; i<n; ++i)
            if (abs (a[i][col]) > abs (a[sel][col]))
                sel = i;
        if (abs (a[sel][col]) < EPS)
            continue;
        for (ll i=col; i<=m; ++i)
            swap (a[sel][i], a[row][i]);
        where[col] = row;

        for (ll i=0; i<n; ++i)
            if (i != row) {
                double c = a[i][col] / a[row][col];
                for (ll j=col; j<=m; ++j)
                    a[i][j] -= a[row][j] * c, a[i][j] = gmod(a[i][j]);
            }
        ++row;
    }

    ans.assign (m, 0);
    for (ll i=0; i<m; ++i)
        if (where[i] != -1)
            ans[i] = a[where[i]][m] / a[where[i]][i];
    for (ll i=0; i<n; ++i) {
        ll sum = 0;
        for (ll j=0; j<m; ++j)
            sum += ans[j] * a[i][j], sum%=2;
        if (abs (sum - a[i][m]) > EPS)
            return 0;
    }

    for (ll i=0; i<m; ++i)
        if (where[i] == -1)
            return INF;
    return 1;
}

