ll msb(ll v){
  v = v | (v >>  1);
  v = v | (v >>  2);
  v = v | (v >>  4);
  v = v | (v >>  8);
  v = v | (v >> 16);
  v = v | (v >> 32);
  return v ^ (v >> 1);
}

vector<ll> elimination_F2(vector<ll> &A){
    vector<ll> V;
    for(ll a: A){
        for(ll v: V){
            if(msb(v)&a) a ^= v;
        }
        if(a>0){
            for(ll& v: V){
                if(msb(a)&v) v ^= a;
            }
            V.push_back(a);
            sort(V.rbegin(), V.rend());
        }
    }
    return V;
} 

