      std::copy(begin, end, std::back_inserter(buffer));

      std::vector<i64>::iterator it1;
      for (it1 = buffer.begin(); it1 != buffer.end(); ++it1) {
        std::iter_swap(it1, std::max_element(it1, buffer.end()));
        if (*it1 == 0) break;
        const i64 threshold = tools::pow2(tools::floor_log2(*it1));
        for (auto it2 = std::next(it1); it2 != buffer.end(); ++it2) {
          if (*it2 >= threshold) {
            *it2 ^= *it1;
          }
        }
      }
      return std::distance(buffer.begin(), it1);
    };

    std::cout << (dim(zero_it, A.end()) < dim(one_it, A.end()) ? '1' : '0') << '\n';
  }
  return 0;
}

