vector<ll> vecrank(vector<ll> v) {
    int n = (int)v.size();
    vector<bool> pivot(n, false);
    REP(i, 60) {
        REP(j, n) {
            if(pivot[j]) continue;
            bitset<60> bs(v[j]);
            if(bs[i] == 1) {
                pivot[j] = true;
                REP(k, n) {
                    if(pivot[k]) continue;
                    bitset<60> bs2(v[k]);
                    if(bs2[i] == 1) v[k] = v[k] ^ v[j];
                }
                break;
            }
        }
    }
    vector<ll> ret;
    REP(i, n) if(pivot[i]) ret.push_back(v[i]);
    return ret;
}

