void add(long long u) {
    for (int i = LOG - 1; i >= 0; i--) {
        if (u >> i & 1) {
            if (!basis[i]) {
                basis[i] = u;
                return;
            }
            u ^= basis[i];
        }
    }
}

bool check(long long u) {
    for (int i = LOG - 1; i >= 0; i--) {
        if (u >> i & 1) {
            if (!basis[i]) {
                return 0;
            }
            u ^= basis[i];
        }
    }
    return u == 0;
}

