template<int L>
struct GaussJordan_Binary {
    using Row = bitset<L>;
    vector<Row> B;
    void gauss_jordan() {
        int n = B.size();
        for (int i = 0, j = 0; i < n; ++i, ++j) {
            for (int k = 0; j < L; ++j) {
                for (k = i; k < n; ++k) if (B[k][j]) break;
                if (k == n) continue;
                else if (k != i) swap(B[i], B[k]);
                break;
            }
            if (j == L) break;
            for (int k = 0; k < n; ++k) if (k != i && B[k][j]) B[k] ^= B[i];
        }
    }
};

