        ret = (ret << 3) + (ret << 1) + (c ^ 48);
    }
    return pos ? ret : -ret;
}

size_t reads(int *s) {
    using namespace _buff;
    size_t ret = 0;
    char c = getc();
    for (; c != '0' && c != '1'; c = getc()) {
        assert(~c);
    }
    for (; c == '0' || c == '1'; c = getc()) {
        s[ret++] = c ^ 48;
    }
    return ret;
}

using u64 = unsigned long long;

const size_t L = 60;

struct Basis {
    u64 b[L];

    Basis() {
        memset(b, 0, sizeof b);
    }

    void add(u64 x) {
        for (size_t i = L; i--; ) {
            if (x >> i & 1) {
                if (!b[i]) {
                    b[i] ^= x;
                    return;
                }
                x ^= b[i];
            }
        }
    }

    bool query(u64 x) {
        for (size_t i = L; i--; ) {
            if (x >> i & 1) {
                x ^= b[i];
            }
        }
        return !x;
    }
};

void add(Basis &b, u64 x) {
    static u64 bas[L];
    memcpy(bas, b.b, sizeof b.b);
    for (size_t i = 0; i < L; ++i) {
        b.add(bas[i] ^ x);
    }
}

const size_t N = 2E2 + 5;

u64 a[N]; int b[N];

void solve() {
    int n = read();
    generate_n(a, n, read);
    assert(n == (int) reads(b));
    reverse(a, a + n); reverse(b, b + n);
    Basis bas;
    for (int i = 0; i < n; ++i) {
        if (b[i]) {
            if (!bas.query(a[i])) {
                puts("1"); return;
            }
        } else {
            add(bas, a[i]);
        }
    }
    puts(bas.query(0) ? "0" : "1");
}

