vll & xor_gauss(vll & a) {
    int cur = 0;
    int n=a.size();
    for(long long mask = 1LL << 62; mask && cur < n; mask >>= 1) {
        for(int i = cur; i < n; i++) {
            if(mask & a[i]) {
                swap(a[i], a[cur]);
                break;
            }
        }
        if(!(mask & a[cur]))
            continue;
        for(int i = 0; i < n; i++)
            if(i != cur && (mask & a[i]))
                a[i] ^= a[cur];
        cur++;
    }
    vll b;
    for(auto x:a) if(x) b.pb(x);
    a=b;
    return a;
}

