  for(int i = MAXLOG - 1; i >= 0; i--)
    if(!((res >> i) & 1) && base[i]) res ^= base[i];
  return res;
 }

  bool possible(int val) {
   for(int i = MAXLOG - 1; i >= 0; i--)
    if(((val >> i) & 1) && base[i]) val ^= base[i];
   return (val == 0);
  }
};

