bool check(ll idx, ll bit , ll x)
{
    if(bit<0)
        return true;
    assert(jitchi[idx][bit][x]>=0 && jitchi[idx][bit][x]<=1);
    return jitchi[idx][bit][x];
}
ll solve(ll idx,ll bit, ll x )
{
    assert(x>=0);
    assert(x<=1);
    if(idx==n)
    {
        return x==0;
    }
    ll &ret = dp[idx][bit][x];
    if(ret!=-1)
    {
        return ret;
    }
    ll ache =0;
    if(a[idx]&(1ll <<bit))
    {
        ache = 1;
    }
    if(s[idx]=='1')
    {
        ll ans = 1;
        if(check(idx,bit-1,1)&& !solve(idx+1,bit, x^ache)){
            ans =0;
            jitchi[idx][bit][1] = 1;
        }
        else{
            jitchi[idx][bit][1] = 0;
        }
        if(check(idx,bit-1,0)&& !solve(idx+1,bit, x))
        {
            ans =0;
            jitchi[idx][bit][0] = 1;
        }
        else{
            jitchi[idx][bit][0] = 0;
        }
        return ret = ans;
    }
    else
    {
        ll ans = 0;
        if(check(idx,bit-1,1)&& solve(idx+1,bit, x^ache)){
            ans =1;
            jitchi[idx][bit][1] = 1;
        }
        else{
            jitchi[idx][bit][1] = 0;
        }
        if(check(idx,bit-1,0)&& solve(idx+1,bit, x))
        {
            ans =1;
            jitchi[idx][bit][0] = 1;
        }
        else{
            jitchi[idx][bit][0] = 0;
        }
        return ret = ans;
    }
}
