bool dp(ll x, int i, V<ll> a, string s, map<P, int> mp) {
	if (mp[P(i, x)])return mp[P(i, x)] - 1;
	if (i == 0) {
		if (x)return false;
		else return true;
	}

	ll xx = x ^ a[i - 1];
	int re;
	if (s[i - 1] - '0') {
		if (dp(x, i - 1, a, s, mp) || dp(xx, i - 1, a, s, mp))re = 1;
		else re = 0;
	}
	else {
		if (dp(x, i - 1, a, s, mp) && dp(xx, i - 1, a, s, mp))re = 1;
		else re = 0;
	}

	mp[P(i, x)] = re + 1;
	return re;

}


