int alphabeta(int idx, long long current){
    if(idx == N) {
        return current == 0 ? 0:1;
    }
    int isMaxi = person[idx] == '1';

    if(memo.find(make_pair(current, idx)) != memo.end()) {
        return memo[make_pair(current,idx)];
    }
    int res = !isMaxi;
    int it = 0;
    while((!isMaxi) == res && it != 2) {
        it++;
        if(isMaxi) {
            int tmp = alphabeta(idx+1, current);
            res = max(res, tmp);
        } else {
            int tmp = alphabeta(idx+1, current);
            res = min(res, tmp);

        }
        current ^= tab[idx];
    }
    memo[make_pair(current,idx)]= res;
    return res;
}


