	for (int i = 29; i >= 0;i--){
		if(x&(1<<i)){
			if(!p[id][i]){
				p[id][i]=x;
				pos[id][i]=cao;
				return;
			}
			if(pos[id][i]<cao){
				swap(p[id][i],x);
				swap(pos[id][i],cao);
			}
			x^=p[id][i];
		}
	}
}
int queryMAX(int l,int r){//查询区间任意组合最大值 
	int maxx=0;
	for (int i = 29; i >= 0;i--){
		if(pos[r][i]>=l&&(maxx^p[r][i])>maxx){
			maxx^=p[r][i];
		}	
	}
	return maxx;
}
int queryMIN(int l,int r){//查询区间任意组合最小值 
	for (int i = 0; i <= 29;i++){
		if(pos[r][i]>=l&&p[r][i]){
			return p[r][i];
		}	
	}
	return 0;
}
bool querycunzai(int l,int r,int k){//查询区间任意组合的值是否有k 
	for (int i = 29; i >= 0;i--){
		if(pos[r][i]>=l&&(k>>i)){
			k^=p[r][i];
		}	
	}
	return k==0;
}

