void add_to_basis (ll vec, vector<ll> &basis) {
  // invariant: smallest set bit of basis[i] is i
  for (int i = 0; i < MAX_LG; i++) {
    if (vec & 1LL << i) {
      if (basis[i] != -1) {
        vec ^= basis[i];
      }
    }
  }

  if (vec == 0) return;

  int idx = -1;
  for (int i = 0; i < MAX_LG; i++) {
    if (vec & 1LL << i) {
      idx = i;
      break;
    }
  }
  basis[idx] = vec;
}

bool in_span (ll vec, vector<ll> &basis) {
  for (int i = 0; i < MAX_LG; i++) {
    if (vec & 1LL << i) {
      if (basis[i] != -1) {
        vec ^= basis[i];
      }
    }
  }
  return vec == 0;
}

