int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<lint> a(n);
        for (int i = 0; i < n; ++i) {
            cin >> a[i];
        }
        string s;
        cin >> s;
        int ns = s.size();
        if (s[ns - 1] == '1') {
            cout << 1 << "\n";
            continue;
        }
        vector<lint> as;
        vector<lint> bs;
        int prev = 1;
        for (int i = 0; i < n; ++i) {
            if (s[i] == '1') {
                if (prev == 0) {
                    // hakidashi
                    vector<bool> used(bs.size(), false);
                    for (lint i = 62; i >= 0; --i) {
                        int idx = -1;
                        for (int j = 0; j < (int)bs.size(); ++j) {
                            if (!used[j] && (bs[j] >> i & 1)) {
                                idx     = j;
                                used[j] = true;
                                break;
                            }
                        }
                        if (idx != -1) {
                            for (int j = 0; j < (int)bs.size(); ++j) {
                                if ((bs[j] >> i & 1) && j != idx) {
                                    bs[j] ^= bs[idx];
                                }
                            }
                            for (int j = 0; j < (int)as.size(); ++j) {
                                if (as[j] >> i & 1) {
                                    as[j] ^= bs[idx];
                                }
                            }
                        }
                    }
                    bs.clear();
                }
                as.push_back(a[i]);
                prev = 1;
            } else {
                bs.push_back(a[i]);
                prev = 0;
            }
        }
        if (prev == 0) {
            vector<bool> used(bs.size(), false);
            for (lint i = 62; i >= 0; --i) {
                int idx = -1;
                for (int j = 0; j < (int)bs.size(); ++j) {
                    if (!used[j] && (bs[j] >> i & 1)) {
                        idx     = j;
                        used[j] = true;
                        break;
                    }
                }
                if (idx != -1) {
                    for (int j = 0; j < (int)bs.size(); ++j) {
                        if ((bs[j] >> i & 1) && j != idx) {
                            bs[j] ^= bs[idx];
                        }
                    }
                    for (int j = 0; j < (int)as.size(); ++j) {
                        if (as[j] >> i & 1) {
                            as[j] ^= bs[idx];
                        }
                    }
                }
            }
            // hakidashi
        }
        int ret = 0;
        for (auto &x : as) {
            if (x != 0) {
                ret = 1;
                break;
            }
        }
        cout << ret << "\n";
    }
    return 0;
}

