    vector<bool> used(N,false);
    for ( int b = 62; b >= 0; b-- ) {
        ll bb = 1LL << b;
        for ( int i = 0; i < N; i++ ) {
            if ( S[i] == '0' && !used[i] && ((A[i] & bb) != 0))  {
                used[i] = true;
                for ( int j = 0; j < N; j++ ) {
                    if ( j == i ) continue;
                    if ( A[j] & bb ) {
                        A[j] ^= A[i];
                    }
                }
            } else {
                if ( S[i] == '1' && ((A[i] & bb) != 0) ) return 1;
            }
        }
    }
    return 0;
}

