            vector<ll> b(a.begin() + l, a.begin() + r);
            xor_bases(b);
            if (c == '1') {
                copy(ALL_OF(b), back_inserter(r1));
                xor_bases(r1);
                if (!issafe(r0, r1)) {
                    ans = 1;
                    break;
                }
            } else {
                copy(ALL_OF(b), back_inserter(r0));
                xor_bases(r0);
            }
            r = l;
        }
        say(ans);
    }

