		cin >> rounds;
		for (int j = 0; j < rounds; j++)
		{
			ll input;
			cin >> input;
			inputs.push_back(input);
		}
		ll output = 0;
		string orderofPlay;
		cin >> orderofPlay;

		vector<ll> ZerosVector;
		for (int j = 0; j < rounds; j++)
		{
			int person = orderofPlay[j] - '0';
			if (person == 0)
			{
				ZerosVector.push_back(inputs[j]);
			}
		}

		for (int j = 0; j < rounds; j++)
		{
			int person = orderofPlay[j] - '0';
			if (person == 0)
			{
				if (output == inputs[j])
				{
					output ^= inputs[j];
				}
			}
			else
			{
				if (output != inputs[j])
				{
					bool found = false;
					for (auto it : ZerosVector)
					{
						ll val = output ^ inputs[j];
						if (it == val)
						{
							found = true;
							break;
						}
					}
					if (!found)
						output ^= inputs[j];
				}
			}
		}
