    bool good = true;
    for (int j = 0; j < (int) c.size(); j++) {
      ull target = c[j];
      ull now = 0;
      auto b_temp = b;
      for (int k = 63; k >= 0; k--) {
        int pivot = -1;
        for (int l = 0; l < (int) b_temp.size(); l++) {
          if (pivot == -1) {
            if (b_temp[l] & (1ULL << k)) {
              pivot = l;
              if ((target & (1ULL << k)) != (now & (1ULL << k))) {
                now ^= b_temp[pivot];
              }
            }
          }
          else {
            if (b_temp[l] & (1ULL << k)) {
              b_temp[l] ^= b_temp[pivot];
            }
          }
        }
