class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    int N;
    vector<ull> A;
    string S;

    bool input() {
        is >> N;
        A.resize(N);
        is >> A >> S;
        return !!is;
    }

    vector<ull> base(vector<ull>& x){
        for (int i = 0; i < x.size(); ++i) {
            sort(ALL(x));
            for (int j = 0; j < x.size(); ++j) {
                if(j == i) continue;
                if((x[j] ^ x[i]) < x[j]){
                    x[j] ^= x[i];
                }
            } // end j
        } // end i
        sort(ALL(x));

        x.erase(unique(ALL(x)), x.end());

        return x;
    }

    bool can(const vector<ull>&x, ull k){
        for (auto i : x) {
            if(k & i){
                k ^= i;
            }
        } // end i
        return k == 0;
    }

    void solve(){
        int r, l;
        l = r = N;
        vector<ull> b;
        while(l-- > 0){
            if(S[l] == '1'){
                if(!can(b, A[l])){
                    os << 1 << endl;
                    return;
                }
            }
            else {
                b.push_back(A[l]);
                base(b);
            }
        }
        os << 0 << '\n';
    }

    void run();
};

int main(int argc, char *argv[]) {
    cin.tie(nullptr);
