	int w=cnt;
	for(int i=0;i<H;++i)
		for(int j=cnt;j<N;++j)
			m[i][j]=o[i][j];
	while(w<N-1&&h<H){
		for(int i=h;i<H;++i)
			if(m[i][w]){swap(h,i);break;}
		if(!m[h][w]){++w;++h;continue;}
		for(int i=h+1;i<H;++i)
			if(m[i][w])
				add(h,i);
		++w;++h;
	}
}

