int msb(uint64_t x) {
  if(x < (1ULL<<32)) return msb32((uint32_t)x);
  return 32 +msb((uint32_t)(x>>32));
}

struct bit_base {
  uint64_t bases[64];
  bit_base() { std::fill_n(bases, 64, (uint64_t)0); }
  uint64_t add(uint64_t n) {
    int x = msb(n);
    while(bases[x] > 0) {
      n ^= bases[x];
      if(n == 0) return 0;
      x = msb(n);
    }
    return bases[x] = n;
  }
};

