vector<ll> basis(d);

void insertVector(ll mask) {
	for (int i = 0; i < d; i++) {
		if ((mask & (1ll << i)) == 0) continue;
		if (!basis[i]) { 
			basis[i] = mask;
			return;
		}
		mask ^= basis[i];
	}
}

bool check(ll val) {
	for (int i = 0; i < d; ++i) {
		if ((val & (1ll << i)) == 0) continue;
		if (!basis[i]) return false;
		val ^= basis[i];
	}
	return true;
}

