long msb(long a){
    long high;
    for(high = 0; (1l << high) < LINF; high++){
        if(!(a & ((LINF-1)-((1l << high) - 1)))){
            break;
        }
    }
    return high;
}

std::vector<long> tri_first(std::vector<long> v){
    //printf(" v.size %ld\n", v.size());
    if(v.size() == 1){
        return v;
    }
    std::sort(v.begin(), v.end());
    long high = msb(v[v.size() - 1]);
    if(high == 0){
        return v;
    }
    //printf("  high %ld\n", high);
    for(long i = 0; i < v.size()-1; i++){
        if(v[i] & (1l << (high-1))){
            v[i] ^= v[v.size() - 1];
        }
    }
    long top = v[v.size() - 1];
    v.pop_back();
    v = tri_first(v);
    v.push_back(top);
    return v;
}

std::vector<long> tri_second(std::vector<long> v){
    std::sort(v.begin(), v.end());
    for(long i = v.size() - 1; i >= 0; i--){
        long high = msb(v[i]);
        if(high == 0){
            continue;
        }
        for(long j = i + 1; j < v.size(); j++){
            if(v[j] & (1l << (high - 1))){
                v[j] ^= v[i];
            }
        }
    }
    return v;
}

