int main(/* int argc, char *argv[] */) {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  cout << setprecision(20);

  const ll msize = 60;

  // the index of the most significant bit
  auto msbi = [](ll x) -> ll {
    return 63 - __builtin_clzll(x);
  };

  auto solve = [&]() -> ll {
    ll N; cin >> N;
    vector<ll> A(N);
    for (ll i = 0; i < N; i++) cin >> A[i];
    string S; cin >> S;
    reverse(A.begin(), A.end());
    reverse(S.begin(), S.end());

    // basis of vector space gen. by {A_i, A_i+1, ..., A_N}
    // for each bit j, there is at most one v in basis such that msbi(v) == j
    vector<ll> basis;

    // basis[m2i[j]] is the index of the basis element v that satisfies msbi(v) == j
    vector<ll> m2i(msize, -1);  

    // If x is in the subspace generated by basis, returns false.
    // Otherwise, extend basis so that x is in space gen. by basis, and returns true.
    auto extend = [&](ll x) -> bool {
      while (true) {
	if (x == 0) return false;
	ll m = msbi(x);
	ll j = m2i[m];
	if (j < 0) {
	  m2i[m] = basis.size();
	  basis.push_back(x);
	  return true;
	}
	x ^= basis[j];
      }
    };

    for (ll i = 0; i < N; i++) {
      bool b = extend(A[i]);
      if (S[i] == '1' && b) return 1;
    }
    return 0;
  };

  ll T; cin >> T;
  for (ll _t = 0; _t < T; _t++) cout << solve() << "\n";

  return 0;
}

