const lint MOD = 1e9 + 7, INF = 1e18;
const double eps = 1e-8;

set<lint> ablest;

lint T, N, A;
vector<lint> arr;
string s;

lint func(vector<vector<lint>> A) {
	const int n = A.size(), m = A[0].size();
	int r = 0;
	for (int i = 0; r < n && i < m; ++i) {
		int pivot = r;
		for (int j = r + 1; j < n; ++j)
			if (abs(A[j][i]) > abs(A[pivot][i])) pivot = j;
		swap(A[pivot], A[r]);
		if (abs(A[r][i]) < eps) continue;
		for (int k = m - 1; k >= i; --k)
			A[r][k] /= A[r][i];
		for (int j = r + 1; j < n; ++j)
			for (int k = i; k < m; ++k)
				A[j][k] -= A[r][k] * A[j][i];
		++r;
	}
	return r;
}

