typedef long long LL;

bool possible(LL t, vector<LL> a) {
	if (a.empty()) return t == 0;
	LL x = 0;
	int st = 0;
	int sz = (int)a.size();
	sort(a.rbegin(), a.rend());
	for (LL b = 60; b >= 0; --b) {
		LL f = 1LL << b;
		if (!(a[st] & f)) continue;
		for (int i = 0; i < sz; ++i) {
			if (i != st && (a[i] & f) != 0) a[i] ^= a[st];
		}
		++st;
		if (st >= sz) break;
		sort(a.rbegin(), a.rbegin() + sz - st);
	}
	for (LL b = 60; b >= 0; --b) {
		LL f = 1LL << b;
		if ((f & t) != 0 && (f & x) == 0) {
			for (int i = 0; i < sz; ++i) {
				if (a[i] & f) {
					x ^= a[i];
					break;
				}
			}
		}
	}
	return t == x;
}

