typedef unsigned long long ull;

int solve(int n, string s, vector<ull> a) {
    if (s[n-1] == '1') return 1;

    // all 0
    bool allZero = true;
    for (int i=0; i<n; i++) if (s[i] != '0') {
        allZero = false;
        break;
    }
    if (allZero) return 0;

    set<ull> a0, a1;
    for (int i=0; i<n; i++) {
        int who = s[i]-'0';
        ((who == 0) ? a0 : a1).insert(a[i]);
    }
    if (a1.size() > a0.size()) return 1; // greedy

    // s end at zero
    unordered_set<ull> v0;
    v0.insert(0);
    for (int i=0; i<n; i++) {
        int who = s[i]-'0';
        if (who == 0) {
            vector<ull> n0;
            for (auto v : v0) n0.push_back(v ^ a[i]);
            for (auto n : n0) v0.insert(n);
        }
    }

    unordered_set<ull> v1;
    v1.insert(0);
    for (int i=0; i<n; i++) {
        int who = s[i]-'0';
        if (who == 1) {
            vector<ull> n1;
            for (auto v : v1) {
                if (v0.find(v ^ a[i]) == v0.end()) {
                    // cerr << "witness: " << (v ^ a[i]) << endl;
                    return 1;
                }
                else n1.push_back(v ^ a[i]);
            }
            for (auto n : n1) v1.insert(n);
        }
    }
    return 0;
}

