int solve() {
  int N; cin >> N;
  vector<LL> A(N); cin >> A;
  string S; cin >> S;

  set<LL> X, Y;  // X: 0, Y: 1
  int mask = ~0LL;
  for (int i = N - 1; i >= 0; --i) {
    if (S[i] == '0') {
      LL a = A[i] & mask;
      if (X.count(A[i])) continue;

      for (LL x : X) {
        LL v = (x ^ A[i]) & mask;
        if (__builtin_popcount(v) == 1) {
          bitset<128> b(v);
          int i = 0;
          for (; i < 128; ++i) {
            if (b.test(i)) break;
          }
          mask = mask ^ (1 << i);
        }
        X.insert(v);
      }
      X.insert(a);
    } else {
      LL a = A[i] & mask;
      if (!X.count(a)) return 1;
    }
  }
  return 0;
}

int main() {
  int N; cin >> N;
  for (int i = 0; i < N; ++i) {
    cout << solve() << endl;;
  }
}

