const int MAX_ROW = 200; // to be set appropriately
const int MAX_COL = 60; // to be set appropriately
struct BitMatrix {
    int n, m;
    bitset<MAX_COL> val[MAX_ROW];
    BitMatrix(int n_ = 1, int m_ = 1) {n = n_; m = m_;}
    inline bitset<MAX_COL>& operator [] (int i) {return val[i];}
    inline friend ostream& operator << (ostream& s, BitMatrix M) {
        s << endl;
        for (int i = 0; i < M.n; ++i) {
            for (int j = 0; j < M.m; ++j) s << M.val[i][j];
            s << endl;
        }
        return s;
    }
};

inline BitMatrix operator * (BitMatrix A, BitMatrix B) {
    BitMatrix R(A.n, B.m);
    BitMatrix tB(B.m, B.n);
    for (int i = 0; i < tB.n; ++i) for (int j = 0; j < tB.m; ++j) tB[i][j] = B[j][i];
    for (int i = 0; i < R.n; ++i) for (int j = 0; j < R.m; ++j) R[i][j] = (A[i] & tB[j]).any();
    return R;
}

int linear_equation(BitMatrix A, vector<int> b) {
    int rank = 0;
    for (int i = 0; i < A.n; ++i) { A[i][A.m] = b[i]; }

    for (int i = 0; i < A.m; ++i) {
        int pivot = -1;
        for (int j = rank; j < A.n; ++j) {
            if (A[j][i]) {
                pivot = j;
                break;
            }
        }
        if (pivot != -1) {
            swap(A[pivot], A[rank]);
            for (int j = 0; j < A.n; ++j) if (j != rank && A[j][i]) A[j] ^= A[rank];
            ++rank;
        }
    }

    for (int i = rank; i < A.n; ++i) if (A[i][A.m]) return -1; // 解なし   
    return rank;
};
void solve(){
    cin >> N;
    for(int i = 0; i < N; i++){
        cin >> A[i];
    }
    int cnt = 0;
    cin >> S;
    BitMatrix BM(60, N);
    for(int i = N-1; i >= 0; i--){
        if(S[i] == '1'){
            vector<int> b(60);
            for(int j = 0; j < 60; j++){
                if(((ll)1<<j)&A[i]) b[j] = 1;
            }
            if(linear_equation(BM, b) == -1){
                cout << 1 << endl;
                return;
            }
        }else if(S[i] == '0'){
            // cout << i << endl;
            for(int j = 0; j < 60; j++){
                if(((ll)1<<j)&A[i]){
                    BM[j][cnt] = 1;
                } 
            }
            cnt++;
        }
    }
    cout << 0 << endl;
}

