#include <bits/stdc++.h>


using namespace std;


int solve(int n, vector <long long> &a, string &s) {
    const int BASE = 61;
    vector <long long> basis(BASE, -1);

    auto addToBasis = [&](long long v) {
        int lead = -1;

        for (int i = BASE - 1; i >= 0; i--) if (v & (1LL << i)) {
            if (basis[i] != -1) {
                v ^= basis[i];
            } else if (lead == -1) {
                lead = i;
            }
        }

        if (lead != -1) {
            basis[lead] = v;
        }
    };

    auto canBeObtained = [&](long long v) {
        for (int i = BASE - 1; i >= 0; i--) if (v & (1LL << i)) {
            if (basis[i] != -1) {
                v ^= basis[i];
            } else {
                return false;
            }
        }

        return true;
    };

    for (int i = n - 1; i >= 0; i--) {
        if (s[i] == '0') {
            addToBasis(a[i]);
        } else {
            if (!canBeObtained(a[i])) {
                return 1;
            }
        }
    }

    return 0;
}


