    vector<ll> a(n);
    for (ll i = 0; i < n; ++i)
    {
      cin>>a[i];
    }
    cin>>s;
    int cnt=0;
    for (int i = 0; i < n; ++i)
    {
      if(s[i]=='0') cnt++;
    }
    vector<vector<ll>> zero(cnt,vector<ll>(64,0));
    vector<vector<ll>> one(n-cnt,vector<ll>(64,0));
    int pos_zero=0,pos_one=0;
    for (ll i = 0; i < n; ++i)
    {
      if(s[i]=='0')
      {
        for (ll j = 0; j < 64; ++j)
        {
          zero[pos_zero][j]+=((a[i]>>j)&1LL);
        }
        pos_zero++;
      }
      else
      {
        for (ll j = 0; j < 64; ++j)
        {
          one[pos_one][j]+=((a[i]>>j)&1LL);
        }
        pos_one++;
      }
    }
    bool flag=false;

    for (int i = 0; i < one.size(); ++i)
    {
      flag=true;
      for (int j = 0; j < zero.size(); ++j)
      {
        int inner_prod=0;
        for (int k = 0; k < 64; ++k)
        {
          inner_prod+=one[i][k]*zero[j][k];
        }
        if(inner_prod!=0) flag=false;
      }
      if(flag) break;
    }
