class bipertite_matching{
    private:
        int siz;
        vector<vector<int>> g;
        vector<bool> done;
        vector<int> match;
    public:
        bipertite_matching(int n){
            siz = n;
            g.resize(n);
            done.resize(n);
            match.resize(n,-1);
        }
        void add_edge(int u,int v){
            g[u].push_back(v);
            g[v].push_back(u);
        }
        bool dfs(int v){
            done[v] = true;
            for(int u:g[v]){
                int w = match[u];
                if (w < 0 || (!done[w] && dfs(w))){
                    match[v] = u;
                    match[u] = v;
                    return true;
                }
            }
            return false;
        }
        int bipartiteMatching(){
            int res = 0;
            rep(i,siz){
                if (match[i] < 0){
                    done.assign(siz,false);
                    if (dfs(i)) res++;
                }
            }
            return res;
        }
};
