void add(LL mask) {
	FOD(i, 61, 0) {
		if ((mask & ((LL)(1) << i))) {
			if (!c[i]) {
				c[i] = mask;

				FOD(j, i - 1, 0) if (c[i] & ((LL)(1) << j)) c[i] ^= c[j];
				FOE(j, i + 1, 61) if (c[j] & ((LL)(1) << i)) c[j] ^= c[i];

				return;
			}

			mask ^= c[i];
		}
	}
}

bool verify(LL u) {
	FOD(i, 61, 0) if (u & ((LL) 1 << i)) u ^= c[i];
	return (u == 0);
}	

