	scanf("%d", &n);

	FOE(i, 1, n) scanf("%lld", &a[i]);

	cin >> s;
	FOE(i, 1, n) b[i] = (s[i - 1] == '0' ? 0 : 1);
	FOE(i, 0, 99) c[i] = 0;

	FOD(i, n, 1) {
		if (b[i] == 1) {
			if (!verify(a[i])) {
				printf("1\n");
				return;
			}
		} else {
			add(a[i]);	
		}
	}

	printf("0\n");
}

