string to_string(queue<T> q)
{
  auto temp = queue<T>{};
  stringstream s;
  s << "queue{";
  while (!q.empty())
  {
    auto top = q.front();
    s << to_string(top) << ", ";
    q.pop();
    temp.push(top);
  }
  s << "}";

  while (!temp.empty())
  {
    auto top = temp.front();
    temp.pop();
    q.push(top);
  }

  return s.str();
}

