int gaussian(int m){
    int r = 0;
    for(int c = 0; c < 64; c++){
        int p = -1;
        for(int i = r; i<m; i++){
            if(bt(c)&sys[i]){
                p = i;
                break;
            }
        }
        if(p == -1) continue;
        if(p != r){
            swap(sys[p], sys[r]);
            swap(ind[p], ind[r]);
        }
        for(int i = 0; i<m; i++){
            if(i == r || !(bt(c)&sys[i])) continue;
            sys[i] ^= sys[r];
        }
        r++;
    }
    return r;
}

