        if(b & 1)ans = 1LL * ans * a % mod;
        a = 1LL * a * a % mod;
        b >>= 1;
    }
    return ans;
}
int pow(int a, ll b, int c){
    int ans = 1;
    while(b){
        if(b & 1)ans = 1LL * ans * a % c;
        a = 1LL * a * a % c;
        b >>= 1;
    }
    return ans;
}

unordered_map<ll, int> dp[202];
ll b[202], a[202];
char s[202];
int solve(int x, int n, ll v, ll a[]){
  if(dp[x].count(v))return dp[x][v];
  if(x == n-1){
    if(v == 0 || v == a[x])return dp[x][v] = 0;
    return dp[x][v] = 1;
  }
  if(s[x] == '1'){
    int p = solve(x+1, n, v, a);
    if(p) return dp[x][v] = 1;
    int q = solve(x+1, n, v ^ a[x], a);
    if(q)return dp[x][v] = 1;
    return dp[x][v] = 0;
  }
  else{
    int p = solve(x+1, n, v, a);
    if(p == 0)return dp[x][v] = 0;
    int q = solve(x+1, n, v ^ a[x], a);
    if(q == 0)return dp[x][v] = 0;
    return dp[x][v] = 1;
  }
}
ll f[61], h[61];
void solve(vector<ll> &v, ll f[]){
  rep(i, 0, 60)f[i] = 0;
  sort(all(v));
  for(auto &x : v){
    ll w = x;
    rep(i, 0, 60)if(f[i] != 0 && (w>>i&1)){
      w ^= f[i];
    }
    rep(i, 0, 60)if(!f[i] && (w>>i&1)){
      f[i] = w;
      break;
    }
  }
}
int main() {
  int ca = 0, T, i, j, k, m, n, K;
  scanf("%d", &T);
  while(T--){
    scanf("%d", &n);
    ll mx = 0;
    rep(i, 0, n)scanf("%lld", &b[i]), Max(mx, b[i]);
    per(i, 0, 60)if(mx >> i & 1){
      K = i+1;
      break;
    }
    scanf("%s", s);
    if(s[n-1] == '1'){
      puts("1");
      continue;
    }
    int ans = 0;
    rep(i, 0, K){
      rep(j, 0, n)dp[j].clear();
      rep(j, 0, n)a[j] = b[j] >> i & 1;
      if(solve(0, n, 0, a)){
        ans = 1;
        break;
      }
    }
    if(ans){
      puts("1");
      continue;
    }
    vector<ll> v, w;
    rep(i, 0, n)if(s[i] == '1'){
      v.pb(b[i]);
    }
    else w.pb(b[i]);
    solve(v, f);
    solve(w, h);
    rep(i, 0, K)if(f[i] != h[i]){
      ans = 1;
      break;
    }
    puts(ans ? "1" : "0");
  }
}

