//bit.ver
//rankを返す
int Gaussian_elimination(mat &A) {
	if (A.empty())return 0;
	int n = A.size(); int m = A[0].size();
	int le = 0;
	rep(j, m) {
		Rep(i, le, n) {
			if (A[i][j]) {
				swap(A[le], A[i]);
				Rep(i2, le + 1, n) {
					if (A[i2][j]) {
						rep(k, m) {
							A[i2][k] ^= A[le][k];
						}
					}
				}
				le++; break;
			}
		}
	}
	return le;
}

bool can(mat &A, vector<int> s) {
	if (A.empty())return false;
	int le = 0;
	rep(j, 60) {
		if (s[j] == 0)continue;
		if (le<A.size()&&A[le][j]) {
			Rep(k, j, 60) {
				s[k] ^= A[le][k];
			}
			le++;
		}
	}
	rep(i, 60)if (s[i])return false;
	return true;
}

void solve() {
	int n; cin >> n;
	vector<ll> a(n);
	rep(i, n)cin >> a[i];
	string s; cin >> s;
	mat A;
	per(i, n) {
		vector<int> cur;
		rep(j, 60) {
			if (a[i] & (1LL << j))cur.push_back(1);
			else cur.push_back(0);
		}
		if (s[i] == '0') {
			A.push_back(cur);
		}
		else {
			Gaussian_elimination(A);
			if (!can(A, cur)) {
				cout << 1 << "\n"; return;
			}
		}
	}
	cout << 0 << "\n";
}

