const int D = 64;

bool insertVector(long long mask, vector<long long> &basis) {
	for (int i = 0; i < D; i++) {
		if ((mask & (1LL << i)) != 0) {
            if (!basis[i]) {
                basis[i] = mask;
                return true;
            }
            mask ^= basis[i];
        }
	}
    return false;
}

