bool check(vector<BS> a, const string& s, int64_t idx) {
    assert(s[idx] == '1');

    int64_t n = s.size();

    BS b = a[idx];
    for (auto i : irange(0L, 64L)) {
        BS t;
        bool found = false;
        for (auto j : irange(idx, n)) {
            if (s[j] == '1') {
                continue;
            }

            if (a[j][i]) {
                if (!found) {
                    found = true;
                    t = a[j];
                    if (b[i]) {
                        b ^= t;
                    }
                }

                a[j] ^= t;
            }
        }

        if (b[i]) {
            return false;
        }
    }

    return true;
}

bool check(const vector<BS>& a, const string& s) {
    int64_t n = s.size();
    for (auto i : irange(0L, n)) {
        if (s[i] == '1') {
            if (!check(a, s, i)) {
                return false;
            }
        }
    }

    return true;
}

