struct Hoge {
	int N;
	const vector<int>& a;
	string S;
	vector<vector<int>> memo;
	map<int,int> sel;
	Hoge(int N, const vector<int>& a, string S) : N(N), a(a), S(S), memo(N, vector<int>(2, -1)) {}
	int run(int p, int q) {
		if (p == N) return q;
		if (a[p] == 0) return run(p+1, q);
		if (memo[p][q] != -1) return memo[p][q];
		int r;
		if (S[p] == '0') {
			int r1 = run(p+1, q);
			int r2 = run(p+1, q^1);
			if (r1 == 0) sel[p] |= 1;
			if (r2 == 0) sel[p] |= 2;
			if (r1 == 0 || r2 == 0) r = 0;
			else r = 1;
		} else {
			if (run(p+1, q) == 1 || run(p+1, q^1) == 1) r = 1;
			else r = 0;
		}
		return memo[p][q] = r;
	}
};
