void solve() {
    int Q;
    cin >> Q;
    Vl A;
    using bs = bitset<202>;
    vector<bs> mat;
    while (Q--) {
        ll N;
        cin >> N;
        A.resize(N);
        for (ll i = 0; i < N; i++) {
            cin >> A[i];
        }
        string S;
        cin >> S;
        reverse(A.begin(), A.end());
        reverse(S.begin(), S.end());

        mat.assign(60, bs());

        bool is_zero = true;

        for (ll i = 0; i < N; i++) {
            if (S[i] == '0') {
                for (ll j = 0; j < 60; j++) {
                    mat[j][i] = (bool)(A[i] & (1ll << j));
                }
            }
            else {
                constexpr ll bk = 201;

                for (ll j = 0; j < 60; j++) {
                    mat[j][bk] = (bool)(A[i] & (1ll << j));
                }

                int rank = 0;
                for (ll col = 0; col < bk; col++) {
                    int pivot = -1;
                    for (ll row = rank; row < 60; ++row) {
                        if (mat[row][col]) {
                            pivot = row;
                            break;
                        }
                    }

                    if (pivot == -1) continue;
                    swap(mat[pivot], mat[rank]);
                    for (ll row = 0; row < 60; ++row) {
                        if (row != rank && mat[row][col]) mat[row] ^= mat[rank];
                    }
                    ++rank;
                }

                for (ll row = rank; row < 60; ++row) {
                    if (mat[row][bk]) {
                        is_zero = false;
                        break;
                    }
                }

                if (!is_zero) {
                    break;
                }
            }
        }

        if (is_zero)
            cout << 0 << "\n";
        else
            cout << 1 << "\n";
    }
}

