using lint = long long int;

vector<lint> convert(vector<lint> v) {
    int n = v.size(), idx = 0;
    for (int i=63; i>=0; --i) {
        bool ok = false;
        for_(j,idx,n) {
            if ((v[j] >> i) & 1) {
                ok = true;
                swap(v[idx], v[j]);
                break;
            }
        }

        if (ok) {
            for_(j,idx+1,n) {
                if ((v[j] >> i) & 1) {
                    v[j] ^= v[idx];
                }
            }
            ++idx;
        }
    }
    v.resize(idx);
    return v;
}

bool able(lint x, const vector<lint>& c) {
    int n = c.size();
    vector<int> b;
    for (int i=63; i>=0; --i) {
        int k = b.size();
        if ((c[k] >> i) & 1) b.push_back(i);
    }

    for_(i,0,n) {
        if ((x >> b[i]) & 1) x ^= c[i];
    }
    return (x == 0);
}

void solve() {
    int N;
    cin >> N;

    vector<lint> A(N);
    for_(i,0,N) cin >> A[i];

    string S;
    cin >> S;

    if (S.back() == '1') {
        puts("1");
        return;
    }

    int L = 0;
    while (L < N and S[L] == '0') ++L;

    if (L == N) {
        puts("0");
        return;
    }

    vector<vector<lint>> v[2];
    v[1].push_back(vector<lint>());

    for_(i,L,N) {
        int k = int(S[i] - '0');
        if (i > L and S[i] != S[i - 1]) v[k].push_back(vector<lint>());
        v[k].back().push_back(A[i]);
    }

    reverse(ALL(v[0]));
    reverse(ALL(v[1]));

    int m = v[0].size();
    vector<lint> cur;
    bool ok = true;
    for_(i,0,m) {
        cur.insert(cur.end(), ALL(v[0][i]));
        vector<lint> c = convert(cur);
        for (lint x : v[1][i]) ok &= able(x, c);
    }
    puts(ok ? "0" : "1");
}

int main() {
    int T;
    cin >> T;
    for_(i,0,T) solve();
}

