bool solve(vector<int>&v, int desired) {
	// cout<<"desired = "<<desired<<" : ";
	// for(auto it:v) cout<<it<<" ";
	// cout<<endl;
	if(v.empty()) return 0;
	int n, t;
	set<int, greater<int> > s, w;
	for (auto it:v) {
		s.insert(it);
	}
	// Guassian Elimination!
	while (!s.empty()) {
		int m = *s.begin();
		s.erase(m);
		w.insert(m);
		int z = bitsz(m) - 1;
		tr (s, it) {
			t = *it;
			if (t>>z & 1) {
				s.erase(t);
				s.insert(t^m);
			}
		}
	}

	int ans= desired;

	for(auto it = w.begin(); it!=w.end(); ++it){
		if(*it == 0) continue;
		int curr = bitsz(*it);
		if(ans&curr) ans ^= (*it);
	}

	return ans == 0;
}

