using lint = long long;

void bool_elimination(std::vector<lint>& mat) {
    int n = mat.size();

    for (int l = 0; l < n; ++l) {
        {
            auto& v = *std::max_element(mat.begin() + l, mat.end());
            std::swap(v, mat[l]);
        }

        const auto& v = mat[l];
        for (int i = l + 1; i < n; ++i) {
            auto u = mat[i];
            u ^= v;
            if (u < mat[i]) std::swap(u, mat[i]);
        }
    }
}

bool independent(std::vector<lint> bs, lint v) {
    bs.push_back(v);
    bool_elimination(bs);
    return bs.back() != 0;
}

