struct LIDS_F2 {
	int rsz;
	int rank = 0;
	vector<vector<int>> R;
	LIDS_F2(int row_size) : rsz(row_size), R(rsz, vector<int>(rsz)) {
		for(int i = 0; i < rsz; i++) R[i][i] = 1;
	}

	int Rv_i(vector<int>& v, int i) {
		int rv = 0;
		for(int j = 0; j < rsz; j++) rv ^= R[i][j] * v[j];
		return rv;
	}

	bool is_indep(vector<int>& v) {
		assert(v.size() == rsz);
		for(int i = rank; i < rsz; i++) if (Rv_i(v, i)) return true;
		return false;
	}

	void add_row(int from, int to) {
		for(int j = 0; j < rsz; j++) R[to][j] ^= R[from][j];
	}

	bool add(vector<int>& v) {
		assert(v.size() == rsz);
		vector<int> t(rsz);
		for(int i = 0; i < rsz; i++) t[i] = Rv_i(v, i);
		int r = rank;
		for(; r < rsz; r++) if (t[r]) break;
		if (r == rsz) return false;
		if (r != rank) add_row(r, rank);
		for(int i = 0; i < rsz; i++) if (i != rank && t[i]) add_row(rank, i);
		rank++;
		return true;
	}
};

