    {
        memset(a,0,sizeof(a));
    }
    inline void insert(long long x)//插入
    {
        for(register int i=W;i>=0;i--)
        {
            if(!x) return;
            if(!((x>>i)&1ll)) continue;
            if(a[i]) x^=a[i];
            else
            {
                for(register int j=0;j<i;j++)
                if((x>>j)&1ll) x^=a[j];
                for(register int j=i+1;j<=W;j++)
                if((a[j]>>i)&1ll) a[j]^=x;
                a[i]=x;
                return;
            }
        }
    }
    inline bool check(long long x)
    {
        for(register int i=W;i>=0;--i)
        {
            if(!((x>>i)&1ll)) continue;
            if(a[i]) x^=a[i];
        }
        return x==0;
