        rep(i,N) cin >> a[i];
        cin >> s;

        chunks.clear();

        int last = '?';
        vll chunk;
        rep(i,N){
            if (s[i]==last){
                chunk.pb(a[i]);
            } else {
                if (!chunk.empty()) {
                    chunks.eb(last-'0', chunk);
                    chunk.clear();
                }
                last = s[i];
                chunk.assign(1, a[i]);
            }
        }
        if (!chunk.empty()) {
            chunks.eb(last-'0', chunk);
        }
    #ifdef DEBUG
        rep(i,chunks.size()){
            cerr << chunks[i].first << chunks[i].second << " | ";
        }
        cerr << endl;
    #endif
        reverse(ALL(chunks));
    }


