        repC2(i,j,63){
            int cur = 1;
            rep(k,a.size()){
                int u = ((a[k]>>i)&1)*2 | ((a[k]>>j)&1);
                rep(b,4){
                    if (cur & (1<<b)) cur |= (1 << (b ^ u));
                }
            }
            res[i][j] = cur;
        }
    }

    vvi bb, ba;

    bool can_block(vll& bs, vll& as){
        better(bb,bs);
        better(ba,as);
        rep(i,63) rep(j,63){
            if (bb[i][j] & ~ba[i][j]) return false;
        }
        return true;
    }

