#define N_TIMES(i, n)     for ( uint64_t i = 0;     i <  n; ++i )
#define N_TIMES_REV(i, n) for (  int64_t i = n - 1; i >= 0; --i )

using namespace std;

const uint64_t K = 64;

vector<uint64_t> operator-(const vector<uint64_t> &v, const vector<uint64_t> &u)
{
  vector<uint64_t> t(v.size());
  N_TIMES(i, v.size()) { t[i] = v[i] - u[i]; }
  return t;
}

bool judge(uint64_t N, const vector<uint64_t> &A, const string &S)
{
  if (S[N - 1] == '1') { return false; }

  vector<vector<uint64_t>> cs0(N + 1, vector<uint64_t>(K, 0));
  vector<vector<uint64_t>> cs1(N + 1, vector<uint64_t>(K, 0));

  N_TIMES(n, N) {
    N_TIMES(k, K) {
      cs0[n + 1][k] = cs0[n][k];
      cs1[n + 1][k] = cs1[n][k];

      bitset<K> bs(A[n]);
      if (S[n] == '0') {
        cs0[n + 1][k] += bs[k];
      } else { // S[n] == '1'
        cs1[n + 1][k] += bs[k];
      }
    }
  }

  uint64_t j = N - 1;
  while (j > 0 && S[j] == '0') { --j; }

  vector<uint64_t> t0 = cs0[N] - cs0[j], t1 = cs1[j + 1];
  N_TIMES(k, K) {
    if (t0[k] < t1[k]) {
      return false;
    }
  }
  return true;
}

int main()
{
  uint64_t T;
