void main_proc(void)
{
    // 定義    
    int N;     //     
    vector<size_t> A;
    string buffer;

    // 読み込み
    cin >> N;
    A.resize(N);
    for(int n = 0; n < N; ++n)
    {
        cin >> A[n];
    }
    cin >> buffer;

    const char *cbuff = buffer.c_str();

    // メインの処理
    vector<size_t> victory_num(1, 0);     // i ラウンドでこの数字だと 0 にできる

    // 
    for(int i = N-1; i >= 0; --i)    
    {
        size_t num = victory_num.size();
        vector<size_t> merge(2*num);

        for(size_t j = 0; j < num; ++j)
        {
            merge[j] = victory_num[j];
            merge[j+num] = victory_num[j]^A[i];
        }

        sort(merge.begin(), merge.end());

        victory_num.clear();
        victory_num.reserve(2*num);

        if(cbuff[i] == '0')     // 0 のときは union
        {
            victory_num.push_back(merge[0]);
            for(size_t j = 1; j < 2*num; ++j)    
            {
                if(merge[j] != merge[j-1])
                {
                    victory_num.push_back(merge[j]);
                }
            }
        }
        else      // 1 のときは intersection
        {
            for(size_t j = 1; j < 2*num; ++j)    
            {
                if(merge[j] == merge[j-1])
                {
                    victory_num.push_back(merge[j]);
                }
            }
        }

        if(victory_num.empty())
        {
            cout << 1 << endl;
            return;    
        }
    }

    vector<size_t>::iterator it = find(victory_num.begin(), victory_num.end(), 0);

    if(it == victory_num.end())    
    {
        cout << 1 << endl;    
    }
    else
    {
        cout << 0 << endl;    
    }
}

int main()
{
    int T;     // 回数
    cin >> T;

    for(int t = 0; t < T; ++t)
    {
        main_proc();
    }

    return 0;    
}

