int bit[ MAXN ] ;

long long calc ( long long x ) {
    for ( int i = 0 ; i < sz ; ++ i ) {
        if ( ( x & ( 1LL << bit[ i ] ) ) > 0 ) {
            x ^= f[ i ] ;
        }
    }
    return x ;
}

void add ( long long x ) {
    x = calc ( x ) ;
    if ( x != 0 ) {
        f[ sz ] = x ;
        bit[ sz ] = 0 ;
        while ( ( x & ( 1LL << bit[ sz ] ) ) == 0 ) { ++ bit[ sz ] ; }
        for ( int i = 0 ; i < sz ; ++ i ) {
            if ( ( f[ i ] & ( 1LL << bit[ sz ] ) ) > 0 ) {
                f[ i ] ^= f[ sz ] ;
            }
        }
        ++ sz ;
    }
}

