string s;

int bits[maxk][maxn], N = 0;

void add(long long target) {
	for (int i = 0; i < maxk; i++) {
		bits[i][N] = (target & (1LL << i)) ? 1 : 0;
	}
	for (int i = 0; i < maxk; i++) if (bits[i][N]) {
		for (int col = 0; col < N; col++) {
			bool is_valid = true;
			for (int row = 0; row < i; row++) if (bits[row][col]) {
				is_valid = false;
				break;
			}
			if (!is_valid) {
				continue;
			}
			for (int row = 0; row < N; row++) {
				bits[row][N] ^= bits[row][col];
			}
			break;
		}
	}
	N++;
}

bool solve(long long target) {
	for (int row = 0; row < maxk; row++) if (target & (1LL << row)) {
		bool ok = false;
		for (int col = 0; col < N; col++) if (bits[row][col]) {
			ok = true;
			break;
		}
		if (!ok) {
			return false;
		}
	}
	return true;
}

