using namespace std;
typedef long long ll;
struct Hoge {
	int N;
	const vector<int>& a;
	string S;
	vector<vector<int>> memo;
	map<int,int> sel;
	Hoge(int N, const vector<int>& a, string S) : N(N), a(a), S(S), memo(N, vector<int>(2, -1)) {}
	int run(int p, int q) {
		if (p == N) return q;
		if (a[p] == 0) return run(p+1, q);
		if (memo[p][q] != -1) return memo[p][q];
		int r;
		int r0 = run(p+1, q);
		int r1 = run(p+1, q^1);
		int s = S[p] - '0';
		r = s^1;
		if (r0 == s) { r = s; sel[p] |= 1; }
		if (r1 == s) { r = s; sel[p] |= 2; }
		return memo[p][q] = r;
	}
};
int solve() {
	int N;
	cin >> N;
	vector<ll> A(N);
	for (auto& x : A) cin >> x;
	string S;
	cin >> S;
	vector<map<int,int>> sels;
	for (int i = 0; i < 60; ++ i) {
		vector<int> a;
		for (auto x : A) a.push_back((x >> i) & 1);
		Hoge hoge(N, a, S);
		if (hoge.run(0, 0)) return 1;
		sels.push_back(hoge.sel);
	}
	ll x = 0;
	for (int p = 0; p < N; ++ p) {
		int t = 3;
		for (int i = 0; i < 60; ++ i) {
			if (sels[i].count(p)) t &= sels[i][p];
		}
		if (t == 2) {
			x ^= A[p];
		}
	}
	return x == 0 ? 0 : 1;
}
