#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
ll A[200];
string s;

priority_queue<ll, vector<ll>, less<ll> > pq;

bool subspace(vector<ll> W, vector<ll> V) {
    for (ll x : V)
        pq.push(x);
    vector<ll> S;
    while (!pq.empty()) {
        ll x = pq.top();
        pq.pop();
        ll x2 = x;
        for (ll y : S)
            if ((x2^y) < x2)
                x2 = (x2^y);
        if (x2 == x)
            S.push_back(x2);
        else if (x2 != 0)
            pq.push(x2);
    }
    for (ll x : W) {
        for (ll y : S)
            if ((x^y) < x)
                x = (x^y);
        if (x != 0)
            return 0;
    }
    return 1;
}

