const int max_n = 203, inf = 1000111222;
const int sz = 10;
const int max_mask = 1 << sz;

int t, n;
bool dp[max_n][max_mask];
long long a[max_n];
string s;

bool get_bit(long long mask, int pos) {
    return (mask >> pos) & 1;
}

mt19937 gen(47228);

int solve() {
    for (int it = 0; it < 100; ++it) {
        vector<int> ids;
        for (int b = 0; b < 60; ++b) {
            ids.push_back(b);
        }
        shuffle(ids.begin(), ids.end(), gen);
        while (ids.size() > sz) {
            ids.pop_back();
        }
        for (int mask = 0; mask < max_mask; ++mask) {
            dp[n][mask] = 1;
        }
        dp[n][0] = 0;
        for (int i = n - 1; i >= 0; --i) {
            int x = 0;
            for (int j = 0; j < sz; ++j) {
                x += (1 << j) * get_bit(a[i], j);
            }
            const int player = s[i] - '0';
            for (int cur = 0; cur < max_mask; ++cur) {
                if (dp[i + 1][cur] == player || dp[i + 1][cur ^ x] == player) {
                    dp[i][cur] = player;
                } else {
                    dp[i][cur] = player ^ 1;
                }
            }
        }
        if (dp[0][0]) {
            return 1;
        }
    }
    return 0;
}

