bool gauss() { //true if linearly dep
  int i=0,j=0;

  while(i<N && j<M) {
    int k;
    for(k=i;k<N;++k) if(A[k][j]) break;
    if(k==N) { ++j; continue; }
    if(k!=i) swap(A[i], A[k]);

    for(int u=i+1;u<N;++u) {
      for(int q=j+1;q<M;++q) A[u][q] = (A[u][q] ^ (A[u][j]*A[i][q]));
      A[u][j]=0;
    }
    ++i; ++j;
  }

  return (A[N-1] == 0);
}

