      while (idx < N && S[idx] == '1') idx++;
      ll idx1 = idx;
      if (idx0 == idx1) break;
      Matrix<Ftwo> mat0(idx0, msize);
      for (ll i = 0; i < idx0; i++) {
	auto vec = i2vec(A.at(i));
	for (ll j = 0; j < msize; j++) mat0.at(i, j) = vec[j];
      }
      auto [rank0, dummy0] = mat0.sweepout();
      Matrix<Ftwo> mat1(idx1, msize);
      for (ll i = 0; i < idx1; i++) {
	auto vec = i2vec(A.at(i));
	for (ll j = 0; j < msize; j++) mat1.at(i, j) = vec[j];
      }
      auto [rank1, dummy1] = mat1.sweepout();
      if (rank0 < rank1) return 1;
    }
    return 0;
  };

  ll T; cin >> T;
  for (ll _t = 0; _t < T; _t++) cout << solve() << "\n";

  return 0;
}

