struct XorVector {
    int rank;
    const int MX;
    vector<long long> span;
    XorVector(int MX) : rank(0), MX(MX), span(MX, 0) {}
    void emplace(ll num) {
        span[rank++] = num;
    }
    bool find(ll num) {
        gaussian_elimination();
        for (int i = 0; i < rank; ++i) num = min(num, num ^ span[i]);
        return num == 0LL;
    }
    void gaussian_elimination() {
        rank = 0;
        for (int col = 63; col >= 0; --col) {
            int pivot = -1;
            for (int row = rank; row < MX; ++row) if (span[row] >> col & 1) { pivot = row; break; }
            if (pivot == -1) continue;
            swap(span[pivot], span[rank]);
            for (int row = 0; row < MX; ++row) if (row != rank and span[row] >> col & 1) span[row] ^= span[rank];
            ++rank;
        }
    }
    void print() {
        for (int i = 0; i < rank; ++i) cerr << bitset<64>(span[i]) << endl;
        cerr << endl;
    }
};

