int ord(li a){
  li b,i=1;
  while(b=(a>>i)){
    a|=b;
    i*=2;
  }
  return __builtin_popcountl(a);
}

int in(li a,vector<li>& space){
  for(li x:space){
    if(ord(x)==ord(a)) a^=x;
  }

  return !a;
}

void normarize(vector<li>& space){
  int n=space.size();
  rep(k,n){
    int i=n-1-k;
    rep(j,i){
      if(ord(space[i]&space[j])==ord(space[i])) space[j]^=space[i];
    }
  }
}

void add(li a,vector<li>& space){
  if(df)print("add",a);
  for(li& x:space){
    if(ord(x)==ord(a)) a^=x;
    if(x<a) swap(a,x);
  }
  if(a){
    space.push_back(a);
  }
  normarize(space);
  if(df)print(space);
}

