int reverseBits2(int n,int nn)
{
	int count = 0;
	for (int i = nn-1; i >= 0; i--)
	{
		count = (n >> i & 1) << (nn-1 - i) | count;//先向右i位,通过&1记录当前最左位是1还是0,然后再回拉31-i位把之前count记录下的结果通过|拷贝回去
																	//因为向左回拉留下的都是0,|操作就是原来count各位是1是0,就会拷贝回来对应的1和0
	}
	return count;
}
