namespace xor_helpers {
    template<typename T>
    std::vector<T> get_base(const std::vector<T> &a) {
        std::vector<T> base;
        for (T t : a) {
            for (T b : base) {
                t = std::min(t, t ^ b);
            }
            if (t != 0) base.push_back(t);
        }
        for (int i = 0; i < (int) base.size(); i++) {
            sort(base.begin() + i, base.end(), std::greater<T>());
            T cur = base[i];
            for (int j = i + 1; j < (int) base.size(); j++)
                base[j] = std::min(base[j], base[j] ^ cur);
        }
        return base;
    }
}
