void v_insert(vector<ulint>& u, ulint a){
    for(ulint v: u){
        u.push_back(a^v);
    }
    sort(all(u));
    u.erase(unique(u.begin(), u.end()), u.end());   
}
void v_erase(vector<ulint>& u, ulint a){
    vector<ulint> w, r;
    for(ulint v: u){
        w.push_back(a^v);
    }
    sort(all(w));
    int i = 0, j = 0;
    while(i<u.size() && j<w.size()){
        if(u[i] == w[j]) r.push_back(u[i]);
        if(u[i] <= w[j]) i++;
        if(u[i] >= w[j]) j++;
    }
    u = r;
}

