ll gauss0(int n, int m)
{
    int col=m-1,row=0,i,j;
    ll ans=0;
    for(;col>=0 && row<n;col--){
        for(i=row;i<n;i++){
            if(v[i][col]){
                swap(v[i],v[row]);
                break;
            }
        }
        if(!v[row][col])continue;

        for(i=0;i<n;i++){
            if(i==row)continue;
            if(v[i][col])
                v[i]^=v[row];
        }
        row++;
    }


    for(i=0;i<n;i++){
        ll x=0;
        for(j=0;j<m;j++)x+=(1LL<<j)*v[i][j];
        ans^=x;
    }


    return ans;
}

ll gauss1(int n, int m)
{
    int col=m-1,row=0,i,j;
    ll ans=0;
    for(;col>=0 && row<n;col--){
        for(i=row;i<n;i++){
            if(w[i][col]){
                swap(w[i],w[row]);
                break;
            }
