        if(!w[row][col])continue;

        for(i=0;i<n;i++){
            if(i==row)continue;
            if(w[i][col])
                w[i]^=w[row];
        }
        row++;
    }


    for(i=0;i<n;i++){
        ll x=0;
        for(j=0;j<m;j++)x+=(1LL<<j)*w[i][j];
        ans^=x;
    }


    return ans;
}

