#define Rep(i, n) for(int i = 0; i < (int)(n); ++i)
#define For(i, s, n) for(int i = s; i < (int)(n); ++i)

set<int> eliminate(vector<int> a) {
  vector<int> basis;
  for (int i : a) {
    for (int b : basis) {
      int x = i ^ b;
      if (x < i) i = x;
    }
    if (i) basis.push_back(i);
  }

  // normalize
  for (;;) {
    bool changed = false;
    Rep(i, basis.size()) {
      For(j, i + 1, basis.size()) {
        int x = basis[i] ^ basis[j];
        if (x < basis[i]) {
          basis[i] = x;
          changed = true;
        }
      }
    }
    if (!changed) break;
  }

  return set<int>(basis.begin(), basis.end());
}

// Returns true iff all of b is contained by a
bool contains(set<int> a, set<int> b) {
  for (int i : b) {
    if (a.count(i) == 0) return false;
  }
  return true;
}

