struct solver
{

    solver()
    {
        using F2=modint<2>;
        int n; cin>>n;
        vector<i64> a(n); cin>>a;
        string s; cin>>s;
        reverse(__all(a));
        reverse(__all(s));

        if(s.front()=='1')
        {
            cout << 1 << "\n";
            return;
        }

        matrix<F2> A(64,n);
        int col=0;

        auto ext=[&](i64 val)->bool
        {
            auto exA(A);
            for(int i=0; i<64; ++i)
            {
                exA[i][col]=val&1;
                val>>=1;
            }
            auto piv=Gauss_Jordan(exA);
            assert(!piv.empty());
            if(piv.back()==col)
            {
                return true;
            }
            return false;
        };

        for(int i=0,j=0,t=0; i<n; i=j,t^=1)
        {
            while(j<n and s[i]==s[j])
            {
                if(ext(a[j]))
                {
                    if(t)
                    {
                        cout << 1 << "\n";
                        return;
                    }
                    for(i64 cop=a[j],r=0; cop; cop>>=1,r++)
                    {
                        A[r][col]=cop&1;
                    }
                    col++;
                }
                j++;
            }
        }
        cout << 0 << "\n";
    }
};
