	auto addBase = [](vll &base, ll val) {
		int n = base.size();
		for (int i = 0; i < n; i++) {
			if ((val^base[i]) < val) {
				val ^= base[i];
			}
		}
		if (!val) return;
		for (int i = 0; i < n; i++) {
			if ((val^base[i]) < base[i]) {
				base[i] ^= val;
			}
		}
		base.push_back(val);
		sort(rbegin(base), rend(base));
	};

	auto containBase = [](vll &base, ll val) {
		int n = base.size();
		for (int i = 0; i < n; i++) {
			if ((val^base[i]) < val) {
				val ^= base[i];
			}
		}
		if (val) return (false);
		return (true);
	};

	for (int i = (int)A.size()-1; i >= 0; i--) {
		if (S[i] == '0') {
			addBase(base, A[i]);
		} else {
			if (!containBase(base, A[i])) {
