class Solver {
 public:
  int n;
  vector<unsigned long long> a, zero;
  string s;
  Solver(LL n) : n(n), a(n){};

  void solve() {
    for (int i = 0; i < n; ++i) {
      cin >> a[i];
    }
    cin >> s;
    DBG(a, s)
    int r = 0;
    for (int i = s.length() - 1; i >= 0; --i) {
      if (s[i] == '0') {
        zero.push_back(a[i]);
        r = sweepout2(zero);
      } else {
        if (!solve(zero, a[i])) {
          cout << 1 << endl;
          return;
        }
      }
      DBG(zero)
    }
    cout << 0 << endl;
  }
  bool solve(vector<unsigned long long> &t, unsigned long long x) {
    int p = 60;
    DBG(t, x)
    for (int i = 0; i < (int)t.size(); ++i) {
      while (p >= 0 && !((t[i] >> p) & 1)) p--;
      DBG(p)
      if (p < 0) break;
      if ((x >> p) & 1) x ^= t[i];
    }
    return x == 0;
  }
  int sweepout2(vector<unsigned long long> &t) {
    int row = t.size(), n = 60, rank = 0;
    for (int i = n - 1; i >= 0; --i) {
      int p = rank;
      while (((t[p] >> i) & 1) == 0) {
        p++;
        if (p == row) break;
      }
      if (p == row) continue;
      swap(t[rank], t[p]);
      for (int j = 0; j < row; ++j) {
        if (j != rank && ((t[j] >> i) & 1)) t[j] ^= t[rank];
      }
      rank++;
      if (rank == min(n, row)) break;
    }
    return rank;
  }
};

