//bit.ver
//rankを返す
int Gaussian_elimination(mat &A) {
	int n = A.size(); int m = A[0].size();
	int le = 0;
	rep(j, m) {
		Rep(i, le, n) {
			if (A[i][j]) {
				swap(A[le], A[i]);
				Rep(i2, le + 1, n) {
					if (A[i2][j]) {
						rep(k, m) {
							A[i2][k] ^= A[le][k];
						}
					}
				}
				le++; break;
			}
		}
	}
	return le;
}

bool can(mat &A, vector<int> s) {
	int le = 0;
	rep(j, 60) {
		if (s[j] == 0)continue;
		if (le<A.size()&&A[le][j]) {
			Rep(k, j, 60) {
				s[k] ^= A[le][k];
			}
			le++;
		}
	}
	rep(i, 60)if (s[i])return false;
	return true;
}

