bool solve(vector<vector<int>> & dp, vector<int> & a, string & s, int pos, int have) {
	if (pos == (int)a.size()) {
		if (have == 0) return 0;
		return 1;
	}
	if (dp[pos][have] != -1) return dp[pos][have];
	int ans;
	if (solve(dp, a, s, pos + 1, have) == s[pos] - '0') {
		ans = s[pos] - '0';
	} else if (solve(dp, a, s, pos + 1, have ^ (a[pos])) == s[pos] - '0') {
		ans = s[pos] - '0'; 
	} else {
		ans = s[pos] - '0';
		ans ^= 1;
	}
	dp[pos][have] = ans;
	return ans;
}

