        int pivot = -1;
        for (int row = rank; row < A.size(); row++) {
            if (A[row][col]) {
                pivot = row;
                break;
            }
        }
        if (pivot == -1) continue;
        swap(A[pivot], A[rank]);
        for (int row = 0; row < A.size(); row++) {
            if (row != rank && A[row][col]) Rep (j, 61) A[row][j] ^= A[rank][j];
        }
        rank++;
    }
}
