vll space(vll bases) {
    int n = bases.size();
    int i = 0;
    int rank = 0;
    reprev(d, 63) {
        repr(j, i, n) {
            if ((bases[j] >> d) & 1) {
                swap(bases[i], bases[j]);
                break;
            }
        }
        if (((bases[i] >> d) & 1) == 0) {
            continue;
        }
        rank++;
        // dump(d, i, bases);
        rep(j, n) {
            if (j == i) continue;
            if ((bases[j] >> d) & 1) {
                bases[j] ^= bases[i];
            }
        }
        i++;
    }
    bases.resize(rank);
    return bases;
}

void solve(int N, vll &A, string &S) {
    // dump(N, A, S);
    if (S.back() == '1') {
        cout << "1\n";
        return;
    }
    char player = '0';
    vll v;
    vll bases;
    reprev(i, N) {
        // dump(N, i, bases);
        v.push_back(A[i]);
        if (i != 0 && S[i - 1] == player) {
        } else {
            if (player == '0') {
                // dump(v, bases);
                bases.resize(bases.size() + v.size());
                copy(v.begin(), v.end(), back_inserter(bases));
                bases = space(bases);
                // dump(bases);
            } else {
                int prev_rank = bases.size();
                v.resize(bases.size() + v.size());
                copy(bases.begin(), bases.end(), back_inserter(v));
                int new_rank = space(v).size();
                // dump(prev_rank, new_rank);
                if (new_rank > prev_rank) {
                    cout << "1\n";
                    return;
                }
            }
            v.clear();
            player = S[i - 1];
        }
    }
    cout << "0\n";
}

