int solve3(vector<int> &A, string &S, int depth, int x = 0){
	if(depth == A.size()) {
		return !!x;
	}

	if(S[depth] == '0') {
		if(solve3(A, S, depth+1, x ^ A[depth]) == 0) return 0;
		if(solve3(A, S, depth+1, x) == 0) return 0;

		return 1;
	} else {
		if(solve3(A, S, depth+1, x ^ A[depth]) == 1) return 1;
		if(solve3(A, S, depth+1, x) == 1) return 1;

		return 0;
	}
}


