ll basis[65];

void insertVector(ll mask) {
    for (ll i = LOG_A - 1LL; i >= 0; i--) {
        if ((mask & 1LL << i) == 0) continue;

        if (!basis[i]) {
            basis[i] = mask;
            return;
        }

        mask ^= basis[i];
    }
}

int check(ll mask) {
    for (ll i = LOG_A - 1; i >= 0; i--) {
        if ((mask & 1LL << i) == 0) continue;

        if (!basis[i]) {
            return 0;
        }
        mask ^= basis[i];
    }
    return 1;
}


