bool bg(vector<int> x, vector<int> y) {
    while (y.size() < 60) y.pb(0);
    for (auto p : x) {
        bitset<60> b;
        for (int i = 0, t = p; i < 60; i++, t >>= 1)
            b[i] = t % 2;
        int n = y.size();
        bitset<201> a[60];
        for (int i = 0; i < 60; i++)
            a[i][n] = b[i];
        for (int i = 0; i < n; i++)
            for (int j = 0, t = y[i]; j < 60; j++, t >>= 1)
                a[j][i] = t % 2;
        int ci = 0, i = 0;
        for (i = 0; i < 60 && ci < n; ci++) {
            int nz = -1;
            for (int j = i; j < 60; j++)
                if (a[j][ci]) {
                    nz = j;
                    break;
                }
            if (nz == -1 || ci == n) {
                if (ci >= n - 1) {
                    for (int j = i; j < 60; j++)
                        if (a[j][n])
                            return 0;
                    return 1;
                }
                continue;
            }
            swap(a[nz], a[i]);
            for (int j = i + 1; j < 60; j++)
                if (a[j][i]) a[j] ^= a[i];
            ++i;
        }
        for (; i < 60; i++)
            if (a[i][n]) return 0;
    }
    return 1;
}

