class Bitwise_Basis {
private:
	vector<ull> basis;
	void add_element_to_basis(vector<ull> &basis, ull x) {
		if (x == 0) return;
		Loop(i, basis.size()) {
			ull y = basis[i];
			ull x_lower = x & ull(-ll(x));
			ull y_lower = y & ull(-ll(y));
			if (x_lower == y_lower) {
				x ^= y;
			}
			else if (x_lower < y_lower) {
				std::swap(x, basis[i]);
			}
			if (x == 0) return;
		}
		if (x != 0) basis.push_back(x);
	}
public:
	void add_element(ull x) {
		add_element_to_basis(this->basis, x);
	}
	bool is_independent(const ull x) {
		vector<ull> basis_bckup = basis;
		size_t rank_bef = basis_bckup.size();
		add_element_to_basis(basis_bckup, x);
		size_t rank_aft = basis_bckup.size();
		if (rank_bef < rank_aft) return true;
		else return false;
	}
	int get_rank() {
		return int(basis.size());
	}
};

int solve(int n, vll &a, string &s) {
	Bitwise_Basis bb;
	Loopr(i, n) {
		if (s[i] == '0') {
			bb.add_element(a[i]);
		}
		else {
			if (bb.is_independent(a[i])) {
				return 1;
			}
		}
	}
	return 0;
}

