void reduce(vector<bitset<K>>& x, int m){ // returns determinant
	int n=x.size();
	int i=0,j=0;
	while(i<n&&j<m){
		int l=i;
		fore(k,i+1,n)if(x[k].test(j))l=k;
		if(!x[l].test(j)){j++;continue;}
		if(l!=i){swap(x[i],x[l]);}
		fore(k,0,n){
