template<typename T> T minv(T a, T m) {    T u = 0, v = 1;    while (a != 0) {        T t = m / a;        m -= t * a;        swap(a, m);        u -= t * v;        swap(u, v);    }    assert(m == 1);    return u;}
template<typename T> T minv(T a) {    if (a < sz(fac)){        return inv[a];    }    T u = 0, v = 1;    T m = MOD;    while (a != 0) {        T t = m / a;        m -= t * a;        swap(a, m);        u -= t * v;        swap(u, v);    }    assert(m == 1);    return u;}
//int型 mod m
template<typename T, typename U> mint mpow(const T& a, const U &b) {if (b < 0)return minv(mpow(a, -b));    mint x = a, res = 1;    U p = b;    while (p > 0) {        if (p & 1) res *= x;        x *= x;        p >>= 1;    }    return res;}
template<typename T, typename U, typename V> int mpowi(const T &a, const U &b, const V &m = MOD) {return mpow(a,b, m);}
