struct gauss2 {
    vi bases;
    int free = 0;
    gauss2() {}
    gauss2(const vi &list) {
        for (int i = 0; i < list.size(); i++) {
            add(list[i]);
        }
    }
    void add(int v) {
        for (int i = 0; i < bases.size(); i++) {
            v = min(v, v ^ bases[i]);
        }
        if (v)bases.push_back(v);
        else free++;
    }

    int max() {
        int res = 0;
        for (int i = 0; i < bases.size(); i++) {
            res = std::max(res, res ^ bases[i]);
        }
        return res;
    }

    mint cou_m(int v) {
        if (can(v))return mpow(2, free);
        else return 0;
    }

    bool can(int v) {
        for (int i = 0; i < bases.size(); i++) {
            v = std::min(v, v ^ bases[i]);
        }
        return v == 0;
    }
};


