long long count0, count1;

void Counter(long long N)
{
    stringstream ss;
    ss << bitset<200>(N);
    string S = ss.str();

    count0 = 0;
    count1 = 0;
    for (long long i = 0; i < S.length(); i++)
    {
        if (S[i] == '1')
        {
            count1++;
        }
        else
        {
            count0++;
        }
    }
    return;
}

int main(void)
{
    long long T, N, tmp0, tmp1, S, tmpS;
    vector<long long> A;
    string str;

    cin >> T;

    for (long long t = 0; t < T; t++)
    {
        A.clear();

        cin >> N;
        long long tmp;
        for (long long i = 0; i < N; i++)
        {
            cin >> tmp;
            A.push_back(tmp);
        }

        cin >> str;
        //reverse(str.begin(), str.end());

        S = 0;
        for (long long j = 0; j < str.size(); j++)
        {
            if (str[j] == '1')
            {
                S = S + pow(2, j);
            }
        }

        long long round;
        for (long long i = 1; 2 * i - 1 < A.size(); i++)
        {

            for (round = 2 * i - 1; round < 2 * (i + 1); round++)
            {
                Counter(S);
                tmp0 = count0;
                tmp1 = count1;

                tmpS = S xor A[round];
                Counter(tmpS);

                if (round % 2 == 0)
                {
                    //0にしたい
                    if (tmp0 < count0)
                    {
                        //論理和後のほうがAll0に近い
                        S = tmpS;
                    }
                }
                else
                {
                    //0にしたくない
                    if (tmp1 < count1)
                    {
                        //論理和後の方がALL0から遠い
                        S = tmpS;
                    }
                }
            }
        }

        Counter(S);

        if (count1 == 0)
        {
            cout << 0 << endl;
        }
        else
        {
            cout << 1 << endl;
        }
    }

    return 0;
}

