namespace xor_helpers {
    template<typename T>
    std::vector<T> get_base(const std::vector<T> &a) {
        std::vector<T> base;
        for (T t : a) {
            for (T &b : base) {
                t = std::min(t, t ^ b);
                b = std::min(b, b ^ t);
            }
            if (t != 0){
                base.push_back(t);
            }
        }
        sort(all(base));
        return base;
    }
