        solver(fs, cout).run();
    }
    if(loop <= 1) {
        cout << "===" << endl;
        while(cin) solver(cin, cout).run();
    }
#else
    solver(cin, cout).run();
#endif
    return 0;
}


void solver::run(){
    int T=0;
    is >> T;
    while(T-->0){
        if(!input()) return;
        solve();
    }
}

