bool solve() {
    using op_type = std::pair<ll, vec<ll>>;
    ll n;
    std::cin >> n;
    vec<ll> av(n);
    for (auto &&e : av) std::cin >> e;
    std::string s;
    std::cin >> s;
    s += '2';
    ll cur = -1;
    vec<ll> cv;
    vec<op_type> ops;
    for (ll i = 0; i < n + 1; i++) {
        ll c = (s[i] - '0');
        if (cur != c) {
            if (cur != -1) ops.emplace_back(cur, std::move(cv));
            cv.clear();
            cur = c;
        }
        if (i < n) cv.push_back(av[i]);
    }

    if (ops.back().first == 1) return true;
    std::reverse(ALL(ops));
    vec<ll> bs;
    for (auto &&op : ops) {
        auto& [ cur, v ] = op;
        ll bsz = bs.size();
        for (ll e : v) {
            for (ll b : bs) chmin(e, e ^ b);
            if (e) bs.push_back(e);
        }
        if (cur == 1 && bsz < bs.size()) return true;
    }
    return false;
}

