vector<LL> xor_basis(vector <LL> a) {
    LL n = a.size();
    LL row = 0;
    vector<LL> basis;
    vector<bool> colm(lg, 0);
    for(LL k = lg-1; k >= 0; k--) {
        for(LL i = row; i < n; i++) {
            if((a[i]>>k)&1) {
                swap(a[i], a[row]);
                break;
            }
        }
        if(row < n && (a[row]>>k)&1) {
            basis.push_back(a[row]);
            colm[k] = 1;
            for(int i = row + 1; i < n; i++) {
                if((a[i]>>k)&1) a[i] ^= a[row];
            }
            row++;
        }
    }
    return basis;
}


