bool append_basis(vector<i64> &basis, i64 x) {
    i64 y = x;
    for(i64 b : basis) {
        min_assign(y, b ^ y);
    }
    if(y == 0) return false;
    basis.push_back(y);
    return true;
}

bool is_element_of(const vector<i64> &basis, i64 x) {
    for (i64 b : basis) {
        min_assign(x, b ^ x);
    }
    return x == 0;
}

