i64 read() {
    using namespace _buff;
    i64 ret = 0;
    bool pos = true;
    char c = getc();
    for (; (c < '0' || c > '9') && c != '-'; c = getc()) {
        assert(~c);
    }
    if (c == '-') {
        pos = false;
        c = getc();
    }
    for (; c >= '0' && c <= '9'; c = getc()) {
        ret = (ret << 3) + (ret << 1) + (c ^ 48);
    }
    return pos ? ret : -ret;
}

size_t reads(int *s) {
    using namespace _buff;
    size_t ret = 0;
    char c = getc();
    for (; c != '0' && c != '1'; c = getc()) {
        assert(~c);
    }
    for (; c == '0' || c == '1'; c = getc()) {
        s[ret++] = c ^ 48;
    }
    return ret;
}

using u64 = unsigned long long;

const size_t L = 60;

struct Basis {
    u64 b[L];

    Basis() {
        memset(b, 0, sizeof b);
    }

    void add(u64 x) {
        for (size_t i = L; i--; ) {
            if (x >> i & 1) {
                if (!b[i]) {
                    b[i] ^= x;
                    return;
                }
                x ^= b[i];
            }
        }
    }

    bool query(u64 x) {
        for (size_t i = L; i--; ) {
            if (x >> i & 1) {
                x ^= b[i];
            }
        }
        return !x;
    }
};

void add(Basis &b, u64 x) {
    static u64 bas[L];
    memcpy(bas, b.b, sizeof b.b);
    for (size_t i = 0; i < L; ++i) {
        b.add(bas[i] ^ x);
    }
}

