    for (int i = 0; i < n; ++i) {
        if (b[i]) {
            if (!bas.query(a[i])) {
                puts("1"); return;
            }
        } else {
            add(bas, a[i]);
        }
    }
    puts(bas.query(0) ? "0" : "1");
}

