void normalize(v_b60& v,v_ll& id){
    ll now=0;
    for(ll i=0;i<60;i++){
        id[i]=-1;
    }
    for(ll d=0;d<60;d++){
        ll f=-1;
        for(ll i=now;i<v.size();i++){
            if (v[i][d]){f=i;break;}
        }
        if (f>=0){
            id[d]=now;
            swap(v[now],v[f]);
            for(ll i=0;i<v.size();i++){
                if (i==now) continue;
                if (v[i][d])v[i][d]=v[i][d]^v[i][now];
            }
            now++;
        }
    }
}

