    rep(i,N){
      if(S[i]=='0'){
        start++;
        continue;
      }
      ll crt=A[i];
      repl(j,start,M){
        minch(crt,(crt^vs[j]));
      }
      if(crt!=0)ok=false;
    }
    if(ok)cout<<"0\n";
    else cout<<"1\n";
  }

  return 0;
}

