int cnt;

void swap(int u,int d){
	int r[N];
	for(int i=cnt;i<N;++i)r[i]=m[d][i];
	for(int i=cnt;i<N;++i)m[d][i]=m[u][i];
	for(int i=cnt;i<N;++i)m[u][i]=r[i];
}
void add(int u,int d){
	for(int i=cnt;i<N;++i)m[d][i]^=m[u][i];
}

void gaus(){
	int h=0;
	int w=cnt;
	for(int i=0;i<H;++i)
		for(int j=cnt;j<N;++j)
			m[i][j]=o[i][j];
	while(w<N-1&&h<H){
		for(int i=h;i<H;++i)
			if(m[i][w]){swap(h,i);break;}
		if(!m[h][w]){++w;++h;continue;}
		for(int i=h+1;i<H;++i)
			if(m[i][w])
				add(h,i);
		++w;++h;
	}
}

bool check(){
	for(int i=0;i<H;++i)
		if(m[i][N-1]){
			bool pos=false;
			for(int j=cnt;j<N-1;++j)
				if(m[i][j]){
					pos=true;break;
				}
			if(!pos)return false;
			}
	return true;
}

