template <class expr>
class binary_elimination
{
    std::vector<expr> base;
public:
    bool add(expr e)
    {
        for(const expr &b : base) if((b ^ e) < e) e ^= b;
        if(e) base.emplace_back(e);
        return e;
    }
    size_t dim() const { return base.size(); }
    typename decltype(base)::iterator begin() const { return std::begin(base); }
    typename decltype(base)::iterator end() const { return std::end(base); }
}; // class binary_elimination

