class XorSet {
public:
    static constexpr int kMaxBit = 60;

    XorSet() : basis(kMaxBit, 0) {
    }

    void Insert(ll val) {
        for (int b = 0; b < kMaxBit; ++b) {
            if (HasBit(val, b)) {
                if (basis[b] == 0) {
                    basis[b] = val;
                    ++size;
                    return;
                }
                val ^= basis[b];
            }
        }
    }

    int Size() const { return size; }

    bool Contains(ll val) {
        for (int b = 0; b < kMaxBit; ++b) {
            if (HasBit(val, b)) {
                if (basis[b] == 0) {
                    return false;
                }
                val ^= basis[b];
            }
        }
        return true;
    }

private:
    vector<ll> basis;
    int size = 0;
};

