int N;
ll span[202];

int gaussian_elimination() {
    int rank = 0;
    for (int col = 0; col < 63; ++col) {
        int pivot = -1;
        for (int row = rank; row < N; ++row) {
            if (span[row] >> col & 1) {
                pivot = row;
                break;
            }
        }
        if (pivot == -1) continue;
        swap(span[pivot], span[rank]);
        for (int row = 0; row < N; ++row) {
            if (row != rank and span[row] >> col & 1) span[row] ^= span[rank];
        }
        ++rank;
    }
    return rank;
}

void print_span(int rank) {
    gaussian_elimination();
    REP(i, rank) {
        cerr << bitset<63>(span[i]) << endl;
    }
    cerr << endl;
}

