int f(const vector<long long int>& a, const string& s, int index, long long int ss, unordered_map<int, unordered_map<long long int, int>>& um) {
    if (um[index].find(ss) != um[index].end()) {
        return um[index][ss];
    }
    if (index >= a.size()) {
        if (ss != 0) {
            return 1;
        } else {
            return 0;
        }
    }
    int ret = f(a, s, index + 1, ss, um);
    if (s[index] == ret + '0') {
        um[index][ss] = ret;
        return ret;
    }
    ret = f(a, s, index + 1, ss ^ a[index], um);
    if (s[index] == ret + '0') {
        um[index][ss] = ret;
        return ret;
    }
    um[index][ss] = 1 - (s[index] - '0');
    return 1 - (s[index] - '0');
}

