map<pair<int,int>, int> dp;

int solve(string order, ll arr[], int n, int idx, ll x) {

	if(idx == n-1) {
		if((x == 0 || (x^arr[idx]) == 0) && order[idx] == '0')
			return 0;
		return 1;
	}
	if(dp.find({idx, x}) != dp.end())
		return dp[{idx,x}];
	int p = solve(order, arr, n, idx+1, x^arr[idx]);
	int q = solve(order, arr, n, idx+1, x);
	if(p == (order[idx]-'0') || q == (order[idx]-'0'))
		return dp[{idx,x}] = (order[idx]-'0');
	else 
		return dp[{idx,x}] = (order[idx] == '0' ? 1 : 0);
}

