ll myRank(const auto& X, ll k) {
  Matrix<Fp> mat(X.size(), k);
  for (int i = 0; i < (ll)X.size(); i++) {
    for (int j = 0; j < k; j++) {
      mat.at(i, j) = X.at(i).at(j);
    }
  }
  mat.self_sweepout();
  ll i = 0;
  for (; i < (ll)X.size(); i++) {
    bool found = false;
    for (ll j = 0; j < k; j++) {
      if (mat.at(i, j) == Fp(1)) {
	found = true;
	break;
      }
    }
    if (!found) break;
  }
  return i;
}


