  auto myAppend = [&](ll a) -> void {
    vector<Fp> nv;
    for (ll i = 0; i < K; i++) {
      nv.push_back(Fp(a & 1));
      a >>= 1;
    }
    X.push_back(nv);
  };

  ll i = 0;
  while (true) {
    while (i < N && S.at(i) == '0') {
      myAppend(A.at(i));
      i++;
    }
    ll y = myRank(X, K);
    DLOG("i=", i, "y=", y);
    if (i == N) return 0;
    if (y == K) return 0;
    while (i < N && S.at(i) == '1') {
      myAppend(A.at(i));
      i++;
    }
    ll z = myRank(X, K);
    DLOG("i=", i, "z=", z);
    if (z > y) return 1;
  }
}

