    if(a.size()==0) return 0;
    long long left=0,right=a.size()-1,mid;
    int ret=1;
    while(1){
        mid=(right+left)/2;
        if(a.at(mid)==val) return 1;
        else if(right==left) return 0;
        else if(a.at(mid)>val){
            right=mid;
        }else{
            left=mid+1;
        }
        if(right<left) return 0;
    }
    return 0;
}
