template<typename T>
struct xorset {
    vector<T> basis;
    xorset() {
    }
    void sweep(){
        int L = basis.size();
        rep(i,L) rep(j,L){
            if (i==j) continue;
            if (!(basis[i] & basis[j])) continue;
            basis[j] ^= basis[i];
        }
        set<T> tmp(ALL(basis));
        if (found(tmp,0)) tmp.erase(0);
        basis.assign(ALL(tmp));
    }
    void insert(T x){
        if (this->has(x)) return;
        basis.pb(x);
        sweep();
    }
    bool has(T x){
        bool res = false;
        if (x == 0) {
            res = true;
        } else {
            for (T b: basis){
                if (!(x & b)) continue;
                x ^= b;
                if (x == 0) { res = true; break; }
            }
        }
        return res;
    }
};

