ll b[64];
void insertVector(ll mask) {
	for (int i = 0; i < 64; i++) {
		if ((mask & 1 << i) == 0) continue;
		if (!b[i]) {
			b[i] = mask;
			return;
		}
		mask ^= b[i];
	}
}
bool checkVector(ll mask) {
	for (int i = 0; i < 64; i++) {
		if ((mask & 1 << i) == 0) continue;
		if (b[i]) mask ^= b[i];
	}
	return (mask==0ll);
}
