struct Gauss{
	vector<T> V;
	void init(){
		V.clear();
	}
	inline T belongs(T x){
		for(auto e:V){
			x = min(x,e^x);
		}
		return x;
	}
	void add(T x){
		T z = belongs(x);
		if (z > 0) {
			V.push_back(z);
		}
	}

	void sorted_add(T x){
		T z = belongs(x);
		if (z > 0){
			uint32_t i = V.size();
			V.push_back(z);
			while( i > 0 && V[i-1] < z){
				swap(V[i],V[i-1]);
				--i;
			}
		}
	}
};

