int main(){

// あるターンにおけるxの2進表現(例えば01101)をベクトル(0,1,1,0,1)と捉える
// DP[i] := 「iターン目の直前に変数xがその状態であれば、人0が最終的にxを0にできる」というベクトルの集合。

/* 前提の整理


  0と1しかないF2({0, 1})の世界（XORの世界、mod2の世界ともいえる）
  この世界の「+（加法）」は XOR である（0と1しかない世界なので、1に1を足しても上が無く、0に戻ってしまう＝XORの動きと同じ）

  F2は体（有限体）である
  加法・乗法について閉じている（足しても掛けても0, 1以外にならない）、逆元（足して0、掛けて0になるもの）が定義できる、分配法則が成り立つなどの条件を満たしているため

  体なので、線形代数学における基底にまつわる定理などを適用することができる
  （具体的には？）--> 基底に含まれるベクトルの線形結合によって、元のベクトル空間（ベクトルの集合）に含まれる全てのベクトルを生成できる
  つまり、「基底->ベクトル空間, ベクトル空間->基底」という変換が可逆的
  これを利用して、膨大な集合である DP[i] をそのまま扱わず、基底に変換して管理することができるようになる！

  各ターンの DP[i] は本当にベクトル空間（基底から生成できる「全ての」ベクトルを含む集合。もちろん基底から生成できないベクトルは含まない）なのか？
  ・人1は何もできない or 空集合にする（人1の勝ちが確定）だけなので、人0が連続する場合を、ゲーム終了後から遡って考える（数学的帰納法のつもり）
  ・DP[N-1]（ゲーム終了後から1ターン遡った状態）: {aN-1}が生成する部分空間{0, aN-1} -> そこから先、次のaが一次従属ならDP変化なし（既に部分空間だから）。では次のaが一次独立なら？
  -> ターンを1遡る（今あるDPは残したまま、DPにxor a を加える）ことは、「あらゆるλ（0か1）の組合せについての(λ1a1+...+λpap)={a1, ..., ap}が生成する部分空間V の全てのベクトル および その全ての要素について xor a をしたベクトルの集合」と言える。この集合は{a1, ..., ap, a}から生成できる全てのベクトルの集合（数が2倍になっていることを考えると分かりやすい）なので、新しいDP[i]は次元p+1のベクトル空間と示せる！

*/

// ＜人1が「何もできない or 空集合にする」のはなぜか？＞
// 人1がiターン目に使えるベクトルをAiとする
// Ai ∉ DPなら、Ai はそのターンより後に人0が使うことができるベクトルに含まれない、新しい次元を持つベクトル（基底の次元を増やすようなベクトル）である
// ということは、人1としては、その「新しい次元」方向にベクトルを伸ばした状態で人0にターンを回せばいい。人0はそのベクトルを相殺できないので、人0の勝利が決まる
// ＜人1の最適行動＞
// (1) 人1に回されたベクトルが、Aiがもつ「新しい次元」方向のベクトルと同じ方向に飛び出たベクトルなら、そのベクトルを残したまま（つまりx^Aiで置き換えずに）回す
// (2) 人1に回されたベクトルが「新しい次元」方向に伸びていないベクトルなら、x^Aiで置き換えて（つまり、「新しい次元」方向にベクトルを伸ばして）回す

  ll T = il();

  rep(i, T){
    bool hito1_win = false;
    ll N = il();
    vector<ll> As;
    rep(i, N){
      As.push_back(il());
    }
    string S = is();
    vector<ll> Ss;
    rep(i, N){
      Ss.p_b((S[i] == '0' ? 0 : 1));
    }

    // iターン目の直前にそうであったら人0が勝てる集合
    // 0-indexed
    // DP[i].H でDP[i]に含まれるベクトル数が分かる
    vector<BitMatrix> DP(N+1);

    // DP[N] は {0}
    DP[N] = BitMatrix(1, 20);
    DP[N][0] = 0;

    // N-j = N-1 ~ 0 についてループ
    // 人1勝利になったらbreak
    // S ∈ DP[0] なら人0の勝ち（最終的にxが0になる）
    REP(j, 1, N+1){
      bitset<20> abitset = As[N-j];

      // DP[N-j+1] に As[i] を加えた集合
      BitMatrix tmp_bitmatr(DP[N-j+1].H + 1, 20);
      rep(k, DP[N-j+1].H) tmp_bitmatr[k] = DP[N-j+1][k];
      tmp_bitmatr[DP[N-j+1].H] = abitset;

      // その基底をとり、新しいrankを判定
      ll newrank = GaussJordan(tmp_bitmatr);

      // 人1の場合
      if (Ss[N-j]==1){
        // abitsetが新しい次元のベクトルであり、人0が勝つ場合が確定するかどうか
        // それは、DP[N-j+1]に新しいベクトルを加えて、rankが増えたかどうかで分かる
        if (newrank > DP[N-j+1].H){
          cout << 1 << endl;
          hito1_win = true;
          break;
        }
        // 勝利できなかったので、DP変化なし
        DP[N-j] = DP[N-j+1];        
      }
      if (hito1_win) break; 

      // 人0の場合、新しい基底がそのまま次のDPとなる
      // ただし、ゼロベクトルの行がゴミとして残っているので、それは削除する（newrank行目までDP[N-j]にコピーして、それより下の行は捨てる）
      // 新しい次元が増えなかった場合、tmp_bitmatr=DP[N-j+1]なので、変化なし
      DP[N-j] = BitMatrix(newrank, 20);
      rep(k, newrank) DP[N-j][k] = tmp_bitmatr[k];

    }
    // 人1が勝利していたら、0を表示せず次のターンへ
    if (hito1_win) continue;

    // DP[0]が求まったので、xの初期値=0が人0勝利条件のベクトル集合に含まれるかどうか判定
    // ……は実はしなくても、途中で人1が勝利していなければ0ベクトルは絶対にはじき出されていないので、人0の勝利が確定する
    cout << 0 << endl;

  }



