      REP(y,r,H)
    if(A[y][x])
      {
        pivot = y;
        break;
      }
      if(pivot == INT_MAX)continue;
      swap(A[r],A[pivot]);

      REP(y,r+1,H)
    {
      short value = A[y][x] * mod_inv(A[r][x],mod) % mod;
      if(value)REP(x2,x,W)
             A[y][x2] = ((A[y][x2] - A[r][x2] * value)%mod + mod ) % mod;
    }
      r++;
    }
  return r;
}



