int basis[L], bsize;

void prepare(int mask) {
  for(int i = 0; i < L; i++) {
    if((mask&(1ll<<i))) {
      if(!basis[i]) {
        basis[i] = mask; bsize++;
        return;
      }
      mask ^= basis[i];
    }
  }
}

bool ok(int mask) {
  for(int i = 0; i < L; i++) {
    if((mask&(1ll<<i))) {
      if(!basis[i]) {
        return 0;
      }
      mask ^= basis[i];
    }
  }
  return 1;
}

