vector<char> getOnes(vector<ll> &A){
	vector<char> B(60, false);
	int b = 0;
	for(int o = 59; o>=0; --o){
		ll m = 1ll<<o;
		for(int i = b; i < sz(A); ++i){
			if(A[i]&m){
				swap(A[i], A[b++]);
				B[o] = true;
				break;
			}
		}
		if(B[o]){
			for(int i = b; i < sz(A); ++i){
				if(A[i]&m) A[i] ^= A[b-1];
			}
		}
	}
	b--;
	for(int o = 0; o < 60; ++o){
		ll m = 1ll<<o;
		if(B[o]){
			for(int i = b-1; i >= 0; --i){
				if(A[i]&m) A[i] ^= A[b];
			}
			b--;
		}
	}
	return B;
}

