bool lc(vector<ll> A, ll y){
	ll x = 0;
	int i = 0;
	for(int o = 59; o >= 0; o--){
		ll m = 1ll << o;
		if((x&m) != (y&m)){
			while(i < sz(A) && !(A[i]&m))i++;
			if(i == sz(A)) break;
			x ^= A[i++];
		}
	}
	return x == y;
}

bool isP(vector<ll> L, vector<ll> R){
	vector<char> L1 = getOnes(L);
	vector<char> R1 = getOnes(R);
	//cerr << "L, R:\n"; printV(L); printV(R);
	//cerr << "L1, R1:\n"; printV(L1); printV(R1);
	for(int i = 0; i < 60; ++i){
		if(L1[i] && !R1[i]) return false;
	}
	for(int i = 0; i < sz(L); ++i){
		if(!lc(R, L[i])) return false;
	}
	return true;
}

