int get_msb(long long x) {
    assert(x != 0);
    return 63 - __builtin_clzll(x);
}
int get_lsb(long long x) {
    assert(x != 0);
    return __builtin_ctzll(x);
}

void GaussJordan(std::vector<Int> &A, bool is_extended = false) {
    Int rank = 0;
    for (Int col = 0; col < 62; ++col) {
        if (is_extended && col == 62 - 1) break;
        Int pivot = -1;
        for (Int row = rank; row < A.size(); ++row) {
            if (A[row] >> col & 1) {
                pivot = row;
                break;
            }
        }
        if (pivot == -1) continue;
        std::swap(A[pivot], A[rank]);
        for (Int row = 0; row < A.size(); ++row) {
            if (row != rank && (A[row] >> col & 1)) A[row] ^= A[rank];
        }
        ++rank;
    }
}
