    for (Int i = n - 1; i >= 0; i--) {
        if (s[i] == '0') {
            acc.push_back(a[i]);
            GaussJordan(acc);
        } else {
            while (a[i]) {
                Int ms = get_msb(a[i]);
                bool ok = false;
                for (Int x : acc) {
                    if (get_msb(x) == ms) {
                        a[i] ^= x;
                        ok = true;
                        break;
                    }
                }
                if (!ok) {
                    std::cout << 1 << "\n";
                    return;
                }
            }
        }
    }
    std::cout << 0 << "\n";
}
