const long long MAX_ROW = 64; // to be set appropriately
const long long MAX_COL = 256; // to be set appropriately
struct BitMatrix {
    long long H, W;
    bitset<MAX_COL> val[MAX_ROW];
    BitMatrix(long long m = 1, long long n = 1) : H(m), W(n) {}
    inline bitset<MAX_COL>& operator [] (long long i) {return val[i];}
};

ostream& operator << (ostream& s, BitMatrix A) {
    s << endl;
    for (long long i = 0; i < A.H; ++i) {
        for (long long j = 0; j < A.W; ++j) {
            s << A[i][j] << ", ";
        }
        s << endl;
    }
    return s;
}

long long GaussJordan(BitMatrix &A, bool is_extended = false) {
    long long rank = 0;
    for (long long col = 0; col < A.W; ++col) {
        if (is_extended && col == A.W - 1) break;
        long long pivot = -1;
        for (long long row = rank; row < A.H; ++row) {
            if (A[row][col]) {
                pivot = row;
                break;
            }
        }
        if (pivot == -1) continue;
        swap(A[pivot], A[rank]);
        for (long long row = 0; row < A.H; ++row) {
            if (row != rank && A[row][col]) A[row] ^= A[rank];
        }
        ++rank;
    }
    return rank;
}

long long linear_equation(BitMatrix A, vector<long long> b, vector<long long> &res) {
    long long m = A.H, n = A.W;
    BitMatrix M(m, n + 1);
    for (long long i = 0; i < m; ++i) {
        for (long long j = 0; j < n; ++j) M[i][j] = A[i][j];
        M[i][n] = b[i];
    }
    long long rank = GaussJordan(M, true);

    // check if it has no solution
    for (long long row = rank; row < m; ++row) if (M[row][n]) return -1;

    // answer
    res.assign(n, 0);
    for (long long i = 0; i < rank; ++i) res[i] = M[i][n];
    return rank;
}

const long long MOD = 1000000007;
long long modpow(long long a, long long n, long long mod) {
    long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}

