void normalize(vector<ll> &original, vector<ll> &tar) {
	vector<ll> basis;

	ll filter = 0LL;
	for(auto &elem: tar) filter |= elem;

	for(auto &elem: original) {
		if((filter | elem) == filter) {
			basis.push_back(elem);
		}
	}
	original.clear();

	const int n = basis.size();
	const int m = 60;
	const int l = tar.size();


	rep(i, n) {
		ll cmax = basis[i], pos = i;
		rep(j, i + 1, n) if(chmax(cmax, basis[j])) pos = j;
		if(cmax == 0) break;
		swap(basis[i], basis[pos]);

		int col = m - 1;
		while(col >= 0 and (((basis[i] >> col) & 1) == 0)) col--;

		rep(j, i + 1, n) {
			if((basis[j] >> col) & 1) {
				basis[j] ^= basis[i];
			}
		}

		rep(k, l) {
			if((tar[k] >> col) & 1) {
				tar[k] ^= basis[i];
			}
		}
	}
}

