}

typedef long long ll;
const int maxn = 205;
int n;
ll A[maxn];
char str[maxn];

int cnt;
ll val[maxn];

void ins(ll x) {
  per(i, 60, 0) if (x >> i & 1) {
    if (val[i]) {
      x ^= val[i]; continue;
    }
    rep(j, 0, i - 1) if (x >> j & 1) x ^= val[j];
    rep(j, i + 1, 60) if (val[j] >> i & 1) val[j] ^= x;
    val[i] = x, cnt++;
    return;
  }
}

void solve() {
  vector <ll> v0, v1;
  cin >> n;
  rep(i, 1, n) scanf("%lld", A + i);
  scanf("%s", str + 1);
  rep(i, 1, n) if (A[i]) {
    if (str[i] == '0') {
      v0.push_back(A[i]);
    } else {
      v1.push_back(A[i]);
    }
  }
  cnt = 0;
  memset(val, 0, sizeof val);
  for (ll x : v1) {
    ins(x);
  }
  int tmp = cnt;
  for (ll x : v0) {
    ins(x);
  }
  puts(tmp != cnt ? "1" : "0");
}

int main() {
  int T = read();
  while (T--) solve();
  return 0;
}

