bool binary_basis_insert(std::vector<i64>& w, i64 a) {
	for (auto v : w) {
		if (v & (-v) & a) {
			a ^= v;
		}
	}
	if (a == (i64)0) return false;
	for (auto& v : w) {
		if (a & (-a) & v) {
			v ^= a;
		}
	}
	w.emplace_back(a);
	return true;
}

