vector<u64> reduce(vector<u64> mat, int m = 62) {
  int n = mat.size();

  vector<u64> ret;
  int r = 0;
  for (int i = 0; i < m; ++i) {
    int k = -1;
    for (int j = r; j < n; ++j) {
      if ((mat[j] >> i) & 1) {
        k = j;
        break;
      }
    }
    if (k == -1) continue;

    swap(mat[k], mat[r]);

    for (int l = 0; l < n; ++l) {
      if (l != r && ((mat[l] >> i) & 1)) {
        mat[l] ^= mat[r];
      }
    }
    ret.push_back(mat[r]);
    r++;
  }
  return ret;
}

bool solve(vector<u64>& A, string S) {
  int N = A.size();

  vector<u64> T;
  for (int i = N - 1; i >= 0; --i) {
    if (S[i] == '1') {
      T.push_back(A[i]);
      if (reduce(T).size() == T.size()) return false;
      T.pop_back();
    } else {
      T.push_back(A[i]);
      T = reduce(T);
    }
  }
  return true;
}

