int solve(){
  int N; cin >>N;
  vector<ll> A(N); rep(i, N) cin >>A[i];
  string s; cin >>s;
  // 最後が人1ならうまくやって\neq 0 にできる
  if (s[N-1] == '1') return 1;
  // dp[i][j] := i回終わって値jにできる
  // 後ろから見ていって、0たち, 1たち, 0たち, 1たち, ... の感じで見ていく
  // xorによって変化する位の組について、0たちのものが1たちものを完全にカバーできていれば0の勝ち
  map<ll,int> nums,nums2;
  for (int i=N-1; i>=0; i--){
    // cerr <<"i = " <<i <<endl;
    if (s[i] == '0'){
      for (auto p : nums){
        nums2[p.first] = 1;
        nums2[A[i]^p.first] = 1;
      }
      nums2[A[i]] = 1;
      // for (auto p : nums2) cerr <<p.first <<" ";
      // cerr <<endl;
      swap(nums,nums2);
      nums2.clear();
    }else{
      if (!nums.count(A[i])) return 1;
    }
  }
  return 0;
}

void operate(map<ll,int> &nums, set<ll> &bn0){
  // numsのうち、bn0のxorを使って消せるものは消す
  map<ll,int> nums2 = nums;
  vector<ll> a(nums2.size());
  {
    int i=0;
    for (auto p : nums2) a[i++] = p.first;
  }
  {
    int i=0;
    for (auto p : nums2){
      swap(a[0],a[i++]);
      int k = p.first;
      // kを使ったnums2中のxor演算をした結果のなかでbn0のなかにあるものがあれば k をサヨナラできる
      set<ll> tmp1,tmp2;
      tmp1.insert(a[0]);
      for (int j=1; j<a.size(); j++){
        for (auto v : tmp1){
          tmp2.insert(v);
          tmp2.insert(v^a[j]);
        }
        swap(tmp1,tmp2);
      }
      for (auto v : tmp1){
        if (bn0.count(v)){
          nums.erase(p.first);
          break;
        }
      }
    }
  }

}

