bool solvable(vector<int> &bs) {
	vector<vector<int> > a = spb;
	int n = bs.size();
	int m = a[0].size();
	int cur = 0;
	for (int i = 0; i < n; ++i) {
		// cout << "i = " << i << endl;
		int firstOne = -1;

		for (int j = cur; j < m; ++j) {
			if (a[i][j]) {
				firstOne = j;
				break;
			}
		}
		// cout << "here" << endl;
		if (firstOne == -1) {
			if (bs[i]) {
				return false;
			}
			continue;
		}
		// cout << "here" << endl;
		if (firstOne != cur) {
			for (int j = 0; j < n; ++j) {
				swap(a[j][firstOne], a[j][cur]);
			}
		}
		// cout << "here" << endl;

		// now we have a[i][cur] == 1
		for (int j = i + 1; j < n; ++j) {
			if (a[j][cur]) {
				for (int k = cur; k < m; ++k) {
					a[j][k] ^= a[i][k];
				}
				bs[j] ^= bs[i];
			}
		}
		// cout << "here" << endl;
		++cur;
	}
	return true;
}

