vector<vector<ll>> mk_block(string& S, vector<ll>& A) {
  vector<vector<ll>> res = {};
  bool start = false;
  char before = '1';
  vector<ll> temp = {};
  for (ll i = 0; i < S.size(); ++i) {
    if (!start && S[i] == '0') {
      continue;
    }
    else {
      start = true;
    }
    if (S[i] == before) {
      temp.push_back(A.at(i));
    }
    else {
      res.push_back(temp);
      temp = {};
      temp.push_back(A.at(i));
    }
    before = S[i];
  }
  if (start && (temp.size() != 0)) {
    res.push_back(temp);
  }
  return res;
}

