typedef long long ll;

void Canonize(vector<ll>& a) {
  for (;;) {
    bool ok = true;
    for (int i = 0 ; i < a.size(); ++i) for (int j = 0; j < a.size(); ++j) if (i != j) {
      if ((a[i] ^ a[j]) < a[i]) {
        a[i] ^= a[j];
        ok = false;
      }
    }
    if (ok) return;
  }
}

