bool HasBit(ll x, int b) {
    return (x >> b) & 1;
}

class XorSet {
public:
    static constexpr int kMaxBit = 60;

    XorSet() : basis(kMaxBit, 0) {
    }

    void Insert(ll val) {
        for (int b = 0; b < kMaxBit; ++b) {
            if (HasBit(val, b)) {
                if (basis[b] == 0) {
                    basis[b] = val;
                    ++size;
                    return;
                }
                val ^= basis[b];
            }
        }
    }

    int Size() const { return size; }

    bool Contains(ll val) {
        for (int b = 0; b < kMaxBit; ++b) {
            if (HasBit(val, b)) {
                if (basis[b] == 0) {
                    return false;
                }
                val ^= basis[b];
            }
        }
        return true;
    }

    void Cross(ll val) {
        if (has_0) {
            Insert(val);
        }
        for (ll b : basis) {
            Insert(b ^ val);
        }
    }

    void AddZero() {
        has_0 = true;
        ++size;
    }

private:
    vector<ll> basis;
    int size = 0;
    bool has_0 = false;
};

