vector<lint> cal(vector<lint> x){
	int rank=0;
	rep(i,63){
		if(rank>=x.size()) break;
		REP(j,rank,x.size()){
			if((x[j]&(1L<<i))) swap(x[rank],x[j]);
		}
		if(!(x[rank]&(1L<<i))) continue;
		rep(j,x.size()){
			if(j==rank) continue;
			if((x[j]&(1L<<i))) x[j]^=x[rank];
		}
		rank++;
	}
	REP(i,rank,x.size()){
		assert(x[i]==0L);
	}
	//x.resize(rank);
	//return x;
	vector<lint> ret;
	rep(i,rank) ret.pb(x[i]);
	return ret;
}
bool ng(lint y,vector<lint> x){
	//cout<<y<<' '<<x<<endl;
	lint f=0;
	rep(i,x.size()){
		f|=(y&x[i]);
		if(((y&x[i])>0L) && ((y&x[i])<x[i])) return true;
	}
	if(f<y) return true;
	return false;
}
