ll dp[N][2][2][2][2];
ll bit1, bit2 , bit3, bit4;
ll solve(ll idx,ll x,ll y, ll z, ll zz )
{
    if(idx==n)
    {
        return x==0&&y==0&& z==0 && zz==0;
    }
    ll &ret = dp[idx][x][y][z][zz];
    if(ret!=-1)
    {
        return ret;
    }
    ll ache =0,ache2 =0, ache3 =0, ache4 =0;
    if(a[idx]&(1ll <<bit1))
    {
        ache = 1;
    }
    if(a[idx]&(1ll <<(bit2)))
    {
        ache2 = 1;
    }
    if(a[idx]&(1ll <<(bit3)))
    {
        ache3 = 1;
    }
    if(a[idx]&(1ll <<(bit4)))
    {
        ache4 = 1;
    }
    if(s[idx]=='1')
    {
        if(!solve(idx+1, x^ache, y^ache2,z^ache3,zz^ache4) || !solve(idx+1, x, y,z,zz))
            return ret = 0;
        return ret = 1;
    }
    else
    {
        if(solve(idx+1, x^ache, y^ache2,z^ache3,zz^ache4) || solve(idx+1, x, y,z,zz))
            return ret = 1;
        return ret = 0;
    }
}
