const int d = 63;

int basis[d];

void insertVector(ll mask) {
	for (int i = 0; i < d; i++) {
		if ((mask & (1ll << i)) == 0) continue;
		if (!basis[i]) { 
			basis[i] = mask;
			return;
		}
		mask ^= basis[i];
	}
}

bool check(ll val) {
	for (int i = 0; i < d; ++i) {
		if ((val & (1ll << i)) == 0) continue;
		if (!basis[i]) return false;
		val ^= basis[i];
	}
	return true;
}

void solve() 
{
	int t;
	cin >> t;
	while (t--) {
		for (int i = 0; i < d; ++i) {
			basis[i] = 0;
		}
		int n;
		cin >> n;
		vector<ll> a(n);
		for (int i = 0; i < n; ++i) {
			cin >> a[i];
		}
		string s;
		cin >> s;
		int f = 1;
		for (int i = n - 1; i >= 0; --i) {
			if (s[i] == '1') {
				if (!check(a[i])) f = 0;
				//cout << a[i] << endl;
			} else {
				insertVector(a[i]);
				//cout << a[i] << endl;
			}
		}
		cout << (f ^ 1) << endl;
	}
}

