        basis[firstpos] = nelem;
        lg(basis);
        return true;
    } else if(prev==nelem){
        llog("nothing to add");
        return false;
    } else {
        nelem ^= prev;
        return modify_basis(nelem, basis);
    }
}

void remove_from_basis(ll nelem, d(ll, ll)& basis){
