    auto inc = [&](ll x) {
        for (int i = 61; i >= 0; i--) {
            if (x & (1LL << i)) {
                if (base[i] == 0) {
                    base[i] = x;
                    return true;
                }
                x ^= base[i];
            }
        }
        return false;
    };
    for (int i = n - 1; i >= 0; i--) {
        bool f = inc(v[i]);
        if (f && s[i] == '1') {
            pr.writeln('1');
            return;
        }
    }
