int MSB64bit(ll a){
    bitset<64> v(a);
    v |= (v>>1);
    v |= (v>>2);
    v |= (v>>4);
    v |= (v>>8);
    v |= (v>>16);
    v |= (v>>32);
    return v.count()-1;
}

ll hakidasi(ll a, vector<ll> dp){

    int asize = MSB64bit(a);

    if(dp.size()==1){
        return a;
    }

    rep(i,dp.size()-1){
        int isize = MSB64bit(dp[i]);

        if(asize>isize)return a;
        if(asize<isize)continue;

        if(asize==isize){
            a ^= dp[i];
            if(a==0)return 0;
            asize = MSB64bit(a);
        }
    }
    return a;
}

