// Forma esglaonada reduida. Les columnes amb
// el primer no-zero de cada fila son (0..1..0).
int gauss(VVT mat) {
  int r = mat.size(), c = mat[0].size();
  int i,j;
  for (i = 0, j = 0; i < r and j < c; ++j) {
    int nz = i;
    for (int k = i + 1; k < r; ++k) {
      if (abs(mat[nz][j]) < abs(mat[k][j])) nz = k;
    }
    if (abs(mat[nz][j]) < 1) continue;
    swap(mat[i], mat[nz]);
    for (int k = 0; k < r; ++k) if (k != i and abs(mat[k][j])) {
      for (int w = j; w < c; ++w)
        mat[k][w] ^= mat[i][w]; // idem
    }
    ++i;
  }
  return i;
}

