bool subset(ll x, ll y){
	if (x == y) return true;
	//check x subset of y
	while (x > 0){
		//cout << "here" << endl;
		if ((x%2) > (y%2)) return false;
		x = (x >> 1);
		y = (y >> 1);
	}
	return true;
}

