ll f(ll i, ll n, vector<ll> &a, string &s) {
    if (i == a.size()-1) {
        if (s[i] == '0') {
            if (n == 0) return 0;
            else if ((n ^ a[i]) == 0) return 0;
            else return 1;
        }
        else {
            return 1;
        }
    }
    else {
        int x = f(i+1,n ^ a[i],a,s);
        int y = f(i+1,n,a,s);
        if (s[i] == '0') {
            if (x == 0 || y == 0) return 0;
            else return 1;
        }
        else {
            if (x == 1 || y == 1) return 1;
            else return 0;
        }
    }
}

