vector<long long> func(vector<long long> A){
	int last = 0;
	for(long long i=60;i>=0;i--){
		int ind = -1;
		for(int j=last;j<A.size();j++){
			if((A[j]>>i) & 1LL){
				swap(A[j],A[last]);
				ind = last;
				last++;
				break;
			}
		}
		if(ind==-1)continue;
		for(int j=0;j<A.size();j++){
			if(j!=ind){
				if((A[j]>>i)&1LL){
					A[j] ^= A[ind];
				}
			}
		}
	}
	while(A.back()==0)A.pop_back();
	return A;
}

bool check(vector<long long> &X,vector<long long> &Y){
	for(long long i=0;i<=60;i++){
		bool f= false;
		for(int j=0;j<Y.size();j++){
			if((Y[j]>>i)&1LL){
				f=true;
				break;
			}
		}
		if(!f)continue;
		f=false;
		for(int j=0;j<X.size();j++){
			if((X[j]>>i)&1LL){
				f=true;
				break;
			}
		}
		if(!f)return false;
	}

	for(long long i=0;i<=60;i++){
		for(long long j=0;j<=60;j++){
			bool f = false;
			for(int k=0;k<Y.size();k++){
				if(((Y[k]>>i)&1LL)^((Y[k]>>j)&1LL)){
					f=true;
					break;
				}
			}
			if(!f)continue;
			int I = -1;
			int J = -1;
			for(int k=0;k<X.size();k++){
				if((X[k]>>i)&1LL){
					assert(I==-1);
					I = k;
				}
				if((X[k]>>j)&1LL){
					assert(J==-1);
					J = k;
				}
			}
			if(I==J)return false;
		}
	}

	return true;
}

