void binary_basis_insert(vector<ulint>& w, ulint a) {
    for(auto v : w) {
        if(v & (-v) & a) {
            a ^= v;
        }
    }
    if(a == 0) {
        return;
    }
    for(auto& v : w) {
        if(a & (-a) & v) {
            v ^= a;
        }
    }
    w.push_back(a);
}

bool binary_basis_check(vector<ulint>& w, ulint a){
    for(auto v : w) {
        if(v & (-v) & a) {
            a ^= v;
        }
    }
    if(a == 0) return false;
    return true;
}

vector<ulint> binary_basis(vector<ulint>& w) {
    vector<ulint> res;
    for(auto v : w) {
        binary_basis_insert(res, v);
    }
    return res;
}


int solve(int n, vector<ulint>& a, string s){
    if(s[n-1] == '1') return 1;
    int now = s[0]-'0';
    vector<ulint> basis;
    vector<ulint> tmp;
    rep(i, n){
        if((s[i]-'0') != now){
            auto bb = binary_basis(tmp);
            if(now == 0){
                vector<ulint> tmq;
                for(ulint b : basis) if(binary_basis_check(bb, b)) tmq.push_back(b);
                basis = binary_basis(tmq);
            }else{
                for(ulint b : bb) binary_basis_insert(basis, b);
            }
            tmp.clear();
            now ^= 1;
        }
        tmp.push_back(a[i]);
    }
    if(!tmp.empty()){
        auto bb = binary_basis(tmp);
        if(now == 0){
            vector<ulint> tmq;
            for(ulint b : basis) if(binary_basis_check(bb, b)) tmq.push_back(b);
            basis = binary_basis(tmq);
        }else{
            for(ulint b : bb) binary_basis_insert(basis, b);
        }
    }
    if(basis.empty()) return 0; else return 1;
}

