                }

                if ((a & (a - 1)) == 0)
                {
                    kiso |= a;
                    kisos.insert(a);
                }
                else
                {
                    ok.insert(a);
                    ok2.push_back(a);
                }

                ok2.clear();
                for (ll k : ok) ok2.push_back(k);

                for (ll k : ok2)
                {
                    if ((~kiso & k) == 0) ok.erase(k);
                }

