            }
            else if (S[_j - 1] == '1')
            {
                if (((~kiso & a) != 0) && ok.count(a) == 0)
                {
                    failed = true;
                    break;
                }
            }
        }

        cout << (failed ? 1 : 0) << endl;
    }
}

