int dp[N][2];
bool B[N];
int n;

int solve(int pos, bool bit) {
    if(pos == n) return bit;
    if(dp[pos][bit] != -1) return dp[pos][bit];
    bool who = false;
    who |= (solve(pos+1, bit^B[pos]) == (S[pos] - '0'));
    who |= (solve(pos+1, bit) == (S[pos] - '0'));
    return dp[pos][bit] = (S[pos]-'0')^1^who;
}


