int a[1234];
int repr[1234],found[1234];
int addit(int val){
	int i;
	fd(i,62,0){
		if((1LL<<i)&val){
			if(found[i]){
				val^=repr[i];
			}
			else{
				found[i]=1;
				repr[i]=val;
				return 0;
			}
		}
	}
	return 0;
}

int checkit(int val){
	int i;
	fd(i,62,0){
		if((1LL<<i)&val){
			if(found[i]){
				val^=repr[i];
			}
			else{
				return 1;
			}
		}
	}
	return 0;
}

