		unsigned long long x = 0;
		int ans;

		for(int i = 0; i < N[k]; i++){
			if(S[k][i] == '0'){
				// x = 0となるように操作をする
				if(x == 0){
				}
				else if((x ^ A[k][i]) == 0)
					x ^= A[k][i];
				else{
					int tmp1 = 0, tmp2 = 0;

					for(int j = 0; j < 63; j++){
						if((x & (1 << j)) >> j == 1)
							tmp1++;
						if(((x ^ A[k][i]) & (1 << j)) >> j == 1)
							tmp2++;
					}
					if(tmp2 < tmp1)
						x ^= A[k][i];
				}
			}
			else{ // if(S[k][i] == '1'){
				// x != 0となるように操作をする
