	void clear(){
		memset(b,0,sizeof(b));
	}
	void add(long long x){
		for(int i=mlog-1;i>=0;i--){
			if(!((x>>i)&1))continue;
			if(b[i])x^=b[i];
			else{
				b[i]=x;
				break;
			}
		}
	}
	bool ask(long long x){
		for(int i=mlog-1;i>=0;i--){
			if(!((x>>i)&1))continue;
			if(b[i])x^=b[i];
		}
		return x==0;
	}
}

