int gauss (vector<unsigned long long> a, int n, int m=64) {    
    int rank = m;
    vector<char> line_used (n);
    for (int i=0; i<m; ++i) {
        int j;
        for (j=0; j<n; ++j)
            if (!line_used[j] && (a[j] & (1ULL << i)))
                break;
        if (j == n)
            --rank;
        else {
            line_used[j] = true;
            for (int k=0; k<n; ++k)
                if (k != j && (a[k] & (1ULL << i)))
                    a[k] ^= a[j];
        }
    }
    return rank;
}


