int game(vector<int>&ar, string &s, int x, int i) {
    if(i == ar.size()) {
        if(x > 0)
            return 1;
        else 
            return 0;
    } else {
        int g = 0;
        if(s[i] == '1' and __builtin_popcount(x) <= __builtin_popcount(x^ar[i]))
            g = game(ar, s, x^ar[i], i+1);
        else if(s[i] == '0' and __builtin_popcount(x) >= __builtin_popcount(x^ar[i]))
            g = game(ar, s, x^ar[i], i+1);
        else 
            g = game(ar, s, x^ar[i], i+1) and game(ar, s, x, i+1);
        return g;
    }
}

