ll basis[64]; 
int sz; 
ll basis2[64];
void insertVector(ll mask) {
    for (int i = 0; i < d; i++) {
        ll zz=pow(2,i);
        if ((mask & zz) == 0) continue; // continue if i != f(mask)
        if (!basis[i]) { // If there is no basis vector with the i'th bit set, then insert this vector into the basis
            basis[i] = mask;
            ++sz;   
            return;
        }
        mask ^= basis[i]; 
    }
}
void insertVector2(ll mask) {
    for (int i = 0; i < d; i++) {
        ll zz=pow(2,i);
        if ((mask & zz) == 0) continue; // continue if i != f(mask)
        if (!basis2[i]) { // If there is no basis vector with the i'th bit set, then insert this vector into the basis
            basis2[i] = mask;
            ++sz;   
            return;
        }
        mask ^= basis2[i]; 
    }
}
