vll get_prefix_array(string s){
    ll n=s.size();
    vll ans(n,0);
    ll j=0,i=1;
    while(i<n){
        if(s[i]==s[j]){
            ans[i]=j+1;
            i++;
            j++;
        }
        else{
            if(j!=0){
                j=ans[j-1];
            }
            else{
                ans[i]=0;
                i++;
            }
        }
    }
    return ans;
}
bool is_present(string text,string pattern){
    ll p=text.size();
    ll q=pattern.size();
    vll temp=get_prefix_array(pattern);
    ll i=0,j=0;
    while(i<p && j<q){
        if(text[i]==pattern[j]){
            i++;
            j++;
        }
        else{
            if(j!=0)
                j=temp[j-1];
            else
                i++;
        }
    }
    if(j==q)
        return true;
    return false;
}
