ll parent[51]={0};
ll siz[51]={0};
void make_set(ll x){
     parent[x]=x;
     siz[x]=1;
 }
 ll find_set(ll x){
     if(x==parent[x])
         return x;
     return parent[x]=find_set(parent[x]);
 }
 void union_sets(ll a,ll b){
     ll p=find_set(a);
     ll q=find_set(b);
     if(p==q)
         return;
     if(siz[p]<siz[q])
         swap(p,q);
     parent[q]=p;
     siz[p]+=siz[q];
 }


