int solve3(vector<int> &A, string &S, map<pair<int,int>,int> &mp, int depth = 0, int x = 0){
	if(depth == A.size()) {
		return !!x;
	}

	if(mp[{depth,x}]) return mp[{depth,x}]-1;


	if(S[depth] == '0') {
		if(solve3(A, S, mp, depth+1, x ^ A[depth]) == 0){
			mp[{depth,x}] = 1;
			return 0;
		}
		if(solve3(A, S,mp, depth+1, x) == 0) {
			mp[{depth,x}] = 1;
			return 0;
		}
		mp[{depth,x}] = 2;
		return 1;
	} else {
		if(solve3(A, S, mp, depth+1, x ^ A[depth]) == 1) {
			mp[{depth,x}] = 2;
			return 1;
		}

		if(solve3(A, S, mp, depth+1, x) == 1) {
			mp[{depth,x}] = 2;
			return 1;
		}
		mp[{depth,x}] = 1;
		return 0;
	}
}


