void Canonize(vector<ll>& a) {
  //cerr << "Canonize before: "; for (ll x : a) cerr << x << " "; cerr << endl;
  for (;;) {
    bool ok = true;
    for (ll i = 0 ; i < a.size(); ++i) for (ll j = 0; j < a.size(); ++j) if (i != j) {
      if ((a[i] ^ a[j]) < a[i]) {
        a[i] ^= a[j];
        ok = false;
      }
    }
    if (ok) {
      //cerr << "Canonize after: "; for (ll x : a) cerr << x << " "; cerr << endl;
      return;
    }
  }
}

