int pow(int a, int b){
    int ans = 1;
    while(b){
        if(b & 1)ans = 1LL * ans * a % mod;
        a = 1LL * a * a % mod;
        b >>= 1;
    }
    return ans;
}
int pow(int a, ll b, int c){
    int ans = 1;
    while(b){
        if(b & 1)ans = 1LL * ans * a % c;
        a = 1LL * a * a % c;
        b >>= 1;
    }
    return ans;
}

unordered_map<ll, int> dp[202];
ll b[202], a[202];
char s[202];
int solve(int x, int n, ll v, ll a[]){
  if(dp[x].count(v))return dp[x][v];
  if(x == n-1){
    if(v == 0 || v == a[x])return dp[x][v] = 0;
    return dp[x][v] = 1;
  }
  if(s[x] == '1'){
    int p = solve(x+1, n, v, a);
    if(p) return dp[x][v] = 1;
    int q = solve(x+1, n, v ^ a[x], a);
    if(q)return dp[x][v] = 1;
    return dp[x][v] = 0;
  }
  else{
    int p = solve(x+1, n, v, a);
    if(p == 0)return dp[x][v] = 0;
    int q = solve(x+1, n, v ^ a[x], a);
    if(q == 0)return dp[x][v] = 0;
    return dp[x][v] = 1;
  }
}
