int solve() {
  int N; cin >> N;
  vector<LL> A(N); cin >> A;
  string S; cin >> S;

  set<LL> X, Y;  // X: 0, Y: 1
  for (int i = N - 1; i >= 0; --i) {
    if (S[i] == '0') {
      if (X.count(A[i])) continue;
      for (LL x : X) {
        X.insert(x ^ A[i]);
      }
      X.insert(A[i]);
    } else {
      if (Y.count(A[i])) continue;
      if (!X.count(A[i])) return 1;
      for (LL y : Y) {
        LL v = y ^ A[i];
        if (!X.count(v)) return 1;
        Y.insert(v);
      }
      Y.insert(A[i]);
    }
  }
  return 0;
}

