void query() {
  int n; cin >> n;
  vector<bitset<64>> arr;
  rep(i,n) {
    ll a; cin >> a;
    arr.emplace_back(a);
  }
  string s; cin >> s;

  vb player(n);
  rep(i,n) player[i] = s[i] == '1';

  if (player.back()) {
    cout << 1 << "\n";
    return;
  }

  Graph<bitset<64>> hand(2);
  bool now = false;
  int idx = n-1;

  while (idx >= 0) {
    hand[now].emplace_back(arr[idx]);
    if (--idx >= 0 && player[idx] == now) continue;

    int sz = hand[now].size();
    int cnt = 0;

    rrep(i,64) {
      REP(j,cnt,sz-1) {
        if (hand[now][j][i]) {
          swap(hand[now][j], hand[now][cnt]);
          rep(k,sz) {
            if (k != cnt && hand[now][k][i]) {
              hand[now][k] ^= hand[now][cnt];
            }
          }
          ++cnt;
          break;
        }
      }
    }

    while (hand[now].back().none()) hand[now].pop_back();

    if (now) {
      for (auto one : hand[1]) {
        for (auto &zero : hand[0]) {
          if ((one & zero).any()) {
            one ^= zero;
          }
        }
        if (one.any()) {
          cout << 1 << "\n";
          return;
        }
      }
    }

    now ^= true;
  }

  cout << 0 << "\n";
}

