  vector <ll> nxt;
  bool added = false;
  for (auto it : basis) {
    if (val && !added) {
      if (leading(val) < leading(it)) {
        nxt.push_back(val);
        added = true;
      }
      else if (leading(val) == leading(it))
        val ^= it;
    }
    nxt.push_back(it);
  }
  if (val && !added) {
    nxt.push_back(val);
    added = true;
  }
  basis = nxt;
  return added;
}

