int sz1, sz2;

void insertVector1(int mask) {
	for (int i = 0; i < d; i++) {
		if ((mask & 1ll << i) == 0) continue;
		if (!basis1[i]) {
			basis1[i] = mask;
			++sz1;

			return;
		}
		mask ^= basis1[i];
	}
}
void insertVector2(int mask) {
	for (int i = 0; i < d; i++) {
		if ((mask & 1ll << i) == 0) continue;

		if (!basis2[i]) {
			basis2[i] = mask;
			++sz2;

			return;
		}

		mask ^= basis2[i];
	}
}
