using namespace std;
typedef long long ll;


bool Solve(int N, vector<ll>& nums, string& moves, int index, ll runningSum, std::unordered_map<int, unordered_map<ll, bool>>& memo)
{
    if(index == int(moves.length()))
    {
	return runningSum == 0;
    }

    if(memo.find(index) != memo.end() && memo[index].find(runningSum) != memo[index].end()) return memo[index][runningSum];

    if(moves[index] == '0')
    {
	if(Solve(N, nums, moves, index+1, runningSum, memo) || Solve(N, nums, moves, index+1, runningSum ^ nums[index], memo))
	    return memo[index][runningSum] = true;
	else
	    return memo[index][runningSum] = false;

    }
    else
    {
	if(!Solve(N, nums, moves, index+1, runningSum, memo) || !Solve(N, nums, moves, index+1, runningSum ^ nums[index], memo))
	    return memo[index][runningSum] = false;
	else
	    return memo[index][runningSum] = true;
    }

    return memo[index][runningSum] = true;
}

