      scanf("%lld", &a[i]);
      dp[i].clear();
    }

    getchar();
    for(int i = 0; i < N; ++i) {
      char ch;
      scanf("%c", &ch);

      if(ch == '1') s[i] = 1;
      else s[i] = 0;
    }

    dp[N].insert(0);
    for(int i = N - 1; i >= 0; --i) {
      if(s[i]) {
        if(dp[i + 1].find(a[i]) == dp[i + 1].end()) {
          dp[i].clear();
        } else {
          dp[i] = dp[i + 1];
        }
      } else {
        dp[i] = dp[i + 1];
        for(int v: dp[i + 1]) dp[i].insert(v ^ a[i]);
      }
    }

    if(dp[0].find(0) == dp[0].end()) printf("1\n");
    else printf("0\n");
  }
