	for (int z = 0; z < t; ++z) {
		int n; cin >> n;
		vector<int> a(n);
		for (int i = 0; i < n; ++i) {
			cin >> a[i];
		}
		string s; cin >> s;
		if (s[s.size()-1] == '1') {
			cout << 1 << "\n";
			continue;
		}
		BitMatrix zero(60, n), one(60, n);
		int z_cnt, o_cnt;
		for (int i = 0; i < n; ++i) {
			if (s[i] == '1') {
				for (int j = 0; j < 60; ++j) {
					if ((a[i] >> j) & 1) one[o_cnt][j] = 1;
				}
				o_cnt++;
			}
			for (int j = 0; j < 60; ++j) {
				if ((a[i] >> j) & 1) zero[z_cnt][j] = 1;
