class LinearBasis{
public:
	ll val[logn];
	LinearBasis(){ memset(val, 0, sizeof(val)); return; }
	inline void insert(ll x){
		for(int i = logn - 1; i >= 0; --i) if(x >> i & 1){
			if(val[i]) x ^= val[i];
			else{
				val[i] = x;
				break;
			}
		}
		return;
	}
	inline bool query(ll x){
		for(int i = logn - 1; i >= 0; --i) if(x >> i & 1){
			if(!val[i])
				return false;
			x ^= val[i];
		}
		return true;
	}
}lb;

