// 中身付きランレングス圧縮 O(N * (中身の比較+コピー))
template <class Iterator>
vector<pair<size_t, typename remove_reference<decltype(*Iterator())>::type>> run_length(Iterator first, Iterator last) {
    vector<pair<size_t, typename remove_reference<decltype(*Iterator())>::type>> rl;
    for (Iterator itr = first; itr != last; ) {
        size_t current_length = 1;
        Iterator jtr = itr++;
        while ((itr != last && *itr == *(itr-1))) itr++, current_length++;
        rl.emplace_back(current_length, *jtr);
    }
    return rl;
}

// XOR基底
void xor_bases(vector<ll> &b) {
    ll w = b.size();
    ll v = 0;
    DSRNG(j, 62, 0) {
        ll vp = -1;
        RANGE(vpp, v, w-1) {
            if (b[vpp] >> j & 1) {
                vp = vpp;
                break;
            }
        }
        if (vp != -1) {
            swap(b[v], b[vp]);
            REP(vq, w) if (vq != v) {
                if (b[vq] >> j & 1) {
                    b[vq] ^= b[v];
                }
            }
            v++;
        }
        if (v >= w) break;
    }
    sort(ALL_OF(b), greater<ll>());
    while (b.back() == 0) b.pop_back();
}

bool issafe(const vector<ll> &r0, const vector<ll> &r1) {
    FOREACH(x, r1) {
        auto itr = lower_bound(ALL_OF(r0), x, greater<ll>());
        if (itr == r0.end() || *itr != x) {
            return false;
        }
    }
    return true;
}

