template<typename T>
struct xorset {
    vector<T> basis;
    int BITS;
    vi rev;

    xorset() : BITS(sizeof(T)*8), rev(sizeof(T)*8, -1) {}


    void sweep(){
        int L = basis.size();
        sort(ALL(basis), greater<T>());
        vector<int> used(L, -1); int ucnt = 0;
        for (int b=BITS-2; b>=0; --b){
            T m = 1LL << (ll)b;
            rep(i,L){
                if (basis[i] == 0) { ++ucnt; continue; }
                if (used[i] != -1) continue;
                if (basis[i] & m) {
                    rep(j,L){
                        if (j==i) continue;
                        if (basis[j] & m){
                            basis[j] ^= basis[i];
                        }
                    }
                    used[i] = b; ++ucnt;
                    break;
                }
            }
        }
        assert(ucnt == L);

        map<T,int> tmp;
        rep(i,L){
            if (used[i] == -1) continue;
            tmp[ basis[i] ] = used[i];
        }

        basis.clear();
        for (auto& p: tmp){
            T val = p.first;
            int b = p.second;
            rev[b] = basis.size();
            basis.pb(val);
        }

    }
    void insert(T x){
        if (this->has(x)) return;
        basis.pb(x);
        sweep();
    }
    bool has(T x){
        bool res = false;
        if (x == 0) {
            res = true;
        } else {
            for(int b=BITS-2; b>=0; --b){
                T m = 1LL << (ll)b;
                if (!(x & m)) continue;
                assert(x & m);

                if (rev[b] == -1) {
                    res = false; break;
                }
                T ba = basis[rev[b]];
                assert(ba & m);
                assert(ba & x);
                x ^= ba;
            }
            if (x == 0) res = true;
