int solve() {
  int N; cin >> N;
  vector<LL> A(N); cin >> A;
  string S; cin >> S;

  set<LL> X, Y;  // X: 0, Y: 1
  int b[65] = {};
  for (int i = N - 1; i >= 0; --i) {
    if (S[i] == '0') {
      if (X.count(A[i])) continue;

      bool no_change = true;
      bitset<65> bit(A[i]);
      for (int i = 0; i < 65; ++i) {
        if (bit.test(i) && b[i] < 4) {
          no_change = false;
          b[i]++;
        }
      }
      if (no_change) continue;

      for (LL x : X) {
        X.insert(x ^ A[i]);
      }
      X.insert(A[i]);
    } else {
      if (Y.count(A[i])) continue;

      bool no_change = true;
      bitset<65> bit(A[i]);
      for (int i = 0; i < 65; ++i) {
        if (bit.test(i) && b[i] < 4) {
          no_change = false;
        }
      }
      if (no_change) continue;

      for (LL y : Y) {
        if (!X.count(y ^ A[i])) return 1;
        Y.insert(y ^ A[i]);
      }
      if (!X.count(A[i])) return 1;
      Y.insert(A[i]);
    }
  }
  return 0;
}

