int pow(int a, int b){
    int ans = 1;
    while(b){
        if(b & 1)ans = 1LL * ans * a % mod;
        a = 1LL * a * a % mod;
        b >>= 1;
    }
    return ans;
}
int pow(int a, ll b, int c){
    int ans = 1;
    while(b){
        if(b & 1)ans = 1LL * ans * a % c;
        a = 1LL * a * a % c;
        b >>= 1;
    }
    return ans;
}

int dp[202][2];
int a[202], e[61][202], K;
ll b[202];
char s[202];
int solve(int x, int n, ll v){
  if(dp[x][v] != -1)return dp[x][v];
  if(x == n-1){
    if(v == 0)e[K][x] |= 1;
    if(v == a[x])e[K][x] |= 2;
    if(v == 0 || v == a[x])return dp[x][v] = 0;
    return dp[x][v] = 1;
  }
  if(s[x] == '1'){
    int p = solve(x+1, n, v);
    int q = solve(x+1, n, v ^ a[x]);
    if(p || q)return dp[x][v] = 1;
    return dp[x][v] = 0;
  }
  else{
    int p = solve(x+1, n, v), q = solve(x+1, n, v ^ a[x]);
    if(p == 0)e[K][x] |= 1;
    if(q == 0)e[K][x] |= 2;
    if(p == 0 || q == 0)return dp[x][v] = 0;
    return dp[x][v] = 1;
  }
}
