void solve() {
	int n = nxt();
	vector<long long> a(n);
	for (int i = 0; i < n; ++i) {
		cin >> a[i];
	}
	string s;
	cin >> s;

	vector<long long> basis;

	auto check = [&](long long x) {
		for (auto b : basis) {
			if (x & (1ll << (63 - __builtin_clzll(b)))) {
				x ^= b;
			}
		}
		return x == 0;
	};

	for (int i = n - 1; i >= 0; --i) {
		if (s[i] == '0') {
			auto x = a[i];
			int j = 0;
			while (x > 0 && j < (int)basis.size() && __builtin_clzll(x) >= __builtin_clzll(basis[j])) {
				if (__builtin_clzll(x) == __builtin_clzll(basis[j])) {
					x ^= basis[j];
				}
				++j;
			}
			if (x == 0) {
				continue;
			}
			basis.insert(basis.begin() + j, x);
		} else {
			if (!check(a[i])) {
				cout << "1\n";
				return;
			}
		}
	}
	cout << "0\n";
}

