int d = 62;
vector<ll> basis(62);

void insert(ll v){
	for(int bit = 0; bit < d; bit++){
		if((v&(1LL<<bit))==0) continue;

		if(!basis[bit]){
			basis[bit] = v;
			return;
		}

		v ^= basis[bit];
	}
}

int check(ll v){
	for(int bit = 0; bit < d; bit++){
		if((v&(1LL<<bit))==0) continue;

		if(!basis[bit]){
			return 0;
		}

		v ^= basis[bit];
	}
	return (v==0);
}




