vector<int>make(vector<int>v) {
	vector<int>ret(60);
	int N = v.size();
	REPR(j, 60) {
		ll tmp = 0;
		REP(i, N) {
			if (v[i] & (1LL << j)) {
				ret[j]=(v[i]);
				tmp = v[i];
				break;
			}
		}
		REP(i, N) {
			if (v[i] & (1LL << j)) {
				v[i] ^= tmp;
			}
		}
	}
	return ret;
}
bool canmake(int x, vector<int>&v) {
	vector<int>s = make(v);
	ll ret = 0;
	int n = s.size();
	REPR(j, 60) {
		if ((x>>j&1)!=(ret>>j&1)) {
			ret ^= s[j];
		}
	}
	return ret == x;
}
