const int NBITS = 60;

ll basis[NBITS]; 

ll sz; 

void insertVector(ll mask)
{
	for (ll i = 0; i < NBITS; i++)
	{
		if ((mask & 1LL << i) == 0) continue; 
		if (!basis[i]) 
		{ 
			basis[i] = mask;
			++sz;
			return;
		}

		mask ^= basis[i];
	}
}

