typedef long long int ll;

void insert_vector (vector < ll > &basis, int msk) {
  for (int i = 0; i < 63; i++) {
    if (((msk >> i) & 1) == 0) continue;

    if (!basis[i]) {
      basis[i] = msk;
    }

    msk ^= basis[i];
  }
}

int main () {
  ios_base::sync_with_stdio(false);
  cin.tie(0);cout.tie(0);

  int tt;
