    cin >> n;
    vector < ll > a (n);
    for (int i = 0; i < n; i++) cin >> a[i];
    string s;
    cin >> s;

    vector < ll > basis0 (63), basis1 (63);
    for (int i = 0; i < n; i++) {
      if (s[i] == '0') insert_vector (basis0, a[i]);
      else insert_vector (basis1, a[i]);
    }

    bool ok = false;
    for (int i = 0; i < 63; i++) {
      int msk = basis1[i];
      for (int j = 0; j < 63; j++) {
        if (((msk >> j) & 1) == 0) continue;

        if (!basis0[j]) {
          ok = true;
        }

        msk ^= basis0[j];
      }
    }

    cout << ok << '\n';
  }
}

