    for (int j = 0; j < n; j++) {
        for (int i = 0; i < m; i++) {
            mat[i][j] = a[j] & 1;
            if (mat[i][j] && s[j] == '1')
                last[i] = j;
            a[j] >>= 1;
        }
    }
    for (int i = 0; i < m; i++) {
        for (int j = 0; j <= last[i]; j++)
            mat[i][j] = 0;
    }
    binaryGauss(mat, b, n, m);
    bool yes = true;
    for (int i = 0; i < m; i++) {
        if (b[i] == 0 && last[i] >= 0)
            yes = false;
    }
    printf("%d\n", yes ? 0 : 1);
}

