constexpr int mx = 64;

struct B {
    vector<long long> basis;
    B() { basis.assign(64, 0ll); }
    void insert_num(long long num) {
        for(int i = 0; i < mx; ++i) {
            if((num & 1ll << i) == 0) continue;
            if(!basis[i]) {
                basis[i] = num;
                return;
            }
            num ^= basis[i];
        }
    }
    bool contains(long long num) {
        for(int i = 0; i < mx; ++i) {
            if( (num & 1ll << i ) == 0 ) continue;
            if(basis[i] == 0) {
                return true;
            }
            num ^= basis[i];
        }
        return false;
    }
    void insert_vec(vector<long long> v) { for(auto& x : v) insert_num(x); }
};

