#include <bits/stdc++.h>

using namespace std;
using ll = long long;

const int N = 202;

const int LOG_MAX = 60;

struct Gauss {
    array<ll, LOG_MAX> vet;
    int size;
    Gauss() : size(0) {
		fill(vet.begin(), vet.end(), 0);
	}
    bool add(ll val) {
        for(int i = 0; i < LOG_MAX; i++) if(val & (1LL << i)) {
            if(vet[i] == 0) {
                vet[i] = val;
                size++;
                return true;
            }
            val ^= vet[i];
        }
        return false;
    }
    bool is_in(ll val) {
        for(int i = 0; i < LOG_MAX; i++) if(val & (1LL << i)) {
            if(vet[i] == 0) {
                return false;
            }
            val ^= vet[i];
        }
        return true;
    }
};

int n;
ll a[N];
char s[N];

int solve() {
	if(s[n - 1] == '1') return 1;
	Gauss p[2];
	for(int i = n - 1; i >= 0; i--) {
		int j = i;
		while(j - 1 >= 0 and s[j - 1] == s[i]) j--;
		for(int k = i; k >= j; k--) {
			p[int(s[i] - '0')].add(a[k]);
		}
		if(s[i] == '1') {
			for(ll v : p[1].vet) if(v) {
				if(!p[0].is_in(v)) {
					return 1;
				}
			}
		}
		i = j;
	}
	return 0;
}

int main() {
	int t;
	scanf("%d", &t);
	while(t--) {
		scanf("%d", &n);
		for(int i = 0; i < n; i++) scanf("%lld", a + i);
		scanf(" %s", s);
		printf("%d\n", solve());
	}
}

