using namespace std;

int get_msb(i64 x) {
	int msb = -1;
	for(auto k : range(63)) {
		if((1LL << k) & x) {
			msb = k;
		}
	}
	return msb;
}

bool is_composable(i64 x, vector<i64>& values) {

	if(values.empty()) {
		return false;
	}

	const int n = values.size();

	for(auto i : range(n)) {

		for(auto j : range(i + 1, n)) {
			if(values[i] < values[j]) {
				swap(values[i], values[j]);
			}
		}

		int msb = get_msb(values[i]);
		if(msb < 0) {
			break;
		}

		for(auto j : range(i + 1, n)) {
			if((1LL << msb) & values[j]) {
				values[j] = values[j] ^ values[i];
			}
		}
	}

	for(auto i : range(n)) {
		i64 y = values[i];
		int msb = get_msb(y);
		if(msb >= 0 && ((1LL << msb) & x)) {
			x = x ^ y;
		}
	}

	return x == 0;
}

void solve() {

	const int N = read_item();
	vector<i64> As(N);
	for(auto i : range(N)) {
		As[i] = read_item();
	}
	string S = read_item();

	bool zero_win = true;

	for(auto pos : range(N)) {

		if(S[pos] == '0') {
			continue;
		}

		i64 x = As[pos];
		vector<i64> zero_items;
		for(auto i : range(pos + 1, N)) {
			if(S[i] == '0') {
				zero_items.push_back(As[i]);
			}
		}

		bool ok = is_composable(x, zero_items);
		if(!ok) {
			zero_win = false;
			break;
		}
	}

	printf("%s\n", zero_win ? "0" : "1");
}

int main() {

	const int T = read_item();
	for(auto i : range(T)) {
		solve();
	}

	return 0;
}

