void ins(ll x) {
	for(int i=62;~i;--i) if(x>>i&1) {
		if(base[i]) x^=base[i];
		else {
			for(int j=i+1;j<63;++j) if(base[j]>>i&1) {
				base[j]^=x;
			}
			for(int j=i-1;~j;--j) if(x>>j&1) {
				x^=base[j];
			}
			base[i]=x;
			break;
		}
	}
