int gauss (vector < vector<int>  > a, int n, int m, vector<int> & ans) {
    vector<int> where (m, -1);
    for (int col=0, row=0; col<m && row<n; ++col) {
        for (int i=row; i<n; ++i)
            if (a[i][col]) {
                swap (a[i], a[row]);
                break;
            }
        if (! a[row][col])
            continue;
        where[col] = row;

        for (int i=0; i<n; ++i)
            if (i != row && a[i][col])
            {
                for(int j=0;j<sz(a[i]);j++)
                    a[i][j]^=a[row][j];
                // a[i] ^= a[row];
            }
        ++row;
    }
        // The rest of implementation is the same as above
    ans.assign (m, 0);
    for (int i=0; i<m; ++i)
        if (where[i] != -1)
            ans[i] = a[where[i]][m] / a[where[i]][i];
    for (int i=0; i<n; ++i) {
        int sum = 0;
        for (int j=0; j<m; ++j)
            sum += ans[j] * a[i][j];
        sum%=2;
        a[i][m]%=2;
        if (sum != a[i][m])
            return 0;
            // exit(0);
    }

    for (int i=0; i<m; ++i)
        if (where[i] == -1)
            return INF;
    return 1;
}
