using ll = long long;

using namespace std;

const int MAX_ROW = 210; // to be set appropriately
const int MAX_COL = 64; // to be set appropriately
struct BitMatrix {
    int H, W;
    bitset<MAX_COL> val[MAX_ROW];
    BitMatrix(int m = 1, int n = 1) : H(m), W(n) {}
    inline bitset<MAX_COL>& operator [] (int i) {return val[i];}
};

int GaussJordan(BitMatrix &A, bool is_extended = false) {
    int rank = 0;
    for (int col = 0; col < A.W; ++col) {
        if (is_extended && col == A.W - 1) break;
        int pivot = -1;
        for (int row = rank; row < A.H; ++row) {
            if (A[row][col]) {
                pivot = row;
                break;
            }
        }
        if (pivot == -1) continue;
        swap(A[pivot], A[rank]);
        for (int row = 0; row < A.H; ++row) {
            if (row != rank && A[row][col]) A[row] ^= A[rank];
        }
        ++rank;
    }
    return rank;
}

int main() {
    int T;
    cin >> T;
    while (T--) {
        int n; cin >> n;
        BitMatrix bm(n, 64);
        ll a[n]; for (auto &ai:a) cin >> ai;
        string s; cin >> s;
        int r = 0;
        bool prev = s.back() - '0';
        int zero = 0;
        bool ans = false;
        for (int i=n-1; i>=0; i--) {
            bool now = s[i] - '0';
            if (now) {
                r = GaussJordan(bm);
                vector<ll> bases; 
                for (int j=0; j<n; j++) {
                    bases.push_back(bm[j].to_ullong());
                }
                sort(bases.begin(), bases.end(), greater<ll>());
                for (int j=0; j<n && bases[j] > 0; j++) {
                    if (a[i] >= bases[j]) {
                        a[i] ^= bases[j];
                    }
                }
                if (a[i] != 0) {
                    ans = true;
                    break;
                }
            } else {
                bm[zero] = a[i];
                zero++;
            }
            prev = now;
        }
        cout << ans << '\n';
    }
    return 0;
}

