template <int D>
struct XorSpace
{
	vector <pair<bitset <D>,int> > basis;
	inline int findBit(bitset <D> &x,int pos=0)
	{
		int fb=-1;
		for(fb=pos;fb<D;fb++)
		{
			if(x[fb]) break;
		}
		return fb;
	}
	inline void normalize(bitset <D> &x)
	{
		int fb=findBit(x);
		for(auto &v:basis)
		{
			if(v.second<fb) continue;
			if(v.second>fb) break;
			x^=v.first;
			fb=findBit(x,fb);
		}
	}
	inline void add(bitset <D> x)
	{
		normalize(x);
		if(x==0) return;
		int fb=findBit(x);
		pair<bitset<D>,int> o;
		basis.push_back(o);
		for(int i=basis.size()-1;i>=0;i--)
		{
			if(i==0 || basis[i-1].second<fb)
			{
				basis[i].first=x;
				basis[i].second=fb;
				break;
			}
			basis[i]=basis[i-1];
		}
	}
	inline bool query(bitset <D> x)
	{
		normalize(x);
		return (x==0);
	}
	inline void clear()
	{
		basis.clear();
	}
	inline void print()
	{
		for(auto &o:basis)
		{
			cout<<o<<endl;
		}
	}
};

