void add(long long x) {
    for (int i = 59; i >= 0; i--) {
        if (x & (1ll << i)) {
            if (basis[i] == 0) {
                basis[i] = x;
                break;
            }

            x ^= basis[i];
        }
    }
}
bool can(long long x) {
    for (int i = 59; i >= 0; i--) if (x & (1ll << i)) {
        x ^= basis[i];
    }

    return x == 0;
}
