char S[205];
int basisSize[2] = {0, 0};

bool insertVector(long long mask, int mode, bool testing = false){
    for(int i = 61; i >= 0; i --){
        if((mask&(1LL<<i)) == 0){continue;}
        if(!basis[i][mode]){
            if(testing){return true;}
            basis[i][mode] = mask;
            basisSize[mode] ++;
            return true;
        }
        mask ^= basis[i][mode];
    }
    return false;
}

