int dp[N][2], a[N];
int n;
string s;

bool rec(int id, int b, bool c){
	if(dp[id][c] != -1)
		return dp[id][c];
	if(id == n+1){
		return c;
	}
	bool x = ((1LL << b) & a[id]);
	bool n = c^x;
	if(s[id-1] == '0'){
		if(rec(id+1, b, n) == 0)
			dp[id][c] = 0;
		else if(rec(id+1, b, c) == 0)
			dp[id][c] = 0;
		else
			dp[id][c] = 1;
	}
	else{
		if(rec(id+1, b, n))
			dp[id][c] = 1;
		else if(rec(id+1, b, c))
			dp[id][c] = 1;
		else
			dp[id][c] = 0;
	}
	return dp[id][c];
}

