  const int DIGIT = 63;
  rep(t,T){
    int N; cin >> N;
    vector<ll> A(N); rep(i,N) cin >> A[i];
    string S; cin >> S;

    if(S[N-1]=='1'){
      cout << 1 << endl;
      continue;
    }

    bool win0 = true;
    rep(i,N){
      if(S[i] == '1'){
        BitMatrix AA(DIGIT, N);
        vector<int> b(DIGIT), res;
        for(int d=0;d<DIGIT;d++){
          for(int x=i+1;x<N;x++){
            if(S[x]=='0'){
              if(A[x] & (1<<d)) AA[d][x] = 1;
            }
          }
          if(A[i]&(1<<d)) b[d] = 1;
        }
        int rank = linear_equation(AA,b,res);
        if(rank==-1) {
          win0 = false;
          break;
        }
      }
    }
    if(win0) cout << 0 << endl;
    else cout << 1 << endl;
  }
