// copy a
bool check(vector<BS> a, const string& s, int64_t idx) {
    assert(s[idx] == '1');

    int64_t n = s.size();

    BS b = a[idx];
    for (auto i : irange(0L, 64L)) {
        int64_t k = -1L;
        for (auto j : irange(idx, n)) {
            if (s[j] == '1') {
                continue;
            }

            if (a[j][i]) {
                if (k < 0) {
                    k = j;
                    if (b[i]) {
                        b ^= a[k];
                    }
                }

                a[j] ^= a[k];
            }
        }

        if (b[i]) {
            return false;
        }
    }

    return true;
}

bool check(const vector<BS>& a, const string& s) {
    int64_t n = s.size();
    for (auto i : irange(0L, n)) {
        if (s[i] == '1') {
            if (!check(a, s, i)) {
                return false;
            }
        }
    }

    return true;
}

