ll MX = 60;

ll g(vll& v, ll x){
  v.push_back(x);
  ll cur = 0;
  PER(i,60,0){
    ll bt = BIT(i);
    REP(j,cur,SIZE(v)-1){
      if(bt & v[j]){
        swap(v[j], v[cur]);
        REP(k,0,SIZE(v)-1){
          if((bt & v[k]) && (cur != k)){
            v[k] ^= v[cur];
          }
        }
        cur++;
        break;
      }
    }
  }
  while(v[SIZE(v)-1] == 0){
    v.pop_back();
  }
}

bool kesenai(vll& v, ll x){
  PER(i,MX,0){
    ll bt = BIT(i);
    if(bt & x){
      REP(i,0,SIZE(v)-1){
        if(bt & v[i]){
          x ^= v[i];
        }
      }
    }
  }
  return x != 0;
}

