template <int N> struct basis_z2 {
    basis_z2() {}
    basis_z2(vector<bitset<N>> a) {
        for (int i = 0, s = 0; i < int(a.size()) && s < N; ++i) {
            int t = int(a[i]._Find_first());
            if (t == N)
                continue;
            ++s;
            for (int j = 0; j < int(a.size()); ++j)
                if (j != i && a[j][t])
                    a[j] ^= a[i];
        }
        for (const auto &v : a)
            if (v.any())
                b.push_back(v);
    }
    bitset<N> elimate(bitset<N> a) {
        for (const auto &v : b) {
            int t = int(v._Find_first());
            if (a[t])
                a ^= v;
        }
        return a;
    }
    void add_vector(bitset<N> a) {
        if ((a = elimate(a)).any())
            b.push_back(a);
    }
    vector<bitset<N>> b;
};
