auto solve(ll n, const VL& a, const string& s) ->bool {
	ll end = n;
	V<unordered_set<ll>> vs(n, {0});
	RREP(i, n) {
		if (i + 1 < n) { vs[i] = vs[i + 1]; }
		if (s[i] == '0') {
			if (i + 1 < n) {
				REPC(x, vs[i + 1]) {
					vs[i].emplace(x ^ a[i]);
				}
			} else {
				vs[i].emplace(a[i]);
			}
		}
	}
	unordered_set<ll> now{0};
	unordered_set<ll> tmp;
	REP(i, n) if (s[i] == '1') {
		tmp = now;
		REPC(x, now) { tmp.emplace(x ^ a[i]); }
		//dump(tmp);
		REPC(x, tmp) {
			if (vs[i].find(x) == vs[i].end()) {
				return false;
			}
		}
		std::swap(tmp, now);
	}

	//dump(vs);
	return true;
}


