const int LOG_A = 19;

ll basis1[LOG_A],basis2[LOG_A];

ll sz1,sz2;

void insertVector1(ll mask) {
    for (int i = 0; i < LOG_A; i++) {
        if ((mask & 1ll << i) == 0) continue;

        if (!basis1[i]) {
            basis1[i] = mask;
            ++sz1;

            return;
        }

        mask ^= basis1[i];
    }
}

void insertVector0(ll mask) {
    for (int i = 0; i < LOG_A; i++) {
        if ((mask & 1ll << i) == 0) continue;

        if (!basis2[i]) {
            basis2[i] = mask;
            ++sz2;
            return;
        }

        mask ^= basis2[i];
    }
}

