ll check(V<ll> a, V<ll> b) 
{
    ll id = 0;
    for(ll i=64;i>=0;i--)
    {
        ll mxid = id, mx = -inf;
        for(ll j=id;j<sz(a);j++)
            if((a[j]&(1LL<<i)) && a[j]>mx)
                mx = a[j], mxid = j;
        if(mx==-inf)
            continue;
        swap(a[id],a[mxid]);
        rep0(j,sz(a))
            if(j!=id && (a[j]&(1LL<<i)))
                a[j] ^= a[id];
        id++;
    }
    ll c[65] = {0};
    for(auto it:a) {
        for(int i=64;i>=0;i--) {
            if((it>>i)&1) {
                c[i] = it;
                break;
            }
        }
    }
    for(auto it:b) {
        ll res = 0;
        for(int i=64;i>=0;i--) {
            if(((it>>i)&1) != ((res>>i)&1)) {
                res ^= c[i];
            }
        }
        if(res!=it) {
            return 1;
        }
    }
    return 0;
}
