#define INT_BITS 64
int eliminate(v(lli) &set, int n) 
{ 
    // Initialize index of 
    // chosen elements 
    int index = 0; 

    // Traverse through all 
    // bits of integer  
    // starting from the most 
    // significant bit (MSB) 
    for (int i = INT_BITS-1; i >= 0; i--) 
    { 
        // Initialize index of 
        // maximum element and 
        // the maximum element 
        int maxInd = index; 
        lli maxEle = LONG_LONG_MIN; 
        for (int j = index; j < n; j++) 
        { 
            // If i'th bit of set[j] 
            // is set and set[j] is  
            // greater than max so far. 
            if ( (set[j] & (1LL << i)) != 0  
                     && set[j] > maxEle ) 
                maxEle = set[j], maxInd = j; 
        } 

        // If there was no  
        // element with i'th 
        // bit set, move to 
        // smaller i 
        if (maxEle == LONG_LONG_MIN) 
        continue; 

        // Put maximum element 
        // with i'th bit set  
        // at index 'index' 
        swap(set[index], set[maxInd]); 

        // Update maxInd and  
        // increment index 
        maxInd = index; 

        // Do XOR of set[maxIndex] 
        // with all numbers having 
        // i'th bit as set. 
        for (int j=0; j<n; j++) 
        { 
            // XOR set[maxInd] those 
            // numbers which have the 
            // i'th bit set 
            if (j != maxInd && 
               (set[j] & (1LL << i)) != 0) 
                set[j] = set[j] ^ set[maxInd]; 
        } 

        // Increment index of 
        // chosen elements 
        index++; 
    } 

    // Final result is  
    // XOR of all elements 

} 
