public:

    vector<ll> zero;

    void hakidashi(ll a) {
      ll tmp = a;
      ll cnt = 0;
      while(tmp > 0) {
        cnt++;
        tmp /= 2;
      }

      for(auto& e: zero) {
        ll tmp = e;
        ll c = 0;
        while(tmp > 0) {
          c++;
          tmp /= 2;
        }
        if (c == cnt) {
          e ^= a;
        }
      }
      zero.push_back(a);
    }

    bool check(ll b) {
      sort(zero.rbegin(), zero.rend());

      for(auto e: zero) {
        auto tmp = b;
        auto cnt = 0;
        while(tmp > 0) {
          cnt++;
          tmp /= 2;
        }
        auto c = 0;
        auto tmp2 = e;
        while(tmp2 > 0) {
          c++;
          tmp2 /= 2;
        }
        if (cnt == c) {
          b ^= e;
        }
      }

      return (b==0);
    }

