}

struct Comparer {
  bool operator()(const pair<int, bitset<61>> &b1,
                  const pair<int, bitset<61>> &b2) const {
    return ii(b1.ff, b1.ss.to_ullong()) < ii(b2.ff, b2.ss.to_ullong());
  }
};

bitset<61> apply(bitset<61> &bs, int x) {
  bitset<61> app(x);
  return (bs ^ app);
}

int solve(int n, bitset<61> &bs, vector<int> &A, string &play,
          map<pair<int, bitset<61>>, int, Comparer> &dp) {
  if (n == 0) {
    // cout << n << " " << bs.to_string() << " " << bs.count() << endl;
    if (bs.count() == 0)
      return 0;
    else
      return 1;
  }
  if (dp.count(mp(n, bs))) return dp[mp(n, bs)];
  int &val = dp[mp(n, bs)];

  set<int> s;
  // get the number or dont get
  auto new_bs = apply(bs, A[n]);

  s.insert(solve(n - 1, new_bs, A, play, dp));
  s.insert(solve(n - 1, bs, A, play, dp));

  // cout << "at " << n << " " << play[n] << endl;
  // cout << bs.to_ullong() << " " << new_bs.to_ullong() << endl;
  // for (int x : s) cout << x << " ";
  // cout << endl;
  if (play[n] == '0') {
    if (!s.count(1))
      val = 0;
    else
      val = 1;
  } else {
    if (!s.count(0))
      val = 1;
    else
      val = 0;
  }

  return val;
}

