const int L = 61;

vl gauss(vl a) {
    int ptr = 0;
    for (int i = 0; i < L; ++i) {
        bool found = false;
        for (int j = ptr; j < a.size(); ++j) {
            if ((a[j] >> i) & 1) {
                found = true;
                swap(a[ptr], a[j]);
                continue;
            }
        }
        if (found) {
            fori (j, a.size()) if (j != ptr) {
                if ((a[j] >> i) & 1) {
                    a[j] ^= a[ptr];
                }
            }
            ptr++;
        }
    }
    a.resize(ptr);
    return a;
}

void solve() {

    int n;
    cin >> n;
    vl a(n);
    string s;
    fori (i, n) {
        cin >> a[i];
    }
    cin >> s;
    reverse(ALL(a));
    reverse(ALL(s));
    vl bs;
    fori (i, n) {
        if (s[i] == '0') {
            bs.push_back(a[i]);
        } else {
            bs = gauss(bs);
            vl tmp = bs;
            tmp.push_back(a[i]);
            if (bs != gauss(tmp)) {
                cout << "1\n";
                return;
            }
        }
    }
    cout << "0\n";
}

