#include <bits/stdc++.h>
using namespace std;

vector<long> a;
string s;

map<pair<long, long>, bool> m;

bool backtrack(long val, long i) {
    if (m.find({val, i}) != m.end()) return m[{val, i}];
    if (i == a.size()) return val == 0;
    else {
        bool zeroWins;
        if (s[i] == '0') {
            if (backtrack(val, i + 1)) zeroWins = true;
            else zeroWins = backtrack(val ^ a[i], i + 1);
        } else {
            if (!backtrack(val ^ a[i], i + 1)) zeroWins = false;
            else zeroWins = backtrack(val, i + 1);
        }
        m[{val, i}] = zeroWins;
        return zeroWins;
    }
}

