void solve() {
    int n;
    cin >> n;
    vl a(n);
    rep (i, n) cin >> a[i];
    string s;
    cin >> s;

    vector<ll> basis;
    ll mask = (1LL << 62) - 1;
    rrep (i, s.size()) {
        if (s[i] == '0') {
            ll now = a[i];
            for (ll b: basis) {
                chmin(now, now ^ b);
            }
            if (now > 0) {
                basis.push_back(now);
                mask = mask & (~now);
            }
        }
        else {
            ll x = a[i];
            for (ll b: basis) {
                ll temp = 1LL << 62;
                while ((temp & b) == 0) temp >>= 1;
                if (x & temp) x ^= b;
            }
            if (x != 0) {
                cout << 1 << endl;
                return;
            }
        }
    }
    // DEBUG_VEC(basis);
    cout << 0 << endl;
}

