using namespace std;

string getBit(int x,int N){
  string s = "";
  int t = x;
  while(t > 0){
    if((t % 2) == 1){
      s = "1" + s;
    }
    else{
      s = "0" + s;
    }
    t /= 2;
  }
  for(;N > s.length();){
    s = "0" + s;
  }

  return s;
}

string getExOr(string s1,string s2){
  string s = "";
  for(int i = 0;i < s1.length();++i){
    if(s1[i] == s2[i]){
      s += "0";
    }
    else{
      s += "1";
    }
  }
  return s;
}

string geo(string s1,int s2){
  return getExOr(s1,getBit(s2,s1.length()));
}

bool g(string S,vector<unsigned long>A,int n,unsigned int x){
  if(n == S.length()){
    if(x != 0){
      return false;
    }
    return true;
  }
  else{
    bool en = g(S,A,n + 1,x ^ A[n]);
    bool nn = g(S,A,n + 1,x);
    if(S[n] == '0'){
      return en || nn;
    }
    else{
      return en && nn;
    }
  }
}

int main() {
  int T;

  cin >> T;
  for(int nnn = 0;nnn < T;++nnn){
    unsigned long x = 0;
    int N;
    vector<unsigned long>A;
    string S;
    cin >> N;

    for(int i = 0;i < N;++i){
  	  unsigned long t = 0;
      cin >> t;
  	  A.push_back(t);
    }
    cin >> S;

    cout << (g(S,A,0,x) ? "0" : "1") << endl;
  }
}

