    int rank = 0;
    for (ll col = 0; col < A[0].size(); col++) {
        int pivot = -1;
        for (int row = rank; row < A.size(); row++) {
            if (A[row][col]) {
                pivot = row;
                break;
            }
        }
        if (pivot == -1) continue;
        swap(A[pivot], A[rank]);
        for (int row = 0; row < A.size(); row++) {
            if (row != rank && A[row][col]) Rep (j, 61) A[row][j] = A[rank][j] ^ A[row][j];
        }
        rank++;
    }
}
bool meq (mat &A, mat &B) {
    bool ret = true;
    Rep (i, A.size()) {
        Rep (j, A[0].size()) {
            if (A[i][j] != B[i][j]) ret = false;
        }
    }

    return ret;
}

