constexpr char newl = '\n';

// http://kazuma8128.hatenablog.com/entry/2018/05/06/022654
template<typename U = unsigned int, int B = 32>
class BinaryTrie {
    struct node {
        int cnt;
        U lazy;
        node *ch[2];
        node() : cnt(0), lazy(0), ch{ nullptr, nullptr } {}
    };
    void push(node* t, int b) {
        if ((t->lazy >> (U)b) & (U)1) swap(t->ch[0], t->ch[1]);
        if (t->ch[0]) t->ch[0]->lazy ^= t->lazy;
        if (t->ch[1]) t->ch[1]->lazy ^= t->lazy;
        t->lazy = 0;
    }
    node* add(node* t, U val, int b = B - 1) {
        if (!t) t = new node;
        t->cnt += 1;
        if (b < 0) return t;
        push(t, b);
        bool f = (val >> (U)b) & (U)1;
        t->ch[f] = add(t->ch[f], val, b - 1);
        return t;
    }
    node* sub(node* t, U val, int b = B - 1) {
        assert(t);
        t->cnt -= 1;
        if (t->cnt == 0) return nullptr;
        if (b < 0) return t;
        push(t, b);
        bool f = (val >> (U)b) & (U)1;
        t->ch[f] = sub(t->ch[f], val, b - 1);
        return t;
    }
    U get_min(node* t, U val, int b = B - 1) {
        assert(t);
        if (b < 0) return 0;
        push(t, b);
        bool f = (val >> (U)b) & (U)1; f ^= !t->ch[f];
        return get_min(t->ch[f], val, b - 1) | ((U)f << (U)b);
    }
    U get(node* t, int k, int b = B - 1) {
        if (b < 0) return 0;
        push(t, b);
        int m = t->ch[0] ? t->ch[0]->cnt : 0;
        return k < m ? get(t->ch[0], k, b - 1) : get(t->ch[1], k - m, b - 1) | ((U)1 << (U)b);
    }
    int count_lower(node* t, U val, int b = B - 1) {
        if (!t || b < 0) return 0;
        push(t, b);
        bool f = (val >> (U)b) & (U)1;
        return (f && t->ch[0] ? t->ch[0]->cnt : 0) + count_lower(t->ch[f], val, b - 1);
    }
    node *root;
public:
    BinaryTrie() : root(nullptr) {}
    int size() const {
        return root ? root->cnt : 0;
    }
    bool empty() const {
        return !root;
    }
    void insert(U val) {
        root = add(root, val);
    }
    void erase(U val) {
        root = sub(root, val);
    }
    void xor_all(U val) {
        if (root) root->lazy ^= val;
    }
    U max_element(U bias = 0) {
        return get_min(root, ~bias);
    }
    U min_element(U bias = 0) {
        return get_min(root, bias);
    }
    int lower_bound(U val) { // return id
        return count_lower(root, val);
    }
    int upper_bound(U val) { // return id
        return count_lower(root, val + 1);
    }
    U operator[](int k) {
        assert(0 <= k && k < size());
        return get(root, k);
    }
    int count(U val) {
        if (!root) return 0;
        node *t = root;
        for (int i = B - 1; i >= 0; i--) {
            push(t, i);
            t = t->ch[(val >> (U)i) & (U)1];
            if (!t) return 0;
        }
        return t->cnt;
    }
};

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int t;
    cin >> t;

    for (int loop = 0; loop < t; loop++) {
        int n;
        cin >> n;

        vector<ll> a(n);
        for (int i = 0; i < n; i++) {
            cin >> a[i];
        }

        string s;
        cin >> s;

        if (s.back() == 1) {
            cout << 1 << newl;
            continue;
        }

        vector<P> v;
        v.push_back(P(0, {}));
        for (int i = n - 1; i >= 0; i--) {
            if (v.back().first == (s[i] - '0')) {
                v.back().second.push_back(a[i]);
            } else {
                int nex = 1 - v.back().first;
                v.push_back(P(nex, {a[i]}));
            }
        }

        for (auto& p : v) {
            sort(p.second.begin(), p.second.end());
        }

        int sz = v.size();
        deque<ll> memo;
        bool f = true;
        for (int i = 0; i < sz; ++i) {
            if (v[i].first == 0) {
                for (ll x : v[i].second) memo.push_back(x);
            } else {
                int sz2 = memo.size();
                int rank = 0;
                for (int j = 59; j >= 0; j--) {
                    int pivot = -1;
                    for (int k = rank; k < sz2; k++) {
                        if (memo[k] >> j & 1) {
                            pivot = k;
                            break;
                        }
                    }

                    if (pivot == -1) continue;
                    swap(memo[pivot], memo[rank]);

                    for (int k = 0; k < sz2; k++) {
                        if (k != rank && (memo[k] >> j & 1)) memo[k] ^= memo[rank];
                    }

                    for (ll& x : v[i].second) {
                        if (x >> j & 1) x ^= memo[rank];
                    }
                    ++rank;
                }

                for (ll x : v[i].second) {
                    if (x != 0) {
                        f = false;
                        break;
                    }
                }

                if (!f) break;

                for (int j = 0; j < rank; j++) {
                    memo.pop_back();
                }
            }
        }

        cout << !f << newl;
    }

    return 0;
}

