const uint64_t K = 64;

bool judge(uint64_t N, const vector<uint64_t> &A, const string &S)
{
  vector<vector<uint64_t>> cs0(N + 1, vector<uint64_t>(K, 0));
  vector<vector<uint64_t>> cs1(N + 1, vector<uint64_t>(K, 0));

  N_TIMES(n, N) {
    N_TIMES(k, K) {
      cs0[n + 1][k] = cs0[n][k];
      cs1[n + 1][k] = cs1[n][k];

      bitset<K> bs(A[n]);
      if (S[n] == '0') {
        cs0[n + 1][k] += bs[k];
      } else { // S[n] == '1'
        cs1[n + 1][k] += bs[k];
      }
    }
  }

  N_TIMES(k, K) {
    if (cs0[N][k] < cs1[N][k]) {
      return false;
    }
  }
  return true;
}

