            A0[bit].second = i;
          } else {
            B0[bit].first++;
            B0[bit].second = i;
            A0[bit].first = 0;
          }
          ++count;
          pos = i;
        }
        ++bit;
        A[i] /= 2;
      }
      if (count == 1) A0_bitonly[pos] = true;
    }

    bool b_win = false;
    rep(i, 64) {
      if (A0[i].second < B0[i].second)
        b_win = true;
      else if (B0[i].first != 0 && A0[i].first == 1 && A0_bitonly[i] == false)
        b_win = true;
    }
    if (b_win)
      cout << 1 << endl;
    else
      cout << 0 << endl;
  }
  return 0;
}

