void normalize(vector<ll> &one, vector<ll> &zero) {
	const int n = zero.size();
	const int m = 60;
	const int k = one.size();

	rep(i, n) {
		ll cmax = zero[i], pos = i;
		rep(j, i + 1, n) if(chmax(cmax, zero[j])) pos = j;
		if(cmax == 0) break;
		swap(zero[i], zero[pos]);

		int col = m - 1;
		while(col >= 0 and ((zero[i] >> col) & 1) == 0) col--;

		rep(j, i + 1, n) {
			if((zero[j] >> col) & 1) {
				zero[j] ^= zero[i];
			}
		}

		rep(j, k) {
			if((one[j] >> col) & 1) {
				one[j] ^= zero[i];
			}
		}
	}
}

