void Gauss(vector<long long> &A) {
  int rank = 0;
  for (int d = 0; d < 60; ++d) {
    int pivot = -1;
    for (int i = rank; i < (int)A.size(); ++i) {
      if (A[i] & (1LL<<d)) {
        pivot = i;
        break;
      }
    }
    if (pivot == -1) continue;
    swap(A[rank], A[pivot]);
    for (int j = 0; j < (int)A.size(); ++j) {
      if (j == rank) continue;
      if (!(A[j] & (1LL<<d))) continue;
      A[j] ^= A[rank];
    }
    ++rank;
  }
}

