vector<lint> cal(vector<lint> x){
	int rank=0;
	rep(i,60){
		if(rank>=x.size()) break;
		REP(j,rank,x.size()){
			if((x[j]&(1LL<<i))) swap(x[rank],x[j]);
		}
		if(!(x[rank]&(1LL<<i))) continue;
		rep(j,x.size()){
			if(j==rank) continue;
			if((x[j]&(1LL<<i))) x[j]^=x[rank];
		}
		rank++;
	}
	REP(i,rank,x.size()){
		assert(x[i]==0LL);
	}
	//x.resize(rank);
	//return x;
	vector<lint> ret;
	rep(i,rank) ret.pb(x[i]);
	return ret;
}
