#define ALL(v) begin(v),end(v)

typedef long long LL;
typedef vector<LL> vll;

vll sweep(vll v){
	int n = v.size();
	for(int i = 0; i < n; ++i){
		swap(v[i], *max_element(v.begin() + i, v.end()));
		LL t = v[i];
		if(t == 0){
			v.resize(i);
			break;
		}
		for(int j = i + 1; j < n; ++j){
			LL &x = v[j];
			if((x ^ t) < x){ x ^= t; }
		}
	}
	return v;
}

bool newbase(const vll &v, LL x){
	for(LL t : v){
		if((x ^ t) < x){ x ^= t; }
	}
	return x;
}

int solve(){
	int n;
	cin >> n;
	vll as(n);
	for(int i = 0; i < n; ++i){
		cin >> as[i];
	}
	string s;
	cin >> s;

	if(s[n - 1] == '1'){ return 1; }
	if(count(ALL(s), '1') == 0){ return 0; }
	int l;
	for(l = n - 1; s[l - 1] == '0'; --l);
	vll v = sweep(vll(as.begin() + l, as.end()));
	for(int r = l; r > 0; r = l){
		for(--l; l > 0 && s[l - 1] == s[l]; --l);
		vll w;
		for(int j = l; j < r; ++j){
			if(newbase(v, as[j])){ w.push_back(as[j]); }
		}
		if(w.empty()){
			return '1' - s[l];
		}
		v = sweep(w);
	}
	return s[0] - '0';
}

