                for (int k = 0; k < 61; k++) {
                    if ((a[j] >> k) & 1LL) {
                        b[k] = 1;
                    } else {
                        b[k] = 0;
                    }
                }
                int res = LinearEquation(m, b, x);
                if (res == -1) {
                    f = false;
                }
            }
        }
        cout << (f ? 0 : 1) << '\n';
    }
}

