void solve() {
    int N; scanf("%d", &N);
    vector<ll> A(N);
    for(int i=0; i<N; i++) scanf("%lld", &A[i]);
    string s; cin >> s;

    // 最後が '1' なら絶対 0 以外にできる
    if(s.back() == '1') {
        puts("1");
        return;
    }

    vector<ll> VA, VB;
    int last_1 = 0;
    for(int i=0; i<N; i++) if(s[i] == '1') last_1 = i;
    for(int i=0; i<N; i++) {
        if(s[i] == '0' and i > last_1) VA.emplace_back(A[i]);
        if(s[i] == '1') VB.emplace_back(A[i]);
    }

    vector<ll> base_A = VA, base_B = VB;
    sort(base_A.begin(), base_A.end());
    sort(base_B.begin(), base_B.end());

    while(true) {
        vector<ll> n_base_A;
        for(auto e : base_A) {
            for(auto b : n_base_A) {
                chmin(e, e ^ b);
            }
            if(e) n_base_A.emplace_back(e);
        }

        sort(n_base_A.begin(), n_base_A.end());
        if(base_A == n_base_A) break;
        swap(n_base_A, base_A);
    }
    while(true) {
        vector<ll> n_base_B;
        for(auto e : base_B) {
            for(auto b : n_base_B) {
                chmin(e, e ^ b);
            }
            if(e) n_base_B.emplace_back(e);
        }

        sort(n_base_B.begin(), n_base_B.end());
        if(base_B == n_base_B) break;
        swap(n_base_B, base_B);
    }

    // 1 側の基底が全部 0 側にあればいい
    bool ok = true;
    for(auto e : base_B) {
        ok &= (binary_search(base_A.begin(), base_A.end(), e));
    }
    printf("%d\n", ok ? 0 : 1);
}

int main() {
    int T; scanf("%d", &T);
    while(T--) solve();
    return 0;
}

