void brute(vector<ll> a, vector<ll> b){
	set<ll> sa, sb;
	for(ll x : a){
		if(!sa.count(x)){
			sa.insert(x);
			for(ll y : sa){
				sa.insert(y ^ x);
			}
		}
	}
	for(ll x : b){
		if(!sb.count(x)){
			sb.insert(x);
			for(ll y : sb){
				sb.insert(y ^ x);
			}
		}
	}
	for(ll x : sb){
		if(!sa.count(x)){
			printf("1\n\n");
			return;
		}
	}
	printf("0\n\n");
}

int main(){
