			else{
				b.pb(v[i]);
			}
		}
		memset(ba, 0, sizeof ba);
		memset(bb, 0, sizeof bb);
		int ans = 0;
		for(ll x : a){
			for(int i = 60; i >= 0; i--){
				if(x & (1LL << i)){
					if(ba[i] == 0){
						ba[i] = x;
