				if(x & (1LL << i)){
					if(bb[i] == 0){
						bb[i] = x;
						break;
					}
					else{
						x ^= bb[i];
					}
				}
			}
		}
		for(int i = 60; i >= 0; i--){
			if(bb[i] && !ba[i]){
				ans = 1;
