struct LB {
	long long a[B];

	void insert (long long x) {
		for (int i = B - 1; x && i >= 0; i--) {
			if (x >> i & 1) {
				if (!a[i]) a[i] = x;
				x ^= a[i];
			}
		}
	}

	long long querymn (long long x = 0) {
		long long ret = x;
		for (int i = B - 1; i >= 0; i--)
			ret = min(ret, ret ^ a[i]);
		return ret;
	}

	long long & operator [] (int x) { return a[x]; }

} lb;

