int t, n, dp[4][220]; string s;
ll A[220];

int solve() {
  cin>>n;
  rep(i,n) cin>>A[i];
  cin>>s;

  int ans = 0;

  for(int i = 0;i < 64;i++) {
    // ith bit

    bool iba = (A[n-1] & 1LL<<i);

    if(s[n-1] == '0') {
      dp[0][n-1] = 1;
      dp[1][n-1] = iba;
    } else {
      dp[0][n-1] = iba;
      dp[1][n-1] = 1;
    }

    for(int j = n-2;j >= 0;j--) {
      iba = (A[j] & 1LL<<i);
      if(s[j] == '0' && s[j+1] == '0') {
        dp[0][j]= dp[0][j+1] || dp[0^iba][j+1];
        dp[1][j]= dp[1][j+1] || dp[1^iba][j+1];
      } else if(s[j] == '0' && s[j+1] == '1') {
        dp[0][j]= !(dp[0][j+1] & dp[0^iba][j+1]);
        dp[1][j]= !(dp[1][j+1] & dp[1^iba][j+1]);
      } else if(s[j] == '1' && s[j+1] == '0') {
        dp[0][j]= !(dp[0][j+1] & dp[0^iba][j+1]);
        dp[1][j]= !(dp[1][j+1] & dp[1^iba][j+1]);
      } else {
        dp[0][j]=dp[0][j+1] || dp[0^iba][j+1];
        dp[1][j]=dp[1][j+1] || dp[1^iba][j+1];
      }
    }

    ans |= (s[0]=='1' && dp[0][0]==1) || (s[0]=='0' && dp[0][0]==0);
  }

  return ans;
}

