// ### BIT CHEAT SHEET ###
// and: a&b
// or: a|b
// not: ~a
// xor: a^b
//
// ビットbitにi番目のフラグが立っているかどうか: if (bit & (1<<i))
// ビットbitにi番目のフラグが消えているかどうか: if (!(bit & (1<<i)))
// ビットbitにi番目のフラグを立てる: bit |= (1<<i)
// ビットbitにi番目のフラグを消す: bit &= ~(1<<i)
// ビットbitに何個のフラグが立っているか: __builtin_popcountll(bit)
// ビットbitにi番目のフラグを立てたもの: bit | (1<<i)
// ビットbitにi番目のフラグを消したもの: bit & ~(1<<i)
//
// maskで表された部分のフラグをまとめて立てる: bit |= mask
// maskで表された部分のフラグをまとめて消す: bit &= ~mask
// maskで表された部分の情報のみを取り出したもの: bit & mask
// maskで表された部分のどれかのフラグが立っているかどうか: if (bit & mask)
// maskで表された部分のすべてのフラグが立っているかどうか: if ((bit & mask) == mask)
//
// nビットより上位のビット列: i>>n==i/(1<<n)
// nビットより下位のビット列: i&((1<<n)-1)==i%(1<<n)
//
// bitの最も右の1のみを抽出する: bit & (-bit)
// bitの最も右の1のみを0にする: bit & (bit - 1)
// 最も右の1は何桁目か: __builtin_ffsll(bit)
//

// 2^63>9*10^18
int main() {
  ll T;
  cin >> T;
  for (ll ii = 0; ii < T; ii++) {
    ll N;
    cin >> N;
    vi Arr(N);
