      cin >> Arr[i];
    }
    string S;
    cin >> S;
    vi A(0), B(0);
    for (ll i = 0; i < S.size(); i++) {
      if (S[i] == '0') {
        A.push_back(Arr[i]);
      } else {
        B.push_back(Arr[i]);
      }
    }

    vi X(70);
    for (ll a : A) {
      for (ll bit = 0; bit < 64; bit++) {
        if ((a >> bit) & 1) {
          if (X[bit] == 0) {
            X[bit] = a;
            break;
          } else {
            a ^= X[bit];
          }
        }
      }
    }

    bool f = false;
    for (ll b : B) {
      for (ll bit = 0; bit < 64; bit++) {
        if ((b >> bit) & 1) {
          b ^= X[bit];
        }
      }
      if (b != 0) {
        f = true;
      }
    }

    if (f)
      cout << 1 << endl;
    else
      cout << 0 << endl;
  }
}

