class AXorBattle {

    static const int LOG = 60;

    void solve(int tc, istream &in, ostream &out) {
        int n;
        in >> n;
        vl A(n);
        in >> A;
        string S;
        in >> S;
        vl base(LOG);
        bool res = false;
        ROF(i, 0, n) {
            ll a = A[i];
            FOR(j, 0, LOG) {
                if (a & (1ll << j)) {
                    a ^= base[j];
                }
            }
            if (S[i] == '0') {
                if (a) {
                    base[__builtin_ctzll(a)] = a;
                }
            } else if (a) {
                res = true;
                break;
            }
        }
        out << res << '\n';
    }

public:
    void solve(std::istream &in, std::ostream &out) {
        int t;
        in >> t;
        FOR(i, 1, t + 1) {
            solve(i, in, out);
        }
    }

    void setup() {}
};


