int mat_rank(vector<vector<int>> mat) {
	int n = mat.size();
	int m = mat[0].size();
	int st = 0;
	rep(j, m) {
		int idx = -1;
		for (int i = st; i < n; i++) {
			if (mat[i][j]) {
				if (idx == -1) {
					idx = i;
					continue;
				}
				rep(k, m) {
					mat[i][k] ^= mat[idx][k];
				}
			}
		}
		for (int i = st - 1; i >= 0; i--) {
			if (mat[i][j]) {
				if (idx == -1) continue;
				rep(k, m) {
					mat[i][k] ^= mat[idx][k];
				}
			}
		}
		if (idx != -1) {
			rep(k, m) {
				swap(mat[idx][k], mat[st][k]);
			}
			st++;
		}
	}
	return st;
}

