bool add (long long val)
{
    for (int i=1; i<=nr; i++)
        if (val & (1LL << bit[i]))
            val ^= base[i];
    if (val != 0)
    {
        bit[++nr] = 0, base[nr] = val;
        while ((val & (1LL << bit[nr])) == 0)
            bit[nr] ++;
        for (int i=1; i<nr; i++)
            if (base[i] & (1LL << bit[nr]))
                base[i] ^= base[nr];
        return 1;
    }
    return 0;
}

