struct BASE {
  lol v[M];
  void init( void ) { memset( v , 0 , sizeof v ); }
  bool chk( lol x ) {
    for( int i = M - 1 ; ~i ; --i )
      if( ( x >> i ) & 1 ) {
        if( !v[i] ) return true;
        x ^= v[i];
      }
    return false;
  }
  void ins( lol x ) {
    for( int i = M - 1 ; ~i ; --i )
      if( ( x >> i ) & 1 ) {
        if( !v[i] ) return v[i] = x , void();
        x ^= v[i];
      }
