struct xorset {
    vector<T> basis;
    int BITS;
    vi rev;

    xorset() : BITS(sizeof(T)*8), rev(sizeof(T)*8, -1) {}

    void insert(T x){
        for (T b : basis)
            amin(x, x ^ b);
        if (x) basis.push_back(x);
    }

    bool has(T x){
        for (T b : basis)
            amin(x, x ^ b);
        return x == 0;
    }
};

