class AXorBattle {
public:
    void gaussianEliminationXOR(vector<vector<int>> &A) {
        int n = A.size(), m = A[0].size(), r = 0;
        set<int> c;
        for (int i = 0; r < n && i < m; ++i) {
            int to = r;
            FOR(j, r + 1, n) if (A[j][i] > A[to][i]) to = j;
            A[r].swap(A[to]);
            if (A[r][i] == 0) continue;
            FOR(j, r + 1, n) FOR(k, m, i) A[j][k] ^= A[r][k] & A[j][i];
            r++;
        }
        ERR(A)
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if(A[i][j]){c.insert(j);break;}
            }
        }
        ERR(c)
        VI cc(ALL(c));
        REP(i,n){
            int ok = 0;
            for(auto e : cc){if(ok)A[i][e] = 0;if(A[i][e])ok = 1;}
        }
//        return c;
    }
void solve(std::istream& cin, std::ostream& cout, std::ostream& cerr) {
        int T;
        cin >> T;
        while(T--){
            int N;cin >> N;
            vector<ll> a(N);cin >> a;
            string s;cin >> s;
            vector<VI> A0, A1;
            REP(i,N){
                bitset<63> t(a[i]);
                VI tt;
                REP(j,63)tt.EB(t[62-j]);
                if(s[i] == '1'){
                    A1.EB(tt);
                }
                else A0.EB(tt);
            }
            gaussianEliminationXOR(A1);
            gaussianEliminationXOR(A0);
            ERR(A1, A0)
            auto allzero = [&](VI a){
                for(auto v : a)if(v)return 0;
                return 1;
            };
            auto same = [&](VI t1, VI t2){
               REP(i,SZ(t1))if(t1[i] != t2[i])return 0;
               return 1;
            };
            auto cont = [&](VI a){
                REP(i,SZ(A0))if(same(A0[i], a))return 1;
                return 0;
            };
            auto ok = [&](){
                REP(i,SZ(A1))if(!allzero(A1[i]))if(!cont(A1[i]))return 0;
                return 1;
            };
            print(ok()?0:1);
        }
}


};


