void gaussJordan(vll &A, ll size) {
	int s = 0;
	for (ll b = size-1; b >= 0; b--) {
		//探す
		ll pos = -1;
		for (int i = s; i < A.size(); i++) {
			if ((A[i]>>b) & 1) { pos = i; break; }
		}
		if (pos == -1) continue;
		if (pos != s) swap(A[pos], A[s]);
		//消す
		for (int i = 0; i < A.size(); i++) {
			if (i != s && ((A[i]>>b) & 1)) A[i] ^= A[s];
		}
		s++;
	}
}

void solve() {
	ll N; cin >> N;
	vll A(N); cin >> A;
	string S; cin >> S;
	if (S.back() == 1) {
		cout << 1 << endl;
		return;
	}

	vll a, b;
	for (int i = 0; i < N; i++) {
		if (S[i] == '0') {
			a.push_back(A[i]);
		} else {
			b.push_back(A[i]);
		}
	}

	gaussJordan(a, 62);
	gaussJordan(b, 62);

	if (a == b) cout << 0 << endl;
	else cout << 1 << endl;
}

void Main() {
	ll T; cin >> T;
	while (T--) solve();
}

