void convert(vector<ll>&A){
	int idx=0;
	for(int i=60;i>=0;i--){
		bool flag=false;
		for(int j=idx;j<A.size();j++){
			if(A[j]>>i&1){
				flag=true;
				swap(A[idx],A[j]);
				break;
			}
		}
		for(int j=idx+1;j<A.size();j++){
			if(A[j]>>i&1){
				A[j]^=A[idx];
			}
		}
		if(flag)idx++;
	}	
}

bool can_make(vector<ll>A,ll x){
	convert(A);
	int j=0;
	for(int i=60;i>=0;i--){
		if(x>>i&1){
			for(;j<A.size();j++){
				if(A[j]>=(1LL<<(i+1)))continue;
				if(A[j]>>i&1){
					x^=A[j];
					j++;
					break;
				}
			}
			if(x>>i&1)return false;
		}
	}
	return true;
}

