auto solve(ll n, const VL& a, const string& s) ->bool {
	VVL values; values.reserve(n);
	{
		VL now; now.reserve(n);
		RREP(i, n) {
			if (s[i] == '0') {
				ll val = a[i];
				REPC(x, now) {
					ll newv = (val ^ x);
					chmin(val, newv);
				}
				now.emplace_back(val);
				RFOR(j, 1, now.size()) {
					if (now[j - 1] < now[j]) {
						std::swap(now[j - 1], now[j]);
					} else break;
				}
			}
			values.emplace_back(now);
		}
	}
	//dump(values);
	REP(i, n)if (s[i] == '1') {
		ll val = a[i];
		REPC(x, values[n - i - 1]) {
			chmin(val, (val ^ x));
		}
		if (val > 0) { return false; }
	}
	return true;
}


