ll cbit(ll i){
  ll tmp=0;
  for(tmp=0;i>0;i/=2){
    tmp++;
  }
  return tmp;
}





ll kensyo(ll aj)
{
  if (aj==0){
    return 0;
  }
  if (zw==0){
    return 1;
  }


  ll caj=cbit(aj);
  ll myno=0;
  vi zdmy(zw);
  ll maxno=0;
  for(int i=0;i<zw;i++){
    zdmy[i]=zsan[i];
    maxno=max(maxno,zsan[i]);
  }

  ll mcbit=cbit(maxno);//maxnoは1<<(mcbit-1)以上～1<<mcbit未満
  if (aj>=(1LL<<mcbit))return 2;

  ll newmaxno=0;
  for(int i=0;i<64;i++){
    mcbit=cbit(maxno);//maxnoは1<<(mcbit-1)以上～1<<mcbit未満
    if (aj>=(1LL<<mcbit))return 3;
    if ((1LL<<(mcbit-1))<=aj)
    {
      aj^=maxno;//これで最上位がきえた
    }
    //cout<<"aj"<<aj<<" ";

    newmaxno=0;
    for(ll j=0;j<zw;j++){
      if ((1LL<<(mcbit-1))<=zdmy[j]) zdmy[j]^=maxno;
      newmaxno=max(newmaxno,zdmy[j]);
    }
    maxno=newmaxno;
    if (maxno==0)break;
  }

  if (aj!=0){
    return 4;
  }
  return 0;
}





