template<typename T>
struct xorset {
    vector<T> basis;
    xorset() {}

    void sweep(){
        int L = basis.size();
        int BITS = (sizeof(T) == 8) ? 64 : 32;
        vector<bool> used(L, false);
        for (int b=BITS-2; b>=0; --b){
            T m = 1LL << b;
            rep(i,L){
                if (used[i]) continue;
                if (basis[i] & m) {
                    rep(j,L){
                        if (j==i) continue;
                        if (basis[j] & m){
                            basis[j] ^= basis[i];
                        }
                    }
                    used[i] = true;
                    break;
                }
            }
        }
        set<T> tmp(ALL(basis));
        if (found(tmp,0)) tmp.erase(0);
        basis.assign(ALL(tmp));
    }
    void insert(T x){
        if (this->has(x)) return;
        basis.pb(x);
        sweep();
    }
    bool has(T x){
        bool res = false;
        if (x == 0) {
            res = true;
        } else {
            for (T b: basis){
                if ((x & b) == 0) continue;
                if ((x & b) != b) { res = false; break; }
                x ^= b;
                if (x == 0) { res = true; break; }
            }
        }
        return res;
    }
};

