struct obs // orderd bit set
{
    ll a;
    friend bool operator<(const obs &x, const obs &y)
    {
        return tie(x.a) < tie(y.a);
    }
    friend bool operator==(const obs &x, const obs &y)
    {
        return x.a == y.a;
    }
    friend obs operator^(const obs &x, const obs &y)
    {
        ll aaaa = (bitset<64>(x.a) ^ bitset<64>(y.a)).to_ullong();
        return obs{aaaa};
    }
};

// これを受け取ったら0さんは勝てる
set<obs> canWin(obs a, set<obs> x)
{
    set<obs> result = x;
    for (obs y : x)
    {
        result.insert(y ^ a);
    }
    return result;
}

// これを受け取ったら1さんは勝てない
set<obs> mustLose(obs a, set<obs> x)
{
    set<obs> result;
    set<obs> temp;
    for (obs y : x)
    {
        if (contains_set(temp, y ^ a))
        {
            result.insert(y);
            result.insert(y ^ a);
            temp.erase(y ^ a);
        }
        else
        {
            temp.insert(y);
        }
    }
    return result;
}

