        for (int i = 0; i < N; i++) {
            if (S[i] == '0') {
                a++;
            } else {
                b++;
            }
        }
        BitMatrix One(b, 64);
        int i = 0;
        b = 0;
        while (i < N) {
            for (; i < N && S[i] == '1'; i++) {
                One[b] = A[i];
                b++;
            }
            BitMatrix Zero(a, 64);
            int za = 0;
            for (; i < N && S[i] == '0'; i++) {
                Zero[za] = A[i];
