const int LOG = 60;

long long basis[LOG];

/* https://codeforces.com/blog/entry/68953 */
bool checkXor(int mask) {
	for (int i = 0; i < LOG; i++) {
		if ((mask & 1 << i) == 0) continue;

		if (!basis[i]) return false;

		mask ^= basis[i];
	}

	return true;
}
void insertVector(long long mask) {
	for (int i = 0; i < LOG; i++) {
		if ((mask & (1LL << i)) == 0) continue;

		if (!basis[i]) {
			basis[i] = mask;

			return;
		}

		mask ^= basis[i];
	}
}

