const int COL = 64;
template<int MAX_COL>
struct BitMatrix {
    int H;
    vector<bitset<MAX_COL>> A;
    BitMatrix(int m) : H(m),A(m) {}

    int GaussJordan() {
        int rank = 0;
        for (int col = 0; col < MAX_COL; ++col) {
            int pivot = -1;
            for (int row = rank; row < H; ++row) {
                if (A[row][col]) {
                    pivot = row;
                    break;
                }
            }
            if (pivot == -1) continue;
            swap(A[pivot], A[rank]);
            for (int row = 0; row < H; ++row) {
                if (row != rank && A[row][col]) A[row] ^= A[rank];
            }
            ++rank;
        }
        return rank;
    }
};

using BM = BitMatrix<COL>; 

void solve() {
