    BM mat(N);
    rep(i,N) {
        //cout << i << endl;
        if (S[i]=='1') {
            int MAX = mat.GaussJordan();
            int rank = 0;
            rep(bit,COL) {
                if ((A[i]>>bit)&1) {
                    while (rank < MAX) {
                        if (mat.A[rank][bit]) {
                            rep(j,COL) {
                                if (mat.A[rank][j]) A[i] ^= (1ull<<j);
                            }
                            rank++;
                            break;
                        }
                        rank++;
                    }
                }
            }
            if (A[i]) {
                cout << 1 << ln;
                return;
            }
        } else {
            rep(bit,COL) {
                if ((A[i]>>bit)&1) {
                    mat.A[i][bit] = 1;
                }
            }
        }
    }

    cout << 0 << ln;

}
