        vector<ll> bases;
        for (int i=n-1; i>=0; i--) {
            bool now = s[(size_t)i] - '0';
            if (now) {
                for (auto &bi:bases) {
                    a[i] = min(a[i], a[i]^bi);
                }
                if (a[i]) {
                    ans = true;
                    break;
                }
            } else {
                bases.push_back(a[i]);
                gauss_jordan(bases);
            }
        }
        cout << ans << '\n';
    }
    return 0;
}

