void v_insert(vector<ulint>& u, ulint a){
    for(ulint v: u){
        u.push_back(a^v);
    }
    if(u.empty()) return;
    sort(all(u));
    u.erase(unique(u.begin(), u.end()), u.end());   
}

void v_erase(vector<ulint>& u, ulint a){
    auto itr = lower_bound(all(u), a);
    if(itr != u.end() && *itr == a) return;
    else u.clear();
}

int solve(int n, vector<ulint>& a, string s){
    if(s[n-1] == '1') return 1;
    int now = (s[0]-'0');
    vector<ulint> tmp; tmp.push_back(0ULL);
    repr(i, n){
        if((s[i]-'0') == 0){
            v_insert(tmp, a[i]);
        }else{
            v_erase(tmp, a[i]);
        }
    }
    if(!tmp.empty() && tmp[0] == 0ULL) return 0;
    else return 1;
}

