auto get_base(std::vector<i64> v) {
    std::vector<i64> ret;
    const int n = v.size();
    int r = 0;
    for (i64 j = 0; j < 60; j++) {
        int p = -1;
        for (int i = r; i < n; i++) {
            if (v[i] & (1ll << j)) {
                p = i;
                break;
            }
        }

        if (p < 0) continue;
        std::swap(v[p], v[r]);
        ret.push_back(v[r]);

        for (int i = 0; i < n; i++) {
            if (i != r && (v[i] & (1ll << j))) v[i] ^= v[r];
        }
        r++;
    }

    return ret;
}

