class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    int N;
    vector<ull> A;
    string S;

    bool input() {
        is >> N;
        A.resize(N);
        is >> A >> S;
        return !!is;
    }

    vector<ull> base(vector<ull>& x){
        for (int i = 0; i < x.size(); ++i) {
            sort(RALL(x));
            for (int j = 0; j < x.size(); ++j) {
                if(j == i) continue;
                if((x[j] ^ x[i]) < x[j]){
                    x[j] ^= x[i];
                }
            } // end j
        } // end i
        sort(ALL(x));

        x.erase(unique(ALL(x)), x.end());

        return x;
    }

    bool can(const vector<ull>&x, ull k){
        for (auto i : x) {
            if(k & i){
                k ^= i;
            }
        } // end i
        return k == 0;
    }

    bool div(vector<ull>&b, vector<ull>& a){
        for (auto &&ak : a) {
            bool k = false;
            for (auto &&bi : b) {
                if(bi & ak){
                    bi ^= ak;
                    k = true;
                }
            } // end bi
            if(!k) return false;
        } // end ak
        sort(ALL(b));
        b.erase(unique(ALL(b)), b.end());

        return true;
    }

    void solve(){
        int l;
        l = N;
        vector<ull> b;

        while(l-- > 0){
            if(S[l] == '1'){
                if(!can(b, A[l])){
                    os << 1 << endl;
                    return;
                }
            }
            else {
                b.push_back(A[l]);
                base(b);
            }
        }
        os << 0 << '\n';
    }

    void run();
};

int main(int argc, char *argv[]) {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout << setprecision(16) << scientific;
#ifdef XELMH
    string test_cases = "test_A.txt";
    cerr << test_cases << " -->" << endl;
    auto fs = fstream(test_cases, fstream::in);
    int loop = 0;
    while(fs) {
        loop++;
        cout << '#' << loop << "#------\n";
        solver(fs, cout).run();
    }
    if(loop <= 1) {
        cout << "===" << endl;
        while(cin) solver(cin, cout).run();
    }
#else
    solver(cin, cout).run();
#endif
    return 0;
}


void solver::run(){
    int T=0;
    is >> T;
    while(T-->0){
        if(!input()) return;
        solve();
    }
}

