void add_num(ll a) {
    span.emplace_back(a);
    RSORT(span);
    int sz = span.size();
    REP(i, sz) {
        REP(j, i + 1, sz) {
            span[i] ^= span[j];
        }
    }
}

bool find_num(ll a) {
    for (auto& e: span) chmin(a, a ^ e);
    return a == 0LL;
}

