bool dfs(vector<map<LL,bool>> &memo, int n, VLL &a, string &s, int pos, LL x) {
    if (pos == n) return x == 0;

    if (memo[pos].count(x) > 0) return memo[pos][x];

    if (s[pos] == '0') return memo[pos][x] = dfs(memo,n,a,s,pos+1,x) || dfs(memo,n,a,s,pos+1,(x^a[pos]));
    else return memo[pos][x] = dfs(memo,n,a,s,pos+1,x) && dfs(memo,n,a,s,pos+1,(x^a[pos]));
}

