struct base{
	long long arr[63]; base(){memset(arr , 0 , sizeof(arr));}
	bool ins(long long val){
		for(int i = 60 ; ~i ; --i)
			if(val >> i & 1)
				if(arr[i]) val ^= arr[i];
				else{arr[i] = val; return 1;}
		return 0;
	}
	bool find(long long val){
		for(int i = 60 ; ~i ; --i)
			if(val >> i & 1)
				if(arr[i]) val ^= arr[i];
				else return 0;
		return 1;
	}
};

