int extgcd(int a,int b,int& x,int& y)
{
  int d = a;
  if(b != 0){
    d = extgcd(b,a%b,y,x);
    y -= (a/b)*x;
  }
  else
    x = 1,y = 0;
  return d;
}

int mod_inv(int a,int m)
{
  int x,y;
  extgcd(a,m,x,y);
  return (m+x%m)%m;
}


int _rank(vector<vector<int> > A,int mod)
{
  int H = A.size(), W = A[0].size();
  int r = 0;
  rep(x,W)
    { 
      int pivot = INT_MAX;
      REP(y,r,H)
    if(A[y][x])
      {
        pivot = y;
        break;
      }
      if(pivot == INT_MAX)continue;
      swap(A[r],A[pivot]);

      REP(y,r+1,H)
    {
      int value = A[y][x] * mod_inv(A[r][x],mod) % mod;
      if(value)REP(x2,x,W)
             A[y][x2] = ((A[y][x2] - A[r][x2] * value)%mod + mod ) % mod;
    }
      r++;
    }
  return r;
}



