typedef long long ll;

void Canonize(vector<ll>& a) {
  int n = a.size();
  for (;;) {
    bool ok = true;
    for (int i = 0; i < n; ++i) for (int j = 0; j < n; ++j) if (i != j && (a[i] ^ a[j]) < a[i]) {
      a[i] ^= a[j];
      ok = false;
    }
    if (ok) break;
  }
  vector<ll> result;
  for (ll x : a) if (x > 0) result.push_back(x);
  a = result;
}

