namespace xor_helpers {
    template<typename T>
    std::vector<T> get_base(const std::vector<T> &a) {
        std::vector<T> base;
        for (T t : a) {
            for (T &b : base) {
                t = std::min(t, t ^ b);
            }
            if (t != 0) {
                base.push_back(t);
            }
        }
        for (int i = ((int) base.size()) - 1; i >= 0; i--) {
            sort(base.begin(), base.begin() + i + 1);
            T cur = base[i];
            for (int j = ((int) base.size()) - 2; j >= 0; j--) {
                base[j] = std::min(base[j], base[j] ^ cur);
            }
        }
        return base;
    }
}
