bool can_represent(ll x, vector <ll> &V) {//V is normalized
  for (auto it : V) {
    int last_bit = __builtin_ctzll(it);
    if (x >> last_bit & 1) x ^= it;
  }

  return x == 0;
}

void normalize(vector <ll> &V) {
  int ind=0;

  REP(i, DIM) {
    FOR(j, ind, (int) V.size()) {
      if (V[j] >> i & 1) {
        swap(V[ind], V[j]);
        FOR(k, j+1, (int) V.size())
          if (V[k] >> i & 1)
            V[k] ^= V[ind];

        ind++;
        break;
      }
    }
  }
}

