struct BitwiseGauss {
    int B;
    vector<ll> bb;
    BitwiseGauss(int _B) {
        B = _B;
        bb.resize(B);
    }

    void insert(ll x) {
        for (int i = B - 1; i >= 0; --i) {
            if (((x >> i) & 1)) {
                if (bb[i]) {
                    x ^= bb[i];
                } else {
                    bb[i] = x;
                    break;
                }
            }
        }
    }
    bool can(ll x) {
    	for (int i = B - 1; i >= 0; --i) {
    		if (((x >> i) & 1)) {
                if (bb[i]) {
                    x ^= bb[i];
                }
            }
    	}
    	return x == 0;
    }
    void clear() {
        fill(bb.begin(), bb.end(), 0);
    }
};

