ll basis[64]; 
int sz; 
void insertVector(ll mask) {
    for (int i = 0; i < d; i++) {
        ll zz=pow(2,i);
        if ((mask & zz) == 0) continue; // continue if i != f(mask)
        if (!basis[i]) { // If there is no basis vector with the i'th bit set, then insert this vector into the basis
            basis[i] = mask;
            ++sz;   
            return;
        }
        mask ^= basis[i]; 
    }
}
