vector<ll> basis;
vector<int> bit;
set<int> bits;

void reset() {
  derr << "resetting" << endl;
  basis.clear();
  bit.clear();
  bits.clear();
}
bool tryadd(ll x) {
  derr << "trying to add " << x << endl;
  for(int i = 0; i < sz(basis); i++) {
    ll mask = 1LL << bit[i];
    if(x&mask) {
      x ^= basis[i];
    }
  }
  if(x == 0) return false;
  derr << "turns into " << x << endl;
  int id = 0;
  while(bits.count(id) || (x&(1LL<<id)) == 0) id++;
  basis.push_back(x);
  bit.push_back(id);
  bits.insert(id);
  return true;
}

ll l[205];
string s;
int n;
void rsolve() {
  cin >> n;
  for(int i = 0; i < n; i++) cin >> l[i];
  cin >> s;
  for(int i = 0; i < n;) {
    if(s[i] == '1') {
      tryadd(l[i]);
      i++;
    }
    else {
      vector<ll> enemy;
      for(ll out: basis) {
        enemy.push_back(out);
      }
      reset();
      int j = i;
      while(j < n && s[j] == '0') tryadd(l[j++]);
      vector<ll> nenemy;
      for(ll out: enemy) {
        if(tryadd(out)) {
          derr << "enemy gains " << basis.back() << endl;
          nenemy.push_back(basis.back());
        }
      }
      reset();
      for(ll out: nenemy) assert(tryadd(out));
      i = j;
    }
  }
  if(sz(basis)) cout << 1 << "\n";
  else cout << 0 << "\n";
}

void solve() {
  int t;
  cin >> t;
  while(t--) rsolve();
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL); cout.tie(NULL);
  solve();
}

