    vector<vi> c;
    while (1) {
        c.push_back({});
        int f = 0;
        for (int &x: a) {
            c[c.size() - 1].push_back(x % 2);
            x /= 2;
            if (x > 0) f = 1;
        }
        c[c.size() - 1].push_back(x % 2);
        x /= 2;
        if (!f && x == 0) break;
    }
    vi sn;
    return gauss(c, sn) > 0;
