	string S;
	vector<vector<int>> memo;
	map<int,int> sel;
	Hoge(int N, const vector<int>& a, string S) : N(N), a(a), S(S), memo(N, vector<int>(2, -1)) {}
	int run(int p, int q) {
		if (p == N) return q;
		if (a[p] == 0) return run(p+1, q);
		if (memo[p][q] != -1) return memo[p][q];
		int r;
		if (S[p] == '0') {
			int r1 = run(p+1, q);
			int r2 = run(p+1, q^1);
			if (r1 == 0) sel[p] |= 1;
			if (r2 == 0) sel[p] |= 2;
			if (r1 == 0 || r2 == 0) r = 0;
			else r = 1;
		} else {
			if (run(p+1, q) == 1 || run(p+1, q^1) == 1) r = 1;
			else r = 0;
		}
		return memo[p][q] = r;
	}
};
int solve() {
	int N;
	cin >> N;
	vector<ll> A(N);
	for (auto& x : A) cin >> x;
	string S;
	cin >> S;
	vector<map<int,int>> sels;
	for (int i = 0; i < 60; ++ i) {
		vector<int> a;
		for (auto x : A) a.push_back((x >> i) & 1);
		Hoge hoge(N, a, S);
		if (hoge.run(0, 0)) return 1;
		sels.push_back(hoge.sel);
	}
	for (int i = 0; i < N; ++ i) if (S[i] == '0') {
		int t = 3;
		for (auto& s : sels) {
			if (s.count(i)) {
				t &= s[i];
			}
		}
		if (t == 0) return 1;
	}
	return 0;
}
int main() {
	int T;
	cin >> T;
	for (int tt = 0; tt < T; ++ tt) {
		cout << solve() << endl;
	}
}

