template<typename T>
struct xorset {
    vector<T> basis;
    vi rev;
    int BITS;

    xorset() : BITS(sizeof(T)*8), rev(sizeof(T)*8, -1) {}


    void sweep(){
        int L = basis.size();
        sort(ALL(basis), greater<T>());
        vector<bool> used(L, false); int ucnt = 0;
        for (int b=BITS-2; b>=0; --b){
            T m = 1LL << b;
            rep(i,L){
                if (basis[i] == 0) { ++ucnt; continue; }
                if (used[i]) continue;
                if (basis[i] & m) {
                    rep(j,L){
                        if (j==i) continue;
                        if (basis[j] & m){
                            basis[j] ^= basis[i];
                        }
                    }
                    used[i] = true; ++ucnt;
                    rev[b] = i;
                    break;
                }
            }
        }
        assert(ucnt == L);
        set<T> tmp(ALL(basis));
        if (found(tmp,0)) tmp.erase(0);
        basis.assign(tmp.rbegin(), tmp.rend());
    }
    void insert(T x){
        if (this->has(x)) return;
        basis.pb(x);
        sweep();
    }
    bool has(T x){
        bool res = false;
        if (x == 0) {
            res = true;
        } else {
            for(int b=BITS-2; b>=0; --b){
                T m = 1LL << b;
                if (!(x & m)) continue;

                if (rev[b] == -1) {
                    res = false; break;
                }
                T ba = basis[rev[b]];
                assert(ba & x);
                x ^= ba;
            }
            if (x == 0) res = true;
        }
        return res;
    }
};

