        bool is_zero = true;
        BitMatrix mat(62, 210);
        Vi b(62), vec;
        for (ll i = 0; i < N; i++) {
            if (S[i] == '0') {
                for (ll j = 0; j < 62; j++) {
                    mat[j][i] = (A[i] & (1ll << j)) ? 1 : 0;
                }
            }
            else {
                for (ll j = 0; j < 62; j++) {
                    b[j] = (A[i] & (1ll << j)) ? 1 : 0;
                }
                ll res = linear_equation(mat, b, vec);
                if (res == -1) {
                    is_zero = false;
                    break;
                }
            }
        }

        if (is_zero) {
            cout << 0 << "\n";
        }
        else {
            cout << 1 << "\n";
        }
    }
}

