    for(long long j = index; j < a.size(); j++){
      if(a[j] & (1ll << b)){
        flag = 1;
        swap(a[j], a[index]);
        break;
      }
    }
    for(long long j = index + 1; j < a.size(); j++){
      if(a[j] & (1ll << b)){
        a[j] ^= a[index];
      }
    }
    if(flag == 1){
      index++;
    }
  }

  index = 0;
  for(int b = 59; b >= 0; b--){
    if((1ll << b) & x){
      if(a[index] & (1ll << b)){
        x ^= a[index];
        index++;
      }else{
        index++;
      }
    }else{
      while(index < a.size() && (a[index] & (1ll << b))){
        index++;
      }
    }
    if(x == 0) return true;
    if(index == a.size()) return false;
  }
