void addBasis(ll a) {
  for(ll i = LOGN - 1; i >= 0; i--) {
    if(ve[i] != -1 && ((a >> i) & 1))
      a ^= ve[i];
  }
  if(a == 0)
    return;
  for(ll i = LOGN - 1; i >= 0; i--) {
    if(ve[i] == -1 && ((a >> i) & 1)){
      ve[i] = a;
      break;
    }
  }
}

bool cek(ll a) {
  for(ll i = LOGN - 1; i >= 0; i--) {
    if(ve[i] != -1 && ((a >> i) & 1))
      a ^= ve[i];
  }
  return a == 0;
}

