class AXorBattle {
public:
    void solve() {
        int n = in.readInt();
        auto a = in.readLongArray(n);
        auto s = in.readString();

        reverse(all(a));
        reverse(all(s));
        vector<ll> base;
        for (int i : range(n)) {
            ll cur = a[i];
            for (ll j : base) {
                if ((cur ^ j) < cur) {
                    cur = cur ^ j;
                }
            }
            if (cur == 0) {
                continue;
            }
            if (s[i] == '1') {
                out.printLine(1);
                return;
            }
            for (ll& j : base) {
                if ((j ^ cur) < j) {
                    j ^= cur;
                }
            }
            base.push_back(cur);
            sort(all(base), greater<>());
        }
        out.printLine(0);
    }
};


