struct Game {
    int N;
    vll a;
    string s;

    using P = pair<int, vll>;
    vector<P> chunks;

    Game(){
    }
    void read(){
        cin >> N;
        a.resize(N);
        rep(i,N) cin >> a[i];
        cin >> s;

        chunks.clear();

        int last = '?';
        vll chunk;
        rep(i,N){
            if (s[i]==last){
                chunk.pb(a[i]);
            } else {
                if (!chunk.empty()) {
                    chunks.eb(last-'0', chunk);
                    chunk.clear();
                }
                last = s[i];
                chunk.assign(1, a[i]);
            }
        }
        if (!chunk.empty()) {
            chunks.eb(last-'0', chunk);
        }
    #ifdef DEBUG
        rep(i,chunks.size()){
            cerr << chunks[i].first << chunks[i].second << " | ";
        }
        cerr << endl;
    #endif
        reverse(ALL(chunks));
    }

    set<ll> naive(vll& a){
        int L = a.size();
        vector<set<ll>> s(2);
        s[0].insert(0);
        rep(i,L){
            int i0=i%2, i1=1-i0;
            s[i1].clear();
            for(ll x: s[i0]){
                s[i1].insert(x);
                s[i1].insert(x ^ a[i]);
            }
        }
        return s[L%2];
    }

    bool can_block(vll& bs, vll& as){
        set<ll> sb = naive(bs), sa = naive(as);
        for(ll x: bs){
            if (!found(sa,x)) return false;
        }
        return true;
    }

    int solve(){
        if (chunks[0].first == 1) return 1;

        vll as, bs;
        rep(i,chunks.size()){
            if (chunks[i].first == 0){
                as.insert(as.end(), ALL(chunks[i].second));
            } else {
                bs.insert(bs.end(), ALL(chunks[i].second));
                if (!can_block(bs, as)) return 1;
            }
        }
        return 0;
    }
};

