int n;
string s;
ll ar[N];
vector<ll> ve;

void addBasis(ll a) {
  for(ll i = LOGN - 1; i >= 0; i--) {
    if(ve[i] != -1 && ((a >> i) & 1))
      a ^= ve[i];
  }
  if(a == 0)
    return;
  for(ll i = LOGN - 1; i >= 0; i--) {
    if(ve[i] == -1 && ((a >> i) & 1)){
      ve[i] = a;
      break;
    }
  }
}

bool cek(ll a) {
  for(ll i = LOGN - 1; i >= 0; i--) {
    if(ve[i] != -1 && ((a >> i) & 1))
      a ^= ve[i];
  }
  return a == 0;
}

int main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0); cout.tie(0);

  #ifndef ONLINE_JUDGE
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
  #endif

  int tc;
  cin >> tc;
  while(tc--) {
  	cin >> n;
  	for(int i = 1; i <= n; i++) {
      cin >> ar[i];
  	}
    cin >> s;
    if(s[n - 1] == '1') {
      cout << 1;
    } else {
      bool belum = true;
      vector<int> t;
      ve.assign(LOGN, -1);
      for(int i = n - 1; i >= 0; i--) {
        if(s[i] == '0'){
          if(belum)
            addBasis(ar[i + 1]);
        }
        else if(s[i] == '1') {
          belum = false;
          t.push_back(ar[i + 1]);
        }
      }
      bool ok = true;
      for(auto j : t) {
        ok &= cek(j);
      }
      cout << (ok ? 0 : 1);
    }
    cout << '\n';
  }
  return 0;
}

