int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);

  int t; cin>>t;
  while (t--) {
    int n; cin>>n;
    vector<unsigned long long> A(n); for (auto& a:A) cin>>a;
    string s; cin>>s;
    vector<unsigned long long> B(64, -1ull);
    auto set_base = [&B](unsigned long long x) {
      for (int i = 0; i < 64; i++) {
        if ((x & (1ull<<i)) == 0) continue;
        if (B[i] == -1ull) {
          B[i] = x;
          return;
        }
        x ^= B[i];
      }
    };
    auto offset = [&](unsigned long long x) {
      for (int i = 0; i < 64; i++) {
        if ((x & (1ull<<i)) == 0) continue;
        if (B[i] == -1)
          return false;
        x ^= B[i];
      }
      return true;
    };
    auto solve = [&]() {
      for (int i = n-1; i >= 0; i--) {
        if (s[i] == '0') {
          set_base(A[i]);
        } else {
          if (!offset(A[i]))
            return false;
        }
      }
      return true;
    };
    cout << (solve() ? 0 : 1) << endl;
  }

  return 0;
}

