bool vis0[62][4];
bool vis1[62][4];
bool memo0[62][4];
bool memo1[62][4];


bool t0(int p, int cur);
bool t1(int p, int cur);

bool t0(int p, int cur) {
    if (vis0[p][cur]) {
        return memo0[p][cur];
    }
    vis0[p][cur] = true;
    auto& memo   = memo0[p][cur];
    memo         = false;
    for (int a : {0, x[p]}) {
        int nxt = cur ^ a;
        if (p == N) {
            memo |= nxt == 0;
        }
        else {
            if (S[p] == '0') {
                memo |= t0(p + 1, nxt);
            }
            else {
                memo |= !t1(p + 1, nxt);
            }
        }
    }
    return memo;
}
bool t1(int p, int cur) {
    if (vis1[p][cur]) {
        return memo1[p][cur];
    }
    vis1[p][cur] = true;
    auto& memo   = memo1[p][cur];
    memo         = false;
    for (int a : {0, x[p]}) {
        int nxt = cur ^ a;
        if (p == N) {
            memo |= nxt != 0;
        }
        else {
            if (S[p] == '0') {
                memo |= !t0(p + 1, nxt);
            }
            else {
                memo |= t1(p + 1, nxt);
            }
        }
    }
    return memo;
}


