template<typename T, int K>
struct Basis {
  array<T, K> bas;
  int n, rank;
  Basis() : bas(), n(), rank() {}
  bool add(T x) {
    ++n;
    for (int i = K - 1; i >= 0; --i) {
      if (x >> i & 1) {
        if (bas[i]) {
          x ^= bas[i];
        } else {
          bas[i] = x, ++rank;
          return true;
        }
      }
    }
    return false;
  }
  Basis operator + (Basis o) const {
    for (int i = 0; i < K; ++i) if (bas[i]) o.add(bas[i]);
    return o;
  }
  bool operator == (const Basis &o) const {
    for (int i = 0; i < K; ++i) if (bas[i] != o.bas[i]) return false;
    return true;
  }
};

