void GaussJordan(vector<bitset<62>> &A){
  int rank=0;
  for(int col=61;col>=0;col--){
    int pivot=-1;
    for(int row=rank;row<201;row++){
      if(A[row].test(col)) {
        pivot=row;
        break;
      }
    }
    if(pivot==-1)continue;
    bitset<62> tmp=A[rank];
    A[rank]=A[pivot];
    A[pivot]=tmp;
    for(int row=0;row<201;row++){
      if(row!=rank && A[row][col])A[row]^=A[rank];
    }
    rank++;
  }
}

