const ll d = 60;
ll basis[d]; // basis[i] keeps the mask of the vector whose f value is i

void insertVector(ll mask) {
	for (ll i = 0; i < d; i++) {
		if ((mask & 1 << i) == 0) continue; // continue if i != f(mask)

		if (!basis[i]) { // If there is no basis vector with the i'th bit set, then insert this vector into the basis
			basis[i] = mask;
			return;
		}

		mask ^= basis[i]; // Otherwise subtract the basis vector from this vector
	}
}

bool is_present(ll v){
	ll curval = 0;
	for (ll i = 0; i < d; i++) {
		if (basis[i] && ((curval ^ v) & (1<<i))) { // If there is no basis vector with the i'th bit set, then insert this vector into the basis
			curval ^= basis[i];
		}
	}
	if(curval == v) return 1;
	else return 0;
}

