void solve() {
	ll N; cin >> N;
	vll A(N); cin >> A;
	string S; cin >> S;

	if (S.back() == '1') {
		cout << 1 << endl;
		return;
	}
	for (ll b = 0; b < 62; b++) {
		for (int i = N-1; i >= 0; i--) {
			if (((A[i]>>b)&1) == 1) {
				if (S[i] == '1') { cout << 1 << endl; return; }
				else break;	
			}
		}
	}
	for (ll ba = 0; ba < 62; ba++) {
		for (ll bb = ba+1; bb < 62; bb++) {
			int color = -1;
			int val1 = -1;
			bool flag1 = false, flag2 = false;
			for (int i = N-1; i >= 0; i--) {
				int a = (A[i]>>ba)&1;
				int b = (A[i]>>bb)&1;
				if (!flag1 && a == 1 && b == 0) {
					if (S[i] == '1') { cout << 1 << endl; return; }
					else flag1 = true;
				}
				if (!flag2 && a == 0 && b == 1) {
					if (S[i] == '1') { cout << 1 << endl; return; }
					else flag2 = true;
				}

				if (S[i]-'0' != color) {
					color = S[i]-'0';
					val1 = -1;
				}
				int dat = (a<<1) | b;
				if (dat > 0) {
					if (val1 == -1) {
						val1 = dat;
					} else if (val1 != dat) {
						if (color == 1) { cout << 1 << endl; return; }
						else break;
					}
				}
				//if (ba == 0 && bb == 1) cout << a << " " << b << endl;
			}
		}
	}
	cout << 0 << endl;
}

