// vを上三角化する
void make(vector<ll> &v){
    int ind = 0;
    int sz = v.size();
    bool check;
    for (int i = 62; i >= 0; i--) {
        if(ind == sz) break;
        check = true;
        if(!(v[ind] & 1LL<<i)){
            check = false;
            for (int j = ind+1; j < sz; j++) {
                if(v[j] & 1LL<<i){
                    swap(v[ind], v[j]);
                    check = true;
                    break;
                }
            }
        }
        if(!check) continue;
        for (int j = 0; j < sz; j++) {
            if(j == ind) continue;
            if(v[j] & 1LL<<i){
                v[j] = v[j] ^ v[ind];
            }
        }
        ind++;
    }
}

// 上三角化されたvでaが作れるか判定する
bool ok(vector<ll> &v, ll a){
    ll tmp = a;
    int ind = 0;
    int sz = v.size();
    for (ll i = 62; i >= 0; i--) {
        if(ind == sz) break;
        if(!(v[ind] & 1LL<<i)) continue;
        if(tmp & 1LL<<i){
            tmp = v[ind] ^ tmp;
        }
        ind++;
    }
    return tmp == 0;
}

