                auto memo = buf;
                int sz2 = memo.size();
                int rank = 0;
                for (int j = 59; j >= 0; j--) {
                    int pivot = -1;
                    for (int k = rank; k < sz2; k++) {
                        if (memo[k] >> j & 1) {
                            pivot = k;
                            break;
                        }
                    }

