                    V<int> b(61), x;
                    for (int j = i - c1 - c0; j < i - c0; j++) {
                        for (int k = 0; k < 61; k++) {
                            if ((a[j] >> k) & 1LL) {
                                b[k] = 1;
                            } else {
                                b[k] = 0;
                            }
                        }
                        int res = LinearEquation(m, b, x);
                        if (res == -1) {
                            f = false;
                        }
                    }
                    c0 = 0, c1 = 1;
                } else {
                    c1++;
                }
            }
        }
        if (c0 > 0) {
            BitMatrix m(61, c0);
            for (int j = n - c0; j < n; j++) {
                for (int k = 0; k < 61; k++) {
                    if ((a[j] >> k) & 1LL) {
                        m[k][j - (n - c0)] = 1;
                    }
                }
            }
            V<int> b(61), x;
            for (int j = n - c1 - c0; j < n - c0; j++) {
                for (int k = 0; k < 61; k++) {
                    if ((a[j] >> k) & 1LL) {
                        b[k] = 1;
                    } else {
                        b[k] = 0;
                    }
                }
                int res = LinearEquation(m, b, x);
                if (res == -1) {
                    f = false;
                }
            }
        }
        cout << (f ? 0 : 1) << '\n';
    }
}

