vl base(vl x){
    sort(rall(x));
    int n = sz(x);
    rep(i,n)
        rep(j,i+1,n-1){
            if((x[j]^x[i]) < x[j])
                x[j] ^= x[i];
        }
    sort(all(x));
    per(i,n)
        rep(j,0,i-1){
            if((x[i] ^ x[j]) < x[i])
                x[i] ^= x[j];
        }
    unique(x);
    return x;
}
bool can_make(vl y, ll x){
    sort(rall(y));
    for(auto _ : y)
        if((x^_) < x)
            x ^= _;
    return x == 0;
}
bool match(vpll a, vpll b){
    vl x,y;
    for(auto _ : a)
        x.pb(_.X);
    for(auto _ : b)
        y.pb(_.X);
    x = base(x);
    y = base(y);
    if(sz(x) > sz(y))
        return false;
    for(ll _ : x)
        if(!can_make(y,_))
            return false;
    return true;
}
