typedef unsigned long long bvec;
const int BITS = sizeof(bvec)*8;
struct basis{
	int rk; bvec dat[BITS];
	void init(){ rk = 0;	for (int i = 0; i < BITS; ++i)	dat[i] = 0; }
	void insert(bvec x){
		for (int k = 0; x && k < BITS; ++k)      if((x&dat[k])>>k)
			x ^= dat[k];
		if(x == 0)	return;
		int p = BITS-1-__builtin_clzll(x);
		dat[p] = x;
		for (int k = p+1; k < BITS; ++k)    if(dat[k]>>p&1)
			dat[k] ^= x;
		++rk;
		assert(rk <= BITS);
	}
	bvec greatest(){
		bvec ret = 0;
		for (int i = 0; i < BITS; ++i)	ret ^= dat[i];
		return ret;
	}
};

const int MAX_N = 200;
int64 A[MAX_N];
basis crt, backup;
bool same(const basis& A, const basis &B){
	FOR(i,BITS)
		if(A.dat[i] != B.dat[i])
			return false;
	return true;
}

