mod num(ll N, ll A) {
	// 0 の個数
	//vvvm dp(N + 1, vvm(A + 1, vm(2)));
	//dp[0][0][0] = 1;
	vvm dp(N + 1, vm(A + 1));

	dp[0][0] = 1;
	rep(i, N) {
		rep(a, A + 1) {
			rep(x, 2) {
				ll na = 0;
				if (a == A) {
					na = A;
				}
				else {
					na = x ? (a + 1) : 0;
				}
				dp[i + 1][na] += dp[i][a];
			}
		}
	}
	return dp[N][A];
}

mod nnum(ll N, ll A, ll B) {
	vvvm dp(N + 1, vvm(A + 1, vm(B + 1)));

	dp[0][0][0] = 1;
	rep(i, N) {
		rep(a, A + 1) {
			rep(b, B + 1) {
				rep(x, 2) {
					ll na, nb;
					if (a == A) {
						na = A;
					}
					else {
						na = x ? (a + 1) : 0;
					}
					if (b == B) {
						nb = B;
					}
					else {
						nb = x ? 0 : (b + 1);
					}

					dp[i + 1][na][nb] += dp[i][a][b];
				}
			}
		}
	}
	return dp[N][A][B];
}


