	// 1 0 1
	// 0 0 1
	// 0 1 0

bool judge(ll a, vi& base) {
	// baseは標準化されているとして、aがbaseで表せるか判定
	for (auto b : base) {
		chmin(a, a^b);
	}

	return a == 0;
}

void Add(ll a, vi& base) {
	// a : 1000
	// base: 
	// 1101
	// 0011

	// 0101
	// 0110

	for (ll i = 0; i < base.size(); i++) {
		ll b = base[i];
		chmin(a, a ^ b);
		if (b < a) {
			base.insert(base.begin() + i, a);
			return;
		}
	}
	base.pb(a);
}


