typedef long long LL;

// 掃き出し法
bool possible(LL t, vector<LL> a) {
	if (a.empty()) return t == 0;
	LL x = 0;
	int st = 0;
	int sz = (int)a.size();
	sort(a.rbegin(), a.rend());
	vector<int> bp(64, -1);
	for (LL b = 60; b >= 0; --b) {
		LL f = 1LL << b;
		if (!(a[st] & f)) continue;
		for (int i = 0; i < sz; ++i) {
			if (i != st && (a[i] & f) != 0) a[i] ^= a[st];
		}
		bp[b] = st++;
		if (st >= sz) break;
		sort(a.rbegin(), a.rbegin() + sz - st);
	}
	for (LL b = 60; b >= 0; --b) {
		LL f = 1LL << b;
		if ((f & t) != 0 && (f & x) == 0 && bp[b] >= 0) {
			x ^= a[bp[b]];
		}
	}
	return t == x;
}

