    int sz;
    vector<T> basis;
    XorBasis(){
        sz = 0;
        basis.assign(SZ, 0);
    }
    void insert(T vec){
        for(int i = 0; i < SZ; ++i){
            if(!((vec >> i) & 1)) continue;
            if(!basis[i]){
                basis[i] = vec;
                sz++;
                return;
            }
            vec ^= basis[i];
