            gj.B.clear();
            rep(j, i + 1, N) {
                if (S[j] == '0') gj.B.emplace_back(A[j]);
            }
            gj.gauss_jordan();

            GaussJordan_Binary<60>::Row a(A[i]), b(0);
            for (int j = 0, k = 0; k < 60; ++k) {
                if ((a ^ b)[k]) {
                    for (; j < (int)gj.B.size(); ++j) {
                        if (gj.B[j][k]) break;
                    }
                    if (j == (int)gj.B.size()) break;
                    b ^= gj.B[j];
                    ++j;
                }
            }
            ans[t] |= a != b;
        }
    }

    for (int x : ans) write(x);
}

