int getBitN(LL x) {
	int res = 0;
	while (x) {
		res += (int)(x % 2);
		x = x >> 1;
	}
	return res;
}

const int maxTimeN = 50;

void work() {
	for (int i = n - 1; i >= 0; --i) {
		int person = s[i] - '0';
		// cout << person << ' ' << a[i] << endl;
		if (person == 0) {
			sp.push_back(a[i]);
		} else {
			LL aa = a[i];
			int bitN = getBitN(aa);
			for (int ii = 0; ii < maxTimeN; ++ii) {
				for (int j = 0; j < sp.size(); ++j) {
					int newBitN = getBitN(aa ^ sp[j]);
					if (newBitN < bitN) {
						aa = aa ^ sp[j];
						bitN = newBitN;
					} else {
						if (randomDouble() < exp(bitN - newBitN)) {
							aa = aa ^ sp[j];
							bitN = newBitN;
						}
					}
					if (!aa) {
						break;
					}
				}
				if (!aa) {
					// cout << ii << endl;
					break;
				}
				// cout << aa << ' ' << bitN << endl;
			}
			if (aa) {
				cout << "1" << endl;
				return ;
			}
		}
	}
	cout << "0" << endl;
}

