vector<lint> cal(vector<lint> x){
	int rank=0;
	rep(i,63){
		if(rank>=x.size()) break;
		REP(j,rank,x.size()){
			if((x[j]&(1L<<i))) swap(x[rank],x[j]);
		}
		if(!(x[rank]&(1L<<i))) continue;
		rep(j,x.size()){
			if(j==rank) continue;
			if((x[j]&(1L<<i))) x[j]^=x[rank];
		}
		rank++;
	}
	REP(i,rank,x.size()){
		assert(x[i]==0L);
	}
	rep(i,rank) REP(j,i+1,rank){
		assert((x[i]&x[j])==0L);
	}
	//x.resize(rank);
	//return x;
	vector<lint> ret;
	rep(i,rank){
		assert(x[i]>0L);
		ret.pb(x[i]);
	}
	return ret;
}
