	//cout<<y<<' '<<x<<endl;
	lint f=0L;
	rep(i,x.size()){
		lint T=(y&x[i]);
		f|=T;
		if(T>0L && T<x[i]) return true;
	}
	if(f!=y) return true;
	return false;
}
