int solve(int n, int &bs, vector<int> &A, string &play,
          map<pair<int, int>, int> &dp) {
  if (n == 0) {
    // cout << n << " " << bs.to_string() << " " << bs.count() << endl;
    if (bs == 0)
      return 0;
    else
      return 1;
  }
  if (dp.count(mp(n, bs))) return dp[mp(n, bs)];
  int &val = dp[mp(n, bs)];

  set<int> s;
  // get the number or dont get
  auto new_bs = (bs ^ A[n]);

  if (play[n] == '0') {
    if (solve(n - 1, new_bs, A, play, dp) == 1) {
      val = 1;
      return val;
    }
    if (solve(n - 1, bs, A, play, dp) == 1) {
      val = 1;
      return val;
    }
    val = 0;
    return val;
  } else {
    if (solve(n - 1, new_bs, A, play, dp) == 0) {
      val = 0;
      return val;
    }
    if (solve(n - 1, bs, A, play, dp) == 0) {
      val = 0;
      return val;
    }
    val = 1;
    return val;
  }

  return val;
}

