bool belong(ll x, vector<ll>& a) {
    //cerr << "op\n";
    a.push_back(x);
    int n = a.size();
    int m = 64;
    vector<ll> b(a);
    a.pop_back();
    int r = 0;
    while (r < n) {
        //cerr << r << endl;
        int k = r;
        while (k < m) {
            if (((b[r] >> k) & 1) == 0)
                ++k;
            else
                break;
        }
        if (k == m)
            return 1;
        for (int i = 0; i < n; ++i) {
            if (((b[i] >> k) ^ (b[i] >> r)) & 1) {
                b[i] ^= (1LL << k) + (1LL << k);
            }
        }
        for (int j = 0; j < n; ++j) {
            if (j == r)
                continue;
            if (((b[j] >> k) & 1) == 0)
                continue;
            b[j] ^= b[r];
        }
        ++r;
    }
    return 0;

}


