bool Solve(int N, vector<ll>& nums, string& moves, int index, ll runningSum, std::unordered_map<ll, bool>& memo)
{
    if(index == int(moves.size()))
    {
	return runningSum == 0;
    }

    ll key = Key(index, runningSum);
    if(memo.find(key) != memo.end()) return memo[key];

    if(moves[index] == '0')
    {
	if(Solve(N, nums, moves, index+1, runningSum, memo) || Solve(N, nums, moves, index+1, runningSum ^ nums[index], memo))
	    return memo[key] = true;
	else
	    return memo[key] = false;

    }
    else
    {
	if(!Solve(N, nums, moves, index+1, runningSum, memo) || !Solve(N, nums, moves, index+1, runningSum ^ nums[index], memo))
	    return memo[key] = false;
	else
	    return memo[key] = true;
    }

    return memo[key] = true;
}

