typedef long long LL;

bool possible(LL t, vector<LL> a) {
	int sz = (int)a.size();
	for (LL b = 60; b >= 0; --b) {
		LL f = 1LL << b;
		if (t & f) {
			LL w = -1;
			for (int i = 0; i < sz; ++i) {
				if (f & a[i]) {
					w = a[i];
					break;
				}
			}
			if (w < 0) return false;
			for (int i = 0; i < sz; ++i) {
				if (!(f & a[i])) {
					a[i] ^= w;
				}
			}
		} else {
			LL w = -1;
			for (int i = 0; i < sz; ++i) {
				if (f & a[i]) {
					w = a[i];
					for (int j = i; j < sz; ++j) {
						if (f & a[j]) {
							a[j] ^= w;
						}
					}
					break;
				}
			}
		}
	}
	for (int i = 0; i < sz; ++i) {
		if (a[i] == t) {
			return true;
		}
	}
	return false;
}

