bool dp(ll x,int i, V<ll> a,string s) {
	if (i == 0) {
		if (x)return false;
		else return true;
	}

	ll xx = x ^ a[i - 1];

	if (s[i - 1] - '0') {
		if (dp(x, i - 1, a, s) || dp(xx, i - 1, a, s))return true;
		else return false;
	}
	else {
		if (dp(x, i - 1, a, s) && dp(xx, i - 1, a, s))return true;
		else return false;
	}
}


