        rep(i,n){
            ll val;
            cin>>val;
            a[i]=bitset<60>(val);
        }
        string s;
        cin>>s;
        bitmat<60> mat;
        int win=0;
        for(int i=n-1;i>=0;--i){
            int oldrank=mat.getRank();
            int newrank=mat.addRow(a[i]);
            if(oldrank==newrank){
                mat.removeRow();
            }
            else if(s[i]=='1'){
                win=1;
                break;
            }
        }
        cout<<win<<endl;
    }
}

