int RankOfF2Vectors(const vector<int64>& input_xs) {
  vector<int64> xs(input_xs.begin(), input_xs.end());
  sort(xs.begin(), xs.end());
  reverse(xs.begin(), xs.end());
  for (int k = 59; k >= 0; k--) {
    for (int i = 0; i < xs.size(); i++) {
      if (xs[i] > (1LL << (k + 1))) {
        continue;
      } else if (xs[i] >= (1LL << k)) {
        // xs[i] is an axis.
        for (int j = i + 1; j < xs.size(); j++) {
          if (xs[j] >= (1LL << k)) {
            xs[j] ^= xs[i];
          }
        }
        sort(xs.begin(), xs.end());
        reverse(xs.begin(), xs.end());
        // cout << "axis: " << xs[i] << endl;
        // cout << "xs: " << xs << endl;
        break;
      } else {
        break;
      }
    }
  }

  int count = 0;
  for (int64 x : xs) {
    if (x > 0) count++;
  }
  return count;
}

