{
    bool flag = true;
    BitMatrix M(N, 60);
    for (int i = N - 1; i >= 0; i--)
    {
        if (S[i] == '0')
        {
            M.val[i] = A[i];
        }
        else
        {
            auto M1 = M,M2 = M;
            int r1 = GaussJordan(M1);

            M2.val[i] = A[i];
            int r2 = GaussJordan(M2);
            if (r1 < r2)
            {
                flag = false;
                break;
            }
        }
    }
