class XorBasis {
private:
  const static int len = 61;
  long long M[len];
public:
  XorBasis() { init(); }

  void init() { rep(i,len) M[i] = 0; }

  void add(long long x) {
    rep(i,len) {
      if( (x>>i) & 1LL ) {
	if( !( (M[i]>>i) & 1LL ) ) {
	  M[i] = M[i] ^ x;
	  return;
	}
	x = x ^ M[i];
      }
    }
  }

  bool query(long long x) {
    rep(i,len) {
      if( (x>>i) & 1LL ) {
	x = x ^ M[i];
      }
    }
    return x == 0LL;
  }

};

void solve() {
  XorBasis basis;
  basis.init();
  for(int i=n-1;i>=0;--i) {
    if( s[i] == '0' ) {
      basis.add(A[i]);
    } else {
      if( !basis.query(A[i]) ) {
	puts("1");
	return;
      }
    }
  }
  puts("0");
}

