class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    int N;
    vector<ull> A;
    string S;

    bool input() {
        is >> N;
        A.resize(N);
        is >> A >> S;
        return !!is;
    }

    vector<ull> base(vector<ull>& x, ull k){
        for (auto &&xi : x) {
            if((k ^ xi) < k){
                k ^= xi;
            }
        } // end xi
        for (auto &&xi : x) {
            if((xi ^ k) < xi){
                xi ^= k;
            }
        } // end xi
        if(k > 0){
            x.push_back(k);
        }
        sort(RALL(x));
        return x;
    }

    bool can(vector<ull>&x, ull k){
        sort(RALL(x));
        for (auto i : x) {
            if(k & i){
                k ^= i;
            }
        } // end i
        return k == 0;
    }

    void solve(){
        int l;
        l = N;
        vector<ull> b;

        while(l-- > 0){
            if(S[l] == '1'){
                if(!can(b, A[l])){
                    os << 1 << endl;
                    return;
                }
            }
            else {
                base(b, A[l]);
            }
        }
        os << 0 << '\n';
    }

    void run();
};

