const int MAXN = 200;
const int m = 60;

//~ const int MAXN = 10;
//~ const int m = 5;

bool solvable(vector<LL> a, LL b) {
    int n = (int)a.size();
    vector<bitset<MAXN>> bs(m,0);
    //~ cout << "Solve\n";
    //~ for (LL x : a) cout << x << " ";
    //~ cout << ": ";
    //~ cout << b << endl;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) bs[j][i] = (a[i]&(1<<j));
    }
    for (int j = 0; j < m; j++) bs[j][n] = (b&(1<<j));
    //~ for (int j = 0; j < m; j++) {
        //~ cout << bs[j] << endl;
    //~ }
    int actrow = 0;
    for (int i = 0; i < n; i++) {
        for (int j = actrow+1; j < m; j++) if (bs[j][i]) {
            swap(bs[j], bs[actrow]);
            //~ cout << i << " " << actrow << " " << j << endl;
        }
        if (!bs[actrow][i]) continue;
        for (int j = actrow+1; j < m; j++) if (bs[j][i]) {
            bs[j] ^= bs[actrow];
            //~ cout << j << " " << i << endl;
        }
        actrow++;
    }
    //~ for (int j = 0; j < m; j++) {
        //~ cout << bs[j] << endl;
    //~ }
    //~ cout << actrow << endl;
    for (int j = actrow; j < m; j++) if (bs[j][n]) return false;
    return true;
}

