        if (S[i] == '1') {
            vector<LL> a;
            for (int j = i+1; j < N; j++) if (S[j] == '0') a.push_back(A[j]);
            if (!solvable(a, A[i])) {
                return 1;
            }
        }
    }
    return 0;
}

