// Returns count of subsets of arr[] with XOR value equals 
// to k. 
int subsetXOR(int arr[], int n, int k) 
{ 
	// Find maximum element in arr[] 
	int max_ele = arr[0]; 
	for (int i=1; i<n; i++) 
	if (arr[i] > max_ele) 
		max_ele = arr[i]; 

