struct basis{
	vector<ll> V;
	bool insert(ll x, bool add = true){
		for(ll a : V) if(a & -a & x) x ^= a;
		bool ret = x == 0;
		if(!add) return ret;
		if(ret) return 0;
		for(ll & a : V) if(x & -x & a) a ^= x;
		V.push_back(x);
		return 1;
	}
};

