ll solve(ll x,ll mask)
{
    if(x==n-1)
    {
        if(s[x]=='0')
        {
            if(mask==0 or (mask^a[x])==0)
            {
                return 0;
            }
            return 1;
        }
        else
        {
            return 1;
        }
    }
    if(mp[x].find(mask)!=mp[x].end())
    {
        return mp[x][mask];
    }
    if(s[x]=='0')
    {
        if(solve(x+1,mask)==0)
        {
            mp[x][mask]=0;
        }
        else if(solve(x+1,mask^a[x])==0)
        {
            mp[x][mask]=0;
        }
        else
        {
            mp[x][mask]=1;
        }
    }
    else
    {
        if(solve(x+1,mask)==1)
        {
            mp[x][mask]=1;
        }
        else if(solve(x+1,mask^a[x])==1)
        {
            mp[x][mask]=1;
        }
        else
        {
            mp[x][mask]=0;
        }
    }
    return mp[x][mask];
}

