ll a[111],b[111];

void mat(int n){
	int i,j,r=0;
	for(j=59; j>=0; --j){
		for(i=r; i<n; ++i){
			if(b[i]&(1ll<<j)){
				break;
			}
		}
		if(i==n){
			continue;
		}
		if(i>r){
			b[r] ^= b[i];
		}
		for(i=r+1; i<n; ++i){
			if(b[i]&(1ll<<j)){
				b[i] ^= b[r];
			}
		}
		++r;
	}
}

bool check(ll x, int n){
	int i;
	for(i=0; i<n; ++i){
