ll f(vector<ll> &v1, ll p){
  if(v1.sz==0){
    if(p==0)return 1;
    else return 0;
  }
  vector<ll> v;
  rep(i,0,v1.sz){
    v.pb(v1[i]);
  }
  long long index = 0;
  for(long long i = 62; i >= 0; i--){
    long long flag = 0;
    for(long long j=index;j<v.sz;j++){
      if(v[j]&(1LL<<i)){
        flag = 1;
        swap(v[index],v[j]);
        break;
      }
    }
    for(long long j=index+1;j<v.sz;j++){
      if(v[j]&(1LL<<i)){
        v[j]^=v[index];
      }
    }
    if(flag==1){
      index++;
    }
  }
  index = 0;
  for(long long i = 62;i >= 0; i--){
    if((v[index]&(1LL<<i))!=0&&(p&(1LL<<i))==0){
      index++;
    }
    else if((v[index]&(1LL<<i))!=0&&(p&(1LL<<i))!=0){
      p ^= v[index];
      index++;
    }    
  }
  if(p==0)return 1;
  return 0;
}

