                        }
                    }

                    if (tmp != 0L) {
                        dp[i].add(tmp)
                    }
                }
                else -> {
                    var tmp = aArr[i]

                    for (b in dp[i + 1]) {
                        if (tmp xor b < tmp) {
                            tmp = tmp xor b
                        }
                    }

                    if (tmp == 0L) {
                        dp[i] = dp[i + 1].toMutableSet()
                    }
                }
            }
        }

        if (dp[0].contains(0L)) {
            builder.appendln(0)
        } else {
            builder.appendln(1)
        }
