fun main() {
    val sc = Scanner(System.`in`)
    val t = sc.nextInt()

    for(tc in 1..t) {
        val n = sc.nextInt()
        // 마지막 자리가 1 이면, 답은 1이다.
        // 마지막 자리가 0 이면, 정말 0 이 나오는  Ai 로 0을 만들어 낼 수 있는지 따져보아야한다.
        val arr = LongArray(n)
        val seq = IntArray(n)

        for(i in 0 until n) {
            arr[i] = sc.nextLong()
        }
        val s = sc.next()

        for(i in 0 until n) {
            seq[i] = s[i] - '0'
        }

        fun solve(idx:Int): HashSet<Long> {
            if(idx == n) {
                return setOf(0L).toHashSet()
            }
            val next = solve(idx + 1)
            if(seq[idx] == 0) {
                val ret = HashSet<Long>()
                for(d in next) {
                    ret.add(d)
                    ret.add(d xor arr[idx])
                }
                return ret
            }
            if(next.contains(arr[idx])) {
                return next
            }
            return HashSet()
        }

        val ans = solve(0)
        if(ans.isNotEmpty()) {
            println(0)
        } else {
            println(1)
        }
    }




