    }

    private void solve2() {
        int N = in.nextInt();
        long[] a = in.nextLongArray(N);

        String s = in.next();
        int[] b = new int[100];
        for (int i = N - 1; i >= 0; i--) {
            long c = a[i];

            main:
            while (true) {
                for (int x = 0; x < 60; x++) {
                    if ((c & (1L << x)) != 0 && b[x] != 0) {
                        c ^= b[x];
                        continue main;
                    }
                }
                break;
            }

            if (s.charAt(i) == '1') {
                if (c != 0) {
                    System.out.println("1");
                    return;
                }
            }
            for (int x = 0; x < 60; x++) {
                if ((c & (1L << x)) != 0) {
                    b[x] ^= c;
                    break;
                }
            }
        }
        System.out.println("0");
    }

