			if (outFlush) {
				outFlush = false;
				flush();
			}
			if (!hasNext()) throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			do sb.append(nextChar()); while(hasNextByte() && isPrintableChar(buffer[read]));
