	static void dfs(char arr[][], int r, int c, int cost) {
		if (r < 0 || r >= arr.length || c < 0 || c >= arr[0].length)
			return;
		if (arr[r][c] == '#')
			return;
		if (dp[r][c] > cost)
			dp[r][c] = cost;
		else
			return;
		dfs(arr, r + 1, c, cost + 1);
		dfs(arr, r, c + 1, cost + 1);
		dfs(arr, r - 1, c, cost + 1);
		dfs(arr, r, c - 1, cost + 1);
	}

