	static int solve(long[] A, char[] s) {
		int N = A.length;

		long[] m = new long[N];
		int size = 0;
		for(int i=N-1; i>=0; i--) {
			if(s[i]=='0') {
				m[size] = A[i];
				size++;
			} else {
				if(!couldBeZero(A[i], m.clone(), size)) {
					return 1;
				}
			}
		}

		return 0;
	}

	static boolean couldBeZero(long goal, long[] m, int size) {
		for(int i=0; i<60; i++) {
			int baseIndex = -1;
			for(int j=1; j<size; j++) {
				if((m[j]&(1l<<i))!=0) {
					baseIndex = j;
					break;
				}
			}
			if(baseIndex<0) {
				if(((goal^m[0])&(1l<<i))!=0) {
					return false;
				} else {
					continue;
				}
			}
			long base = m[baseIndex];
			if(((m[0]^goal)&(1l<<i))!=0) {
				m[0] ^= base;
			}
			for(int j=1; j<size; j++) {
				if((m[j]&(1l<<i))!=0) {
					m[j] ^= base;
				}
			}
		}

		return true;
	}
