		if (arr[r][c] == '#')
			return;
		if (dp[r][c] > cost)
			dp[r][c] = cost;
		else
			return;
		dfs(arr, r + 1, c, cost + 1);
		dfs(arr, r, c + 1, cost + 1);
		dfs(arr, r - 1, c, cost + 1);
		dfs(arr, r, c - 1, cost + 1);
	}

