			if (me == bit) {
				val ^= set[i];
				me = Long.highestOneBit(val);
			}
		}
		if (val != 0) {
			set[size++] = val;
			Arrays.sort(set, 0, size);
		}
	}

	static boolean canRemove(long val) {
		long me = Long.highestOneBit(val);
		for (int i = size - 1; i >= 0; i--) {
			long bit = Long.highestOneBit(set[i]);
			if (me == bit) {
				val ^= set[i];
				if (val == 0) {
					return true;
				}
				me = Long.highestOneBit(val);
			}
		}
		return false;
	}


