public class Main{
  public static void main(String...args) {
    try (Scanner sc = new Scanner(System.in)) {
      int T = sc.nextInt();
      int xor_result = 0;

      for(int i = 0; i < T; i++) {
        int N = sc.nextInt();
        int A[] = new int[N];
        for(int j = 0; j < N; j++){
          A[j] = sc.nextInt();
        }
        String S = sc.next();
        xor_result = calc(xor_result, N, A, S, 0);
        if(xor_result == 0)
          System.out.println("0");
        else
          System.out.println("1");
      }
    } catch(Exception e) {
      System.out.println(e.getMessage());
    }
  }

  public static int calc(int r, int n, int[] a, String s, int index) {
    int temp = r;
    if(n == index)
      return r;
    int a_case = a[index];
    String s_case = s.substring(index,index+1);
    index += 1;

    if("1".equals(s_case)) {

      if(r != 0){
        if(!s.substring(index-1).contains("0")){
          return r;
        }
      }

      if(r == 0){
        temp = r^a_case;
        temp = calc(temp, n, a, s, index);
      } else {
        temp = calc(r, n, a, s, index);
        if(temp != 0)
          temp = calc(r, n, a, s, index);
      }
    } else {

      if(r == 0){
        if(!s.substring(index-1).contains("1")){
          return 0;
        }
      }

      if(r != 0){
        temp = r^a_case;
        temp = calc(temp, n, a, s, index);
        if(temp != 0)
          temp = calc(r, n, a, s, index);
      }else{
        temp = calc(r, n, a, s, index);
      }
    }
    return temp;
  }
}

import java.math.BigInteger;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int numTimes = scan.nextInt();
		for(int i = 0; i < numTimes; i++) {
			int N = scan.nextInt();
			long[] A = new long[N];
			for(int index = 0; index < N; index++) {
				A[index] = scan.nextLong();
			}
			scan.nextLine();
			BigInteger X = BigInteger.ZERO;
			String[] S = scan.nextLine().split("");

			X = getSolution(S, A);

			if(!X.equals(BigInteger.ZERO)) {
				System.out.println(1);
			}
			else {
				System.out.println(0);
			}
		}
	}
	public static BigInteger getSolution(String[] S, long[] A) {
		BigInteger X = BigInteger.ONE;

		Queue<Number> queue = new LinkedList<Number>();
		boolean found = false;
		queue.add(new Number(BigInteger.ZERO, 0L));


		while(queue.size() != 0 || found) {

			Number curr = queue.poll();
			BigInteger currA = curr.current;
			long currMoves = curr.numMoves;


			if(currA.equals(BigInteger.ZERO) && currMoves == (S.length)) {
				found = true;
				X = BigInteger.ZERO;
				break;
			}
			if(currMoves+1 <= S.length) {
				BigInteger optionOne = currA.xor(BigInteger.valueOf(A[(int) (currMoves)]));
				if(S[(int) currMoves].equals("1")) {
					if(currA.equals(BigInteger.ZERO)) {
						if(!optionOne.equals(BigInteger.ZERO)) {
							queue.add(new Number(optionOne, currMoves+1));
						}
					}
					else {
						queue.add(new Number(currA, currMoves+1));
					}
				}
				else {
					queue.add(new Number(currA, currMoves+1));
					queue.add(new Number(optionOne, currMoves+1));

				}
			}
		}

		return X;
	}
}
