public class Solution {
    //SOLUTION BEGIN
    //Into the Hardware Mode
    void pre() throws Exception {}
    void solve(int TC) throws Exception{
        int N = ni(), B = 61;
        long[] A = new long[N];
        for(int i = 0; i <N; i++)A[i] = nl();
        String s = n();
        long[] basis = new long[B];
        int sz = 0;
        boolean zero = true;
        for(int i = N-1; i>= 0; i--){
            if(s.charAt(i) == '1')
                zero &= represent(basis, sz, A[i]) == 0;
            else{
                long x = represent(basis, sz, A[i]);
                if(x > 0) {
                    basis[sz++] = x;
                    Arrays.sort(basis, 0, sz);
                }
            }
        }
        if(zero)pn(0);
        else pn(1);
    }
    long represent(long[] basis, int n, long value){
        for(int i = n-1; i>= 0; i--)
            if((value & Long.highestOneBit(basis[i])) > 0)
                value ^= basis[i];
        return value;
    }
    //SOLUTION END
    void hold(boolean b)throws Exception{if(!b)throw new Exception("Hold right there, Sparky!");}
    void exit(boolean b){if(!b)System.exit(0);}
