/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        AXorBattle solver = new AXorBattle();
        int testCount = Integer.parseInt(in.next());
        for (int i = 1; i <= testCount; i++)
            solver.solve(i, in, out);
        out.close();
    }

    static class AXorBattle {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            long[] a = in.nextLongArray(n);
            String s = in.next();
            for (int i = s.length() - 1; i >= 0; i--) {
                if (s.charAt(i) == '1') {
                    if (a[i] != 0) {
                        out.println(1);
                        return;
                    }
                }

                for (int bit = 0; bit < 60; bit++) {
                    if (((a[i] >> bit) & 1) != 0) {
                        for (int j = 0; j < i; j++) {
                            if (((a[j] >> bit) & 1) != 0) {
                                a[j] ^= a[i];
                            }
                        }
                        break;
                    }
                }
            }
            out.println(0);
        }

    }

    static class FastScanner {
        public BufferedReader br;
        public StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public FastScanner(String fileName) {
            try {
                br = new BufferedReader(new FileReader(fileName));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                String line = null;
                try {
                    line = br.readLine();
                } catch (IOException e) {
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public long[] nextLongArray(int n) {
            long[] ret = new long[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextLong();
            }
            return ret;
        }

    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

public final class Main {

    public static void main(String[] args) {
        final Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        final int t = Integer.parseInt(in.nextLine());
        for (int x = 0; x < t; x++) {
            final int n = Integer.parseInt(in.nextLine());
            final long[] arr = new long[n];
            final String[] w = in.nextLine().split(" ");
            for (int i = 0; i < w.length; i++) {
                arr[i] = Long.parseLong(w[i]);
            }
            final String s = in.nextLine();
            final Set<Long> left = new HashSet<>();
            final Set<Long> right = new HashSet<>();
            for (int j = 0; j < s.length(); j++) {
                if (s.charAt(j) == '1') {
                    left.add(arr[j]);
                } else {
                    right.add(arr[j]);
                }
            }
            final Set<Long> set = new HashSet<>();
            dfs(new ArrayList<>(left), set, 0, 0, true);
            dfs(new ArrayList<>(right), set, 0, 0, false);
            System.out.println(set.isEmpty() ? 0 : 1);
            System.out.flush();
        }
    }

    public static void dfs(List<Long> nums, Set<Long> res, long curr, int idx, boolean turn) {
        if (turn) {
            res.add(curr);
        } else {
            res.remove(curr);
        }
        for (int i = idx; i < nums.size(); i++) {
            curr ^= nums.get(i);
            dfs(nums, res, curr, i + 1, turn);
            curr ^= nums.get(i);
        }
    }
}

