public void solve() {
	int q = ni();
	for(int query = 0; query < q; query ++) {
		int num = ni();
		long a[] = nl(num);
		boolean b[] = nb(num, '1');
		boolean zero = true;
		reverse(a);
		reverse(b);
		int len = 60;
		boolean connect[][] = new boolean[len][len];
		fill(connect, true);
		for(int i = 0; i < num; i ++) {
			if(b[i]) {
				boolean ok = true;
				for(int j = 0; j < 60; j ++) {
					for(int k = j + 1; k < 60; k ++) {
						if(isFlagged(a[i], j) != isFlagged(a[i], k)) {
							ok &= !connect[j][k];
						}
					}
				}
				zero &= ok;
			}else {
				for(int j = 0; j < 60; j ++) {
					for(int k = j + 1; k < 60; k ++) {
						if(isFlagged(a[i], j) != isFlagged(a[i], k)) {
							connect[j][k] = false;
						}
					}
				}
			}
		}
		prtln(zero ? 0 : 1);
	}
