	static boolean dfs(long x, int idx) {
		if(idx == n) {
			if(x == 0)return true;
			else return false;
		}
		Pair key = new Pair(x, idx);
		if(memo.containsKey(key)){
			return memo.get(key);
		}
		boolean res = false;
		if(s[idx] == '0') {
			//0になる選択があれば、それを選ぶ
			res |= dfs(x ^ a[idx], idx+1);
			res |= dfs(x , idx+1);
			memo.put(key, res);
			return res;
		}
		else {
			if(!dfs(x ^ a[idx], idx+1))return false;
			if(!dfs(x , idx+1)) return false;
			memo.put(key, res);
			return true;
		}
