    public void solve() {
        int N = in.nextInt();
        int M = in.nextInt();
        long[] A = in.nextLongArray(N);
        long[] B = in.nextLongArray(N);

        long[] R = new long[4];
        for (int i = 1; i <= 3; i++) {
            R[i] = in.nextLong();
        }

        // 0 : src
        // 1-3 : index of trial
        // 4-N+3 : sticks
        // N+4 : sink
        Graph<CappedEdge> g = Graph.create(N + 3 + 2);
        for (int i = 1; i <= 3; i++) {
            {
                CappedEdgeImpl.CappedEdgePair cp = CappedEdgeImpl.pairedEdges(0, i, M, 0);
                g.addDirectionalEdge(0, cp.normal);
                g.addDirectionalEdge(i, cp.rev);
            }
            for (int j = 0; j < N; j++) {
                long cost = (A[j] * pow(B[j], i) % R[i]);
                CappedEdgeImpl.CappedEdgePair cp = CappedEdgeImpl.pairedEdges(i, 4 + j, 1, -cost);
                g.addDirectionalEdge(i, cp.normal);
                g.addDirectionalEdge(4 + j, cp.rev);
            }
        }

        for (int i = 0; i < N; i++) {
            long[] penalties = new long[4];
            for (int j = 1; j <= 3; j++) {
                penalties[j] = A[i] * pow(B[i], j);
            }
            for (int j = 1; j <= 3; j++) {
                long penalty = penalties[j] - penalties[j-1];
                CappedEdgeImpl.CappedEdgePair cp = CappedEdgeImpl.pairedEdges(i + 4, N + 4, 1, penalty);
                g.addDirectionalEdge(i + 4, cp.normal);
                g.addDirectionalEdge(N + 4, cp.rev);
            }
        }
        PrimaryDual primaryDual = new PrimaryDual(g, true);
        System.out.println(-primaryDual.doit(0, N + 4, 3 * M));
    }

    private long pow(long x, int a) {
        long res = 1;
        for (int i = 0; i < a; i++) {
            res *= x;
        }
        return res;
    }

    public void run() {
        if (__FILE_DEBUG_FLAG__ == __t__) {
            try {
                is = new FileInputStream(__DEBUG_FILE_NAME__);
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
            System.out.println("FILE_INPUT!");
        } else {
            is = System.in;
        }
        in = new FastScanner(is);
        out = new PrintWriter(System.out);

        solve();
    }

    public static void main(final String[] args) {
        new Main().run();
    }
}


