class PrimaryDual {
    public static final long INF = 1L << 60;

    final Graph<CappedEdge> g;
    final boolean withMinEdge;

    final int[] prevNodes;
    final int[] prevEdges;
    final long[] minDist;
    final long[] potential;

    public PrimaryDual(Graph<CappedEdge> g, boolean withNegativeEdge) {
        this.g = g;
        this.withMinEdge = withNegativeEdge;
        prevNodes= new int[g.size()];
        prevEdges = new int[g.size()];
        minDist = new long[g.size()];
        potential = new long[g.size()];
    }

    public long doit(int source, int sink, int flow) {
        long res = 0;
        if (withMinEdge) {
            bellmanford(source);
        } else {
            Arrays.fill(potential, 0);
        }
        while (flow > 0) {
            DijkstraResult dres = dijkstra(source, potential);
            if (dres.minDist[sink] == INF) {
                return -1;
            }
            for (int i = 0; i < g.size(); i++) {
                potential[i] += dres.minDist[i];
            }
            long minFlow = flow;
            for (int v = sink; v != source; v = dres.prevNodes[v]) {
                minFlow = Math.min(minFlow, g.edges(dres.prevNodes[v]).get(dres.prevEdges[v]).cap());
            }
            flow -= minFlow;

            res += minFlow * potential[sink];
            for (int v = sink; v != source; v = dres.prevNodes[v]) {
                CappedEdge e = g.edges(dres.prevNodes[v]).get(dres.prevEdges[v]);
                e.addCap(-minFlow);
                e.rev().addCap(minFlow);
            }
        }
        return res;
    }

    private DijkstraResult dijkstra(int start, long[] potential) {
        Arrays.fill(minDist, INF);
        minDist[start] = 0;
        prevNodes[start] = prevEdges[start] = -1;

        PriorityQueue<State> pq = new PriorityQueue<>(Comparator.comparingLong(st -> st.cost));
        pq.add(new State(0, start));

        while (!pq.isEmpty()) {
            State st = pq.poll();
            List<? extends CappedEdge> es = g.edges(st.u);
            for (int i = 0; i < es.size(); i++) {
                CappedEdge e = es.get(i);
                if (e.cap() == 0 || st.cost > minDist[st.u]) {
                    continue;
                }
                long ncost = minDist[st.u] + e.cost() + potential[st.u] - potential[e.to()];
                if (minDist[e.to()] > ncost) {
                    minDist[e.to()] = ncost;
                    prevNodes[e.to()] = st.u;
                    prevEdges[e.to()] = i;
                    pq.add(new State(ncost, e.to()));
                }
            }
        }
        return new DijkstraResult(minDist, prevNodes, prevEdges);
    }

    private void bellmanford(int start) {
        int n = g.size();
        Arrays.fill(potential, INF);
        potential[start] = 0;

        for (int i = 0; i < n - 1; i++) {
            for (int u = 0; u < n; u++) {
                List<? extends CappedEdge> es = g.edges(u);
                for (int j = 0; j < es.size(); j++) {
                    CappedEdge e = es.get(j);
                    long ncost = potential[u] + e.cost();
                    if (e.cap() != 0 && potential[e.to()] > ncost) {
                        potential[e.to()] = ncost;
                    }
                }
            }
        }
    }

    private class State {
        final long cost;
        final int u;

        public State(long cost, int u) {
            this.cost = cost;
            this.u = u;
        }
    }

    private class DijkstraResult {
        public final long[] minDist;
        public final int[] prevNodes;
        public final int[] prevEdges;

        public DijkstraResult(long[] minDist, int[] prevNodes, int[] prevEdges) {
            this.minDist = minDist;
            this.prevNodes = prevNodes;
            this.prevEdges = prevEdges;
        }
    }
}

class CappedEdgeImpl implements CappedEdge {
    final int to;
    final long cost;

    private long cap;
    private CappedEdge rev;

    private CappedEdgeImpl(int to, long cost, long cap) {
        this.to = to;
        this.cost = cost;
        this.cap = cap;
    }

    public static class CappedEdgePair {
        public final CappedEdge normal;
        public final CappedEdge rev;

        public CappedEdgePair(CappedEdge normal, CappedEdge rev) {
            this.normal = normal;
            this.rev = rev;
        }
    }

    public static CappedEdgePair pairedEdges(int from, int to, long cap, long cost) {
        CappedEdgeImpl e = new CappedEdgeImpl(to, cost, cap);
        CappedEdgeImpl revE = new CappedEdgeImpl(from, -cost, 0);
        e.rev = revE;
        revE.rev = e;
        return new CappedEdgePair(e, revE);
    }

    @Override
    public int to() {
        return to;
    }

    @Override
    public long cost() {
        return cost;
    }

    @Override
    public long cap() {
        return cap;
    }

    @Override
    public CappedEdge rev() {
        return rev;
    }

    @Override
    public void addCap(long cap) {
        this.cap += cap;
    }
}


class FastScanner {
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;

    public FastScanner(InputStream stream) {
        this.stream = stream;
        // stream = new FileInputStream(new File("dec.in"));
    }

    int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    public boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public boolean isEndline(int c) {
        return c == '\n' || c == '\r' || c == -1;
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public int[] nextIntArray(int n) {
        int[] array = new int[n];
        for (int i = 0; i < n; i++)
            array[i] = nextInt();

        return array;
    }

    public int[][] nextIntMap(int n, int m) {
        int[][] map = new int[n][m];
        for (int i = 0; i < n; i++) {
            map[i] = nextIntArray(m);
        }
        return map;
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public long[] nextLongArray(int n) {
        long[] array = new long[n];
        for (int i = 0; i < n; i++)
            array[i] = nextLong();

        return array;
    }

    public long[][] nextLongMap(int n, int m) {
        long[][] map = new long[n][m];
        for (int i = 0; i < n; i++) {
            map[i] = nextLongArray(m);
        }
        return map;
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }

    public double[] nextDoubleArray(int n) {
        double[] array = new double[n];
        for (int i = 0; i < n; i++)
            array[i] = nextDouble();

        return array;
    }

    public double[][] nextDoubleMap(int n, int m) {
        double[][] map = new double[n][m];
        for (int i = 0; i < n; i++) {
            map[i] = nextDoubleArray(m);
        }
        return map;
    }

    public String next() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    public String[] nextStringArray(int n) {
        String[] array = new String[n];
        for (int i = 0; i < n; i++)
            array[i] = next();

        return array;
    }

    public String nextLine() {
        int c = read();
        while (isEndline(c))
            c = read();
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isEndline(c));
        return res.toString();
    }

    public int[][] nextPackedIntArrays(int packN, int size) {
        int[][] res = new int[packN][size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < packN; j++) {
                res[j][i] = nextInt();
            }
        }
        return res;
    }
}

