 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        AXorBattle solver = new AXorBattle();
        int testCount = Integer.parseInt(in.next());
        for (int i = 1; i <= testCount; i++)
            solver.solve(i, in, out);
        out.close();
    }

    static class AXorBattle {
        public void solve(int testNumber, FastReader s, PrintWriter w) {
            int n = s.nextInt();
            long[] a = new long[n];
            TreeSet<Long> val = new TreeSet<>();
            for (int i = 0; i < n; i++) a[i] = s.nextLong();
            char[] c = s.next().toCharArray();
            for (int i = n - 1; i >= 0; i--) {
                if (c[i] == '1') {
                    if (!val.contains(a[i])) {
                        w.println(1);
                        return;
                    }
                } else {
                    ArrayList<Long> tem = new ArrayList<>();
                    tem.add(a[i]);
                    for (long l : val) tem.add(a[i] ^ l);
                    val.addAll(tem);
                }
            }
            w.println(0);
        }

    }

    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private FastReader.SpaceCharFilter filter;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {

            if (numChars == -1)
                throw new InputMismatchException();

            if (curChar >= numChars) {

                curChar = 0;

                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }

                if (numChars <= 0)
                    return -1;
            }

            return buf[curChar++];
        }

        public int nextInt() {

            int c = read();

            while (isSpaceChar(c))
                c = read();

            int sgn = 1;

            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;

            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();

                res *= 10;
                res += c - '0';
                c = read();
            }
            while (!isSpaceChar(c));

            return res * sgn;
        }

        public long nextLong() {

            int c = read();

            while (isSpaceChar(c))
                c = read();

            int sgn = 1;

            if (c == '-') {
                sgn = -1;
                c = read();
            }

            long res = 0;

            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();

                res *= 10;
                res += c - '0';
                c = read();
            }

            while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {

            int c = read();

            while (isSpaceChar(c))
                c = read();

            StringBuilder res = new StringBuilder();

            do {
                res.appendCodePoint(c);
                c = read();
            }
            while (!isSpaceChar(c));

            return res.toString();
        }

        public boolean isSpaceChar(int c) {

            if (filter != null)
                return filter.isSpaceChar(c);

            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int T = sc.nextInt();
		for (int i = 0; i < T; i++) {
			int N = sc.nextInt();
			long A[] = new long[N];
			for (int j = 0; j < N; j++) {
				A[j] = sc.nextLong();
			}
			String S = sc.next();
			Set<Long> setZero = new HashSet<Long>();
			setZero.add(0l);
			Set<Long> setOne = new HashSet<Long>();
			setOne.add(0l);
			boolean b = false;
			for (int j = N - 1; j >= 0; j--) {
				if (S.charAt(j) == '0') {
					Long[] temp = setZero.toArray(new Long[setZero.size()]);
					for (int k = 0; k < temp.length; k++) {
						setZero.add(A[j] ^ temp[k]);
					}
				} else {
					Long[] temp = setOne.toArray(new Long[setOne.size()]);
					for (int k = 0; k < temp.length; k++) {
						if (setZero.contains(A[j] ^ temp[k]) == false) {
							b = true;
							break;
						} else {
							setOne.add(A[j] ^ temp[k]);
						}
					}
				}
			}
