public class Main {

  public static void main(String[] args) {
    FastReader sc = new FastReader();
    int t = Integer.parseInt(sc.nextLine());
    for (int i = 0; i < t; i++) {
      int n = Integer.parseInt(sc.nextLine());
      long[] a = new long[n];
      String[] attr_a = sc.nextLine().split(" ");
      for(int j = 0; j < n; j++){
        a[j] = Long.parseLong(attr_a[j]);
      }
      String s = sc.nextLine();
      long result = minmax(0, s, a, 0);
      System.out.println(result == 0 ? 0 : 1);
    }
  }
  static long minmax(long cur, String s, long[] arr, int depth){
    if(s.length() <= depth){
      return cur;
    }
    if(s.charAt(depth) == '0'){
      if(cur != 0){
        if(minmax(cur ^ arr[depth], s, arr, depth + 1) == 0){
          return 0;
        } else {
          return minmax(cur , s, arr, depth + 1);
        }
      }
    } else {
      if(cur == 0){
        return minmax(cur ^ arr[depth], s, arr, depth + 1);
      } else {
        return minmax(cur , s, arr, depth + 1);
      }
    }
    return 0;
  }

  public static class FastReader {
    BufferedReader br;
    StringTokenizer st;


    public FastReader() {
      br = new BufferedReader(new InputStreamReader(System.in));
    }

    String next() {
      while (st == null || !st.hasMoreTokens()) {
        try {
          st = new StringTokenizer(br.readLine());
        } catch (Exception r) {
          r.printStackTrace();
        }
      }
      return st.nextToken();
    }

    int nextInt() {
      return Integer.parseInt(next());//converts string to integer
    }

    double nextDouble() {
      return Double.parseDouble(next());
    }

    long nextLong() {
      return Long.parseLong(next());
    }

    String nextLine() {
      String str = "";
      try {
        str = br.readLine();
      } catch (Exception r) {
        r.printStackTrace();
      }
      return str;
    }
  }
}

