		Scanner input = new Scanner(System.in);
		int T = input.nextInt();
		for (int i = 1; i <= T; i++) {
			int N = input.nextInt();
			long[] arr = new long[N];
			long x = 0;
			for (int j = 0 ; j < N; j++) {
				arr[j] = input.nextLong();
			}
			String S = input.next();
			for (int turn = 0; turn < N; turn++) {
				if (S.charAt(turn)=='0') {
					if (x==arr[turn]) x^=arr[turn];
					boolean found = false;
					long temp = x^arr[turn];
					for (int next = turn+1; next < N; next++) {
						if (temp==arr[next]) {
							found=true;
							break;
						}
					}
					if (found) x^=arr[turn];
				}else {
					boolean found = false;
					long temp = x^arr[turn];
					for (int next = turn+1; next < N; next++) {
						if (temp==arr[next]) {
							found=true;
							break;
						}
					}
					if (!found) x^=arr[turn]; //Kills 0's chances of making 0
				}
			}
			System.out.println(x==0?"0":"1");
		}
	}
