class Myon

{
    public Myon() { }
    public static int Main()
    {
        cin = new Scanner();
        new Myon().calc();
        return 0;
    }
    static Scanner cin;

    void calc()
    {
        int T = cin.nextInt();
        for (int i = 0; i < T; i++)
        {
            Console.WriteLine(calc2());
        }
    }

    int calc2()
    {
        int N = cin.nextInt();
        long[] A = cin.ArrayLong(N);
        string S = cin.next();
        int cnt = S.Length - 1;

        long all = 0;
        List<long> allL = new List<long>();

        while(cnt >= 0)
        {
            List<long> LA = new List<long>();
            List<long> LB = new List<long>();

            while(cnt >= 0 && S[cnt] == '0') { allL.Add(A[cnt]); LA.Add(A[cnt--]); }
            while(cnt >= 0 && S[cnt] == '1') { LB.Add(A[cnt--]); }

            LA.Sort();
            LA.Reverse();
            for (int i = 0; i < LA.Count; i++)
            {
                for (int j = i + 1; j < LA.Count; j++)
                {
                    long next = LA[i] ^ LA[j];
                    if (next < LA[j]) LA[j] = next;
                }
                LA.Sort();
                LA.Reverse();
            }

            long last = -1;

            foreach (var b in LB)
            {
                long now = b;
                foreach (var a in LA)
                {
                    if (now > (now ^ a)) now ^= a;
                }
                if (last == -1) last = now;
                else if (now != last) return 1;
            }

            if (last != -1) all ^= last;
        }

        allL.Sort();
        allL.Reverse();
        for (int i = 0; i < allL.Count; i++)
        {
            for (int j = i + 1; j < allL.Count; j++)
            {
                long next = allL[i] ^ allL[j];
                if (next < allL[j]) allL[j] = next;
            }
            allL.Sort();
            allL.Reverse();
        }


        foreach (var a in allL)
        {
            if (all > (all ^ a)) all ^= a;
        }
        if (all != 0) return 1;
        return 0;
    }
}


