namespace AtCoder {
    class XorBattle {
        static void Main(string[] args) {
            var T = int.Parse(Console.ReadLine());
            for (int t = 0; t < T; t++) {
                int N = int.Parse(Console.ReadLine());
                long[] A = new long[N];
                var parts = Console.ReadLine().Split(' ');
                for (int i = 0; i < N; i++) {
                    A[i] = long.Parse(parts[i]);
                }
                string S = Console.ReadLine();

                bool canWin = true;
                for (int bit = 0; bit < 60; bit++) {
                    int[] AA = new int[N];
                    for (int i = 0; i < N; i++) {
                        AA[i] = (A[i] & (1L << bit)) != 0 ? 1 : 0;
                    }

                    bool[][] dp = new bool[N + 1][];
                    for (int i = 0; i <= N; i++) {
                        dp[i] = new bool[2];
                    }

                    dp[N][0] = true;

                    for (int i = N - 1; i >= 0; i--) {
                        for (int j = 0; j < 2; j++) {
                            if (S[i] == '0') {
                                dp[i][j] = dp[i + 1][j] | dp[i + 1][j ^ AA[i]];
                            } else {
                                dp[i][j] = dp[i + 1][j] & dp[i + 1][j ^ AA[i]];
                            }
                        }
                    }

                    if (!dp[0][0]) {
                        canWin = false;
                        break;
                    }
                }

                Console.WriteLine(canWin ? "0" : "1");
            }
        }
    }
}

