    public static void Swap<T>(ref T lhs, ref T rhs) { T temp; temp = lhs; lhs = rhs; rhs = temp; }

    public static int BinaryRank(long[] A) {
        int n = A.Length;
        int rank = 0;
        for (int i = 0; i < 64; i++) {
            int t = -1;
            for (int j = rank; j < n; j++) {
                if (((1L << i) & A[j]) != 0) { t = j; break; }
            }

            if (t == -1) {
                continue;
            }

            Swap(ref A[rank], ref A[t]);
            for (int j = 0; j < n; j++) {
                if (rank != j && (A[j] & (1L << i)) != 0) {
                    A[j] ^= A[rank];
                }
            }

            rank++;
        }
        return rank;
    }


    bool CanCreate(IEnumerable<long> array, long x) {
        var m = array.Append(x).ToArray();
        return BinaryRank(m) == BinaryRank(array.ToArray());
    }

    private char Solve(int n, long[] a, string s) {
        var x = new List<long>();

        for (int i = s.Length - 1; i >= 0; i--) {
            if (s[i] == '0') {
                x.Add(a[i]);
            } else {
                if (!CanCreate(x, a[i])) {
                    return '1';
                }
            }
        }

        return '0';
    }
