public class Solution
{
    static int Solve(int N, long[] A, string S)
    {
        var basis = new List<long>();

        for (int i = N - 1; i >= 0; i--)
        {
            var e = A[i];
            foreach (var b in basis)
            {
                e = Math.Min(e, e ^ b);
            }
            if (e > 0)
            {
                if (S[i] == '0')
                {
                    basis.Add(e);
                }
                else
                {
                    return 1;
                }
            }
        }
        return 0;
    }

