    public void Solve()
    {
        var sc = new Scanner();
        int t = sc.NextInt();
        Console.SetOut(new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false });


        for (int i = 0; i < t; i++)
        {
            Console.WriteLine(Q(sc.NextInt(), sc.LongArray(), sc.Next()));
        }
        Console.Out.Flush();
    }

    string Q(int n, long[] a, string s)
    {
        // 1の操作だけでできる数　∈ 0の人の操作だけでできる数
        // なら0
        // else 1
        // 
        // 1の人のそれぞれを消せる 0の操作があるなら0

        var one = new List<long>();
        var zero = new List<long>();
        for (int i = 0; i < n; i++)
        {
            if (s[i] == '0') zero.Add(a[i]);
            else one.Add(a[i]);
        }
        var zz = zero.ToArray();

        foreach (var l in one)
        {
            if (GFG.subsetXOR(zz, zz.Length, l) == 0)
            {
                return "1";
            }
        }
        return "0";
    }

    public static void Main(string[] args) => new Program().Solve();
}

class GFG
{

    // Returns count of subsets of arr[] with  
    // XOR value equals to k. 
    public static int subsetXOR(long[] arr, int n, long k)
    {
        // Find maximum element in arr[] 
        long max_ele = arr[0];
        for (int i = 1; i < n; i++)
            if (arr[i] > max_ele)
                max_ele = arr[i];

        // Maximum possible XOR value 
        int m = (1 << (int)(Math.Log(max_ele, 2) + 1)) - 1;

        // The value of dp[i][j] is the number of subsets having 
        // XOR of their elements as j from the set arr[0...i-1] 
        int[,] dp = new int[n + 1, m + 1];

        // Initializing all the values of dp[i][j] as 0 
        for (int i = 0; i <= n; i++)
            for (int j = 0; j <= m; j++)
                dp[i, j] = 0;

        // The xor of empty subset is 0 
        dp[0, 0] = 1;

        // Fill the dp table 
        for (int i = 1; i <= n; i++)
            for (int j = 0; j <= m; j++)
                dp[i, j] = dp[i - 1, j] + dp[i - 1, j ^ arr[i - 1]];

        // The answer is the number of subset from set 
        // arr[0..n-1] having XOR of elements as k 
        return dp[n, k];
    }
}

