	List<long> Gauss(List<long> _l){
		var l = _l.ToList();
		int row = 0;
		int msb = 63;
		while(true){
			l.Sort();
			l.Reverse();
			if(row >= l.Count || l[row] == 0) break;
			while((l[row] >> msb) % 2 == 0) msb--;
			for(int j=row + 1;j < l.Count; j++){
				if((l[j] >> msb) % 2 == 1) l[j] ^= l[row];
			}
			row++;
		}
		while(l.Count > 0 && l[l.Count - 1] == 0) l.RemoveAt(l.Count - 1);
		return l;
	}





