class Bits
{
    private long[] arr = new long[60];
    public bool CanMake(long num)
    {
        for (int i = MSB(num); i >= 0; i = MSB(num))
        {
            if (arr[i] == 0)
                return false;
            num ^= arr[i];
            if (num == 0)
                return true;
        }
        return false;
    }
    public void Update(long num)
    {
        while (num > 0 && arr[MSB(num)] != 0)
        {
            num ^= arr[MSB(num)];
        }
        if (num > 0)
            arr[MSB(num)] = num;
    }
}

