class Solver
{
    public void Solve(Scanner sc)
    {
        var T = sc.Int;
        while (T-- > 0)
        {
            var N = sc.Int;
            var A = new long[N + 1];
            for (int i = 0; i < N; i++)
            {
                A[i] = sc.Next<long>();
            }
            var S = sc.Str + '0';

            var a = new List<long>();
            var b = new List<long>();
            for (int i = N; i>=0;i--)
            {
                if (S[i] == '0')
                    a.Add(A[i]);
            }
            int idx = 0;
            for(int i = 0; i < N; )
            {
                idx = i;
                if (S[idx] == '0') { i++;a.PopBack(); continue; }
                while (S[idx] == '1') { b.Add(A[idx]);idx++; }
                var cp = a.ToList();
                GaussJordan(cp);
                GaussJordan(b);
                cp.Reverse();
                for (int j = 0; j < b.Count; j++)
                {
                    var s = b[j];
                    for(int k=0;k<cp.Count;k++)
                    {
                        var m = MSB(cp[k]);
                        if ((1 & s >> m) == 1) s ^= cp[k];
                    }
                    if (s != 0) { Console.WriteLine(1);goto END; }
                }
                b.Clear();
                i = idx;
            }
            Console.WriteLine(0);
        END:;
        }
    }

    int MSB(long v)
    {
        var rt = 0;
        if ((v >> 32) > 0) { rt |= 32;v >>= 32; }
        if ((v >> 16) > 0) { rt |= 16; v >>= 16; }
        if ((v >> 8) > 0) { rt |= 8; v >>= 8; }
        if ((v >> 4) > 0) { rt |= 4; v >>= 4; }
        if ((v >> 2) > 0) { rt |= 2; v >>= 2; }
        return rt | (int)(v >> 1);
    }
    int GaussJordan(List<long> A)
    {
        int H = A.Count, W = 61,rank = 0;
        for (int i = 0; i < W; i++)
        {
            int pivot = -1;
            for (int row = rank; row < H; ++row)
            {
                if ((1&A[row]>>i) != 0)
                {
                    pivot = row;
                    break;
                }
            }
            if (pivot == -1) continue;
            A.swap(pivot, rank);
            for (int row = 0; row < H; ++row)
            {
                if (row != rank && (1&A[row]>>i) != 0)
                        A[row] ^= A[rank];
            }
            rank++;
        }
        return rank;
    }
}

