        {
            if (S[i] == '0')
            {
                foreach (var j in dp[i + 1])
                {
                    dp[i].Add(j);
                    dp[i].Add(j ^ A[i]);
                }
            }
            else
            {
                // t^a_i,tの両方がdp[i+1]に含まれる
                foreach (int j in dp[i + 1])
                {
                    if (dp[i + 1].Contains(j ^ A[i])) dp[i].Add(j);
                }
            }
        }

        Console.WriteLine(dp[0].Contains(0) ? "0" : "1");
    }

    public static void Main(string[] args) => new Program().Solve();
}

