namespace ProblemA
{
    class Program
    {
        static void Main(string[] args)
        {
            var T = int.Parse(Console.ReadLine());
            var res = new int[T];
            for (int loop = 0; loop < T; loop++)
            {
                var N = int.Parse(Console.ReadLine());
                var As = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
                var S = Console.ReadLine().ToCharArray();

                if (S.Last() == '1')
                    res[loop] = 1;
                else if (S.All(x => x == '0'))
                    res[loop] = 0;
                else
                {
                    var winOne = false;
                    int indForZeroStart, indForOneStart;
                    try
                    {
                        indForZeroStart = S.Select((x, i) => new { x, i }).Where(s => s.x == '1').Last().i + 1;
                    }
                    catch
                    {
                        indForZeroStart = 0;
                    }
                    try
                    {
                        indForOneStart = S.Select((x, i) => new { x, i }).Where(e => e.x == '0' && e.i < indForZeroStart).Last().i + 1;
                    }
                    catch
                    {
                        indForOneStart = 0;
                    }
                    var listZero = new List<long>() { 0, As[indForZeroStart] };
                    var listOne = new List<long>() { 0, As[indForOneStart] };
                    for (int i = indForZeroStart + 1; i < S.Length; i++)
                    {
                        var addList = listZero.Select(x => x ^ As[i]).ToArray();
                        listZero.AddRange(addList);
                    }
                    for (int i = indForOneStart + 1; i < indForZeroStart; i++)
                    {
                        var addList = listOne.Select(x => x ^ As[i]).ToArray();
                        listOne.AddRange(addList);
                    }
                    foreach (var oneElement in listOne)
                    {
                        if (!listZero.Contains(oneElement))
                            winOne = true;
                    }
                    res[loop] = winOne ? 1 : 0;
                }
            }
            for (int loop = 0; loop < T; loop++)
            {
                Console.WriteLine(res[loop]);
            }
        }
    }
}

