namespace AtCoderGrandContest045.Questions
{
    public class QuestionA : AtCoderQuestionBase
    {
        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            var tests = inputStream.ReadInt();

            for (int t = 0; t < tests; t++)
            {
                var n = inputStream.ReadInt();
                var a = inputStream.ReadLongArray();
                var s = inputStream.ReadLine();

                var zeroSet = new HashSet<long>();
                var oneSet = new HashSet<long>();

                for (int i = 0; i < a.Length; i++)
                {
                    if (s[i] == '0')
                    {
                        zeroSet.Add(a[i]);
                    }
                    else
                    {
                        oneSet.Add(a[i]);
                    }
                }

                const int maxRow = 60;
                var matrix = new int[maxRow, zeroSet.Count + oneSet.Count];
                var index = 0;
                foreach (var v in zeroSet)
                {
                    for (int digit = 0; digit < maxRow; digit++)
                    {
                        matrix[digit, index] = (int)(v >> digit) & 1;
                    }
                    index++;
                }

                foreach (var v in oneSet)
                {
                    for (int digit = 0; digit < maxRow; digit++)
                    {
                        matrix[digit, index] = (int)(v >> digit) & 1;
                    }
                    index++;
                }


                yield return GaussJordan(matrix, zeroSet.Count) ? 0 : 1;
            }
        }

        bool GaussJordan(int[,] matrix, int zeroCount)
        {
            int rank = 0;
            var maxRow = matrix.GetLength(0);
            var maxColumn = matrix.GetLength(1);
            for (int column = 0; column < maxColumn; column++)
            {
                int pivot = -1;
                for (int row = rank; row < maxRow; row++)
                {
                    if (matrix[row, column] > 0)
                    {
                        pivot = row;
                        break;
                    }
                }

                if (pivot == -1)
                {
                    continue;
                }

                for (int col = 0; col < maxColumn; col++)
                {
                    Swap(ref matrix[pivot, col], ref matrix[rank, col]);
                }

                for (int row = 0; row < maxRow; row++)
                {
                    if (row != rank && matrix[row, column] > 0)
                    {
                        for (int col = 0; col < maxColumn; col++)
                        {
                            matrix[row, col] ^= matrix[rank, col];
                        }
                    }
                }

                rank++;
            }

            return rank <= zeroCount;
        }

        static void Swap<T>(ref T value1, ref T value2)
        {
            var temp = value1;
            value1 = value2;
            value2 = temp;
        }

        static bool GetAt(int digit, long value) => ((value >> digit) & 1) > 0;
    }
}


namespace AtCoderGrandContest045
{
    class Program
    {
        static void Main(string[] args)
        {
            IAtCoderQuestion question = new QuestionA();
            var answers = question.Solve(Console.In);

            var writer = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(writer);
            foreach (var answer in answers)
            {
                Console.WriteLine(answer);
            }
            Console.Out.Flush();
        }
    }
}

