		static void Main()
		{
			var cin = new Scanner();
			int t = cin.Int();

			int Solve()
			{
				int n = cin.Int();
				var a = cin.ArrayLong(n);
				string s = cin.Next();

				var bases = new List<long>();
				for (int j = n - 1; j >= 0; j--) {
					long v = a[j];
					foreach (var b in bases) {
						v = Math.Min(v, v ^ b);
