            {
                int n = ReadInt();
                long[] array = ReadLongs();
                string s = Read();

                List<long> bases = new List<long>();
                bool can = true;
                for(int j = n - 1; j >= 0; j--)
                {
                    long val = array[j];
                    bases.Sort();
                    bases.Reverse();
                    for(int k = 0; k < bases.Count; k++)
                    {
                        val = Min(val, val ^ bases[k]);
                    }

                    if (s[j] == '0')
                    {
                        if (val > 0)
                        {
                            bases.Add(val);
                        }
