                    else
                    {
                        if (!dp.Contains(args[i]))
                        {

                            ans.Add(1);
                            break;

                        }
                    }

                if (ans.Count == num)
                    ans.Add(0);

            }

            foreach (var buf in ans) Console.WriteLine(buf);

        }

