namespace AtCoder
{
    class Program
    {

        const int BiggestMod = 1000000007;

        public static void Main()
        {

            var ans = new List<int>();

            for (int num = 0, numT = int.Parse(Console.ReadLine()); num < numT; num++)
            {

                int numN = int.Parse(Console.ReadLine());
                var args = Console.ReadLine().Split(' ').ToList().ConvertAll(x => long.Parse(x));
                var turn = Console.ReadLine().ToArray();

                var dp = new List<long>[numN + 1];

                dp[numN] = new List<long>() { 0 };

                for (int i = numN - 1; -1 < i; i--)
                    if (turn[i] == '0')
                    {

                        dp[i] = new List<long>(dp[i + 1]);
                        foreach (var arg in dp[i + 1])
                        {

                            var buf = arg ^ args[i];
                            if (!dp[i].Contains(buf)) dp[i].Add(buf);
                        }

                    }
                    else
                    {
                        if (dp[i + 1].Contains(args[i])) dp[i] = dp[i + 1];
                        else
                        {

                            ans.Add(1);
                            break;

                        }
                    }

                if (ans.Count == num)
                    ans.Add(dp[0].Contains(0) ? 0 : 1);

            }

            foreach (var buf in ans) Console.WriteLine(buf);

        }

    }

}

using System;
using System.Collections.Generic;
using System.Linq;

namespace AtCoder0607
{
	class Program
	{
		static void Main(string[] args)
		{
			A();

		}

		static void A()
		{
			var cases = int.Parse(Console.ReadLine());
			var sols = new bool[cases];

			for (int i = 0; i < cases; i++)
			{
				var n = int.Parse(Console.ReadLine());
				var a = Console.ReadLine().Split().Select(x => ulong.Parse(x)).ToArray();
				var s = Console.ReadLine();

				bool ok = true;
				for (int j = 0; j < n; j++)
				{
					if (s[j] == '0')
						continue;

					var ones = a.Take(j + 1).Where((x, ind) => s[ind] == '1').ToArray();
					var reducedOnes = Reduce(ones);
					var zeroes = a.Where((x, ind) => ind > j && s[ind] == '0').ToArray();
					var reducedZeroes = Reduce(zeroes);

					foreach (var one in reducedOnes)
					{
						if (one == 0)
							continue;

						var oneCpy = one;
						for (int ind = 0; ind < 64; ind++)
						{
							if ((oneCpy & (1UL << ind)) == 0)
								continue;

							oneCpy ^= reducedZeroes[ind];
						}

						if (oneCpy != 0)
							ok = false;
					}
				}

				sols[i] = !ok;
			}

			foreach (var sol in sols)
				Console.WriteLine(sol ? 1 : 0);
		}

		private static ulong[] Reduce(ulong[] vectors)
		{
			var N = 64;
			var X = vectors.ToList();
			for (int i = vectors.Length; i < N; i++)
				X.Add(0);

			var deadInds = new HashSet<int>();

			for (int row = 0; row < N; row++)
			{
				//First ensure that we have a non-zero entry in X[K,K]
				if ((X[row] & (1UL << row)) == 0)
					for (int i = 0; i < X.Count; ++i)
					{
						if (i < row && !deadInds.Contains(i))
							continue;

						if ((X[i] & (1UL << row)) != 0)
						{
							var tmp = X[i];
							X[i] = X[row];
							X[row] = tmp;
							break;
						}
					}

				if ((X[row] & (1UL << row)) == 0)
				{
					deadInds.Add(row);
					continue;
				}

				// Do full row elimination.
				for (int i = 0; i < X.Count; ++i)
					if (i != row && ((X[i] & (1UL << row)) != 0))
						X[i] ^= X[row];
			}

			return Enumerable.Range(0, N).Select(x => X[x]).ToArray();
		}
	}
}

