public class Gj{
	public List<long> li=new List<long>();
	public int cnt=0;
	public void Add(long v){
		int c=cnt;
		for(int j = 0;j<cnt;j++) {
			v=Min(v,li[j]^v);
			if(v>li[j]&&c==cnt){c=j;}
		}
		if(v!=0){
			li.Add(v);
			for(int j = cnt-1;j>=0;j--) {
				li[j]=Min(li[j],v^li[j]);
				if(j>=c){
					li[j+1]=li[j];
					if(j==c){li[c]=v;}
				}
			}
			cnt++;
		}
	}
	public long this[int i]{get{return li[i];}}
	public bool Ck(long v){
		for(int i = 0;i<cnt;i++) {v=Min(v,li[i]^v);}
		return v==0;
	}
}
