        for (int i = 0; i < T; i++)
        {
            Console.WriteLine(calc2());
        }
    }

    int calc2()
    {
        int N = cin.nextInt();
        long[] A = cin.ArrayLong(N);
        string S = cin.next();
        int cnt = S.Length - 1;

        while(cnt >= 0)
        {
            List<long> LA = new List<long>();
            List<long> LB = new List<long>();

            while(cnt >= 0 && S[cnt] == '0') { LA.Add(A[cnt--]); }
            while(cnt >= 0 && S[cnt] == '1') { LB.Add(A[cnt--]); }

            LA.Sort();
            LA.Reverse();
            for (int i = 0; i < LA.Count; i++)
            {
                for (int j = i + 1; j < LA.Count; j++)
                {
                    long next = LA[i] ^ LA[j];
                    if (next < LA[j]) LA[j] = next;
                }
                LA.Sort();
                LA.Reverse();
            }

            foreach (var b in LB)
            {
                long now = b;
                foreach (var a in LA)
                {
                    if (now > (now ^ a)) now ^= a;
                }
                if (now != 0) return 1;
            }
        }

        return 0;
    }
}


