using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using CompLib.Util;

public class Program
{
    public void Solve()
    {
        var sc = new Scanner();
        int t = sc.NextInt();
        Console.SetOut(new StreamWriter(Console.OpenStandardOutput()) {AutoFlush = false});
        for (int i = 0; i < t; i++)
        {
            Q(sc);
        }

        Console.Out.Flush();
    }

    private int N;
    private long[] A;
    private string S;

    void Q(Scanner sc)
    {
        N = sc.NextInt();
        A = sc.LongArray();
        S = sc.Next();

        // ラウンドiの時点でtなら0にできる
        // tの集合
        var dp = new HashSet<long>();
        dp.Add(0);
        for (int i = N - 1; i >= 0; i--)
        {
            if (S[i] == '0')
            {
                List<long> add = new List<long>();
                foreach (long j in dp)
                {
                    add.Add(j ^ A[i]);
                }

                foreach (long l in add)
                {
                    dp.Add(l);
                }
            }
            else
            {
                // t^a_i,tの両方がdp[i+1]に含まれる
                List<long> rm = new List<long>();
                foreach (long j in dp)
                {
                    if (!dp.Contains(j ^ A[i])) rm.Add(j);
                }

                foreach (long l in rm)
                {
                    dp.Remove(l);
                }
            }
        }

        Console.WriteLine(dp.Contains(0) ? "0" : "1");
    }

    public static void Main(string[] args) => new Program().Solve();
}

