public class WinNumberSet
{
	ulong[] _numberArray;

	public WinNumberSet()
	{
		_numberArray = new ulong[64];
	}

	public void Add(ulong a)
	{
		int arrIdx = 0;
		for(ulong i = 1; (i & a) != a; i = (i << 1) + 1) arrIdx++;
		if(_numberArray[arrIdx] == 0) _numberArray[arrIdx] = a;
		else if(_numberArray[arrIdx] != a) Add(a ^ _numberArray[arrIdx]);
	}

	public bool Contains(ulong a)
	{
		int arrIdx = 0;
		for(ulong i = 1; (i & a) != a; i = (i << 1) + 1) arrIdx++;
		if(_numberArray[arrIdx] == 0) return false;
		if(_numberArray[arrIdx] == a) return true;
		else return Contains(a ^ _numberArray[arrIdx]);
	}

	public override string ToString()
	{
		string s = "";
		for(int i=0; i<64; i++)
		{
			if(i==0) s = _numberArray[i].ToString();
			else s = s + " " + _numberArray[i].ToString();
		}
		return s;
	}
}

