  constructor(){
    this.a = Array(60).fill(0n);
  }
  add(s){
    var c = 0, t = BigInt(s);
    for(var i = 60; i--;){
      if((t >> BigInt(i)) & 1n){
        if(this.a[i])t ^= this.a[i];
        else c = Math.max(i,c);
      }
    }
    if(t)this.a[c] = t;
  }
  has(s){
    var t = BigInt(s);
    for(var i = 60; i--;){
      if((t >> BigInt(i)) & 1n){
        if(this.a[i])t ^= this.a[i];
        else return false;
      }
    }
    return true;
  }
}

