function xorBattle(N, A, S) {
  // Number that P0 can win with.
  const candidates = new Set();
  candidates.add(0);
  for (let i = N - 1; i >= 0; i--) {
    if (S[i] === "0") {
      const values = [...candidates.values()];
      for (const value of values) {
        candidates.add(value ^ A[i]);
      }
    } else {
      for (const value of candidates) {
        const theOther = value ^ A[i];
        if (!candidates.has(theOther)) {
          candidates.delete(value);
        }
      }
    }
  }
  return candidates.has(0) ? 0 : 1;
}

