package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
)

func out(x ...interface{}) {
	fmt.Println(x...)
}

var sc = bufio.NewScanner(os.Stdin)

func getInt() int {
	sc.Scan()
	i, e := strconv.Atoi(sc.Text())
	if e != nil {
		panic(e)
	}
	return i
}

func getString() string {
	sc.Scan()
	return sc.Text()
}

// min, max, asub, absなど基本関数
func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func asub(a, b int) int {
	if a > b {
		return a - b
	}
	return b - a
}

func abs(a int) int {
	if a >= 0 {
		return a
	}
	return -a
}

func lowerBound(a []int, x int) int {
	idx := sort.Search(len(a), func(i int) bool {
		return a[i] >= x
	})
	return idx
}

func upperBound(a []int, x int) int {
	idx := sort.Search(len(a), func(i int) bool {
		return a[i] > x
	})
	return idx
}

func check(b []int, s string) bool {
	n := len(b)
	// out(b, s, n)

	// who have one
	last1 := -1
	for i := n - 1; i >= 0; i-- {
		if b[i] == 1 {
			if s[i] == '0' {
				last1 = 0
			} else {
				last1 = 1
			}
			break
		}
	}
	// out(last1)
	if last1 == 1 {
		return false
	}

	return true
}

func solve() {
	N := getInt()
	a := make([]int, N)
	for i := 0; i < N; i++ {
		a[i] = getInt()
	}
	s := getString()
	win0 := true
	for i := 0; i < 18; i++ {
		b := make([]int, N)
		for j := 0; j < N; j++ {
			b[j] = (a[j] >> uint(i)) % 2
		}
		flg := check(b, s)
		if flg == false {
			win0 = false
			break
		}
	}

	if win0 {
		out(0)
	} else {
		out(1)
	}
}

func main() {
	sc.Split(bufio.ScanWords)
	sc.Buffer([]byte{}, 1000000)
	T := getInt()
	for i := 0; i < T; i++ {
		solve()
	}
}

package main

import (
	"bufio"
