			if x == 0 && a[0] == 0 {
				return true
			} else {
				return false
			}
		}
	}
	temp_a := log(a[1:],s[1:],x)
	t := a[0]
	temp_b := log(a[1:],s[1:],x^t)
	if s[0:1] == "0" {
		if temp_a || temp_b {
			return true
		} else {
			return false
		}
	} else {
		if temp_a && temp_b {
			return true
		} else {
			return false
		}
	}
}

