	n := tc.n
	a := tc.a
	s := []rune(tc.s)
	src := []int{}
	for i := n - 1; i >= 0; i-- {
		if s[i] == '0' {
			src = append(src, a[i])
			continue
		}
		if isLinearDependent(a[i], src) {
			return 1
		}
	}
	return 0
}

func isLinearDependent(tgt int, src []int) bool {
	for i, maxIter := 0, 1<<len(src); i < maxIter; i++ {
		num := 0
		for j := 0; j < len(src); j++ {
			if i>>j&1 == 1 {
				num ^= src[j]
			}
		}
		if num == tgt {
			return false
		}
	}
	return true
}

