	fmt.Fprintln(writer, 0)
}
func makeGrid(h, w int) [][]bool {
	index := make([][]bool, h, h)
	data := make([]bool, h*w, h*w)
	for i := 0; i < h; i++ {
		index[i] = data[i*w : (i+1)*w]
	}
	return index
}

