		} else {
			if b[a[i]] != 0 {
				continue
			}
			b = f(b, a[i])
			// out(b)
			for i := len(b) - 1; i > 0; i-- {
				if b[i] > b[i-1] {
					b[i], b[i-1] = b[i-1], b[i]
				}
			}
		}
	}
	out(0)
}

