		As := nextInts(N)
		S := next()
		fmt.Println(solve(As, S))
	}
}

func solve(As []int, S string) int {
	memo := make([]map[int]int, len(As)+1)
	return solveHelper(memo, 0, 1, As, S)
}

func solveHelper(memo []map[int]int, x int, round int, As []int, S string) int {
	if round == len(As)+1 {
		if x > 0 {
			return 1
		} else {
			return 0
		}
	}

	if memo[round] == nil {
		memo[round] = make(map[int]int)
	}
	if v, ok := memo[round][x]; ok {
		return v
	}

	next1 := solveHelper(memo, x, round+1, As, S)
	next2 := solveHelper(memo, x^As[round-1], round+1, As, S)

	if next1 == next2 {
		memo[round][x] = next1
		return memo[round][x]
	}

	if S[round-1] == '0' {
		if next1 == 0 || next2 == 0 {
			memo[round][x] = 0
		} else {
			memo[round][x] = 1
		}
	} else {
		if next1 == 1 || next2 == 1 {
			memo[round][x] = 1
		} else {
			memo[round][x] = 0
		}
	}
	return memo[round][x]
}

