func debug(a ...interface{}) {
	fmt.Println(a...)
}

func isZero(n int, a []int, s string) int {
	zeros := []int{}
	ones := []int{}
	for i, v := range s {
		switch v {
		case '0':
			zeros = append(zeros, i)
		case '1':
			ones = append(ones, i)
		}
	}
	for _, v := range ones {
		goal := a[v]
		if !isAchievable(goal, zeros, a) {
			return 1
		}
	}
	return 0
}

func isAchievable(goal int, zeros []int, a []int) bool {
	bitLength := len(zeros)
	maxBits := 1 << bitLength
	for bits := 0; bits < maxBits; bits++ {
		chosen := []int{}
		for i := 0; i < bitLength; i++ {
			if (bits & (1 << i)) > 0 {
				chosen = append(chosen, i)
			}
		}
		// debug("chosen", chosen)
		bitwiseXor := 0
		for _, v := range chosen {
			bitwiseXor ^= a[zeros[v]]
		}
		if bitwiseXor == goal {
			return true
		}
	}
	return false
}

