func Solve() {
  var T, N int
  var A, C []int
  var B [][]int
  var S string
  NextInt(&T)
  for test := 0; test < T; test++ {
    NextInt(&N)
    NextIntVec(&A)
    S = NextLine()
    B = make([][]int, N)
    for i, a := range A {
      B[i] = make([]int, 60)
      for j := range B[i] {
        B[i][j] = a % 2
        a /= 2
      }
    }
    F := func(a int) bool {
      M := make([][]int, 60)
      X := make([]int, 60)
      for i := range M {
        M[i] = make([]int, len(C))
        for j := range M[i] { M[i][j] = B[C[j]][i] }
        X[i] = B[a][i]
      }
      for i, j := 0, 0; i < 60; i, j = i + 1, j + 1 {
        if j == len(C) { break }
        for j < len(C) && M[i][j] == 0 {
          for p := i + 1; p < 60; p++ {
            if M[p][j] == 0 { continue }
            M[i], M[p] = M[p], M[i]
            X[i], X[p] = X[p], X[i]
            break
          }
          if M[i][j] == 0 { j++ }
        }
        if j == len(C) { break }
        for k := range M {
          if k == i { continue }
          m := M[k][j]
          for l := range M[k] { M[k][l] ^= M[i][l] * m }
          X[k] ^= X[i] * m
        }
      }
      ret := true
      for i := range M {
        ret = ret && ((i < len(C) && M[i][i] == 1) || X[i] == 0)
      }
      return ret
    }
    C = make([]int, 0)
    ans := 0
    for i := N - 1; 0 <= i; i-- {
      s := int(S[i]) - int('0')
      if s == 0 {
        C = append(C, i)
      } else if !F(i) {
        ans = 1; break
      }
    }
    Write(ans)
  }
}

func main() {
  Solve()
  Output()
}

