// min, max, asub, absなど基本関数
func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func asub(a, b int) int {
	if a > b {
		return a - b
	}
	return b - a
}

func abs(a int) int {
	if a >= 0 {
		return a
	}
	return -a
}

func lowerBound(a []int, x int) int {
	idx := sort.Search(len(a), func(i int) bool {
		return a[i] >= x
	})
	return idx
}

func upperBound(a []int, x int) int {
	idx := sort.Search(len(a), func(i int) bool {
		return a[i] > x
	})
	return idx
}

func check(b []int, s string) bool {
	n := len(b)

	// who have one
	last1 := -1
	for i := n - 1; i >= 0; i-- {
		if b[i] == 1 {
			if s[i] == '0' {
				last1 = 0
			} else {
				last1 = 1
			}
			break
		}
	}
	// out(last1)
	// out(b, s, n, last1)
	if last1 == 1 {
		return false
	}

	return true
}

func solve() {
	N := getInt()
	a := make([]int, N)
	for i := 0; i < N; i++ {
		a[i] = getInt()
	}
	s := getString()
	win0 := true
	for i := 0; i < 63; i++ {
		b := make([]int, N)
		for j := 0; j < N; j++ {
			b[j] = (a[j] >> uint(i)) % 2
		}
		flg := check(b, s)
		if flg == false {
			win0 = false
			break
		}
	}

	if win0 {
		out(0)
	} else {
		out(1)
	}
}

