    NextInt(&N)
    NextIntVec(&A)
    S = NextLine()
    B = make([][]int, N)
    for i, a := range A {
      B[i] = make([]int, 60)
      for j := range B[i] {
        B[i][j] = a % 2
        a /= 2
      }
    }
    F := func(a int) bool {
      M := make([][]int, 60)
      X := make([]int, 60)
      for i := range M {
        M[i] = make([]int, len(C))
        for j := range M[i] { M[i][j] = B[C[j]][i] }
        X[i] = B[a][i]
      }
      for i, j := 0, 0; i < 60 && j < len(C); i, j = i + 1, j + 1 {
        for j < len(C) && M[i][j] == 0 {
          for p := i + 1; p < 60; p++ {
            if M[p][j] == 0 { continue }
            M[i], M[p] = M[p], M[i]
            X[i], X[p] = X[p], X[i]
            break
          }
          if M[i][j] == 0 { j++ }
        }
        if j == len(C) { break }
        for k := range M {
          if k == i { continue }
          m := M[k][j]
          for l := range M[k] { M[k][l] ^= M[i][l] * m }
          X[k] ^= X[i] * m
        }
      }
      ret := true
      for i, j := 0, 0; i < 60; i, j = i + 1, j + 1 {
        for j < len(C) && M[i][j] == 0 { j++ }
        ret = ret && (j < len(C) || X[i] == 0)
      }
      return ret
    }
