    ans := 0
    for i := N - 1; 0 <= i; i-- {
      s := int(S[i]) - int('0')
      if s == 0 {
        C = append(C, i)
      } else if !F(i) {
        ans = 1; break
      }
    }
    Write(ans)
  }
}

