func solve(tc testCase) (ans int) {
	n := tc.n
	a := tc.a
	s := []rune(tc.s)
	tbl := table{0: true}
	for i := n - 1; i >= 0; i-- {
		if s[i] == '0' {
			tbl.update(a[i])
			continue
		}
		if !tbl.exists(a[i]) {
			return 1
		}
	}
	return 0
}

type table map[int]bool

func (t table) update(num int) {
	if t.exists(num) {
		return
	}
	for k := range t {
		t[k^num] = true
	}
}

func (t table) exists(num int) bool {
	_, ok := t[num]
	return ok
}

