type XorVectorSet struct {
	bases []int
	dim   int
}

func newXorVectorSet() *XorVectorSet {
	return &XorVectorSet{}
}

// asuume s.contain(a) == false
func (s *XorVectorSet) add(a int) {
	s.bases = append(s.bases, a)
	s.dim++

	for j := s.dim - 1; j > 0; j-- {
		if s.bases[j-1] > s.bases[j] {
			break
		}
		s.bases[j-1], s.bases[j] = s.bases[j], s.bases[j-1]
	}

	for i := 1; i < s.dim; i++ {
		if s.bases[i]^s.bases[i-1] < s.bases[i] {
			s.bases[i] = s.bases[i] ^ s.bases[i-1]

			for j := i + 1; j < s.dim; j++ {
				if s.bases[j-1] > s.bases[j] {
					break
				}
				s.bases[j-1], s.bases[j] = s.bases[j], s.bases[j-1]
			}
		}
	}
}

func (s *XorVectorSet) contain(a int) bool {
	x := a
	for i := 0; i < s.dim; i++ {
		if s.bases[i]^x < x {
			x = s.bases[i] ^ x
		}
		if x == 0 {
			return true
		}
	}
	return false
}

func answer(N int, A []int, S string) int {
	s := newXorVectorSet()
	for i := N - 1; i >= 0; i-- {
		switch S[i] {
		case '0':
			if !s.contain(A[i]) {
				s.add(A[i])
			}
		case '1':
			if !s.contain(A[i]) {
				return 1
			}
		}
	}
	return 0
}

