func testcase(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	aa := make([]int64, n)
	for i := 0; i < n; i++ {
		aa[i] = getNextInt64(scanner)
	}
	s := getNextString(scanner)
	bits0 := makeGrid(63, 63)
	bits1 := makeGrid(63, 63)
	for i := n - 1; i >= 0; i-- {
		if s[i] == '0' {
			for j := 0; j < 63; j++ {
				for k := 0; k < 63; k++ {
					bits0[j][k] = bits0[j][k] || (aa[i]>>uint(j)%2 != aa[i]>>uint(k)%2)
				}
			}
			continue
		}
		for j := 0; j < 63; j++ {
			for k := 0; k < 63; k++ {
				bits1[j][k] = bits1[j][k] || (aa[i]>>uint(j)%2 != aa[i]>>uint(k)%2)
				if bits1[j][k] && !bits0[j][k] {
					fmt.Fprintln(writer, 1)
					return
				}
			}
		}
	}
	fmt.Fprintln(writer, 0)
}
func makeGrid(h, w int) [][]bool {
	index := make([][]bool, h, h)
	data := make([]bool, h*w, h*w)
	for i := 0; i < h; i++ {
		index[i] = data[i*w : (i+1)*w]
	}
	return index
}

