		line := strings.Split(sc.Text(), " ")
		a := []int{}
		for i := 0; i < n; i++ {
			ai, _ := strconv.Atoi(line[i])
			a = append(a, ai)
		}
		sc.Scan()
		s := sc.Text()
		testCases = append(testCases, testCase{n, a, s})
	}
	for i := range testCases {
		ans := solve(testCases[i])
		fmt.Println(ans)
	}
}

func solve(tc testCase) (ans int) {
	n := tc.n
	a := tc.a
	s := []rune(tc.s)
	tbl := table{0: true}
	for i := n - 1; i >= 0; i-- {
		if s[i] == '0' {
			tbl.update(a[i])
			continue
		}
		if !tbl.exists(a[i]) {
			return 1
		}
	}
	return 0
}

type table map[int]bool

func (t table) update(num int) {
	for k := range t {
		t[k^num] = true
	}
}

func (t table) exists(num int) bool {
	_, ok := t[num]
	return ok
}

