auto parse( Range )( Range input )
if( isInputRange!Range && is( ElementType!Range == string ) )
{
	auto t = input.front.to!( long );
	auto asss = new Tuple!( long[], dchar[] )[ t ];
	foreach( ref ass; asss )
	{
		input.popFront;
		input.popFront;
		auto as = input.front.split.to!( long[] );
		input.popFront;
		auto s = input.front.to!( dchar[] );
		ass = tuple( as, s );
	}
	return tuple( asss );
}

auto solve( Tuple!( long[], dchar[] )[] asss )
{
	auto anss = new long[ asss.length ];
	foreach( ref ans, ass; lockstep( anss, asss ) )
	{
		// ゲームの終わりから遡って考える
		auto zs = [ 0L:true ];
		foreach_reverse( a, c; lockstep( ass[ 0 ], ass[ 1 ] ) )
		{
			if( c == '0' )
			{
				// 人0の番の場合
				foreach( x, z; zs )
				{
					zs[ x ^ a ] = true;
				}
			}
			else
			{
				// 人1の番の場合
				if( a !in zs )
				{
					ans = 1;
					break;
				}
			}
		}
	}
	return anss.to!( string[] ).join( "\n" );
}

