# 各人0と人1のターン毎に最適な行動をとろうとするものと仮定
import re
import itertools

t = int(input())
for idx in range(0, t):
    n = int(input())
    arr = list(map(int, input().split(' ')))
    s = input()

    # s を 0...01...1 または 1...10...0 に分割する
    count_zero = 0
    count_one = 0
    for si in s:
        if si == '0':
            count_zero = count_zero + 1
        elif si == '1':
            count_one = count_one + 1

    if s.endswith('0'):
        ones = arr[0:count_one]
        zeros = arr[count_one:]

    elif s.endswith('1'):
        zeros = arr[0:count_zero] 
        ones = arr[count_zero:]

    zero_pairs = []
    for n in range(1, len(zeros)+1):
        for conb in itertools.combinations(zeros, n):
            val = 0
            for num in conb:
                val = val^num
            zero_pairs.append(val)

    one_pairs = []
    for n in range(1, len(ones)+1):
        for conb in itertools.combinations(ones, n):
            val = 0
            for num in conb:
                val = val^num
            one_pairs.append(val)

    if (s.endswith('0')):
        if (set(zero_pairs) & set(one_pairs)):
            print(0)
        else:
            print(1)
    else:
        if (set(zero_pairs) & set(one_pairs)):
            print(1)
        else:
            print(0)

