def solve(*args: str) -> str:
    t = int(args[0])
    ret = []
    for i in range(1, 3*t+1, 3):
        n = int(args[i])
        A = map(int, args[i+1].split())
        S = map(int, tuple(args[i+2]))

        A0 = []
        A1 = []
        for a, s in zip(A, S):
            if s == 1:
                A0.append(a)
            elif s == 0:
                A1.append(a)
        X = set([0])
        for a in A1:
            for x in X.copy():
                X.add(a ^ x)

        Y = set([0])
        for a in A0:
            for y in Y.copy():
                Y.add(a ^ y)

        ret.append(1*(1 == len(X & Y)))

    return '\n'.join(map(str, ret))


