def main():
    # rankを出力、modを使って実装
    def matrix_rank(a, mod=10**9+7):
        n, m = len(a), len(a[0])
        M = [[j for j in i] for i in a]
        rank = min(n, m)
        for i in range(min(n, m)):
            if M[i][i] == 0:
                for j in range(i+1, n):
                    if M[j][i] != 0:
                        for k in range(i, m):
                            M[i][k] = (M[i][k]+M[j][k]) % mod
                        break
                else:
                    for j in range(i+1, m):
                        if M[i][j] != 0:
                            for k in range(i, n):
                                M[k][i] = (M[k][i]+M[k][j]) % mod
                            break
                    else:
                        rank -= 1
            pinv = pow(M[i][i], mod-2, mod)
            for j in range(m):
                M[i][j] = M[i][j]*pinv % mod
            M2 = M[i]
            for j in range(i+1, n):
                M3 = M[j][i]
                M[j][i] = 0
                for k in range(i+1, m):
                    M[j][k] = (M[j][k]-M3*M2[k]) % mod
        return rank

