class VectorSpace:
    def __init__(self, k):
        self.k = k
        self.E = [0] * k

    def chk(self, n):
        for i in range(self.k)[::-1]:
            n = min(n, n ^ self.E[i])
        return 1 if n == 0 else 0

    def add(self, n):
        for i in range(self.k)[::-1]:
            n = min(n, n ^ self.E[i])
        if n: self.E[n.bit_length() - 1] = n
        return 1 if n == 0 else 0

    def dimension(self):
        return len(self.E)

