# Useful algo: https://math.stackexchange.com/questions/2150103/xor-number-combinations, similar to Gaussian elim
# Returns a linearly independent set.
# Inspired by the above
def add_to_bit_mask(masks_by_bit, mask):
    while masks_by_bit[mask.bit_length() - 1]:
        mask ^= masks_by_bit[mask.bit_length() - 1]
    if mask:
        masks_by_bit[mask.bit_length() - 1] = mask

def check_if_spanned(masks_by_bit, mask):
    while masks_by_bit[mask.bit_length() - 1]:
        mask ^= masks_by_bit[mask.bit_length() - 1]
    return not mask


