def ref(N, A, S):
    if S[-1] == '1':
        return 1

    if N > 20:
        N = 20
        A = A[:-20]
        S = S[:-20]

    def f(i, x):
        if i == N:
            if x == 0:
                return 0
            else:
                return 1
        p = int(S[i])
        if f(i+1, x ^ A[i]) == p:
            return p
        if f(i+1, x) == p:
            return p
        return p ^ 1

    return f(0, 0)

