def solve(*args: str) -> str:
    t = int(args[0])
    ret = []
    for i in range(1, 3*t+1, 3):
        n = int(args[i])
        A = map(int, args[i+1].split())
        S = map(int, tuple(args[i+2]))

        A0 = set()
        A1 = set()
        for a, s in zip(A, S):
            if s == 1:
                A0.add(a)
            elif s == 0:
                A1.add(a)

        Y = set([0])
        for a in A0:
            if a not in Y:
                for y in Y.copy():
                    Y.add(a ^ y)

        is_subset = True
        X = set([0])
        for a in A1:
            Z = set()
            if a not in X:
                for x in X:
                    Z.add(a ^ x)

            if not Z <= Y:
                is_subset = False
                break
            X |= Z

        ret.append(0 if is_subset else 1)

    return '\n'.join(map(str, ret))


