    index = 0
    for i in reversed(range(60)):
        if k & (1 << i) != (1 << i): continue
        flag = 0
        for j in range(index, len(Nums)):
            if Nums[j] & (1 << i) == (1 << i):
                Nums[index], Nums[j] = Nums[j], Nums[index]
                break
        else: return False
        for j in range(index + 1, len(Nums)):
            Nums[j] ^= Nums[index]
    return True


