def read():
    N = int(input().strip())
    A = list(map(int, input().strip().split()))
    S = input().strip()
    return N, A, S


def solve(N, A, S):
    if S[-1] == "1":
        return 1
    P = [0, 0]
    U = [set(), set()]
    for s, a in zip(S, A):
        if s == "0":
            P[0] |= int(a)
            U[0].add(a)
        elif s == "1":
            P[1] |= int(a)
            U[1].add(a)
        else:
            raise ValueError()
    if len(U[0]) < bin(P[0]).count("1"):
        return 1
    while P[0] > 0 or P[1] > 0:
        if P[1] & 1 == 1 and P[0] & 1 == 0:
            return 1
        P[0] >>= 1
        P[1] >>= 1
    return 0


