  for i in range(b)[::-1]:
    if x&1<<i:
      if i not in pivot:
        return False
      for j in range(len(mat)):
        if mat[j]&1<<i:
          x ^= mat[j]
          break
  return True
def add(mat,x,pivot):
  b = x.bit_length()
  for i in range(b)[::-1]:
    if x&1<<i:
      if i in pivot:
        for j in range(len(mat)):
          if mat[j]&1<<i:
            x ^= mat[j]
            break
      else:
        pivot.add(i)
        for j in range(len(mat)):
          if mat[j] > x and mat[j]&1<<i:
            mat[j] ^= x
          elif mat[j] < x:
            mat.insert(j,x)
            break
        else:
          mat.append(x)
        break
