def num2bin(n):
    return tuple(int(d) for d in "{:070b}".format(n))


def can_reach_zero(n, bs, s):
    bins = [num2bin(b) for b in bs]
    max_len = len(bins[0])
    score = [[0 for _ in range(max_len)] for _ in range(2)]
    for i, player in enumerate(s):
        for j, c in enumerate(bins[i]):
            if c == 1:
                score[player][j] += 1
    for player, c in zip(range(2), range(max_len)):
        score[player][c] %= 2
    for s0, s1 in zip(score[0], score[1]):
        if s0 < s1:
            return False
    else:
        return True


