def deepcopy(li): return [x[:] for x in li]

def gauss_jordan(A, extended=False):
    """ ガウス・ジョルダン法(連立方程式の解) """

    N, M = len(A), len(A[0])
    B = deepcopy(A)
    rank = 0
    res = []
    for col in range(M):
        if extended and col == M-1:
            break
        pivot = -1
        for row in range(rank, N):
            if B[row][col] != 0:
                pivot = row
                break
        if pivot == -1:
            continue
        B[rank], B[pivot] = B[pivot], B[rank]
        for row in range(N):
            if row != rank and B[row][col]:
                for i in range(M):
                    B[row][i] ^= B[rank][i]
        res.append(col)
        rank += 1
    for row in range(rank, N):
        if B[row][-1]:
            return (-1, [])
    return (rank, res)

