	n, m = len(a), len(a[0])
	#a = np.array([list(map(int, input().split())) for _ in [0]*n])
	if n > m:
		a = a.T
		n, m = m, n
	r = 0
	for i in range(n):
		if a[i][i] != 1:
			for j in range(i+1, m):
				if a[i][j] == 1:
					a[:, [i, j]] = a[:, [j, i]]
					break
			else:
				for j in range(i+1, n):
					if a[j][i] == 1:
						a[[i, j]] = a[[j, i]]
					break
				else:
					break
		if a[i][i] == 0:
			continue

		r += 1
		for j in range(i+1, m):
			a[:, j] += a[i][j] * a[:, i]
			a[:, j] %= 2
		for j in range(i+1, n):
			a[j] += a[j][i] * a[i]
			a[j] %= 2

	return r
