def inv(a, mod):
    r = [1, 0, a]
    w = [0, 1, mod]
    while w[2] != 1:
        q = r[2]//w[2]
        r_new = [r[0]-q*w[0], r[1]-q*w[1], r[2]-q*w[2]]
        r = w
        w = r_new
    x, y = w[0], w[1]    # a*x+y*mod = 1
    return (mod+x % mod) % mod


def gauss_jordan_mod(A, mod):
    EPS = 1e-8
    n = len(A)
    m = len(A[0])
    for i in range(n):
        if len(A[i]) != m:
            return "Error!"

    for i in range(n):
        for j in range(m):
            A[i][j] %= mod

    rank = 0
    for i in range(n):
        pivot = i
        for k in range(i, n):
            if abs(A[k][i]) > abs(A[pivot][i]):
                pivot = k
        A[i], A[pivot] = A[pivot], A[i]
        if abs(A[i][i]) < EPS:
            continue
        rank += 1
        s = inv(A[i][i], mod)
        for j in range(i, m):
            A[i][j] *= s
            A[i][j] %= mod
        for k in range(n):
            if k != i:
                s = A[k][i]
                for j in range(i, m):
                    A[k][j] -= s * A[i][j]
                    A[k][j] %= mod
    return A, rank


