from itertools import product
from typing import List


class Phase:
    def __init__(self, player):
        self.player = player
        self.commmands = []

    def __repr__(self):
        return f"{self.player} with {self.commmands}"


def parse_phases(S, A) -> List[Phase]:
    phases = []
    for i, s in enumerate(S):
        if len(phases) == 0 or phases[-1].player != int(s):
            phases.append(Phase(int(s)))
        phases[-1].commmands.append(A[i])
    return phases


def calc_patterns(x, commmands):
    r = []
    for p in product(*[(False, True) for _ in commmands]):
        y = x
        for i, b in enumerate(p):
            if b:
                y = y ^commmands[i]
        r.append(y)
    return r


def calc_game(S, A):
    x = 0
    phases = parse_phases(S, A)
    for p in phases:
        patterns = calc_patterns(x, p.commmands)
        x = min(patterns) if p.player == 0 else max(patterns)
    return "1" if x > 0 else "0"


