                    for j in range(N):
                        E[j]^=(F[j]<<I)

    p=0
    while 0 in E[:L]:
        p+=1
        E.remove(0)

    H=0   
    for i in range(K):
        f=0
        for j in range(L-p):
            f=max(f,(E[j]>>i)%2)

        if f==0:
            for j in range(L-p,N-p):
                if (E[j]>>i)%2:
                    H=1

