def main():
    def sweep(arr):
        col = max(arr).bit_length()
        row = len(arr)

        rank = 0
        for c in range(col):
            piv = -1
            for r in range(rank, row):
                if arr[r] >> c & 1:
                    piv = r
            if piv == -1:
                continue

            arr[piv], arr[rank] = arr[rank], arr[piv]

            for r in range(row):
                if r == rank:
                    continue
                if arr[r] >> c & 1:
                    arr[r] ^= arr[rank]

            rank += 1

        return set(arr)

    def solve():
        N = int(input())
        A = list(map(int, input().split()))[::-1]
        S = input()[::-1]
        B0 = set()

        pre = '-1'
        left = 0
        for i, s in enumerate(S):
            if s != pre and i != 0:
                if s == '0':
                    B1 = sweep(A[left:i])
                    for b1 in B1:
                        for b0 in B0:
                            if b1 & b0 == b0:
                                b1 ^= b0
                        if b1:
                            return 1
                else:
                    B0 = sweep(A[left:i] + list(B0))

                left = i

            pre = s

        if pre == '1':
            B1 = sweep(A[left:])
            for b1 in B1:
                for b0 in B0:
                    if b1 & b0 == b0:
                        b1 ^= b0
                if b1:
                    return 1

        return 0

    for _ in [0]*int(input()):
        print(solve())


