    result = []
    def dfs(r,sum):
        if r==len(ls):
            if sum ^ v == 0:
                return True
            else:
                return False
        if dfs(r+1,sum):
            return True
        if dfs(r+1,sum^ls[r]):
            result.append(ls[r])
            return True

        return False
    res = dfs(0,0)
    return res,result
