const SIZE: u64 = 60;
fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let t: usize = sc.read();
    for _ in 0..t {
        let n: usize = sc.read();
        let a: Vec<u64> = sc.vec(n);
        let s = sc.chars().into_iter().map(|c| c == '0').collect::<Vec<_>>();
        if solve(a, s) {
            println!("0");
        } else {
            println!("1");
        }
    }
