fn solve(a: Vec<u64>, s: Vec<bool>) -> bool {
    let n = a.len();
    if !s[n - 1] {
        return false;
    }

    let mut one_started = false;
    let mut a0 = vec![];
    let mut a1 = vec![];
    for i in 0..n {
        if s[i] && one_started {
            a0.push(a[i]);
        } else {
            one_started = true;
            a1.push(a[i]);
        }
    }

    let rank0 = normalize(&mut a0);
    let rank1 = normalize(&mut a1);
    if rank0 < rank1 {
        return false;
    }

    let mut set0 = BTreeSet::new();
    for i in 0..rank0 {
        set0.insert(a0[i]);
    }

    for i in 0..rank1 {
        if !set0.contains(&a1[i]) {
            return false;
        }
    }
    true
}

fn normalize(a: &mut Vec<u64>) -> usize {
    let n = a.len();
    let mut cur = 0;
    for pos in 0..SIZE {
        if let Some(i) = (cur..n).find(|&i| a[i] & (1 << pos) != 0) {
            a.swap(cur, i);
            for i in 0..n {
                if i == cur {
                    continue;
                }
                if a[i] & (1 << pos) != 0 {
                    a[i] ^= a[cur];
                }
            }
            cur += 1;
        }
    }
    cur
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        Self(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

