fn solve_each() -> Result<(), Box<dyn Error>> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let n = input.trim().parse::<usize>()?;
    input.clear();

    io::stdin().read_line(&mut input)?;
    let a_s: Vec<i64> = input
        .trim()
        .split_whitespace()
        .map(|s| s.parse::<i64>().unwrap())
        .collect();
    input.clear();

    io::stdin().read_line(&mut input)?;
    let s_s = input.trim().to_owned();
    input.clear();

    let mut s_s: Vec<char> = s_s.chars().collect();
    if *s_s.last().unwrap() == '1' {
        println!("1");
        return Ok(());
    }
    s_s.reverse();
    let mut one_variations: HashSet<i64> = HashSet::new();
    let mut zero_variations: HashSet<i64> = HashSet::new();
    for (index, &x) in s_s.iter().enumerate() {
        if x == '1' {
            let temp = one_variations.clone();
            for &one in &temp {
                let value = one ^ a_s[index];
                if !zero_variations.contains(&value) {
                    println!("1");
                    return Ok(());
                }
                one_variations.insert(value);
            }
            if !zero_variations.contains(&a_s[index]) {
                println!("1");
                return Ok(());
            }
            one_variations.insert(a_s[index]);
        } else {
            // x == '0'
            // one_variations.clear();
            for &zero in &zero_variations.clone() {
                zero_variations.insert(zero ^ a_s[index]);
            }
            zero_variations.insert(a_s[index]);
        }
    }
    println!("0");
    return Ok(());
}

