use std::cmp::Ordering;

pub trait BinarySearch<T> {
    fn lower_bound(&self, x: &T) -> usize;
    fn upper_bound(&self, x: &T) -> usize;
}

impl<T: Ord> BinarySearch<T> for [T] {
    fn lower_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();

        while low != high {
            let mid = (low + high) / 2;
            match self[mid].cmp(x) {
                Ordering::Less => {
                    low = mid + 1;
                }
                Ordering::Equal | Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }

    fn upper_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();

        while low != high {
            let mid = (low + high) / 2;
            match self[mid].cmp(x) {
                Ordering::Less | Ordering::Equal => {
                    low = mid + 1;
                }
                Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }
}

use proconio::input;

fn proc_r(depth: usize, a: &Vec<usize>, v: &Vec<char>, result: usize) -> bool {
	if depth == a.len() {
		if result == 0 {
			return true;
		}
		else {
			return false;
		}
	}
	match v[depth] {
		'0' => {	// 人0のターン
			//xorする
			let r1 = proc_r(depth+1, a, v, result^a[depth]);
			if r1 {
				return true;
			}
			//何もしない
			let r2 = proc_r(depth+1, a, v, result);
			return r2;
		},
		_ => {		// 人1のターン
			//xorする
			let r1 = proc_r(depth+1, a, v, result^a[depth]);
			if !r1 {
				return false;
			}
			//何もしない
			let r2 = proc_r(depth+1, a, v, result);
			return r2;
		},
	}
}


