fn solve() -> bool {
    let n = read::<usize>();
    let a = read_vec::<i64>();
    let s = read::<String>().chars().collect::<Vec<_>>();
    let mut bases: HashSet<i64> = HashSet::new();
    bases.insert(0);
    for i in (0..n).rev() {
        let mut added = vec![];
        for &elem in bases.iter() {
            if !bases.contains(&(elem ^ a[i])) {
                added.push(elem ^ a[i]);
            }
        }
        if added.is_empty() {
            continue;
        }
        if s[i] == '1' {
            return false;
        } else {
            for elem in added {
                bases.insert(elem);
            }
        }
    }

    true // zero wins
}

