use std::cmp::Ordering;

pub trait BinarySearch<T> {
    fn lower_bound(&self, x: &T) -> usize;
    fn upper_bound(&self, x: &T) -> usize;
}

impl<T: Ord> BinarySearch<T> for [T] {
    fn lower_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();

        while low != high {
            let mid = (low + high) / 2;
            match self[mid].cmp(x) {
                Ordering::Less => {
                    low = mid + 1;
                }
                Ordering::Equal | Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }

    fn upper_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();

        while low != high {
            let mid = (low + high) / 2;
            match self[mid].cmp(x) {
                Ordering::Less | Ordering::Equal => {
                    low = mid + 1;
                }
                Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }
}

use std::io::stdin;

struct Tree {
    state: usize,
    player: Vec<usize>,
    moves: Vec<usize>,
    len: usize,
}

impl Tree {
    fn new(player: Vec<usize>, moves: Vec<usize>) -> Tree {
        let len = player.len();
        Tree {
            state: 0,
            player,
            moves,
            len,
        }
    }

    fn and_or_search(&mut self, t: usize) -> usize {
        if t == self.len {
            return if self.state > 0 { 1 } else { 0 };
        }

        let now = self.player[t];
        let mut winner = self.and_or_search(t + 1);
        if now != winner {
            self.state ^= self.moves[t];
            winner = self.and_or_search(t + 1);
            self.state ^= self.moves[t];
        }

        winner
    }
}

