fn check(one: u64, mut zeros: Vec<u64>) -> bool {
    for bit_pos in 0..64 {
        if one & (1<<bit_pos) != 0 {
            match zeros.iter().position(|z| z & (1<<bit_pos) != 0) {
                None => return false,
                Some(i) => {
                    for j in i+1..zeros.len() {
                        if zeros[j] & (1<<bit_pos) != 0 {
                            zeros[j] ^= zeros[i];
                        }
                    }
                }
            }
        }
    }
    true
}

