// おこりうる遷移を全部見る
fn dfs(s: &Vec<char>, a: &Vec<usize>, n: usize, x: usize, res: &mut Vec<(usize, String)>) {
    if s.len() == n {
        println!("{}: {:?}", n, res);
        return;
    }
    if s[n] == '0' {
        res[n] = (0, format!("{:b}", x));
        dfs(s, a, n + 1, x, res);
        res[n] = (0, format!("{:b}", x ^ a[n]));
        dfs(s, a, n + 1, x ^ a[n], res);
    } else {
        res[n] = (1, format!("{:b}", x));
        dfs(s, a, n + 1, x, res);
        res[n] = (1, format!("{:b}", x ^ a[n]));
        dfs(s, a, n + 1, x ^ a[n], res);
    }
}

