#[allow(unused_macros)]
macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
}

#[allow(unused_macros)]
macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, ($($t: ty),*)) => {
        ($(parse_val!($it, $t)),*)
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, t: usize);
    const M: usize = 61;
    let msb = |x: &usize| {
        let mut ret = M;
        while ret > 0 && *x >> ret == 0 {
            ret -= 1
        }
        ret
    };
    'outer: for _ in 0..t {
        parse!(it, n: usize, a: [usize; n]);
        let s: Vec<bool> = it.next().unwrap().bytes().map(|x| x == b'1').collect();
        let mut bases = vec![];
        for i in (0..n).rev() {
            let mut res = a[i];
            while res > 0 {
                let m = msb(&res);
                if let Ok(i) = bases.binary_search_by_key(&m, msb) {
                    res ^= bases[i];
                } else {
                    break;
                }
            }
            if res != 0 {
                if s[i] {
                    println!("{}", 1);
                    continue 'outer;
                } else {
                    bases.push(res);
                    bases.sort()
                }
            }
        }
        println!("{}", 0);
    }
}

