fn proc_r(depth: usize, a: &Vec<usize>, s: &String, result: usize) -> bool {
	if depth == a.len() {
		if result == 0 {
			return true;
		}
		else {
			return false;
		}
	}
	match s.chars().nth(depth).unwrap() {
		'0' => {	// 人0のターン
			//xorする
			let r1 = proc_r(depth+1, a, s, result^a[depth]);
			if r1 {
				return true;
			}
			//何もしない
			let r2 = proc_r(depth+1, a, s, result);
			return r2;
		},
		_ => {		// 人1のターン
			//xorする
			let r1 = proc_r(depth+1, a, s, result^a[depth]);
			if !r1 {
				return false;
			}
			//何もしない
			let r2 = proc_r(depth+1, a, s, result);
			return r2;
		},
	}
}

