fn solve() {
    input! {
        n: usize,
        a: [usize; n],
        s: Chars
    }

    let mut z = hashset![0usize];
    let mut o = hashset![0usize];

    for (i, p) in s.iter().enumerate().rev() {
        match p {
            '0' => {
                let mut add = HashSet::new();
                for e in z.iter() {
                    add.insert(*e ^ a[i]);
                }
                z.extend(add.iter());
            }
            '1' => {
                let mut add = HashSet::new();
                for e in o.iter() {
                    add.insert(*e ^ a[i]);
                }
                o.extend(add.iter());
            }
            _ => unreachable!()
        }
    }

    if z.is_superset(&o) {
        println!("0");
    } else {
        println!("1");
    }
}

