    let s = read::<String>().chars().collect::<Vec<_>>();

    let mut bases = vec![];
    for i in (0..n).rev() {
        let mut cur = a[i];
        for &elem in bases.iter().rev() {
            cur = min(elem ^ cur, cur);
        }
        if cur == 0 {
            continue;
        }
        if s[i] == '1' {
            return false;
        } else {
            bases.push(cur);
            bases.sort();
        }
