fn solve() -> bool {
    let n = read::<usize>();
    let a = read_vec::<i64>();
    let s = read::<String>().chars().collect::<Vec<_>>();
    let zero_poses = (0..n).filter(|&x| s[x] == '0').collect::<Vec<_>>();
    let one_poses = (0..n).filter(|&x| s[x] == '1').collect::<Vec<_>>();

    let mut dp = vec![vec![]; n];
    dp[zero_poses[zero_poses.len() - 1]].push(0);
    dp[zero_poses[zero_poses.len() - 1]].push(a[zero_poses[zero_poses.len() - 1]]);
    for i in (0..zero_poses.len() - 1).rev() {
        let mut next = dp[zero_poses[i + 1]].clone();
        for &elem in &dp[zero_poses[i + 1]] {
            if !dp[zero_poses[i + 1]].contains(&(elem ^ a[zero_poses[i]])) {
                next.push(elem ^ a[zero_poses[i]]);
            }
        }
        dp[zero_poses[i]] = next;
    }

    let mut cur = vec![0];
    for one_pos in one_poses {
        let next_zero_idx = zero_poses.lower_bound(&one_pos);
        if next_zero_idx == zero_poses.len() {
            return false;
        }
        let next_zero = zero_poses[next_zero_idx];

        let mut next = vec![];
        for &elem in &cur {
            next.push(elem ^ a[one_pos]);
            if !dp[next_zero].contains(&(elem ^ a[one_pos])) {
                // debug!(next_zero);
                // debug!(dp[next_zero]);
                return false;
            }
        }
        for &elem in &cur {
            next.push(elem);
        }
        next.sort();
        next.dedup();
        cur = next;
    }
    true // zero wins
}

