fn gau(v: &mut Vec<usize>) {
    let mut r = 0;
    const BS: usize = 61;
    let n = v.len();
    for j in (0..BS).rev() {
        if r >= v.len() {
            break;
        }
        if let Some(pivot) = (r..n).filter(|&i| !v[i] & 1usize << j == 0).next() {
            v.swap(r, pivot);
            for i in 0..n {
                if i != r && v[i] & 1usize << j != 0 {
                    v[i] ^= v[r];
                }
            }
            r += 1;
        }
    }
    v.truncate(r);
}
