fn run() -> Result<(), Box<dyn Error>> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let t = input.trim().parse::<i32>()?;
    input.clear();

    for _i in 0..t {
        solve_each();
    }

    Ok(())
}

fn solve_each() -> Result<(), Box<dyn Error>> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let n = input.trim().parse::<usize>()?;
    input.clear();

    io::stdin().read_line(&mut input)?;
    let a_s: Vec<i64> = input
        .trim()
        .split_whitespace()
        .map(|s| s.parse::<i64>().unwrap())
        .collect();
    input.clear();

    io::stdin().read_line(&mut input)?;
    let s_s = input.trim().to_owned();
    input.clear();

    let mut s_s: Vec<char> = s_s.chars().collect();
    if *s_s.last().unwrap() == '1' {
        println!("1");
        return Ok(());
    }
    s_s.reverse();
    let mut one_variations: Vec<i64> = vec![];
    let mut zero_variations: Vec<i64> = vec![];
    for (index, &x) in s_s.iter().enumerate() {
        if x == '1' {
            let mut new_one = vec![];
            for &one in &one_variations {
                new_one.push(one ^ a_s[index]);
            }
            new_one.push(a_s[index]);

            for one in new_one {
                if !zero_variations.contains(&one) {
                    println!("1");
                    return Ok(());
                }
                one_variations.push(one);
            }
        } else {
            // x == '0'
            // one_variations.clear();
            let mut new_zero = vec![];
            for &zero in &zero_variations {
                new_zero.push(zero ^ a_s[index]);
            }
            new_zero.push(a_s[index]);
            for zero in new_zero {
                zero_variations.push(zero);
            }
        }
    }
    println!("0");
    return Ok(());
}

