#[derive(Clone)]
struct BitSet {
    size: usize,
    a: Vec<usize>,
}

fn bit_size() -> usize {
    8 * std::mem::size_of::<usize>()
}

fn quot_rem(n: usize) -> (usize, usize) {
    let w = bit_size();
    (n / w, n % w)
}

#[allow(dead_code)]
impl BitSet {
    fn new(size: usize) -> Self {
        let w = bit_size();
        BitSet {
            size: size,
            a: vec![0; (size + w - 1) / w],
        }
    }
    fn set_at(&mut self, x: usize) {
        assert!(x < self.size);
        let (q, r) = quot_rem(x);
        self.a[q] |= 1 << r;
    }
    fn clear_at(&mut self, x: usize) {
        assert!(x < self.size);
        let (q, r) = quot_rem(x);
        self.a[q] &= !(1 << r);
    }
    fn get_at(&self, x: usize) -> bool {
        if x >= self.size {
            return false;
        }
        let (q, r) = quot_rem(x);
        (self.a[q] >> r) & 1 == 1
    }
    fn any(&self) -> bool {
        self.a.iter().any(|a| *a != 0)
    }
    fn fix(&mut self) {
        let (q, r) = quot_rem(self.size);
        if r != 0 {
            self.a[q] &= (1 << r) - 1;
        }
    }
    fn clear(&mut self) {
        let len = self.a.len();
        self.a.clear();
        self.a.resize(len, 0);
    }
    fn truncate(&mut self, len: usize) {
        if len >= self.size {
            return;
        }
        let w = bit_size();
        self.a.truncate((len + w - 1) / w);
        self.size = len;
        self.fix();
    }
    fn popcnt(&self) -> usize {
        self.a.iter().fold(0, |s, a| s + a.count_ones() as usize)
    }
    fn shift_left(&self, rhs: usize) -> Self {
        let (q, r) = quot_rem(rhs);
        let mut ans = BitSet::new(self.size + rhs);
        if r == 0 {
            for (x, y) in ans.a[q..].iter_mut().zip(self.a.iter()) {
                *x = *y;
            }
        } else {
            let w = bit_size();
            let mut prev = 0;
            for (x, y) in ans.a[q..].iter_mut().zip(self.a.iter()) {
                *x = (*y << r) | (prev >> (w - r));
                prev = *y;
            }
            *ans.a.last_mut().unwrap() |= prev >> (w - r);
        }
        ans.fix();
        ans
    }
    fn shift_right(&self, rhs: usize) -> Self {
        if rhs >= self.size {
            return BitSet::new(1);
        }
        let (q, r) = quot_rem(rhs);
        let mut ans = BitSet::new(self.size - rhs);
        if r == 0 {
            for (x, y) in ans.a.iter_mut().zip(self.a[q..].iter()) {
                *x = *y;
            }
        } else {
            let w = bit_size();
            let mut prev = 0;
            for (x, y) in ans.a.iter_mut().zip(self.a[q..].iter()).rev() {
                *x |= (*y >> r) | (prev << (w - r));
                prev = *y;
            }
        }
        ans.fix();
        ans
    }
    fn bitwise_or(&self, rhs: &Self) -> Self {
        let (x, y) = if self.size >= rhs.size {(self, rhs)} else {(rhs, self)};
        let mut a = x.a.clone();
        for (a, y) in a.iter_mut().zip(y.a.iter()) {
            *a |= *y;
        }
        BitSet {
            size: x.size,
            a: a,
        }
    }
    fn bitwise_and(&self, rhs: &Self) -> Self {
        let (x, y) = if self.size <= rhs.size {(self, rhs)} else {(rhs, self)};
        let mut a = x.a.clone();
        for (a, y) in a.iter_mut().zip(y.a.iter()) {
            *a &= *y;
        }
        BitSet {
            size: x.size,
            a: a,
        }
    }
    fn bitwise_xor(&self, rhs: &Self) -> Self {
        let (x, y) = if self.size >= rhs.size {(self, rhs)} else {(rhs, self)};
        let mut a = x.a.clone();
        for (a, y) in a.iter_mut().zip(y.a.iter()) {
            *a ^= *y;
        }
        BitSet {
            size: x.size,
            a: a,
        }
    }
    fn bitwise_or_assign(&mut self, rhs: &Self) {
        if self.size < rhs.size {
            self.size = rhs.size;
            self.a.resize(rhs.a.len(), 0);
        }
        for (a, b) in self.a.iter_mut().zip(rhs.a.iter()) {
            *a |= *b;
        }
    }
    fn bitwise_and_assign(&mut self, rhs: &Self) {
        if self.size > rhs.size {
            self.size = rhs.size;
            self.a.resize(rhs.a.len(), 0);
        }
        for (a, b) in self.a.iter_mut().zip(rhs.a.iter()) {
            *a &= *b;
        }
    }
    fn bitwise_xor_assign(&mut self, rhs: &Self) {
        if self.size < rhs.size {
            self.size = rhs.size;
            self.a.resize(rhs.a.len(), 0);
        }
        for (a, b) in self.a.iter_mut().zip(rhs.a.iter()) {
            *a ^= *b;
        }
    }
}

struct Gauss_Jordan {
	A: Vec<BitSet>,
	size: usize,
} 

impl Gauss_Jordan {
	pub fn new (A: Vec<BitSet>) -> Self {
		let mut s = 0;
		for i in 0..A.len() {
			s = max(s, A[i].size);
		}
		Gauss_Jordan {
			A: A,
			size: s,
		}
	}
	pub fn push(&mut self, x: BitSet) {
		self.size = max(self.size, x.size);
		self.A.push(x);
	}
	pub fn calc(&mut self) {
		let mut seen = vec![false; self.A.len()];
		for c in (0..self.size).rev() {
			let mut root = self.A.len();
			for r in 0..self.A.len() {
				if seen[r] {
					continue;
				}
				if self.A[r].get_at(c) {
					root = r;
					break;
				}
			}
			if root==self.A.len() {
				continue;
			}
			let root_val = self.A[root].clone();
			for r in 0..self.A.len() {
				if r==root || !self.A[r].get_at(c) {
					continue;
				}
				self.A[r].bitwise_xor_assign(&root_val);
			}
			seen[root] = true;
		}
	}
	pub fn include(&self, x: BitSet) -> bool {
		let mut v = x.clone();
		for c in (0..self.size).rev() {
			if !v.get_at(c) {
				continue;
			}
			for r in 0..self.A.len() {
				if !self.A[r].get_at(c) {
					continue;
				}
				v.bitwise_xor_assign(&self.A[r]);
				continue;
			}
		}
		match v.popcnt() {
			0 => true,
			_ => false,
		}
	}
	pub fn print(&self) {
		for i in 0..self.A.len() {
			for j in (0..self.size).rev() {
				if self.A[i].get_at(j) {
					print!("1");
				}
				else {
					print!("0");
				}
			}
			println!();
		}
	}
}

fn solve() {
	let t = read!(usize);
	for i in 0..t {
		let n = read!(usize);
		let a = read!([i64]);
		let s = read!(String);
		let c = s.chars().collect::<Vec<char>>();

		let mut gj = Gauss_Jordan::new(vec![BitSet::new(0)]);
		let mut flag = true;
		for j in (0..n).rev() {
			let mut bit = BitSet::new(100);
			for k in 0..100 {
				if (a[j]>>k)%2==1 {
					bit.set_at(k);
				}
			}
			if c[j]=='0' {
				gj.push(bit);
			}
			else {
				gj.calc();
				if !gj.include(bit) {
					flag = false;
					break;
				}
			}
		}
		if flag {
			println!("0");
		}
		else {
			println!("1");
		}
	}
}

fn run() {
    solve();
}

use proconio::*;
use proconio::marker::Chars;
use std::cmp::min;

#[fastout]
fn run() {
    input! {
        t: usize,
    }
    for _ in 0..t {
        input! {
            n: usize,
            mut a: [usize; n],
            s: Chars,
        }
        let mut ans = 0;
        for (i, c) in s.into_iter().enumerate().rev() {
            let v = a[i];
            if v == 0 {
                continue;
            }
            if c == '1' {
                ans = 1;
            } else {
                for a in a.iter_mut() {
                    *a = min(*a, *a ^ v);
                }
            }
        }
        println!("{}", ans);
    }
}

fn main() {
    run();
}

