        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, ($($t: ty),*)) => {
        ($(parse_val!($it, $t)),*)
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, t: usize);
    'outer: for _ in 0..t {
        parse!(it, n: usize, a: [usize; n]);
        let s: Vec<bool> = it.next().unwrap().bytes().map(|x| x == b'1').collect();
        let mut bases = vec![];
        for i in (0..n).rev() {
            let mut res = a[i];
            for &b in bases.iter() {
                res = min(res, res ^ b)
            }
            if res != 0 {
                if s[i] {
                    println!("{}", 1);
                    continue 'outer;
                } else {
                    bases.push(res)
                }
            }
        }
        println!("{}", 0);
    }
}

