            println!("0");
        } else {
            println!("1");
        }
    }
}

fn solve(mut a: Vec<u64>, mut s: Vec<bool>) -> bool {
    let n = a.len();
    if !s[n - 1] {
        return false;
    }

    let mut a0 = vec![];
    let mut a1 = vec![];

    let mut s0 = vec![];
    let mut s1 = vec![];

    let mut prev_turn = true;
    while let Some(turn) = s.pop() {
        if turn != prev_turn {
            if prev_turn {
                s0.push(a0);
                a0 = vec![];
            } else {
                s1.push(a1);
                a1 = vec![];
            }
            prev_turn = turn;
        }

        let a = a.pop().unwrap();
        if turn {
            a0.push(a);
        } else {
            a1.push(a);
        }
    }

    if !prev_turn {
        s1.push(a1);
    }

    assert_eq!(s0.len(), s1.len());
    let m = s0.len();
    let mut t0 = vec![];
    let mut t1 = vec![];
    for i in 0..m {
        t0.extend_from_slice(&s0[i]);
        t1.extend_from_slice(&s1[i]);

        let rank0 = normalize(&mut t0);
        let rank1 = normalize(&mut t1);
        if rank0 < rank1 {
            return false;
        }

        for &s1 in t1.iter() {
            let mut cur = s1;
            for &s0 in t0.iter() {
                if cur ^ s0 < cur {
                    cur ^= s0;
                }
            }
            if cur != 0 {
                return false;
            }
        }
    }

    true
}

fn normalize(a: &mut Vec<u64>) -> usize {
    let n = a.len();
    let mut cur = 0;
    for pos in 0..SIZE {
        if let Some(i) = (cur..n).find(|&i| a[i] & (1 << pos) != 0) {
            a.swap(cur, i);
            for i in 0..n {
                if i == cur {
                    continue;
                }
                if a[i] & (1 << pos) != 0 {
                    a[i] ^= a[cur];
                }
            }
            cur += 1;
        }
    }
    cur
}

