// A != 0 なので
// 最後に操作できる人が1ならどうやってもx!=0となる
// 最後に操作するのが0だとする
// 最後に操作できる空間に入らないように1が調整可能か
// 最後の0連打までは0は何も操作しないのがいい？
// ->嘘、4, 4, 2, 2 (1010)
//
// 落ち着こう、操作がA=1のみで考えよう
// これは最後に操作できる方が勝ち
//
// 1が最後に操作できるbitがあるなら1
// そうでない時は？
// 1,2,3 (110) とかは1になるがどのbitも最後に操作可能なのは0のみ
//

fn calc(x: &mut Vec<u64>) {
    if x.len() == 0 {
        return;
    }
    let mut ans = vec![];
    loop {
        let p = *x.iter().max().unwrap();
        if p == 0 {
            break;
        }
        for x in x.iter_mut().chain(ans.iter_mut()) {
            *x = std::cmp::min(*x, *x ^ p);
        }
        ans.push(p);
    }
    *x = ans;
}

fn run(sc: &mut scanner::Scanner, out: &mut std::io::BufWriter<std::io::StdoutLock>) {
    let t: usize = sc.next();
    for _ in 0..t {
        let n: usize = sc.next();
        let a: Vec<u64> = (0..n).map(|_| sc.next()).collect();
        let s: Vec<_> = sc.next_chars().into_iter().map(|d| d.to_digit(10).unwrap() as usize).collect();
        let w = 60;
        let mut x = vec![];
        let mut y = vec![];
        let mut last = vec![0; 60];
        for (&a, &d) in a.iter().zip(s.iter()).rev() {
            if d == 1 {
                y.push(a);
                for i in 0..w {
                    if a >> i & 1 == 1 {
                        last[i] = 1;
                    }
                }
            } else if (0..w).all(|k| (a >> k) & 1 == 0 || last[k] == 0) {
                x.push(a);
            }
        }
        calc(&mut x);
        let mut ans = "0";
        for y in y.iter() {
            let mut y = *y;
            for x in x.iter() {
                y = std::cmp::min(y, y ^ x);
            }
            if y != 0 {
                ans = "1";
            }
        }
        writeln!(out, "{}", ans).ok();
    }
}

