// 

fn calc(x: &mut Vec<u64>) {
    if x.len() == 0 {
        return;
    }
    let mut ans = vec![];
    loop {
        let p = *x.iter().max().unwrap();
        if p == 0 {
            break;
        }
        for x in x.iter_mut().chain(ans.iter_mut()) {
            *x = std::cmp::min(*x, *x ^ p);
        }
        ans.push(p);
    }
    *x = ans;
}

fn run(sc: &mut scanner::Scanner, out: &mut std::io::BufWriter<std::io::StdoutLock>) {
    let t: usize = sc.next();
    for _ in 0..t {
        let n: usize = sc.next();
        let mut a: Vec<u64> = (0..n).map(|_| sc.next()).collect();
        let s: Vec<_> = sc.next_chars().into_iter().map(|d| d.to_digit(10).unwrap() as usize).collect();
        let mut ans = 0;
        for i in (0..n).rev() {
            if s[i] == 1 {
                if a[i] != 0 {
                    ans = 1;
                }
            } else if a[i] != 0 {
                let v = a[i];
                let k = v.trailing_zeros() as u64;
                for j in 0..=i {
                    if a[j] >> k & 1 == 1 {
                        a[j] ^= v;
                    }
                }
            }
        }
        writeln!(out, "{}", ans).ok();
    }
}

