fn solve() {
    let stdin = io::stdin();
    let mut kin = KInput::new(stdin.lock());
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    macro_rules! output { ($($args:expr),+) => { write!(&mut out, $($args),+).unwrap(); }; }
    macro_rules! outputln {
        ($($args:expr),+) => { output!($($args),+); outputln!(); };
        () => { output!("\n"); if cfg!(debug_assertions) { out.flush().unwrap(); } }
    }

    let t: usize = kin.input();
    'test: for _ in 0..t {
        let n: usize = kin.input();
        let mut a: Vec<u64> = kin.seq(n);
        let s: Vec<u8> = kin.input();

        if s.last() == Some(&b'1') {
            outputln!("1");
            continue;
        }

        let mut i = 0;
        while s.get(i) == Some(&b'0') {
            i += 1;
        }

        while i < n {
            let l = i;
            while s.get(i) == Some(&b'1') {
                i += 1;
            }
            let m = i;
            while s.get(i) == Some(&b'0') {
                i += 1;
            }
            let r = i;
            let rm = l + elimination(&mut a[l..m]);
            let rr = m + elimination(&mut a[m..r]);
            for i in l..rm {
                let mut x = a[i];
                for j in m..rr {
                    x = x.min(x ^ a[j]);
                }
                if x != 0 {
                    outputln!("1");
                    continue 'test;
                }
            }
        }
        outputln!("0");
    }
}

pub fn elimination<T>(a: &mut [T]) -> usize
where
    T: std::ops::BitXor<Output = T> + Ord + Default + Copy,
{
    for k in 0..a.len() {
        let (pi, &p) = a.iter().enumerate().skip(k).max_by_key(|(_, r)| *r).unwrap();
        if p == T::default() {
            return k;
        }
        a.swap(k, pi);
        for (i, r) in a.iter_mut().enumerate() {
            if i != k {
                *r = (*r).min(*r ^ p);
            }
        }
    }
    a.len()
}

