			while let Some(v) = q.pop() {
				nq.push(v);
				for j in (0..31).rev() {
					if (v>>j)==1_i64 {
						if (val>>j)==1_i64{
							val ^= v;
						}
						break;
					}
				}
			}
			if c[i]=='0' {
				if val!=0 {
					nq.push(val);
				}
			}
			else {
				if val!=0 {
					println!("1");
					flag = false;
					break;
				}
			}
			q = nq;
		}
		if flag {
			println!("0");
		}
	}
}

