use proconio::marker::Chars;
use proconio::{fastout, input};

fn solve() {
    input! { in_n: usize, in_a: [i128; in_n], in_s: Chars};
    let mut nums = Vec::new();

    for i in (0..in_s.len()).rev() {
        if in_s[i] == '0' {
            let mut a = in_a[i];
            let mut j = 0;

            while a != 0 {
                if j == nums.len() {
                    nums.push(a);
                    a = 0;
                } else {
                    if a > nums[j] {
                        std::mem::swap(&mut a, &mut nums[j]);
                    }

                    let b = nums[j] ^ a;

                    if b < a {
                        a = b;
                    }

                    j += 1;
                }
            }
        } else {
            let mut a = in_a[i];

            for n in &nums {
                let b = a ^ *n;

                if b < a {
                    a = b;
                }
            }

            if a != 0 {
                println!("1");
                return;
            }
        }
    }

    println!("0");
}

#[fastout]
fn main() {
    input! {in_t: usize};

    for _ in 0..in_t {
        solve();
    }
}

