fn f() -> usize {
    input! {
        n:usize,
        a:[usize;n],
        s:Chars
    }

    let mut dp = vec![];
    for i in (0..n).rev() {
        let mut tmp = a[i];
        for j in &dp {
            tmp = std::cmp::min(tmp, tmp ^ *j);
        }
        if s[i] == '0' {
            if tmp > 0 {
                dp.push(tmp);
            }
        } else {
            if tmp > 0 {
                return 1;
            }
        }
    }
    0
}

