struct Gauss_Jordan {
	A: Vec<BitSet>,
	size: usize,
} 

impl Gauss_Jordan {
	pub fn new (A: Vec<BitSet>) -> Self {
		let mut s = 0;
		for i in 0..A.len() {
			s = max(s, A[i].size);
		}
		Gauss_Jordan {
			A: A,
			size: s,
		}
	}
	pub fn push(&mut self, x: BitSet) {
		self.size = max(self.size, x.size);
		self.A.push(x);
	}
	pub fn calc(&mut self) {
		let mut seen = vec![false; self.A.len()];
		for c in (0..self.size).rev() {
			let mut root = self.A.len();
			for r in 0..self.A.len() {
				if seen[r] {
					continue;
				}
				if self.A[r].get_at(c) {
					root = r;
					break;
				}
			}
			if root==self.A.len() {
				continue;
			}
			let root_val = self.A[root].clone();
			for r in 0..self.A.len() {
				if r==root || !self.A[r].get_at(c) {
					continue;
				}
				self.A[r].bitwise_xor_assign(&root_val);
			}
			seen[root] = true;
		}
	}
	pub fn include(&self, x: BitSet) -> bool {
		let mut v = x.clone();
		for c in (0..self.size).rev() {
			if !v.get_at(c) {
				continue;
			}
			for r in 0..self.A.len() {
				if !self.A[r].get_at(c) {
					continue;
				}
				v.bitwise_xor_assign(&self.A[r]);
				continue;
			}
		}
		match v.popcnt() {
			0 => true,
			_ => false,
		}
	}
	pub fn print(&self) {
		for i in 0..self.A.len() {
			for j in (0..self.size).rev() {
				if self.A[i].get_at(j) {
					print!("1");
				}
				else {
					print!("0");
				}
			}
			println!();
		}
	}
}

