use std::collections::BTreeSet;

const SIZE: u64 = 60;
fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let t: usize = sc.read();
    for _ in 0..t {
        let n: usize = sc.read();
        let a: Vec<u64> = sc.vec(n);
        let s = sc.chars().into_iter().map(|c| c == '0').collect::<Vec<_>>();
        if solve(a, s) {
            println!("0");
        } else {
            println!("1");
        }
    }
}

fn solve(mut a: Vec<u64>, mut s: Vec<bool>) -> bool {
    let n = a.len();
    if !s[n - 1] {
        return false;
    }

    let mut a0 = vec![];
    let mut a1 = vec![];

    let mut s0 = vec![];
    let mut s1 = vec![];

    let mut prev_turn = true;
    while let Some(turn) = s.pop() {
        if turn != prev_turn {
            if prev_turn {
                s0.push(a0);
                a0 = vec![];
            } else {
                s1.push(a1);
                a1 = vec![];
            }
            prev_turn = turn;
        }

        let a = a.pop().unwrap();
        if turn {
            a0.push(a);
        } else {
            a1.push(a);
        }
    }

    if !prev_turn {
        s1.push(a1);
    }

    assert_eq!(s0.len(), s1.len());
    let m = s0.len();
    let mut t0 = vec![];
    let mut t1 = vec![];
    for i in 0..m {
        t0.extend_from_slice(&s0[i]);
        t1.extend_from_slice(&s1[i]);

        let rank0 = normalize(&mut t0);
        let rank1 = normalize(&mut t1);
        if rank0 < rank1 {
            return false;
        }
        let mut set0 = BTreeSet::new();
        for i in 0..rank0 {
            set0.insert(t0[i]);
        }

        for i in 0..rank1 {
            if !set0.contains(&t1[i]) {
                return false;
            }
        }
    }

    true
}

fn normalize(a: &mut Vec<u64>) -> usize {
    let n = a.len();
    let mut cur = 0;
    for pos in 0..SIZE {
        if let Some(i) = (cur..n).find(|&i| a[i] & (1 << pos) != 0) {
            a.swap(cur, i);
            for i in 0..n {
                if i == cur {
                    continue;
                }
                if a[i] & (1 << pos) != 0 {
                    a[i] ^= a[cur];
                }
            }
            cur += 1;
        }
    }
    cur
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        Self(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

