			if c[j]=='0' {
				gj.push(bit);
			}
			else {
				gj.calc();
				if !gj.is_dependent(bit) {
					flag = false;
					break;
				}
			}
		}
		if flag {
			println!("0");
		}
		else {
			println!("1");
		}
	}
}

fn run() {
    solve();
}

