fn solve() -> bool {
    let n = read::<usize>();
    let a = read_vec::<i64>();
    let s = read::<String>().chars().collect::<Vec<_>>();
    let zero_poses = (0..n).filter(|&x| s[x] == '0').collect::<Vec<_>>();
    let one_poses = (0..n).filter(|&x| s[x] == '1').collect::<Vec<_>>();

    let mut dp = vec![HashSet::new(); n];
    dp[zero_poses[zero_poses.len() - 1]].insert(0);
    dp[zero_poses[zero_poses.len() - 1]].insert(a[zero_poses[zero_poses.len() - 1]]);
    for i in (0..zero_poses.len() - 1).rev() {
        let mut next = dp[zero_poses[i + 1]].clone();
        for &elem in &dp[zero_poses[i + 1]] {
            next.insert(elem ^ a[zero_poses[i]]);
        }
        dp[zero_poses[i]] = next;
    }

    let mut cur = HashSet::new();
    cur.insert(0);
    for one_pos in one_poses {
        let next_zero_idx = zero_poses.lower_bound(&one_pos);
        if next_zero_idx == zero_poses.len() {
            return false;
        }
        let next_zero = zero_poses[next_zero_idx];

        let mut next = cur.clone();
        for &elem in &cur {
            next.insert(elem ^ a[one_pos]);
            if !dp[next_zero].contains(&(elem ^ a[one_pos])) {
                // debug!(next_zero);
                // debug!(dp[next_zero]);
                return false;
            }
        }
        cur = next;
    }
    true // zero wins
}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

use std::cmp::Ordering;

pub trait BinarySearch<T> {
    fn lower_bound(&self, x: &T) -> usize;
    fn upper_bound(&self, x: &T) -> usize;
}

impl<T: Ord> BinarySearch<T> for [T] {
    fn lower_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();

        while low != high {
            let mid = (low + high) / 2;
            match self[mid].cmp(x) {
                Ordering::Less => {
                    low = mid + 1;
                }
                Ordering::Equal | Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }

    fn upper_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();

        while low != high {
            let mid = (low + high) / 2;
            match self[mid].cmp(x) {
                Ordering::Less | Ordering::Equal => {
                    low = mid + 1;
                }
                Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }
}

